const hadithCollection = [
    { id: 1, text: "Mü’minlerin emiri Ebû Hafs Ömer b. Hattâb b. Nüfeyi b. Abdüluzza b. Riyâh b. Abdullah b. Kurt b. Rezâh b. Adiyy b, Ka'b b. Lüeyy b. Gâlib el Kureyşî el-Adevî (r.a)'dan şöyle rivayet edilmiştir: Allah Resulü (s.a.v)’i şöyle söylerken duydum; \"Ameller, niyetlere göredir. Her kişiye, sadece niyetinin karşılığı vardır. Her kimin hicreti Allah ve Resulüne ise, onun hicreti de Allah ve Resûlünedir. Her kimin hicreti de elde edeceği dünya -malı- veya nikahlayacağı bir kadın için olursa, onun hicreti de o yöneldiği şeyedir.\" Hadisin sıhhatinde ittifak vardır. Hadisi; hadisçilerin imamı E-   bu Abdullah Muhammed b. İsmail b. İbrahim b. Muğire b. Berdiz-be el Cûfî el-Buhari ve Ebu Hüseyn Müslim b. Haccac b. Müslim el-Kuşeyrî Nisâburî (r.a), tasnif edilen kitapların en sahihlerinden 'Sahihayn'da rivayet etmiştir.", source: "Hadis-i Şerif" },
    { id: 2, text: "Mü'minlerin annesi, Abdullah'ın h. Zübeyr'in teyzesi Âişe (r.a)'dan şöyle rivayet edilmiştir: Resûlüllâh (s.a.v) şöyle buyurmuştur: \"Bir takım askerler Ka'be'ye doğru -savaşmak kastıyla- yola çıkarlar. 'Beydâ' denilen yere geldiklerinde, ön tarafta bulunanlar da arka tarafta bulunanlar da yerin dibine geçirilirler.\" Hazreti Aişe (r.a) diyor ki, ben; \"Ey Allah'ın elçisi, nasıl olur da Öndekilerin ve arkadakilerin tümü yerin dibine geçiriliyor? Oysa onların arasında çarşı pazarda dolaşan ve onlardan olmayıp -aralarına karışanlar— var!\" dedim. Resûlüllâh (s.a.v) da şöyle buyurdu: \"Öndekilerin ve arkadakilerin hepsi yerin dibine geçirilir; sonra da niyetlerine göre diriltilirler.\" (Buhari ve Müslim)  İHLAS VE SAMİMİ NİYET", source: "Hadis-i Şerif" },
    { id: 3, text: "Ebâ Abdullah Câbir b. Abdullah el-Ensarî (r.a) şöyle söylemiştir: Bir savaşta Allah Resulü (s.a.v) ile birlikteydik. Bir ara şöyle buyurdu: \"Medine'de -savaşa iştirak edememiş- öyle erler vardır ki, yürüyüp geçtiğiniz her yerde, aştığınız her vadide sizinle beraberdirler; ancak onları hastalık alıkoydu.\" Diğer bir rivayette şöyle söylenmiştir: \"Ancak onlar, sevapta size ortak olmuşlardır.\" (Müslim rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 4, text: "Ebû Yezid Ma'n b. Yezid b. El-Ahnes (r.a)'dan şöyle rivayet edilmiştir: ( Bu kişi, babası ve dedesi sahabidirler) Babam Yezid, sadaka olarak vermek için birkaç dinar çıkarıp onları mescitte bir adamın yanına koydu. Ben de gelip onları aldım ve babama götürdüm. Babam; 'Allah'a yemin olsun ki, sana vermeyi dilememiştim’ dedi. Bunun üzerine Resûlüllâh'ın (s.a.v) huzurunda tartıştık. Allah Resulü (s.a.v) şöyle buyurdu: \"Ey Yezid, sana niyetinin - sevabı - vardır ve Ey Ma'n, aldıkların da senindir.\" (Buhari rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 5, text: "Ebû Hureyre Abdurrahmân b, Sahr'dan (r.a), Resûlüllâh (s.a.v) 'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki Allah sizin cisimlerinize ve görünüşlerinize bakmaz; ama kalplerinize bakar.\" (Müslim rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 6, text: "Ebül-Abbas Abdullah b. Abbas b. Abdül-Muttalib (r.a)'dan rivayet edildiğine göre, Resûlüllâh (s.a.v) Yüce Rabbinden şöyle ri vayet buyurdu; \"Şüphesiz ki Allah iyiliklerin ve kötülüklerin yazılmasını emretti; sonra da bunları açıkladı. Kim bir iyilik yapmaya niyetlenir de yapamazsa, Allah (c.c) onu kendi katında tam bir iyilik -yapılmış gibi- yazar. Eğer o iyiliği yapmaya niyetlenir ve yaparsa, Allah (c.c) onu on kat sevaptan yedi yüz kat sevaba, hatta daha fazlasına katlayarak yazar. Eğer bir fenalık yapmaya niyetlenir de yapmazsa, Allah (c.c) onu tam bir iyilik olarak yazar. Eğer o fenalığı yapmaya niyet eder ve de yaparsa, Allah (c.c) onu bir tek günah olarak yazar.\" (Buharı ve Müslim) TEVBE  TEVBE", source: "Hadis-i Şerif" },
    { id: 7, text: "Ebû Hureyre (r.a)'dan gelen rivayette demiştir ki; Resûlüllâh (s.a.v)'i şöyle söylerken işittim: \"Allah'a yemin olsun ki, ben günde yetmiş defadan daha fazla Allah'tan af diliyorum ve O'na tevbe ediyorum.\" (Buhari rivayet etmiştir.) .", source: "Hadis-i Şerif" },
    { id: 8, text: "Resûlüllâh (s.a.v)'in hizmetini yapan Ebû Hamza Enes b. Mâlik'den, Resûlüllâh (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kulunun tevbe etmesindeki Allah'ın hoşnutluğu, sizden birinin ıssız bir çölde devesini kaybedip de sonra bulduğunda duyduğu sevinçten daha fazladır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 9, text: "Ebû Musa Abdullah b. Kays el-Eş'ari (r.a)'den, Resûlüllâh (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki Allah, gündüz günah işleyenlerin tevbe etmeleri için geceleyin elini açar; gece günah işleyenlerin tevbe etmeleri için de gündüz elini açar onları tevbeye çağırır- Bu hal, güneşin battığı yerden doğmasına kadar kıyamete kadar- sürer.\" (Buhari rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 10, text: "Ebû Hureyre (r.a)'den, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Kim, güneş batıdan doğmadan -kıyamet kopmadan- tevbe ederse, Allah (c.c) tevbesini kabul eder.\" (Müslim rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 11, text: "Ebû Abdurrahman Abdullah b. ‘Ömer b. Hattab (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki Allah, can boğaza gelmedikçe kulunun tevbesini kabul eder.\" (Tirmizi rivayet etmiş ve demiştir ki; hadis, hasendir.)", source: "Hadis-i Şerif" },
    { id: 12, text: "İbn-i Abbas ve Enes b. Mâlik (r.a)'dan, Resûlüllah (s.a.v)’in şöyle buyurduğu rivayet edilmiştir: \"Âdemoğlunun bir vadi -dolusu- altını olsa, yine de iki vadi -dolusu- daha olmasını arzular. Onun ağzını ancak toprak doldurur. Allah (c.c), tevbe edenlerin tevbesini kabul eder.\" (Buhari ve Müslim)  SABIR SABIR", source: "Hadis-i Şerif" },
    { id: 13, text: "Ebu Mâlîk el-Hâris b. Asım el-Eş'arî (r.a)'dan, Resûlüllah (s.a.v)'ın söyle buyurduğu rivayet edilmiştir: \"Temizlik imanın yarısıdır. 'El-Hamdülillah' zikri-nin sevabı-mizanı doldurur. 'Sübhânellahi vel-Hamdülillahİ’ zikri ise, yerle gök arasını doldurur. Namaz nurdur. Sadaka, sahibinin imanına işaret eder. Sabır, aydınlıktır. Kur'an, senin lehine veya aleyhine bir delildir. Bütün insanlar sabahleyin işine çıkar, kendisini satar. Ya kurtarır, ya da helak olur.\" (Müslim rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 14, text: "Ebu Said Sa'd b. Sinhan el-Hudrî (r.a)'dan rivayet edil miştir: Ensardan bir grup insan Resûlüllah (s.a.v)'dan sadaka istediler, o da onlara verdi. Sonra O'ndan yine istediler, O yine verdi. Ta   ki yanındakiler tükendi. Elinde bulunan her şeyi onlara verdikten sonra kendilerine şöyle buyurdu: \"Yanımda -dağıtacak- bir mal kalsaydı, onu sizden esirgemezdim. Her kim dilenmekten kaçınırsa, Allah (c.c) onu iffetli kılar. Kim, hiçbir kimseye muhtaç olmamayı dilerse, Allah (c.c) onu kimseye muhtaç etmez. Her kim sabretmeye çalışırsa, Allah (c.c) ona sabır verir. Hiçbir kimseye de sabırdan daha hayırlı ve daha geniş bir lütuf verilmemiştir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 15, text: "Ebu Yahya Suheyb b. Sinan (r.a)'dan, Resûlüllah (s.a.v) şöyle buyurdu: \"Mü'minin işine şaşarım; çünkü onun bütün işi, kendisi için bir hayırdır. Bu durum, sadece mü'mine mahsustur. Eğer ona sürûr verecek bir şeyle karşılaşırsa şükreder; bu kendisi için bir hayırdır. Eğer onu üzecek bir şeyle karşılaşırsa sabreder; bu da kendisi için bir hayır olur.\" (Müslim rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 16, text: "Hz. Âişe (r.a)'dan rivayet olunmuştur. Kendisi, Resûlüllah (s.a.v)'e Tâûn hastalığından- sormuş, Resûlüllah (s.a.v) de ona şu haberi vermiştir:  SABIR \"Tâûn, yüce Allah'ın dilediğinin üzerine saldığı bir azap idi; Allah (c.c) onu mü'minler için bir rahmet yaptı. Tâûn'a uğrayan bir kul sabreder ve ecrini umarak oturduğu yerde kalır, kendisine Allah'ın yazdığından başka bir şeyin dokunmayacağını bilirse, kendisine şehit sevabı gibi sevap verilir.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 17, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğunu işittim: \"Allah (c.c) şöyle buyurdu; Ben bir kulumu, iki gözünü alarak imtihan ettiğimde sabrederse, kendisine o iki gözüne karşılık cennet veririm.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 18, text: "Ebu Abdurrahman Abdullah b. Mes'ud (r.a)'ın şöyle söylediği rivayet edilmiştir: \"Allah Resulünün (s.a.v), peygamberlerden bir peygamberin (a.s) halini anlatmasını sanki hala görmekteyim. Kavmi onu dövmüş kan revan halinde bırakmıştı. O ise, yüzündeki kanı siliyor ve şöyle dua ediyordu: Allah'ım, kavmimi affet, çünkü onlar -ne yaptıklarını- bilmiyorlar!\"", source: "Hadis-i Şerif" },
    { id: 19, text: "Ebu Saîd ve Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir müslümana isabet eden yorgunluk, ağrı, gam, keder, eza ve cefa, hatta vücuduna batan bir diken gibi her ne şey varsa, Allah (c.c) bu sebeple onun hatalarının bir kısmını örter.”(Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 20, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah (c.c) kime hayır dilerse, onu musibet verir.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 21, text: "Enes (r.a)'dan rivayet edildiğine göre Resûlüllah (s.a.v) şöyle buyurmuştur: \"Sizden biriniz, kendisine isabet eden bir zarardan dolayı sakın ölümü arzulamasın. Eğer mutlaka yapacaksa şöyle desin: SABIR Allah'ım, yaşamak benim için hayırlı olduğu sürece beni yaşat ve ölüm benim için hayırlı olduğu zaman da beni öldür.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 22, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Güçlü olan -güreşte- hasmını yere seren değildir; asıl güçlü olan, öfkelendiği zaman kendine hakim olandır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 23, text: "Süleyman b. Sured (r.a)'ın şöyle söylediği rivayet edilmiştir: \"Ben, Resûlüllah (s.a.v) ile birlikte oturmaktaydım. O esnada iki kişi birbirine küfrediyordu. Onlardan birinin yüzü kıpkırmızı olmuş, şahdamarları şişmişti. Resûlüllah (s.a.v) şöyle buyurdu: Ben bir kelime biliyorum ki, eğer o adam onu söylese kendisindeki bu hiddet ondan kaybolur. Eğer; 'Eûzü billahi mineş-şeyta-nir-racım' dese, kendisindeki bu Öfke kaybolur. Bunun üzerine o adama şöyle dendi:    Peygamber (s.a.v), lanetlenmiş şeytandan Allah'a sığınmanı emrediyor.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 24, text: "Muâz b. Enes (r.a)'dan, Resûlüllah (s.a.v) şöyle buyur muştur: \"Kim uygulamaya gücü yettiği halde öfkesini yutarsa, Allah (c.c) onu kıyamet günü mahlukatın karşısına çağırır ve hurilerden istediğini almakta kendisini serbest bırakır.\" (Ebu Davud ve Tirmizi rivayet etmiş ve Tirmizi; Hadis hasendir, demiştir.)", source: "Hadis-i Şerif" },
    { id: 25, text: "Ibn-i Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Yakında benden sonra adam kayırmalar ve hoşlanmayacağınız işler olacaktır. Ashab: - Ey Allah'ın Resulü, böyle bir zamanda bize ne emreder sin? diye sordular. Resûlüllah (s.a.v); - Üzerinize düşen hakkı verir, kendi alacağınızı da Allah'dan istersiniz, buyurmuştur.\" SABIR - DOĞRULUK", source: "Hadis-i Şerif" },
    { id: 26, text: "Ebu Yahya Useyd b. Hudayr (r.a)'dan şöyle rivayet edil miştir: \"Ensar'dan bir kişi; Ey Allah'ın Resulü, falancayı âmil-zekat toplama gibi görevlerle görevlendirilenler- tayin ettiğiniz gibi beni de âmil tayin etmez misiniz? Resûlüllah (s.a.v) şöyle buyurdu: Şüphesiz ki siz, yakında benden sonra adam kayırmalarla kar şılaşacaksınız. O zaman sabrediniz ki, Kevser'in başında bana kavuşasınız.\" (Buharı ve Müslim) DOĞRULUK", source: "Hadis-i Şerif" },
    { id: 27, text: "İbn-i Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Doğruluk, iyiliğe iletir; iyilik de cennete götürür. Bir insan doğru söyleye söyleye Allah katında 'Doğru' olarak yazılır. Yalan ise kötülüğe; kötülük  de  cehenneme götürür. Bir insan yalan konuşa konuşa Allah katında 'Yalancı' olarak yazılır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 28, text: "Ebu Süfyan Sahr b. Harb (r.a.)'dan, Hirakl kıssasıyla ilgili uzun bir hadisinde şöyle rivayet yapılmıştır: \"Hirakl, Peygamber (s.a.v)'i kastederek, size neyi emrediyor?dedi. Ebu Süfyan, şöyle cevap verdiğini belirtiyor: Sadece bir olan Allah'a ibadet ediniz, O'na hiçbir şeyi ortak koşmayınız ve atalarınızın söylediklerini bırakınız diyor; bize namaz kılmayı, doğruluğu, haramlardan kaçınmayı ve yakınlarla -akrabalık- ilişkilerinin sürdürülmesini emrediyor.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 29, text: "Ebu Sabit, Ebu Said ve Ebul-Velid künyesi İle anılan, Bedir'de de bulunmuş olan Sefil b. Huneyf (r.a)'dan, Peygamber (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Kim samimiyetle Yüce Allah'dan şehit olmayı isterse, yatağında ölse bile Allah (c.c) onu şehitlerin derecesine ulaştırır.\" (Müslim)   MURAKABE MURAKABE", source: "Hadis-i Şerif" },
    { id: 30, text: "Ebu Zer Cündüb b. Cünâde ve Ebu Abdurrahman Muâb b. Cebel (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edil miştir: \"Her nerede olursan ol, Allah'tan kork! İşlediğin bir günahın ardından, onu silecek bir iyilik ekle ve insanlara güzel ahlak ile muamelede bulun.\" (Tirmizi rivayet etmiş ve hadis basendir, demiştir.)", source: "Hadis-i Şerif" },
    { id: 31, text: "Enes (r.a.)'dan şöyle rivayet edilmiştir: \"Siz, kendi nazarınızda kıldan daha ince-ufak- bir takım işler yapıyorsunuz; oysa biz, Resûlüllah (s.a.v)'ın zamanında onları helak edici -iş-lerden sayardık.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 32, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Şüphesiz ki Yüce Allah kıskanır. Allah (c.c)'in kıskanması, Allah'ın haram kıldığı şeyi kişinin yapmasıdır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 33, text: "Ebu Ya'la Şeddâd b. Evs (r.a)'dan, Resûlüllah (s.a.v)'inşöyle buyurduğu rivayet edilmiştir: \"Akıllı, kendini hesaba çeken ve ölümden sonrası için çalışandır. Âciz ise, kendisini hevasına kaptıran ve Allah'dan -olmayacak- şeyler bekleyendir.\" (Tirmizi rivayet etmiş ve hadis hasendir, demişrtir)", source: "Hadis-i Şerif" },
    { id: 34, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'ın şöyle buyur duğu rivayet edilmiştir: \"Kişinin boş şeylerle meşgul olmayı b ırakması, müslümanlığının güzelliğindendir.\" (Hadis hasendir; Tirmizi ve başkaları tarafından rivayet edilmiştir ) TAKVA  TAKVA", source: "Hadis-i Şerif" },
    { id: 35, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Ey Allah'ın Resulü, insanların en üstünü kimdir?\"denildi. Resûlüllah (s.a.v) da; \"Allah'tan en çok korkan kimsedir\" buyurdu. Dediler ki; \"Senden bunu sormuyoruz.\" Resûlüllah (s.a.v); \"Allah dostunun oğlu, Allah'ın peygamberinin evladı, Allah'ın elçisi Yusuf'tur\" buyurdu. \"Sana bundan sormadık\"dediler. Bu sefer Resûlüllah (s.a.v) şöyle buyurdu: \"O zaman bana Arapların üstünlüklerinden soruyorsunuz. Onların cahiliyye dönemindeki iyileri, dini iyi anlayıp yaşadıkları takdirde İslam döneminde de en hayırlıları olurlar.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 36, text: "Ebu Tarîf Adiy b. Hatim et-Tâî (r.a)'ın, Resûlüllah (s.a.v)' ı şöyle söylerken işittim, dediği rivayet edilmiştir: \"Kim bir şey için yemin eder de, sonra yemininin aksine bir şey yapmayı takvaya daha uygun görürse, takvayı yerine getirsin.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 37, text: "Ebu Umâme Suday b. Aclân el-Bâhilî (r.a)'ın, Resûlüllah   (s.a.v)'i Veda haccında hutbe irad ederken şöyle söylediğini işittim, dediği rivayet edilmiştir: \"Allah'dan korkunuz, beş vakit namazınızı kılınız, Ramazan ayında oruç tutunuz, mallarınızın zekatını veriniz, idarecilerinize -meşru isteklerine- itaat ediniz; Rabbinizin cennetine girersiniz.\" (Tirmisi rivayet etmiş ve hadis hasendir,sahihtir demiştir.) YAKÎN VE TEVEKKÜL", source: "Hadis-i Şerif" },
    { id: 38, text: "Ibn-i Abbâs (r.a)'dan, Resûlüllah (s.a.v)'ın şöyle buyurduğu rivayet edilmiştir: \"Ey Allah'ım, ancak sana teslim oldum, sana inandım, sana güvendim, sana yöneldim ve senin yardımınla mücadele ettim. Ey Allah'ım, beni sapıtmandan senin izzetine sığınıyorum; senden başka ilah yok. Sen, hiç ölmeyen dirisin; insanlar ve cinler ise ölürler.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 39, text: "Ebu Hureyre (r.a.)'dan, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir:  YAKÎN VE TEVEKKÜL \"Bir takım kavimler, kalpleri kuşların kalpleri gibi olduğu halde -onlar gibi Allah'a dayanıp güvendikleri için- cennete girerler.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 40, text: "Hz. Ömer (r.a)'dan, Resûlüllah (s.a.v)'ı şöyle söylerken işittim, dediği rivayet edilmiştir: \"Eğer siz, Allah'a hakkıyla dayanıp güvenseydiniz, kuşları rızıklandırdığı gibi sizi de rızıklandırırdı; sabahleyin açlıktan karınları çekilmiş bir vaziyette çıkarlar, akşama karınları dolmuş olarak dönerler.\" (Tirmizi rivayet etmiş ve Hadis hasendir, demiştir.)", source: "Hadis-i Şerif" },
    { id: 41, text: "Ebu Bekir Sıddık b. Osman b. Amir b. Amr b. Ka'b b. Sa'd b. Teym b. Mürre b. Ka'b b.Lüeyy b.Galib el-Kureşî et-Teymî-bu zat, anası ve babası sahabidirler- (a.s)'dan rivayette şöyle denmiştir: \"Biz mağarada -saklanmış- onlar başımızın üstünde dolaşırken müşriklerin ayaklarına baktım ve dedim ki: Ey Allah'ın Resulü, eğer onlardan birisi ayaklarının ucuna bakacak olsa muhakkak bizi görür!   Resûlüllah (s.a.v) buyurdu ki: Ey Ebu Bekir, üçüncüsü Allah olan iki kişiyi sen ne sanıyorsun?\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 42, text: "Müminlerin anneleri Ümmü Seleme ki, onun adı Hint b. Ebu Ümeyye Huzeyfe el-Mahzûmî (r.a)'dan şöyle rivayet edilmiştir: \"Hz. Peygamber (s.a.v) evinden çıktığı zaman şöyle derdi: Allah'ın adıyla başlar, Allah'a tevekkül ederim. Allah'ım! Sapmaktan veya saptırılmaktan, kaymaktan veya kaydırılmaktan, haksızlık yapmaktan veya haksızlığa uğramaktan, saygısızlık yapmaktan veya bana saygısızlık yapılmasından sana sığınıyorum.\" (Hadis sahihtir; Ebu Davud, Tirmizi ve diğerleri sahih senetlerle rivayet etmişlerdir. Tirmizi, hadis sahihtir demiştir. Metin Ebu Davud'undur.) 43 Enes (r.a)'dan, Resûlüllah (s.a.v)'ın şöyle buyurduğu rivayet edilmiştir: \"Kim evinden çıkarken; 'Allah'ın adıyla başlarım, Allah'a te vekkül ederim,  DOĞRU YOL ÜZERE OLMA Allah'ın izni dışında hiçbir hareket ve kuvvet yoktur’ derse, o kişiye şöyle denilir: 'Hidayete erdirildin, yeterli kılındın ve koruma altına alındın' ve şeytan o kişiden uzaklaşır.\" (Tirmisi, Ebu Davud, Neseî ve diğerleri rivayet etmiş, Tirmizi; hadis hasendir demiştir.) DOĞRU YOL ÜZERE OLMA", source: "Hadis-i Şerif" },
    { id: 43, text: "Ebu Amr - Ebu Amre Süfyan b. Abdullah'da denilir - (r.a)'dan, kendisinin şöyle dediği rivayet olunmuştur: \"Ey Allah'ın Resulü, bana İslam hakkında öyle bir söz söyle ki, senden başka hiçbir kimseye bu hususta bir şey sormayayım. Resûlüllah (s.a.v) şöyle buyurdu: Allah'a iman ettim, de. Sonra da dosdoğru ol.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 44, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Hareketlerinizde orta yollu ve dosdoğru olunuz. Şunu bilinki; sizden hiç   biriniz yaptıklarıyla kurtuluşa ulaşamaz. Sahabiler dediler ki: Ey Allah'ın Resulü, sen de mi? Resûlüllah (s.a.v) şöyle buyurdu: Ben bile! Ancak Allah (c.c), rahmeti ve lütfü ile beni koruya.\" (Müslim) HAYRA KOŞMAK", source: "Hadis-i Şerif" },
    { id: 45, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hayırlı işler yapmakta acele ediniz! Yakında karanlık gece parçaları gibi fitneler ortaya çıkacaktır. Kişi mü'min olarak sabahlayıp, kafir olarak geceler; mü'min olarak geceler, kâfir olarak sabahlar. Bir parça dünya malı için dinini satar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 46, text: "Câbir (r.a)'ın şöyle dediği rivayet edilir: \"Bir adam, Uhud -savaşı- günü Peygamber (s.a.v)'e gelip dedi ki: 'Eğer Allah yolunda öldürülürsem nerede olurum?' Resûlüllah (s,a.v) şöyle buyurdu: Cennette!  HAYRA KOŞMAK Bunun üzerine adam elindeki hurmaları attı, öldürülünceye kadar savaştı” (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 47, text: "Enes (r.a)'dan söyle rivayet edilmiştir: \"Resûlüllah (s.a.v), Uhud -savaşı- günü eline bir kılıç alıp şöyle buyurdu: 'Bunu benden kim alacak?' Orada bulunanlardan hepsi; ben, ben diyordu. Peygamber (s.a.v): 'Onu, hakkını vererek kim alabilir?’ buyurdu. Halk birden durakladı. Ebu Dücâne (r.a) dedi ki: 'Onu, hakkını vermek üzere ben alacağım.' Hemen kılıcı aldı ve onunla müşriklerin başlarını ikiye ayırdı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 48, text: "Zübeyr b. Adiyy (r.a)'dan şöyle söylediği rivayet edilmektedir: \"Enes b. Mâlik (r.a)'ın yanına gittik. Haccâc'tan karşılaştığımız hususları kendisine şikayet ettik. Enes (r.a) dedi ki: Rabbinize kavuşuncaya kadar sabredin. Çünkü sondan gelen zaman, bir öncekinden daha şerli olacaktır. Bunu, Peygamberinizden (s.a.v) işittim.\" (Buhari)   MÜCADELE", source: "Hadis-i Şerif" },
    { id: 49, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yüce Allah buyuruyor ki: Kim benim dostlarımdan birine düşmanlık yaparsa, şüphesiz ona savaş açarım. Kulum, kendisine farz kıldığım ibadetlerden daha sevimli hiçbir şeyle bana yaklaşamaz. Kulum, nafile ibadetlerle bana yaklaşmaya devam ettiği sürece sonunda ben onu severim. Onu sevdiğim zaman da işiten kulağı, gören gözü, tutan eli ve yürüyen ayağı olurum. Benden bir şey isterse veririm. Bana sığınırsa, mutlaka onu korurum.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 50, text: "İbn-i Âbbâs (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İki nimet vardır ki, insanların çoğu o hususlarda aldanmışlardır. Onlar sıhhat ve boş vakittir.\" (Buhari)  MÜCADELE", source: "Hadis-i Şerif" },
    { id: 51, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir: \"Peygamber (s.a.v), ayakları yarılacak hale gelesiye kadar -namaz için- gece ayakta kalırdı. Ona dedim ki: 'Ey Allah'ın elçisi, Allah (c.c) sizin geçmiş ve gelecek günahlarınızı bağışladığı halde niçin böyle yapıyorsunuz?' O da şöyle buyurdu: Şükreden bir kul olmayı istemeyeyim mi?\" (Buhari ve Müslim. Bu, Buhari'nin lafzıdır. Sahihayn'daki Muğire b. Şu'be'nin rivayeti de aynı şekildedir.)", source: "Hadis-i Şerif" },
    { id: 52, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir: \"Ramazan ayının son on günü girince, Resûlü'llah (s.a.v) geceleri uyanık geçirir, ev halkını uyandırır, ibadete ağırlık verir ve hanımlarından uzaklaşırdı.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 53, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Kuvvetli mü'min, Allah'a göre zayıf mü'minden daha hayırlı ve daha sevimlidir. Hepsinde de bir hayır vardır. Sana yarar sağlayacak şeylere düşkün ol. Allah'tan yardım iste ve acizliğe düşme. Eğer sana bir şey isabet ederse; 'Eğer şöyle yapsaydım böyle olurdu' deme. Ama şöyle söyle; 'Allah takdir etti ve dilediğini yaptı.’ Çünkü 'Şöyle yapsaydım...' sözü şeytanın -hilesine- kapı açar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 54, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v) şöyle buyurmuştur: \"Cehennem -ateşi- şehvetlerle, cennet de nefsin hoşlanmadığı şeylerle çevrilmiştir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 55, text: "Ibn-i Mes'ud (r.a)' ın şöyle söylediği rivayet edilmiştir: \"Bir gece Resûlüllah (s.a.v) ile birlikte namaz kıldım. Ayakta o kadar kaldı ki, nerdeyse uygunsuz bir iş yapmayı dahi düşündüm. Denildi ki: 'Ne düşünmüş idin?' O da; Oturmayı ve Resûlüllah (s.a.v)'i -ayakta- bırakmayı düşünmüştüm.\" (Buharı ve Müslim)  MÜCADELE", source: "Hadis-i Şerif" },
    { id: 56, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayetedilmiştir: \"Üç şey ölünün -mezara- kadar peşinden gider; ev halkı, malı ve ameli. İkisi geri döner, biri kalır. Ev halkı ve malı geri döner, ameli ile baş başa kalır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 57, text: "Resûlüllah (s.a.v)'in hizmetinde bulunan ve Suffe ehlinden olan Ebu Firâs Rabîa b. Ka'b el-Eslemî (r.a)'in şöyle söylediği rivayet edilmiştir: \"Resûlüllah (s.a.v) ile birlikte geceler, ona abdest suyunu getirirdim. Bir keresinde buyurdu ki: 'Benden bir şey iste.' Ben de dedim ki: 'Cennette senin yanında olmayı isterim.' Buyurdu ki: 'Bundan başka bir şey var mı?' Dedim ki: 'İstediğim sadece budur.' O da şöyle buyurdu: O halde çok secde yaparak nefsin hususunda bana yardımcı ol.\" (Müslim)   ÖMRÜN SONUNDA HAYRI ARTIRMAK", source: "Hadis-i Şerif" },
    { id: 58, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'İn şöyle buyur duğu rivayet edilmiştir: \"Allah (c.c), altmış yaşına ulaşıncaya kadar ecelini geciktirdiği kişiye, iler sürebileceği hiçbir mazeret bırakmamıştır.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 59, text: "Enes (r.a)'ın şöyle söylediği rivayet edilmiştir: \"Allah (c.c), Resûlüllah (s.a.v)'e vefatından önce çok sık olarak vahiy göndermiştir. Hatta vahyin en yoğun olarak indirildiği bir zamanda Resûlüllah (s.a.v) vefat etmiştir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 60, text: "Câbir (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Her kul, öldüğü hal üzere diriltilir.\" (Müslim)  HAYİR YOLLARININ ÇOKLUĞU HAYIR YOLLARININ ÇOKLUĞU", source: "Hadis-i Şerif" },
    { id: 61, text: "Ebu Zer Cündüb h. Cünâde (r.a)'ın şöyle söylediği rivayet edilmiştir: \"Dedim ki: 'Ey Allah'ın elçisi, amellerin hangisi daha üstündür?' Şöyle buyurdu: 'Allah'a iman ve Allah yolunda cihat etmektir.' Dedim ki: 'Hangi köleyi âzâd etmek daha faziletlidir?' Şöyle buyurdu: 'Sahibi yanında en kıymetlisi ve en pahalı olanını.' Dedim ki: 'Eğer bunları yapamazsam?' Şöyle buyurdu: 'Becerikli birine yardım edersin, elinden bir şey gelmeyenin de işini yaparsın.' Dedim ki: 'Ey Allah'ın elçisi, bazı işleri yapmaktan aciz düşersem?' Resûlüllah (s.a.v) şöyle buyurdu: İnsanlara zarar vermekten kendini alıkoyarsın; bu, senin kendine karşı verdiğin- bir sadakadır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 62, text: "Ebu Zer (r.a)'dan, Resûlüllah (s.a.v)'ın şöyle buyurduğu rivayet edilmiştir:   \"İyisiyle kötüsüyle ümmetimin amelleri bana sunuldu. İyi ameller arasında; geçenlere zarar verebilecek bir şeyin yoldan kaldırılmasını buldum. Kötü ameller arasında da; mescide atılmış, ama üstü örtülmemiş tükürüğü gördüm.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 63, text: "Ebu Zer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kardeşini güler yüzle karşılamak dahi olsa , hiçbir iyiliği hor görme.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 64, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilir: \"Kim. sabah veya akşam mescide gidip gelirse, her gidişinde veya dönüşünde Allah ona cennette bir ziyafet hazırlar.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 65, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilir:  HAYİR YOLLARININ ÇOKLUĞU \"Ey Müslüman kadınlar, hiçbir komşu kadını, velev ki koyun paçası bile olsa, komşusunun verdiği bir şeyi hakir görmesin.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 66, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyur duğu rivayet edilir: \"İman yetmiş küsur veya altmış küsur şubedir. En üstünü; 'Lâ ilahe illallah' sözüdür. En aşağısı da; eza verebilecek şeyi yoldan kaldırmaktır. Haya da, imandan bir şubedir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 67, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'ın şöyle buyurduğu rivayet edilmektedir: \"Allah'ın hataları yok ettiği ve dereceleri yükselttiği şeyi sizlere göstereyim mi? Dediler ki: 'Evet Ey Allah'ın Resulü.' Şöyle buyurdu: Zorluklara rağmen güzelce abdest almak, mescidlere -gitmek İçin- adımları çoğaltmak, bir namazdan sonra diğer namazı beklemek; dikkat edin, bunlar -düşmana karşı- nöbettir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 68, text: "Ebu Musa el-Eş'arî (r.a)'dan, Resûlüllah (s.a.v)'ın söyle buyurduğu rivayet edilmiştir: \"Kim iki soğuk-vaktin, sabah ve ikindi- namazını kılarsa cennete girer.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 69, text: "Câbir (r.a)'dan, Resûlüllah (s.a.v)'ın söyle buyurduğu rivayet edilmiştir: \"Her iyilik sadakadır.\" (Buhari rivayet etmiştir. Müslim, Ebu Huzeyfe yoluyla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 70, text: "Ebu Münzir Übey b. Ka'b (r.a)'ın şöyle dediği rivayet edilmiştir: \"Bir adam vardı; evi mescide ondan daha uzak düşen bir kimseyi bilmiyorum. Hiçbir namaz -cemaate devam hususunda- onu yanıltmadı. Ona denildi ki -veya ben dedim ki: 'Keşke, karanlık gecelerde veya sıcak günlerde binecek bir merkep satın alsaydın!' O dedi ki: 'Evimin mescidin yanında olması beni sevindirmez. Çünkü ben, mescide giderken ve aileme dönerken attığım adımların yazılmasını istiyorum.  HAYIR YOLLARININ ÇOKLUĞU 'Resûlüllah (s.a.v) şöyle buyurdu; Muhakkak Allah, bunların hepsini senin için bir araya topladı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 71, text: "Ebu Musa (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Her müslümanın sadaka vermesi icap eder. Ashaptan biri: 'Eğer bulamazsa ne dersiniz?' dedi. Şöyle buyurdu: 'Eliyle çalışır, hem kendisine faydası olur, hem de sadaka verir.' Sahabi dedi ki: 'Eğer buna güç yettiremezse ne dersiniz?' Şöyle buyurdu: 'Güç durumda kalmış bir ihtiyaç sahibine yardım eder.' Sahabi; 'Buna da güç yettiremezse ne buyurursunuz?'dedi. Şöyle buyurdu: 'İyiliği veya hayrı emreder.' Sahabi; 'Bunu da yapamazsa ne buyurursunuz?' Resûlüllah (s.a.v) bu sefer şöyle buyurdu: Kendini kötülükten alıkoyar; çünkü bu da bir sadakadır.\" (Buhari ve Müslim) İBADETTE MUTEDİL OLMAK", source: "Hadis-i Şerif" },
    { id: 72, text: "Hz. Âişe (r.a)'dan söyle rivayet edilmiştir:   \"Kendisinin yanında bir kadın varken, Resûlüllah (s.a.v) Hz. Âişe (r.a)' ın yanına girdi ve dedi ki: 'Bu kadın da kim?' Hz. Âişe (r.a); 'Falan kadındır; kıldığı namazlarından bahsediyor' dedi. Resûlüllah (s.a.v) şöyle buyurdu: 'Bırak! Gücünüzün yettiği kadarı sizin üzerinize borçtur. Allah'a yemin olsun ki, siz -ibadetten- usan-madıkça Allah -sevap yazmaktan- usanmaz.\" Resûlüllah (s.a.v)' ın en hoşuna giden ibadet, sahibinin devamlı yaptığı ibadettir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 73, text: "İbn-i Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Dini hususlarda -gereksiz yere şiddet -aşırılık- gösterenler helak oldu.\" Resûlüllah (s.a.v) bu sözü üç defa tekrarladı. (Müslim)", source: "Hadis-i Şerif" },
    { id: 74, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Din kolaylıktır. Dini hususlarda aşırılığa kaçanlara, din hep galip gelmiştir. O halde orta yollu olunuz, elinizden gelen en İyiyi yapınız, müjdeleyiniz, sabah -akşam ve biraz da gecenin bir bölümünde Allah'dan yardım dileyiniz.\" (Buhari) Buhari'den diğer bir rivayette de şöyle buyrulur:  İBADETTE MUTEDİL OLMAK \"Ortalama gidiniz, güzele en yakın olanı yapınız. Sabah, öğle ile akşam arası ve biraz da gecenin bir bölümünden yararlanınız. Orta, orta yollu olunuz ki maksada eresiniz.\"", source: "Hadis-i Şerif" },
    { id: 75, text: "Hz. Âişe (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz namaz kılarken uyuklarsa, hemen uykusu geçinceye kadar yatıp uyusun. Çünkü biriniz uykulu iken namaz kılarsa, farkında olmaz, belki de kendisi için istiğfar edeyim derken bedduada bulunuyor.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 76, text: "Ebu Abdullah Câbir b. Semure (r.a)'in şöyle dediği rivayet edilmiştir: \"Ben, Resûlüllah (s.a.v) ile birlikte namaz kılardım; O'nun namazı da orta yollu, hutbesi de orta yollu olurdu.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 77, text: "İbn-i Abbas (r.a)'ın şöyle dediği rivayet edilmiştir:   \"Resûlüllah (s.a.v) bir ara hutbe verirken, ayakta duran bir adam gördü ve onun kim olduğunu sordu. Dediler ki; 'Ebu İsrail'dir, güneşte oturmayıp ayakta durmaya, gölgelenmemeye, konuşmamaya ve oruç tutmaya söz verdi.' Resûlüllah (s.a.v) şöyle buyurdu: Ona emredin; konuşsun, gölgelensin, otursun ve orucunu tamamlasın.\" (Buharı) AMELLERE DEVAM ETMEK", source: "Hadis-i Şerif" },
    { id: 78, text: "Ömer b. Hattâb (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim, gece virdini veya ondan bir şeyi okumadan uyuyakalır da onu sabah namazı ile öğle namazı arasında okursa, sanki onu geceden okumuş gibi kendisine yazılır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 79, text: "Abdullah b. Amr b. As (r.a)'ın şöyle söylediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bana dedi ki: Ey Abdullah, sakın gece -ibadet için- kalkarken, gece kalkmayı bırakan falanca gibi olma!\" (Buharı ve Müslim) SÜNNET VE SÜNNET ÂDÂBINA RİÂYET", source: "Hadis-i Şerif" },
    { id: 80, text: "Hz. Aişe (r.a)'m şöyle söylediği rivayet edilmiştir: \"Resûlüllah (s.a.v), ağrı veya başka nedenlerden dolayı gece namazını kılmayı kaçırdığında, gündüzün on iki rekat namaz kılardı.\" (Müslim) SÜNNET VE SÜNNET ÂDÂBINA RİÂYET", source: "Hadis-i Şerif" },
    { id: 81, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ben sizi -kendi halinize- terk ettiğim sürece, beni de kendi -halime- bırakınız. Zira sizden Öncekileri, çok soru sormaları ve peygamberleriyle münakaşa etmeleri helak etmiştir. Sizi bir şeyden men edersem, ondan sakınınız ve size bir emir verirsem, gücünüz yettiği kadar onu yapınız.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 82, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ümmetimin hepsi cennete girecek; ancak yüz çevirenler hariç. Denildi ki: 'Ey Allah'ın Resulü, yüz çevirenler de kimdir?' Buyurdu ki: Kim bana itaat ederse cennete girer, kim de bana isyan ederse yüz çevirmiş olur.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 83, text: "Ebu Müslim -Ebbu îyâs da denilir- Seleme b. Amr b. Ekva' (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam, Resûlüllah (s.a.v)'in yanında sol eliyle yedi. Resûlüllah (s.a.v) buyurdu ki: Sağ elinle ye! Dedi ki: Yiyemiyorum. Resûlüîlah (s.a.v) buyurdu ki: Yiyemez olasın! O adamı bunu yapmaktan alıkoyan şey, kibir idi. Artık bir daha elini -ağzına- kaldıramaz oldu!\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 84, text: "Ebu Abdullah Nu'man b. Beşir (r.a)'ın şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'ı şöyle söylerken işittim: Ya saflarınızı düzeltirsiniz, ya da Allah yüzlerinizi farklı yönlere çevirir.\" (Buhari ve Müslim)  SÜNNET VE SÜNNET ÂDABINA RİÂYET Müslim'in diğer bir rivayetinde İse şöyle buyrulmuştur; \"Resûlüllah (s.a.v), sanki okları düzeltir gibi saflarımızı düzeltirdi; ta ki bizim anladığımıza kanaat getirinceye kadar. Bir gün namaza çıkmıştı. Tam tekbir alıp duracağı sırada, göğsü dışarıda kalan bir kişi gördü ve buyurdu ki: Ey Allah'ın kullarrı, ya saflarınızı düzeltirsiniz, ya da Allah yüzlerinizi farklı yönlere çevirir.\"", source: "Hadis-i Şerif" },
    { id: 85, text: "Ebu Musa (r.a)'dan şöyle rivayet edilmiştir: \"Medine'de bir ev, içindeki halkıyla birlikte geceleyin yanmıştı. Onların durumları Resûlüllah (s.a.v)'e anlatıldığında buyurdu ki: Bu ateş sizin düşmanınızdır; uyuyacağınız zaman onu söndürünüz.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 86, text: "Abis b. Rebîa (r.a)'ın söyle şöylediği rivayet edilmiştir: \"Ömer b. Hattâb (r.a)'ı Hacer'ül Esved taşını öperken gördüm. Şöyle diyordu: Muhakkak ben, senin bir taş olduğunu, fayda ve zarar veremeyeceğini biliyorum. Eğer ben Resûlüllah (s.a.v)'ı seni öperken görmeseydim, seni öpmezdim.\" (Buharı ve Müslim)   ALLAH'IN HÜKMÜNE BOYUN EĞMEK", source: "Hadis-i Şerif" },
    { id: 87, text: "Ebu Hureyre (r.a)'ın şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'e; 'Göklerde ve yerde ne varsa Allah'ındır. Siz, içinizden geçeni açıklasanız da, saklasanız da Allah onunla sizi hesaba çeker. Sonra dilediğini bağışlar, dilediğine de azap eder. Allah, her şeye kadirdir.' (Bakara; 284) ayeti indirilince, bu ayet Resûlüllah (s.a.v)'in ashabına ağır geldi. Resûlüllah (s.a.v)'a gelerek, diz çöküp dediler ki: Ey Allah'ın Resulü, namaz, cihat, oruç ve sadaka gibi gücümüzün yettiği amellerle sorumlu tutulmuştuk. Oysa şimdi sana bu ayet indi; ona güç yettiremeyeceğiz! Resûlüllah (s.a.v) buyurdu ki: Sizden önceki iki kitap ehlinin de dediği gibi; 'işittik ve isyan ettik' mi demek istiyorsunuz?  ALLAH'IN HÜKMÜNE BOYUN EĞMEK Bilakis şöyle söyleyin: 'İşittik ve itaat ettik. Ey Rabbimiz, affını talep ediyoruz, varışımız sanadır.' Ashap, bu ayeti okuyup dilleri ona yatınca, peşinden şu ayeti indirdi: 'O peygamber de kendisine Rabbinden indirilene iman etti, mü'minler de. Her biri Allah'a, meleklerine, kitaplarına ve peygam berlerine iman etti. O'nun peygamberlerinden hiç birini, diğerinden ayırmayız, işittik ve itaat ettik; Ey Rabbimiz, affını talep ediyoruz, varışımız ancak sanadır dediler.' Ne zaman ki böyle yaptılar, Allah (c.c)'da -kendilerine ağır gelen- o ayeti neshetti ve şu ayeti indirdi: 'Allah, hiçbir kimseye gücünün dışında bir şey yüklemez. Herkesin kazandığı -iyilik- kendine, işlediği -kötülük de- aleyhinedir. Ey Rabbimiz, unuttuysak veya yanılmışsak bundan dolayı bizi sorguya çekme!' Allah (c.c); 'tamam' buyurdu. 'Ey Rabbimiz, bizden öncekilere yüklediğin gibi bizim üzerimize taşıyamayacağımız-yük yükleme!' Allah (c.c); 'tamam' buyurdu. 'Ey Rabbimiz, güç yettiremeyeceğimiz şeyi bize taşıtma!' Allah (c.c); 'tamam' buyurdu. 'Bizden çıkan günahları sil, bizi bağışla, bizi yarlığa, bizi acı; sen bizim sahibimizsin. Artık kafirler topluluğuna karşı bize yardım et.' Allah (c.c); 'tamam-is teklerinizi yerine getirdim' buyurdu.\" (Müslim) BİD'AT VE SONRADAN UYDURULMUŞ İŞLERDEN MEN", source: "Hadis-i Şerif" },
    { id: 88, text: "Hz. Âişe (r.a) 'dan, Resûlüllah (s.a,v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bizim bu -din- işlerimizde, ondan olmayan bir şey uydurursa o şey reddedilmiştir.\" (Buharİ ve Müslim)", source: "Hadis-i Şerif" },
    { id: 89, text: "Câbir (r.a)'ın şöyle söylediği rivayet edilmiştir: \"Resûlüllah (s.a.v), hutbe verdiği bir sırada gözleri kızardı, sesi yükseldi, öfkesi şiddetlendi! Sanki O, askere; düşman, akşama sabaha size saldırmak üzere' diye uyaran bir -kumandan- gibiydi. Şehadet ve orta parmağını birbirine yaklaştırıp; 'Ben gönderildiğimde, benimle kıyamet arasındaki mesafe şu iki parmak -mesafesi- gibiydi!' Sonra şöyle devam etti: Hamd ve senadan sonra, sözün en hayırlısı Allah'ın kitabıdır. Yolun en hayırlısı ise, Muhammed (a.s)'ın yoludur. İşlerin en şerlisi, sonradan uydurulmuş olanlarıdır. Her bid'at sapıklıktır. Sonra şöyle buyurdu: Ben, her mü'mine kendisinden daha evlayım. Kim bir mal bırakırsa, kendi ehline aittir. Kim bir borç bırakırsa benim üzerimedir; veya yetim bırakırsa bana aittir.\" (Müslim)  İYİ VEYA KÖTÜ ÇIĞIR AÇANLAR İYİ VEYA KÖTÜ ÇIĞIR AÇANLAR", source: "Hadis-i Şerif" },
    { id: 90, text: "Ebu Amr Cerîr b. Abdullah (r.a)'dan şöyle rivayet edilmiştir: \"Gündüzün ilk vaktinde Resûlüllah (s.a.v)'in yanında bulunuyorduk. Nemire veya Aba —denilen- kumaşı delip başına geçirmiş, kılıç kuşanmış, çoğunluğu hatta tümü Mudar kabilesinden yarı çıplak bir grup Resûlüllah (s.a.v)'e geldi. Onlarda gördüğü bu yoksulluktan dolayı Resûlüllah (s.a.v)'in yüzünün rengi değişti! Hemen evine girdi, sonra çıktı. Bilâl'a emrederek ezan okutup kamet getirtti ve namaz kıldırdı. Sonra da -aşağıdaki ayetleri okuyup- bir hutbe verdi: Ey insanlar, sizi bir tek candan yaratan, ondan da yine onun eşini var eden ve ikisinden bir çok erkekler ve kadınlar çoğaltan Rabbinizden sakının. Kendisinin adını ileri sürerek birbirinizden bir Şeyler istediğiniz Allah'dan ve akrabalık bağlarını koparmaktan kaçının. Çünkü Allah, sizin üzerinizde tam bir gözeticidir. (Nisa: 1) Bir de Haşr sûresinin sonlarındaki -şu- ayeti okudu: 'Ey iman edenler, Allah'dan korkun; herkes yarın için önden ne gönderdiğine baksın. Allah'dan korkun; çünkü Allah, yaptıklarınızın hepsinden haberdardır.' Herkes altınından, gümüşünden, elbisesinden, bir ölçek buğdayından, bir ölçek hurmasından sadaka versin. Hatta buyurdu ki; yarım ölçek bile olsa -sadaka versin. Ensar'dan bir adam -büyük -bir torba getirdi; eliyle taşımakta zorlanıyordu, hatta taşıyamadı bile.   Daha sonra insanlar -sadaka vermede- birbirlerini izlediler. Hatta yiyecek ve giyecekten iki yığın biriktiğini, böylelikle Resûlüllah (s.a.v)'in yüzünün güldüğünü gördüm. Sanki yüzü, altın suyu ile kaplanmış gibi parıldıyordu. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Kim İslam'da iyi bir çığır açarsa, açtığı çığırın mükafatı ve kendinden sonra onunla amel edenlerin sevabı, onların sevabından hiçbir şey eksilmeksizin, o çığın açana verilecektir. Kim de İslam'da kötü bir çığır açarsa, açtığı bu çığırın günahı ve kendisinden sonra onunla amel edenlerin günahı, onların günahından hiçbir şey eksilmeksizin, o çığırı açana verilecektir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 91, text: "İbn-i Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Haksız yere öldürülen hiçbir kimse yoktur ki, Adem'in ilk evladının-Kâbil- üzerine akan o kandan bir günah yüklenmiş olmasın! Çünkü o, öldürme çığırını başlatan ilk kişi idi.\" (Buhari ve Müslim) HAYRA ÖNCÜLÜK, HİDAYETE VEYA SAPIKLIĞA ÇAĞRI  HAYRA ÖNCÜLÜK, HİDAYETE VEYA SAPIKLIĞA ÇAĞRI", source: "Hadis-i Şerif" },
    { id: 92, text: "Ebu Mes'ud Ukbe b. Amr el-Ensarî el-bedrî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim hayra Öncülük ederse, onu yapanın mükafatı kadar kendisine de mükafat vardır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 93, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bir hayra çağrı yaparsa, o kişiye, kendisine uyanların sevapları kadar sevap verilir. Bu, onların sevabından hiçbir şey eksiltmez. Kim de sapıklığa çağırırsa, o kişiye, kendisine uyanların günahları kadar günah vardır. Bu, onların günahından hiçbir şey eksiltmez.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 94, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Eslem kabilesinden bir genç; 'Ey Allah'ın Resulü, ben harbe katılmak istiyorum, ama yanımda hazırlık yapacağım bir şeyim yok' dedi. Resûlüllah (s.a.v); 'Falancaya git, çünkü o -savaşa- hazırlık yapmış,   ama hastalanmış idi' buyurdu. Genç, o adamın yanına gitti ve dedi ki: 'Allah Resulü (s.a.v), sana selam yolladı ve teçchizatını bana vermeni söyledi.' O şahıs şöyle dedi: Ey falanca -kadın, techizatımı bu gence ver; ve içinden hiçbir şey alıkoyma. Allah'a yemin olsun, ondan hiçbir şeyi alıkoyma ki ondan dolayı berekete nail olasın!\" İYİLİK VE TAKVADA YARDIMLAŞMA", source: "Hadis-i Şerif" },
    { id: 95, text: "Ebu Abdurrahman Zeyd b. Halid el-Cühenî (r.a)'dan, Re-sûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim, Allah yolunda cihat eden bir gaziyi savaşa hazırlarsa, muhakkak gaza etmiş gibi -sevap işlemiş- olur. Kim, cihada çıkan gazinin ailesine yardım ederse, muhakkak gaza etmiş gibi-sevap işlemiş- olur.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 96, text: "Ebu Saîd el-Hudri (r.a.)'dan söyle rivayet edilmiştir: \"Resûlüllah (s.a.v), Huzeyl kabilesinden Lihyanoğullarına bir birlik  İYİLİK VE TAKVADA YARDIMLAŞMA -NASİHAT göndereceği sırada şöyle buyurmuştur: Aynı ailedeki- iki kişiden biri gitsin; sevap ikisi arasında ortaktır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 97, text: "Ebû Musa el- Eş'arî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:: \"Müslüman bir veznedar, emredileni gönül hoşnutluğu ile ve tastamam olarak yerine getirip, emredilen kişiye verirse, sadaka verenlerden biri gibi sevaba nail- olur.\" (Buharı ve Müslim) NASİHAT", source: "Hadis-i Şerif" },
    { id: 98, text: "Ebu Rukeyye Temim b. Evs ed-Dârî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Din nasihattir.\" Biz; kime? diye sorduk. Resûlüllah (s.a.v) buyurdu ki: \"Allah'a, O'nun kitabına, O'nun elçisine, müslümanlann ileri gelenlerine ve bütün müslümanlara!\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 99, text: "Cerîr b, Abdullah (r.a) şöyle rivayet etmiştir: \"Ben, Resûlüllah (s.a.v)'e namazı dosdoğru kılmak, zekatı vermek ve her müslümana hayırlı tavsiyelerde bulunmak üzere biat ettim.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 100, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz, kendisi için sevdiğini kardeşi için de sevmedikçe hakkıyla- iman etmiş olamaz.\" (Buharı ve Müslim) İYİLİĞİ EMRETMEK, KÖTÜLÜKTEN MENETMEK", source: "Hadis-i Şerif" },
    { id: 101, text: "Ebu Saîd el-Hudrî (r.a)'dan şöyle rivayet edilmiştir:  İYİLİĞİ EMRETMEK, KÖTÜLÜKTEN MEN ETMEK \"Resûlüllah (s.a.v)'i şöyle söylerken işittim: Sizden kim bir kötülük görürse, hemen onu eliyle değiştirsin. Eğer güç yettiremezse diliyle -değiştirsin. Eğer buna da güç yettiremezse kalbiyle- reddetsin; bu ise imanın en zayıf derecesidir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 102, text: "Ebu Velid Ubâde b. Sâmit (r.a)'dan söyle rivayet edilmiştir: \"Biz, Resûlüllah (s.a.v)'e zorlukta ve kolaylıkta, hoşa giden ve hoşa gitmeyen hususta sözünü dinleyip itaat etmek, bazı vazifelerde- kendimizi tercih etmek-ileri sürmek, Allah (c.c)'dan yanınızda bulunan delile göre açıkça bir küfür görmedikçe idarecilerle çekişmemek ve nerede olursak olalım Allah yolunda hiçbir kınayıcının kınamasından korkmadan hakkı söylemek üzere biatlaştık.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 103, text: "Mü'minlerin annesi Ümmü Seleme Hind b. Ebu Umeyye Huzeyfe (r.a), Resûlüllah (s.a.v)'ın şöyle buyurduğu rivayet edil miştir: \"Sizin üzerinize bir takım idareciler tayin edilir. Onların yaptıklarının bir kısmını beğenir, bir kısmını da beğenmezsiniz, Kim -onların dine ters işlerini- beğenmezse, günahtan- kurtulur. Ama   kim rıza gösterir ve kendilerine uyarsa -sorumluluktan kurtulamaz. Dediler ki: 'Ey Allah'ın Resulü, onlarla savaşmayalım mı?' Buyurdu ki; Sizinle namaz kıldıkları sürece hayır!\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 104, text: "Ebu Saîd Hudrî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizi, yollar üzerinde oturmaktan sakındırırım. Ashap; 'Ey Allah'ın Resulü, yolda oturmayı bırakmamız imkansızdır; çünkü -iş icabı- orada konuşuyoruz' dediler. O zaman Resûlüllah (s.a.v) şöyle buyurdu: 'Oturmaktan başka çareniz yoksa, o takdirde yolun hakkını veriniz.' Dediler ki: 'Ey Allah'ın Resulü, yolun hakkı nedir?' Resûlüllah şöyle buyurdu: Gözü -haramdan- yummak, gelip geçene-eziyet vermemek, selâmı almak, iyiliği emretmek, kötülükten de nehyetmektir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 105, text: "İbn-i Abbas (r.a)'dan söyle rivayet edilmiştir: \"Resûlüllah (s.a.v) bir adamın elinde altın yüzük gördü, hemen  İYİLİĞİ EMRETMEK, KÖTÜLÜKTEN MEN ETMEK onu çıkarıp attı ve şöyle buyurdu: 'Sizden biri ateşten bir kor parçasını tutup parmağına geçirmeye kalkışıyor!' Resûlüllah (s.a.v) gittikten sonra o adama denildi ki: 'Yüzüğünü al ve onunla-helal-yolla faydalan,' Adam şöyle dedi: Hayır! Allah'a yemin olsun ki, Resûlüllah (s.a.v) onu attıktan sonra ben onu ebediyen almam.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 106, text: "Huzeyfe (r.a)'dan, Resûlüllah (s.a.v)'İn şöyle buyurduğu rivayet edilmiştir: \"Nefsim-kudret-elinde olan Allah'a yemin olsun ki, ya iyiliği emreder kötülüklerden sakındırırsınız, ya da yakında Allah üzerinize bir bela gönderir; sonra O'na dua edersiniz, ama duanız kabul olunmaz.\" (Tirmizi rivayet etmiş ve Hadis Hasen'dir demiştir.)", source: "Hadis-i Şerif" },
    { id: 107, text: "Ebu Bekir Sıddık (r.a)'ın şöyle buyurduğu rivayet edilmiştir: \"Ey insanlar, siz şu ayeti okuyorsunuz: 'Ey iman edenler, siz kendi nefislerinizi düzeltmeye çalışınız. Siz doğru yolu bulduktan sonra, sapanlar size bir veremez. ' (Maide: 105) Halbuki ben, Resûlüllah (s.a.v)'i şöyle buyururken işittim:   İnsanlar zalimi gördüğü zaman onun ellerini-zulmetmekten-çekmezlerse, Allah'ın katından gönderilecek bir azabın onların hepsini içine alması yakındır.\" (Ebu Davud, Tirmizi ve Neseî sahih isnatlarla rivayet etmişlerdir.)", source: "Hadis-i Şerif" },
    { id: 108, text: "Ebu Zeyd Üsâme b. Zeyd b. Harise (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim: Kıyamet günü adamın biri getirilip cehenneme atılır. Karnındaki bağırsakları dışarı dökülür. Bu hal üzere, merkebin değirmen taşında döndüğü gibi döner durur. Cehennem ehli başına toplanır ve derler ki: 'Ey falan, nedir bu halin! Sen iyiliği emredip kötülükten nehyetmez miydin?' O da der ki: 'Evet, ben iyiliği emreder ama kendim yapmazdım, kötülükten nehyeder ama onu kendim yapardım,\" (Buhari ve Müslim) EMANETE RİAYET", source: "Hadis-i Şerif" },
    { id: 109, text: "Ebu Hureyre (r.a) dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  EMANETE RİAYET \"Münafığın alameti üçtür; konuştuğunda yalan konuşur, söz verdiğinde yerine getirmez, kendisine verilen- emanete hıyanetlik eder.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 110, text: "Huzeyfe b. Yemani (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v), bize iki haber getirdi; ben bunlardan birini gördüm, diğerini de beklemekteyim. Bize -şunu- anlattı: Emanet, kişilerin kalplerinin derinliğinde yer etmiştir. Sonra Kur'an indi ve Kur'an'ı öğrendiler, sünneti tanıdılar. Resûlüllah (s.a.v)- bize emanetin kalkmasından haber verdi ve buyurdu ki: 'Kişi uykusuna dalar, kalbinden emanet alınır, ama onun eseri silik bir iz gibi kalakalır. Sonra -yine- uykuya dalar, kalbinden emanet alınır, ama onun eseri kabarcıklar gibi olur. Ayağının üzerine döktüğün közden derin kabarır; sen onu çok kabarık görürsün, ama içinde hiçbir şey yoktur.' Sonra Resûlüllah (s.a.v) eline bir çakıl taşı alıp onları ayaklarının üzerinde yuvarladı- ve şöyle buyurdu: 'İnsanlar alışveriş ya parlar, ama nerdeyse emanete riayet eden hiçbir kimse bulunmaz. Hatta denilir ki;   \"Falan oğulları arasında güvenilir bir kişi var.\" Hatta bir kişi için; \"Ne cesur adam, ne kibar biri, ne akıllı insan! \" denilecek, ama o kişinin kalbinde hardal tanesi kadar imandan eser bulunmayacak.' Başımdan öyle zaman geçti ki, hanginizle alış veriş yaptığıma aldırış etmedim. Eğer müslüman ise, onun dini, hakkımı bana iade ettirirdi. Eğer Hıristiyan veya Yahudi ise, onun yöneticisi hakkımı bana iade ettirirdi. Bu güne gelince; artık falan ve falan kişiden başka birisiyle alışveriş yapamaz oldum.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 111, text: "Huzeyfe ve Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah (c,c), insanları bir araya toplar. Mü'minler kalkar, hatta cennet onlara yakınlaştırılır. Âdem (a.s)'a gelirler ve derler ki: 'Ey babamız, cennetin bize açılması için aracı ol.' Âdem (a.s) der ki: 'Sizi  EMANETE RİAYET cennetten çıkaran babanızın hatası idi. Ben bu -şefaate- yetkili değilim. Allah'ın dostu oğlum İbrahim'e gidiniz. 'Resûlüllah (s.a.v) buyurdu ki; 'Hemen İbrahim'e giderler.' İbrahim (a.s) der ki: 'Ben şefaat sahibi değilim. Ben sadece Öteden öteye dost oldum. Siz, Allah'ın kendisiyle konuştuğu Musa'ya gidin.' Hemen Musa (a.s)'a gelirler. Musa (a.s); 'Ben, şefaat sahibi değilim. Allah'ın kelimesi -ile yaratılan- ve ruhu olan İsa'ya (a.s) gidin' der. İsa (a.s)'da der ki: 'Ben, şefaat sahibi değilim.' Sonunda Muhammed (a.s)'a gelirler. O kalkar -secdeye kapanır- ve kendisine şefaat izni verilir. Emanet ve yakınlık yollanır, sıratın sağ ve sol tarafında dururlar. Sizin ilk kafileniz -sırattan- şimşek gibi geçer. Dedim ki: 'Anam babam sana feda olsun, şimşek gibi geçmek de nedir?' Buyurdu ki: 'Göz açıp kapayıncaya kadar -şimşeğin- nasıl geçtiğini görmüyor musun? Sonra rüzgar gibi geçer giderler. Sonra da kuşların geçişi ve hızlı yürüyen adamlar gibi geçer giderler. Onları bu şekilde -sırattan- geçiren amelleridir. Sizin peygamberiniz de sıratın başında durup; \"Rabbim, selamet ver, sela met ver!\" diye dua eder. Nihayet kulların amelleri, kendilerini -sırattan geçirmekten- aciz kalır. Öyle ki, yürümeye mecali kalmamış bir kişi sürünerek gelir. Sıratın her iki tarafına asılmış, emredilenleri tutmakla görevli çengeller bulunur. Bunlara takılanlar- kurtulmuş olur, üst üste yığılmış olanlar da ateştedir.' Ebu Hureyre (r.a) demiştir ki: Ebu Hureyre'nin nefsi -kudret-elinde olana yemin olsun ki, cehennemin derinliği yetmiş yıllık mesafe kadardır.\" ZULMÜN HARAMLIĞI VE KUL HAKLARININ SAHİPLERİNE İADESİ", source: "Hadis-i Şerif" },
    { id: 112, text: "Câbir (r.a)'dan rivayette, Resûlüllah (s.a.v) şöyle buyur muştur: \"Zulümden kaçınınız. Çünkü zulüm, kıyamet gününde karanlıklar halinde zulmedeni- sarar. Cimrilikten de kaçınınız. Çünkü cimrilik, sizden öncekileri helak etti, onları birbirlerinin kanlarını akıtmaya ve haramları helal saymaya sürükledi.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 113, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Kıyamet günü haklar, sahiplerine mutlaka iade edilecektir. Hatta boynuzsuz koyun için boynuzlu koyuna kısas -tatbik- edilecektir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 114, text: "Hz. Âişe (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bir karış toprağı haksız yere gasbederse, yedi kat yer onun boğazına geçirilir.\" (Buharı ve Müslim)  ZULMÜN HARAMLIĞI VE KUL HAKLARININ SAHİPLERİNE İADESİ", source: "Hadis-i Şerif" },
    { id: 115, text: "Muaz (r.a) dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) beni -Yemen'e vali olarak- gönderdiğinde şöyle buyurdu: Şüphesiz sen, kitap ehlinden olan bir kavme gidiyorsun. Onları; Allah'tan başka ilah olmadığına ve benim Allah'ın peygamberi olduğuma şehadet etmeye çağır. Eğer onlar buna itaat ederlerse, kendilerine Allah'ın her gün ve gecede beş vakit namazı farz kıldığını bildir. Eğer onlar buna da itaat ederlerse, kendilerine Allah'ın zenginlerinden alınıp fakirlerine verilen sadakayı-zekatı-emrettiğini bildir. Eğer onlar buna da itaat ederlerse, onların mallarının en kıymetlisini almaktan kaçının. Mazlumun duasından sakının; çünkü onunla Allah arasında hiçbir perde yoktur,\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 116, text: "Abdullah b. Amr b.Âs (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Müslüman; dilinden ve elinden müslümanların selamette olduğu kimsedir. Muhacir de; Allah'ın men ettiği şeyleri terk edendir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 117, text: "Abdullah b, Amr b. Âs (r.a)'dan şöyle rivayet edilmiştir:   \"Resûlüllah (s.a.v)'in ağır işlerine bakan ve kendisine 'Kirkire' denen bir adam vardı. Bu kişi ölünce, Resûlüllah (s.a.v) buyurdu ki: 'O, cehennemdedir.' Hemen ona -ait eşyalara- bakmaya gittiler ve -ganimet mallarından çaldığı- bir aba buldular,\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 118, text: "Ebu Umâme İyâs b. Sa'lebe Harisi (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim, bir müslümanın hakkını yemin ederek gasbederse, Allah ona cehennemi vacip, cenneti de haram kılar.\" Bir adam dedi ki: 'Ey Allah'ın Resulü, basit bir şey olsa da mı?' Resûlüllah (s.a.v) buyurdu ki: Misvak ağacından bir dal bile olsa.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 119, text: "Ömer b. Hattâb (r.a)'dan şöyle rivayet edilmiştir: \"Hayber -savaşının yapıldığı- gün, Resûlüllah (s.a.v)'in ashabından bir grup gelip dediler ki: Falanca şehittir, falanca şehittir. Hatta bir adamın yanından geçtiklerinde dediler ki: Falanca da şehittir. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Hayır! Çünkü ben onu, çaldığı bir hırka ile cehennemde gördüm.\" (Müslim)  ZULMÜN HARAMLIĞI VE KUL HAKLARININ SAHİPLERİNE İADESİ", source: "Hadis-i Şerif" },
    { id: 120, text: "Ebu Katâde Haris b. Reb'i (r,a), Resûlüllah (s.a.v)'den söyle rivayet etmiştir: \"Resûlüllah (s.a.v), ashabının arasında bulunurken ayağa kalktı ve onlara şöyle nasihatta bulundu: 'Allah yolunda cihat ve Allah'a iman etmek, amellerin en üstünüdür.' Bir adam ayağa kalktı ve dedi ki: 'Ey Allah'ın Resulü, Allah yolunda öldürülürsem benim hatalarım bağışlanır mı?' Resûlüllah (s.a.v) şöyle buyurdu: Evet, eğer Allah yolunda sabrederek, sevabını -Allah'dan-umarak, arkanı dönmeden savaşa yönelmiş bir halde öldürülürsen-günahların bağışlanır. Sonra Resûlüllah (s.a.v) şöyle buyurdu: 'Nasıl demiştin?' O adam da- dedi ki: 'Söyle bakalım, eğer Allah yolunda öldürülürsem benim hatalarım affedilir mi?' Bu sefer Resûlüllah (s.a.v) şöyle buyurdu: Evet, sabrederek, sevabını Allah'dan bekleyerek, geriye dönmeyip savaşa yönelmiş olarak öldürülürsen, borçtan başka -günah-ların affedilir. Çünkü bunu bana Cebrail söyledi.\" (Müslim) MÜSLÜMANLARIN HAKLARINA SAYGI", source: "Hadis-i Şerif" },
    { id: 121, text: "Ebu Musa (r.a)'dan, Resûlüllah (s.a.v) şöyle buyurdu: \"Bir mü'min diğer bir mü'min için, birbirine geçmiş bir bina gibidir.\" Resûlüllah (s.a.v) bunu söylerken- parmaklarını birbirine geçirip kenetledi. (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 122, text: "Ebu Musa (r.a)'ddn, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Kim, yanında ok bulunduğu halde mescitlerimizden veya çarşı pazarlarımızdan bir yere uğrarsa, müslümanlardan herhangi birine bir zarar vermemesi için avucunun içiyle okunun demirlerini kapatsın.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 123, text: "Nu'man b. Beşîr (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Mü'minler birbirlerini sevmede, acımada ve koruyup kollamada bir beden gibidirler. O bedenden bir uzuv -ağrıdan- şikayet etse, bedenin diğer uzuvları birbirlerini uykusuzluk ve ateş ile ona ortak olmaya çağırırlar.\" (Buhari ve Müslim)  MÜSLÜMANLARIN HAKLARINA SAYGI", source: "Hadis-i Şerif" },
    { id: 124, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Resûlüllah (s.a.v), Hz. Ali'nin oğlu Hasan'ı (r.a), yanında Akra' b. Habis bulunduğu sırada öptü. Akr'a dedi ki: 'Benim on tane oğlum var; onlardan hiç birini öpmedim.' Resûlüllah (s.a.v) ona baktı ve şöyle buyurdu: Merhamet etmeyen, merhamet olunmaz.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 125, text: "Hz. Âige (r.a)'dan şöyle rivayet edilmiştir: \"Bedevilerden bir grup insan Resûlüllah (s.a.v)'e geldiler ve dediler ki: 'Siz çocuklarınızı öper misiniz?' Resûlüllah (s.a.v) şöyle buyurdu: 'Evet. ' Dediler ki: 'Fakat biz, Allah'a yemin olsun ki öpmeyiz.' Bu sefer Resûlüllah (s.a.v) şöyle buyurdu: Eğer Allah, sizin kalplerinizden merhameti soyup almış ise, ben ne yapabilirim ki?\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 126, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz insanlara namaz kıldırdığı zaman hafif kıldırsın. Çünkü onların arasında zayıf, hasta ve yaşlılar vardır. Ama sizden biriniz kendi başına namaz kıldığı zaman, istediği kadar uzatsın.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 127, text: "Hz. Âişe (r.a) dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v), ashabına olan merhametinden dolayı onların ara vermeden oruç tutmalarını yasakladı. Dediler ki: 'Sen aralıksız oruç tutuyorsun?' Resûlüllah (s.a.v) şöyle buyurdu: Ben sizin durumunuzda değilim; beni Rabbim yedirir ve içirir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 128, text: "Ebu Katâde Haris b. Rab'i (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Çoğu zaman ben namaza dururum ve namazda -okumayı-uzatmak isterim. Birden bir çocuğun ağlamasını işitirim de, anasına zahmet vermesini istemediğimden dolayı namazı kısa tutarım.\" (Buhari)  MÜSLÜMANLARIN HAKLARINA SAYGI", source: "Hadis-i Şerif" },
    { id: 129, text: "Cündüb b. Abdullah (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim sabah namazını kılarsa, o kişi Allah'ın koruması altındadır. Sakın Allah, -himayesine alırken yaptığınız- anlaşmadan dolayı sizden bir şey istemesin! Çünkü O, yaptığı anlaşmadan dolayı kimden bir şeyi isterse onu yakalar, sonra da yüz üstü onu cehennem ateşine atar!\"", source: "Hadis-i Şerif" },
    { id: 130, text: "İbn-İ Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Müslüman, müslümanın kardeşidir; ona zulmetmez, onu düşmana teslim etmez. Kim kardeşinin ihtiyacını giderirse, Allah da onun ihtiyacını giderir. Kim bir müslümandan bir sıkıntı kaldırırsa, Allah da ondan kıyametin sıkıntılarından bir sıkıntıyı kaldırır. Kim bir müslümanın ayıbını Örterse, Allah da kıyamet günü onun ayıbını örter.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 131, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Birbirinize haset etmeyiniz, almayacağınız malın fiyatını artırmayınız, birbirinize düşman olmayınız, birbirinize sırt çevirmeyiniz, bazınız bazınızın satışını bozarak kendi malını satmasın. Ey Allah'ın kulları, kardeş olunuz! Müslüman müslümanın kardeşidir; ona zulmetmez, onu aşağılamaz, ona yardım etmeyi bırakmaz.\" Resûlüllah (s.a.v) kalbini işaret ederek; \"Takva buradadır. Bir kişiye şer olarak, müslüman kardeşini hakir görmesi yeter! Her müslümanın kanı, malı ve namusu diğer müslümana haramdır\" buyurdu. (Müslim) MÜSLÜMANLARIN İHTİYAÇLARINI GİDERME", source: "Hadis-i Şerif" },
    { id: 132, text: "îbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurdugu rivayet edilmiştir: \"Müslüman, müslümanın kardeşidir. Ona zulmetmez, onu düşmana teslim etmez. Kim bir kardeşinin ihtiyacını giderirse, Allah da onun ihtiyacını giderir. Kim bir müslümandan bir sıkıntı giderirse, Allah da ondan kıyamet gününün sıkıntılarından bir sıkıntıyı giderir. Kim bir müslümanın ayıbını örterse, Allah da kıyamet günü onun ayıbını örter.\" (Buharı ve Müslim)  MÜSLÜMANLARIN İHTİYAÇLARINI GİDERME-ŞEFAAT", source: "Hadis-i Şerif" },
    { id: 133, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bir mü'minden dünya sıkıntılarından birini giderip rahat bir nefes aldırırsa, Allah da ondan kıyamet günü sıkıntılarından bir sıkıntıyı gidererek nefes aldırır. Kim zorda kalmış birine kolaylık sağlarsa, Allah da ona dünya ve ahirette kolaylık sağlar. Kim bir müslümanın ayıbını örterse, Allah da dünya ve ahirette onun ayıbını örter. Bir kul, müslüman kardeşinin yardımında olduğu sürece, Allah da o kulun yardımında olur. Kim ilim öğrenmek için bir yola girerse, Allah da bu sebeple ona cennetin yolunu kolaylaştırır. Bir toplum, Allah'ın evlerinden bir eve toplanıp da Allah'ın kitabını okur ve aralarında onun müzakeresini yaparsa, Allah da onların üzerine bir güven indirir ve onları bir rahmet sarar. Melekler çevre lerini sararlar ve Allah onları katında bulunan-peygamber ve meleklere- anlatır. Kimin ameli kendini geri bırakırsa, soyu onu ileri geçirmez.\" (Müslim) ŞEFAAT", source: "Hadis-i Şerif" },
    { id: 134, text: "Ebu Musa Eş'arî (r.a)'dan, şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v), kendisine bir şey isteyen biri geldiği vakit, oturmakta olduğu kimselere döner ve şöyle buyururdu: Bu işe aracı olun, mükafatlandırılırsınız. Allah, peygamberinin diliyle sevdiğini yerine getirir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 135, text: "İbn-i Abbâs (r.a), Berîre ve kocasının hikayesi hakkında şöyle rivayet etmiştir: \"Resûlüllah (s.a.v) Berire'ye şöyle buyurdu: 'Keşke kocana dönsen!' Berîre dedi ki: 'Ey Allah'ın Resulü, yoksa bana -dönmemi mi emrediyorsun?' Buyurdu ki: 'Ben sadece aracı oluyorum.' Berîre dedi ki: Benim ona -dönmeye- ihtiyacım yok.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 136, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'ın şöyle buyurduğu rivayet edilmiştir: 'İnsanların her bir mafsalı üzerine, güneşin doğduğu her günde bir sadaka vermek- gerekir.  İNSANLARIN ARASINI DÜZELTMEK İki kişi arasında adaletle davranman sadakadır. Hayvanına binmek isteyen birine yardım edip, onu hayvana bindirmen de sadakadır. Ya da onun eşyasını hayvanın üzerine yüklemen sadakadır. Namaz kılmak için attığın her adım sadakadır. Yoldan -İnsanlara zarar verebilecek- ezayı kaldırman da sadakadır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 137, text: "Ümmü Gülsüm b. Ebu Muayt (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle söylerken işittim: İnsanların arasını düzeltmek için iyi haber getiren veya hayır söyleyen yalancı değil-dir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 138, text: "Hz. Âişe (r.a)'in şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) kapı önünde seslerini gittikçe artıran hasımların sesini işitti. Bunlardan biri diğerinden -borcunda bir miktar- indirim yapmasını ve kendisine esnek muamele etmesini İstiyor, diğeri ise; 'Allah'a yemin ederim ki, yapmayacağım' diyordu. Hemen Resûlüllah (s.a.v) onların yanlarına çıktı ve buyurdu ki:   'İyilik yapmamak üzere Allah'a yemin eden nerede?' Bu sefer o kişi: 'Benim Ey Allah'ın Resulü! Bunlardan hangisini istiyorsa onun-olsun' dedi.\" (Buharı ve Müslim) ZAYIFLARIN, FAKİRLERİN VE ADI-SANI OLMAYAN KİMSELERİN FAZİLETLERİ", source: "Hadis-i Şerif" },
    { id: 139, text: "Harise b. Vehb (r.a)'dan, şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle söylerken işittim: Dikkat edin! Size cennet ehlini haber vereyim mi? Horlanan her zayıf kişidir ki, eğer Allah'a yemin etse, hemen onun yeminini yerine getirir. Dikkat edin! Size cehennem ehlini de haber vereyim mi? Her katı kalpli, cimri zengin ve kibirli kimsedir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 140, text: "Ebu Saîd Hudri (r.a)'dan, Resûlüllah (s.a,v)'in şöyle buyurduğu rivayet edilmiştir:  ZAYIFLARIN,FAKİRLERİN VE ADI-SANI OLMAYANLARIN FAZİLETLERİ \"Cennet ve cehennem birbirleriyle atıştılar. Cehennem; 'Halka zulmedenler ve büyüklük taslayanlar bendedir' dedi. Cennet de; 'İnsanların zayıfları ve miskinleri bendedir' dedi. Allah (c.c) aralarında şöyle hüküm verdi: Sen ey cennet, benim rahmetimsin, seninle dilediğime merhamet ederim. Sen ey cehennem, benim azabımsın, dilediğime seninle azap ederim. İkinizi de doldurmak bana aittir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 141, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kıyamet günü iri vücutlu, gayet besili bir adam -ilahi huzura- gelir. Oysa Allah katında sinek kanadı kadar bir ağırlığı -sevabı- yoktur.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 142, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir; \"Siyah bir kadın-veya bir genç- mescidi süpürürdü. Resûlüllah (s.a.v) onu bir müddet göremedi. Ondan sual edince dediler ki: 'Öldü!' Resûlüllah (s.a.v); 'Onun ölümünü bana bildirmeniz gerekmez miydi? ' buyurdu. Ashab, sanki onu küçümsemişlerdi. Resûlüllah (s.a,v); 'Beni onun kabrine götürün' buyurdu. Resûlüllah (s.a.v)'i o nun kabrine götürdüler; kabri üzerinde cenaze namazını kıldı.   Sonra şöyle buyurdu: Şüphesiz şu kabirler, sahiplerine karşı karanlık do ludur. Muhakkak Allah, üzerlerine kıldığım namazla onların kabirlerini nurlandırdı.\" (Buharı ve Müslim) YETİMLERE, KIZ ÇOCUKLARINA, ZAYIFLARA VE YOKSULLARA YUMUŞAK DAVRANMAK", source: "Hadis-i Şerif" },
    { id: 143, text: "Sa'd b. Ebu Vakkâs (r.a)'dan, şöyle rivayet edilmiştir: \"Biz altı kişi Resûlüllah (s.a.v) ile beraber bulunuyorduk. Müşrikler Peygamber (a.s)'a; 'Şu kişileri kov ki, bize karşı cüretkâr olmasınlar' dediler. Orada-ben, İbn-i Mes'ud, Huzeyl kabilesinden bir kişi, Bilal ve isimlendiremeyeceğim iki kişi daha vardı. Birden Resûlüllah (s.a.v)'in kalbine, Allah'ın doğmasını istediği şey doğmuş, içinden onu geçirmişti. Bunun üzerine Allah şu ayeti indirdi: Sabah akşam Rablerine, sırf O'nun cemâlini dileyerek dua edenleri yanından kovma.\" En'am: 52 (Müslim)  YETİMLERE, KIZ ÇOCUKLARINA, ZAYIFLARA VE YOKSULLARA ...", source: "Hadis-i Şerif" },
    { id: 144, text: "Sehl b. Sa'd (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ben ve yetimi kollayıp gözeten, işini üzerine alan kimse cennette böylece beraber- olacağız.\" Resûlüllah (s.a.v) şehadet parmağı ile orta parmağını gösterip, aralarım biraz ayırdı. (Buhari)", source: "Hadis-i Şerif" },
    { id: 145, text: "Ebu Hureyre (r,a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kendisinin veya başkasının yetimini kollayıp gözeten, işlerini üzerine alan kimse İle ben, cennette böylece beraber olacağız.\" Hadisi rivayet eden Mâlik b. Enes, şehadet parmağı ile orta parmağını işaret etti. (Müslim)", source: "Hadis-i Şerif" },
    { id: 146, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Dul kadın ve yoksulların işi için koşuşturanlar, Allah yolunda cihat edenler gibidir.\" Rivayet eden zat diyor ki: Resûlüllah (s.a.v)'in; 'Bıkıp usanmadan -gece- ibadetine kalkan ve hiç iftar etmeden oruç tutan gibidir' dediğini sanıyorum. (Müslim)", source: "Hadis-i Şerif" },
    { id: 147, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim, ergenlik çağına ulaşıncaya kadar iki kızı bakıp büyütürse, kıyamet gününe ben ve o böylece -beraber- gelir.\" Resûlüllah (s.a.v)- parmaklarını birbirine geçirdi. (Müslim)", source: "Hadis-i Şerif" },
    { id: 148, text: "Ebu Şureyh Huveylid b. Amr Huzâî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah'ım, ben iki zayıfın; yetim ve kadının hakkından sakınıyorum.\" (Hadis hasendir. Nesei bu hadisi iyi bir isnatla rivayet etmiştir.) KADINLARA İYİ DAVRANMAYI TAVSİYE", source: "Hadis-i Şerif" },
    { id: 149, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  KADINLARA İYİ DAVRANMAYI TAVSİYE \"Mü'min bir erkek, mü'min bir kadına kin beslemesin. Eğer onun bir huyundan hoşlanmazsa, diğer bir huyundan razı olabilir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 150, text: "Muaviye b. Hayde (r.a)'dan şöyle rivayet edilmiştir: \"Ben dedim ki: Ey Allah'ın elçisi, birimizin hanımının üzerindeki hakkı nedir? Resûlüllah (s.a.v) şöyle buyurdu: Yediğin zaman onu da yedirmen, giydiğin zaman onu da giydirmen, yüzüne vurmaman, kötülememen, evin içinde olanı hariç, kendisini terk etmemen.\" (Hadis hasendir; Ebu Davud rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 151, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Mü'minlerin iman bakımından en olgun olanı, ahlakça en güzel olanıdır. Hayırlılarınız da, kadınlarınıza hayırlı olanınızdır.\" (Tirmizi rivayet etmiş ve Hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 152, text: "Abdullah b. Amr b.As (r.a)'dan, Resâlüllah (s.a.v)in şöyle buyurduğu rivayet edilmiştir: \"Dünya faydalanılacak bir metadır. Dünya metaının en hayırlısı ise iyi ahlaklı, dindar- kadındır.\" (Müslim) ERKEĞİN HANIMI ÜZERİNDEKİ HAKLARI", source: "Hadis-i Şerif" },
    { id: 153, text: "Ebu Hureyre (r.a)'dan, Resâlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hiçbir kadına, kocası yanında iken izni olmadıkça -nafîle-oruç tutması, yine onun izni dışında evine herhangi birinin girmesine izin vermesi helal değildir.\" (Buhari ve Müslim rivayet etmiştir. Bu, Buhari' nin lafzıdır.)", source: "Hadis-i Şerif" },
    { id: 154, text: "Ibn-i Ömer (r.a)'dan, Resâlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hepiniz birer çobansınız ve hepiniz sorumluluğunuz altındakilerden sorumlusunuz. Halife bir koruyucudur. Erkek, ev halkı üzerinde bir koruyucudur. Kadın, kocasının evinde ve çocuğunun üzerinde bir  ERKEĞİN HANIMI ÜZERİNDEKİ HAKLARI koruyucudur. Dolayısıyla hepiniz çobansınız ve hepiniz idareniz altında olanlardan sorumlusunuz.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 155, text: "Ebu Ali Talk b. Ali (r.a)'dan, Resûlüllah (s.a.v) şöyle buyurmuştur: \"Bİr erkek, herhangi bir ihtiyacı için hanımını çağırdığı zaman, tandır başında bile olsa hemen onun yanına gelsin.\" (Tirmizi ve Nesei rivayet etmiş; Tirmizi hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 156, text: "Ümmü Seleme (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hangi kadın, kocası kendisinden razı olduğu halde ölürse cennete girer.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.) AİLE FERTLERİNE HARCAMADA BULUNMAK", source: "Hadis-i Şerif" },
    { id: 157, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah yolunda harcadığın bir dinar, kölenin hürriyetine kavuşması için harcadığın bir dinar, yoksula harcadığın bir dinar ve kendi ev halkına harcadığın bir dinar var ya, bunların sevap bakımından en büyüğü ev halkına yaptığın harcamadır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 158, text: "Ümmü Seleme (r.a)'ın şöyle dediği rivayet edilmiştir: \"Ey Allah'ın elçisi, Ebu Seleme'nin çocuklarına yaptığım harcamalardan dolayı bana bir sevap var mı? Ben onları şöyle veya böyle terk etmedim; onlar benim çocuklarım. Resûlüllah (s.a.v) şöyle buyurdu: Evet, onlara yaptığın bütün harcamalardan dolayı sana sevap vardır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 159, text: "Sa'd b. Ebî Vakkâs (r.a)'dan rivayet edilen ve kitabın başındaki Niyyet bölümünde bulunan uzunca bir hadiste, Resûlüllah (s.a.v) Sa'd'a şöyle buyurmuştur: \"Allah'ın rızasını kazanmak maksadıyla yaptığın harcamadan dolayı sevap kazanırsın. Hatta hanımının ağzına koyduğun bir lokmadan dolayı bile!\" (Buhari ve Müslim)  AİLE FERTLERİNE HARCAMADA BULUNMAK", source: "Hadis-i Şerif" },
    { id: 160, text: "Ebu Hur ey re (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kulların sabaha ulaştıkları her gün iki melek yeryüzüne iner ve onlardan biri der ki: Ey Allah'ım, Allah yolunda-dağıtana, harcadığının yerini tutacak olanı ver. Diğeri ise şöyle der: Ey Allah'ım, cimrilik yapıp- malını tutana da telef ver.\" (Buharı ve Müslim) SEVDİKLERİNDEN VE İYİSİNDEN HARCAMAK", source: "Hadis-i Şerif" },
    { id: 161, text: "Enes (r.a)'ın şöyle dediği rivayet edilmiştir: \"Ebu Talha (r.a), Medine'de ensarın en çok hurmalığı olan ki şisiidi.   Mallarının içinde kendisine en sevimli geleni, mescidin karşısında bulunan Beyreha isimli bahçe idi. Resûlülîah (s.a.v) oraya girer ve İçindeki iyi sudan içerdi. Enes demiştir ki: 'Sevdiğiniz şeylerden Allah yolunda harca-madıkça İyiliğe eremezsiniz' ayeti İnince, Ebu Talha kalktı Resûlüllah (s.a.v)'e dedi ki: Ey Allah'ın elçisi, Allah (c.c) sana; 'Sevdiğiniz şeylerden harcamadıkça iyiliğe eremezsiniz' ayetini indirdi. Benim en çok sevdiği malım ise Beyreha -hurmalığı-dır. Artık o-bah-çe- Allah (c.c) için sadakadır. Onun Allah katında hayrını ve ahiret azığı olmasını bekliyorum. Ey Allah'ın Resulü, onu Allah'ın size gösterdiği gibi değerlendirin. Bunun üzerine Resûlülîlah (s.a.v) şöyle buyurdu: Vay! Bu ne kârlı bir mal, bu ne kârlı bir mal! Ben, senin söylediğini işittim. Ama ben, onu akrabalarına -sadaka olarak-dağıtmanı uygun görüyorum. Ebu Talha: Öyle yapacağım Ey Al lah'ın Resulü, dedi ve o bahçeyi akrabalarına ve amca oğullarına taksim etti.\" (Buharı ve Müslim) AİLE, ÇOCUKLARI VE EMRİ ALTINDAKİLERE ALLAH'A İTAATİ EMRETME", source: "Hadis-i Şerif" },
    { id: 162, text: "Ebu Hureyre (r.a)'ın şöyle dediği rivayet edilmiştir: \"Hz. Ali'nin (r.a) oğlu Hasan, zekat hurmalarından bir hurma alıp ağzına götürmüştü. Resûlüllah (s.a.v) şöyle buyurdu: E,e! Onu at. Bilmiyor musun, biz -ehli beyt- sadaka yemeyiz.\" (Buhari ve Müslim)  KOMŞU HAKKI VE BUNA DAİR TAVSİYELER", source: "Hadis-i Şerif" },
    { id: 163, text: "Ibn-i Ömer (r.a)'ın, Resûlüllah (s.a.v)'in şöyle dediğini işittiği rivayet edilmiştir: \"Hepiniz çobansınız. Hepiniz yönetiminiz altında bulunanlardan sorumlusunuz. Halife, çobandır ve yönetimi altındakilerden sorumludur. Erkek, aile fertlerinin çobanıdır ve onlardan sorumludur. Kadın, kocasının evinin çobanıdır ve onların durumundan sorumludur. Hizmetçi, efendisinin malının çobanıdır ve vazifesinden sorumludur. Velhasıl hepiniz çobansınız ve sorumluluğunuz altında bulunanlardan sorumlusunuz.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 164, text: "Ebu Süreyye Sebre b. Ma'bed el-Cühenî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yedi yaşına girmiş çocuğa namazı öğretin; on yaşına bastığında ise eğer kılmazsa- onu dövün.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.) KOMŞU HAKKI VE BUNA DAİR TAVSİYELER", source: "Hadis-i Şerif" },
    { id: 165, text: "İbn-i Ömer ve Hz. Âişe (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Cebrail bana sürekli komşu hakkına riayet etmeyi tavsiye edip durdu. O kadar ki, komşuyu komşuya mirasçı kılacak sandım.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 166, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ey müslüman kadınlar! Velev ki koyun paçası olsun, hiçbir komşu komşusunun yaptığı iyiliği hor görmesin.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 167, text: "Hz. Âişe (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Ey Allah'ın Resulü! Benim iki komşum var; bunlardan hangisine hediye vereyim? Şöyle buyurdu: sana kapısı en yakın olana-ver.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 168, text: "Abdullah b. Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  KOMŞU HAKKI VE BUNA DAİR TAVSİYELER \"Allah katında arkadaşların hayırlısı, arkadaşına hayırlı olandır. Allah katında komşuların hayırlısı, komşusuna hayırlı olandır,\" (Tirmizi rivayet etmiş ve Hadis Hasendir, demiştir.) ANA BABAYA İYİLİK, DOST VE AKRABAYI GÖZETMEK, ZİYARETTE BULUNMAK", source: "Hadis-i Şerif" },
    { id: 169, text: "Ebu Abdurrahman Abdullah b. Mes'ud (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.)'a şunu sordum: Allah'a (c.c) hangi amel daha sevimlidir? Şöyle buyurdu: Vaktinde kılınan namazdır. Dedim ki: Sonra hangisidir? Buyurdu ki: Ana babaya iyilikte bulunmaktır. Dedim ki: Sonra hangisidir? Şöyle buyurdu: Allah yolunda cihat etmektir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 170, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Bir evlat, babasının hakkını, ancak onu köle olarak bulup satın alır ve âzât ederse ödeyebilir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 171, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Burnu yerde sürünsün, burnu yerde sürünsün, burnu yerde sürünsün! Ana babasından birine veya her ikisine ihtiyarlık zamanlarında yetişip de cennete giremeyen kimsenin.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 172, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim rızkının bol olmasını ve ömrünün uzun olmasını arzu ediyorsa, akrabalarıyla ilişkisini kesmesin, onlara iyilikte bulunsun.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 173, text: "Abdullah b. Amr b.Âs (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  ANA BABAYA İYİLİK, AKRABAYI GÖZETMEK VE ZİYARETTE BULUNMAK \"Akrabalarından gördüğü yakınlığa-iyiliğe-aynı ile mukabelede bulunmak, akrabalığın hakkını vermek değildir. Asıl akrabalığı gözetmek, akrabalık ilişkileri kesildiği zaman onu devam ettirmektir.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 174, text: "Ebu Bekir'in kızı Esma (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) zamanında müşrik olan annem bana gelmişti. Ben, Resûlüllah (s.a.v)'den fetva istedim ve dedim ki: Annem bana geldi; benden bir şeyler istiyor. Annemi ziyaret edebilir miyim? Resûlüllah (s.a,v) şöyle buyurdu: Evet, anneni ziyaret et-onunla ilgilen.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 175, text: "Ebu Süfyan Sahr b. Harb (r.a)'ın Herakliyus kıssası ile ilgili uzun hadisinde şöyle rivayet edilmiştir: \"Herakliyus Ebu Süfyan'a dedi ki: 'Resûlüllah (s.a.v) size ne emrediyor?' Ebu Süfyan şöyle dediğini söylüyor: 'O, bir olan Allah'a ibadet ediniz, O'na hiçbir şeyi ortak koşmayınız ve atalarınızın söylediklerini bırakınız' diyor. Ve bize, namaz kılmayı, doğruluğu, İffetli olmayı ve akrabayı gözetmeyi-ilişkileri sürdürmeyi-emrediyor.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 176, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"En yakın akrabalarını uyar, (Şuara: 214) ayeti indiği vakit, Resûlüllah (s.a.v) Kureyş'i çağırdı. Onlar da hemen toplandılar. Resûlüllah (s.a.v), umumi ve hususi olarak şöyle buyurdu: Ey Abd-i Şems oğulları, Ey Ka'b b. Lüey oğulları, kendinizi cehennem ateşinden kurtarınız! Ey Mürre b. Ka'b oğulları, kendinizi cehennem ateşinden kurtarınız! Ey Abdül-Menaf oğulları, kendinizi cehennem ateşinden kurtarınız! Ey Hâşim oğulları, kendinizi cehennem ateşinden kurtarınız! Ey Abdül-Muttalip oğulları, kendinizi cehennem ateşinden kurtannız! Ey Fatıma, kendini cehennem ateşinden kurtar! Çünkü ben, Allah'dan gelebilecek -azabı- sizden def etmeye muktedir değilim. Benim sizinle bir yakınlığım bulunmaktadır. Ben ancak ona riayet edebilirim.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 177, text: "Ebu Abdullah Âmr b. Âs (r.a)'dan şöyle rivayet edilmiştir; \"Ben Resûlüllah (s.a.v)'in, gizli değil aşikâre olarak şunu söylediğini işittim:  ANA BABAYA İYİLİK, AKRABAYI GÖZETMEK VE ZİYARETTE BULUNMAK Falan oğulların ailesi benim dostlarım değildir. Benim dostum, Allah ve iyi mü'minlerdir. Fakat onlarla -aramızda-akrabalık bağı vardır; ben onu yerine getiririm.\" (Buharı ve Müslim. Lafız Buharı'nindir.)", source: "Hadis-i Şerif" },
    { id: 178, text: "Ebu Eyyub Halid b. Zeyd el-Ensarî (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam; Ey Allah'ın Resulü, beni cennete koyacak ve cehennemden uzaklaştıracak bir iş haber veriver, dedi. Resûlüllah (s.a.v)'de şöyle buyurdu: Allah'a ibadet edersin, O'na hiçbir şeyi ortak koşmazsın, namazı hakkıyla kılarsın, zekatı verirsin ve akrabalık bağlarını sürdürürsün.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 179, text: "İbn-i Ömer (r.a)'dan, şöyle rivayet edilmiştir: \"Nikahım altında bir hanımım vardı, ben onu seviyordum. Babam-ömer (r.a) ise ondan hoşlanmıyordu. Bir gün bana dedi ki: 'Onu boşa!' Ben de boşamadım, Ömer (r.a), Resûlüllah (s.a.v)'e giderek durumu ona anlattı. Resûlüllah (s.a.v); 'Onu boşa!' buyurdu.\" (Ebu Davud ve Tirmizi rivayet etti ve Tirmizi; Hadis hesendir, sahihtir, dedi.)", source: "Hadis-i Şerif" },
    { id: 180, text: "Ebu Derda (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam Ebu Derda'ya gelip; 'Benim bir hanımım var, ama annem onu boşamamı emrediyor' dedi. Ebu Derda şöyle söyledi: Ben, Resûlüllah (s.a.v)'in şöyle buyurduğunu işittim: Anne ve baba, cennetin kapılarının tam ortasıdır. O halde istersen o kapıyı zayi et, istersen muhafaza et!\" (Tirmizi rivayet etmiş ve Hadis hasendİr, sahihtir, demiştir,)", source: "Hadis-i Şerif" },
    { id: 181, text: "Ebu Bekre Nüfey b. Haris (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Size günahların en büyüğünü haber vereyim mi? Bunu üç kez tekrarladı. Biz dedik ki: 'Evet, Ey Allah'ın Resulü.' Resûlüllah (s.a.v) yaslandığı yerden şöyle buyurdu: Allah'a ortak koşmak, anne ve babaya isyan etmektir. Sonra doğrulup oturdu ve şöyle devam etti: Dikkat edin, yalan söylemek ve yalan yere şahitlik yapmaktır! Resûlüllah (s.a.v) bunu o kadar tekrar ediyordu ki, biz; 'Keşke sus-saydı-kendini yormasa' dedik.\" (Buhari ve Müslim)  ANA BABAYA İYİLİK, AKRABAYI GÖZETMEK VE ZİYARETTE BULUNMAK", source: "Hadis-i Şerif" },
    { id: 182, text: "Ebu Muhammed Cübeyr b. Mut'im (r,a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Akrabalık bağlarını kesen cennete giremez.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 183, text: "Ebu İsa Muğîre Şube (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yüce Allah size, annelere isyan etmeyi, fakirlerin haklarını-vermemeyi, hakkı olmayan şeyi istemeyi ve kız çocuklarını diri diri toprağa gömmeyi haram kıldı. Sizin dedi kodu yapmanızı, çok soru sormanızı ve malınızı gereksiz yere- zayi etmenizi hoş karşılamadı.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 184, text: "İbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İyiliklerin en güzeli, kişinin babasının dostlarıyla ilişkileri, dostluğu sürdürmesidir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 185, text: "Ebu Üseyd Mâlik b. Rabîa es-Sâidî (r.a)'dan şöyle rivayet edilmiştir: \"Bir ara biz Resûlüllah (s.a.v)'in yanında oturuyorken, Benî Seleme kabilesinden bir adam çıkıp geldi ve dedi ki: Ey Allah'ın Resulü, anne ve babama ölümlerinden sonra yapabileceğim bir iyilik var mı? Resûlüllah (s.a.v) şöyle buyurdu: Evet, onlara dua etmek,bağışlanmalarını istemek, onların kendilerinden sonraki -vasiyet, borç v.s. gibi- ahitlerini yerine getirmek, ancak onlara -saygı göstererek- yerine getirilebilecek akrabalık bağlarını gözetmek ve onların arkadaşlarına ikram etmektir.\" (EbuDavud)", source: "Hadis-i Şerif" },
    { id: 186, text: "Enes b. Malik (r.a)'dan şöyle rivayet edilmiştir: \"Ben, Cerîr b. Abdullah ile birlikte bir sefere çıkmıştım. Yaşça büyük olmasına rağmen- bana hizmet ediyordu. Ben dedim ki: 'Böyle yapma!' O da şöyle dedi: Muhakkak ki ben, Ensar'ın Resûlüllah'a yaptığı büyük hizmeti gördüm. Ben de kendi kendime; eğer Ensar'dan biri ile arkadaşlık yaparsam mutlaka ona hizmet edeceğim, diye söz vermiştim.\" (Buhari ve Müslim) RESÛLÜLLAH (S.A.V)'IN EHL-İ BEYTİNE İKRAM VE ONLARIN ÜSTÜNLÜKLERİ  RESÛLÜLLAH (S.A.V)'IN EHL-İ BEYTİNE İKRAM", source: "Hadis-i Şerif" },
    { id: 187, text: "Yezid b. Hayyânın şöyle dediği rivayet edilmiştir: \"Ben, Husayn b. Sebre ve Amr b. Müslim, Zeyd b. Erkam (r.a)'a gittik. Oraya varıp oturunca, Husayn ona dedi ki: 'Ey Zeyd, muhakkak sen çok hayırlı işlerle karşılaştın. Resûlüllah (s.a.v)'i gördün, O'nun anlattıklarını dinledin, onunla beraber savaşa çıktın ve arkasında namaz kıldın. Andolsun ki Ey Zeyd, sen çok hayırlı işlere nail oldun. Ey Zeyd, Resûlüllah (s.a.v)'den duyduklarını bize anlat! Zeyd şöyle dedi: Ey kardeşimin oğlu, Allah'a yemin olsun ki yaşım ilerledi, aradan çok zaman geçti ve ben, Resûlüllah (s.a.v)'den duyup muhafaza ettiğim şeylerin bir kısmını unuttum. Onun için size anlatacağım şeyleri kabul edin; anlatmadığım hususlarda da beni zorlamayın. Sonra şunları söyledi: Bir gün Resûlüllah (s.a.v), Mekke ile Medine arasındaki Huma denilen suyun başında ayağa kalkıp bize bir hutbe okudu. Allah'a hamd ve sena ettikten sonra vaaz ederek nasihatte bulundu. Daha sonra da şöyle buyurdu: Dikkat edin Ey insanlar! Ben ancak bir beşerim. Rabbimin elçisinin Azrail'in- gelmesi ve benim onun davetine İcabet etmem yakındır.   Ben size iki büyük şey bırakıyorum; onlardan ilki, kendisinde hidayet ve nur bulunan Allah'ın kitabıdır. O halde Allah'ın kitabını alın ve ona sımsıkı sarılın. Resûlüllah (s.a.v), Allah'ın kitabına teşvik ve rağbet ettirdikten sonra şöyle buyurdu: İkincisi de, Ehl-i Beytim'dir. Ehl-i Beyt'im hakkında size Allah'ı hatırlatırım, Ehl-i Beyt'im hakkında size Allah'ı hatırlatırım. Husayn Zeyd'e, Ehl-i Beyt'in kim olduğunu, onların kadınlarının da Ehl-i Beyt'e dahil olup olmadıklarım sordu. Zeyd dedi ki: Onların kadınları da Ehl-i Beyt'tendir, fakat onun Ehl-i Beyt'i, kendisinden sonra da sadaka kabul etmeleri haram kılınan kimselerdir. Husayn, onlar kimdir diye sorunca Zeyd şöyle dedi: Ali, Akîl, Ca'fer ve Abbas aileleridir. Husayn, onların hepsine sadaka almak haram mı kılındı, diye sorunca Zeyd, evet, dedi.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 188, text: "İbn-i Ömer (r.a), Ebu Bekir (r.a)'dan Mevkuf olarak şöyle dediğini rivayet etmiştir: \"Muhammed'e, Ehl-i Beytinin içinde hürmet gösteriniz.\" (Buharı) ALİMLERE HÜRMET GÖSTERMEK  ALİMLERE HÜRMET GÖSTERMEK", source: "Hadis-i Şerif" },
    { id: 189, text: "Ebu Mes'ud Ukbe b. Amr el-Bedrî el-Ensarî (r.a) 'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir topluma, Allah'ın kitabını en iyi okuyanı İmamlık yapsın. Eğer okuyuşta müsavi iseler, sünneti en iyi bilen imamlık yapsın. Eğer sünneti bilmede de müsavi iseler, en önce hicret edeni, eğer bunda da müsavi iseler en yaşlı olanı imamlık yapsın. Bir kişi, ev sahibinin izni olmadan imamlık yapmasın ve onun izni olmadıkça evindeki minderine de oturmasın.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 190, text: "Ebu Mes'ud Ukbe b. Amr el-Bedrî el-Ensarî (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) namazda omuzlarımıza dokunur ve şöyle buyururdu: Safları düz tutunuz ve yamuk yumuk yapmayınız; sonra kalpleriniz de yamuk yumuk olur. İçinizden en hilim ve akıl sahibi olanlar -namazda- bana yakın dursun. Sonra bunlara yakın olanlar, daha sonra da bunlara yakın olanlar -namazda arkama dursun.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 191, text: "Abdullah b, Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Sizden akıl sahipleri ve olgun olanlar -namazda-bana yakın dursun. Sonra da -üç kez tekrarlayarak- onlara yakın olanlar arkamda dursun. Pazar yerlerinde görülen karışıklık ve kargaşalar gibi saf tutmaktan sakının,\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 192, text: "Câbir (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v), Uhud şehitlerinden iki kişiyi aynı kabre defnediyordu. Sonra buyurdu ki: 'Bunlardan hangisi, Kur'an'ı daha çok ezberlemiştir?' Onlardan birine işaret edildiğinde ise, onu kıbleye doğru lahit içine koydu.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 193, text: "Ibn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Rüyada kendimi, dişlerimi misvaklarken gördüm. Birden yanıma iki adam çıkageldi; onlardan biri diğerinden daha yaşlı idi. Küçük olanına misvakı uzattığımda ise bana denildi ki: 'Büyüğe- ver.' Bende onlardan büyük olanına misvakı verdim.\" (Buharı ve Müslim)  ALİMLERE HÜRMET GÖSTERMEK", source: "Hadis-i Şerif" },
    { id: 194, text: "Ebu Musa (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet etmiştir: \"Saçı sakalı ağarmış ihtiyar bir müslümana, haddi aşmayan ve onunla amel etmekten uzaklaşmayan Kur'an hafızına ve adil devlet başkanına ikramda bulunmak, Yüce Allah'a saygıdan sayılır.\" (Ebu Davud, Hadis Hasendir.)", source: "Hadis-i Şerif" },
    { id: 195, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'in vefatından sonra Hz. Ebu Bekir, Hz. Ömer (r.a)'a dedi ki: 'Yürü bizimle Ümmü Eymen (r.a)'a gidelim; Resûlüllah (s.a.v)'in kendisini ziyaret ettiği gibi, biz de onu ziyaret edelim.' Ona vardıklarında Ümmü Eymen ağladı. Kendisine dediler ki: 'Ama niye ağlıyorsun? Bilmiyor musun ki, Allah katında bulunan -lütfün- Resûlüllah (s.a.v) için daha hayırlıdır.' Ümmü Eymen dedi ki: 'Ben onun için ağlamıyorum. Allah katında bulunan -lütfün- Resûlüllah (s.a.v) için daha hayırlı olduğunu biliyorum. Fakat ben, gökten inen vahyin kesilmesine ağlıyorum.' Bu söz-onları da heyecanlandırdı ve Ümmü Eymen ile birlikte onlar da ağladılar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 196, text: "Ebu Hureyre (r.a) 'dan, Resûlüllah (.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah için bir hastayı veya bir kardeşini ziyaret edene bir çağrıcı -melek- şöyle seslenir: Sana mübarek olsun, ne mübarek yolculuk o! Cennette bir yer edindin.\" (Tirmizi)", source: "Hadis-i Şerif" },
    { id: 197, text: "Ebu Musa el-Eş'arî (r.a) ' dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"İyi ve kötü arkadaşın benzeri, misk taşıyanla körük çeken demirci gibidir. Misk taşıyana gelince; ya sana ondan İkram eder, ya sen ondan satın alırsın, ya da ondan güzel bir koku koklamış olursun. Körük çeken demirciye gelince; ya senin elbiseni yakar, ya da sen ondan kötü koku koklamak zorunda kalırsın.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 198, text: "Ebu Hureyre (r.a)'dan, Resûlülîah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  ALİMLERE HÜRMET GÖSTERMEK \"Kadın, dört şey için nikah edilir: Malı için, soyu sopu için, güzelliği için ve dindarlığı için. Dindar olanını seç ki, mutlu olasın-ellerin topraklansın.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 199, text: "Ibn-i Abbas (r.a)'dan, Resûlüllah (s.a.v)'in Cebrail'e şöyle dediği rivayet edilmiştir: \"Seni, Önceki ziyaretlerinden daha fazla bizi ziyaret etmene engel olan da ne? Bunun üzerine şu ayet İndi: Biz-elçiler, ancak senin Rabbinin izni ile ineriz. Önümüzde, arkamızda ve her ikisinin arasında ne varsa hepsi O'nundur.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 200, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kişi, dostunun dini üzeredir. O halde herkes, kimi dost edindiğine -iyi- baksın.\" (Ebu Davud ve Tirmizi sahih bir İsnatla rivayet etmiştir. Tirmizi ise hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 201, text: "Ibn-i Mes'ud (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam Resûlüllah (s.a.v)'e gelip şöyle dedi: 'Bir toplumu sevdiği halde onlara katılamayan kişi hakkında ne dersiniz?' Resûlüllah (s.a.v) şöyle buyurdu: Kişi, sevdiği ile beraberdir.\" (Buharı ve Müslim) ALLAH İÇİN SEVMEK", source: "Hadis-i Şerif" },
    { id: 202, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim de şu üç şey bulunursa, imanın tadını almış olur; Allah ve Resulü ona, diğer her şeyden daha sevimli olması, sevdiği bir kimseyi ancak Allah için sevmesi, ateşe atılmayı nasıl hoş karşılamazsa, Allah kendisini kurtardıktan sonra, tekrar küfre dönmekten nefret etmesi.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 203, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah (c.c) kıyamet günü şöyle buyuracak: Benim rızam için birbiriyle sevişenler neredeler?  ALLAH İÇİN SEVMEK Kendi gölgemden başka hiçbir gölgenin bulunmadığı bu gün, onları kendi gölgemde -Arş'ın gölgesinde- gölgelendireceğim.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 204, text: "Ebu Hureyre (r.a)'dan, Resûlüilah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Nefsim -kudret- elinde bulunana yemin ederim ki, iman etmedikçe cennete giremezsiniz. Birbirinizi sevmedikçe de iman etmiş olamazsınız. Yaptığınız takdirde birbirinizi seveceğiniz bir şeyi size haber vereyim mi? Aranızda selâmı yayınız,\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 205, text: "Berâ b. Âzib (r.a) 'dan, Resûlüillah (s.a.v)'in Ensar hak kında şöyle buyurduğu rivayet edilmiştir: \"Onları ancak mü'min sever; onlara ancak münafık kin besler. Kim onları severse, Allah da onu sever. Kim de onlara kin tutarsa, Allah da ona buğzeder-kızar.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 206, text: "Muaz (r.a)'dan, şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) elimi tuttu ve dedi ki: 'Ey Muaz, Allah'a yemin olsun ki seni seviyorum.' Sonra Ey Muaz, her namazın akabinde hiç terk etmeden şu duayı okumanı sana tavsiye ediyorum: Allah'ım, seni zikretmek, sana şükretmek ve sana güzel güzel ibadet etmek hususunda bana yardımcı ol.\" (Ebu Davud ve Neseî sahih bir isnatla rivayet etmiştir.) ALLAH'IN KULUNU SEVMESİNİN ALAMETLERİ VE 0 ALAMETLERLE AHLAKLANMAK", source: "Hadis-i Şerif" },
    { id: 207, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yüce Allah şöyle buyurdu: Kim benim dostlarımdan birine düşmanlık yaparsa, hiç şüphesiz ona harp açarım. Kulum bana, kendisine farz kıldığım ibadetlerden daha sevimli hiçbir şeyle yaklaşamaz. Kulum bana, nafile ibadetleri yaparak yaklaşmayı sürdürür, sonunda ben onu severim. Onu sevdiğim zaman da, İşiten kulağı, gören gözü, tutan eli ve yürüyen ayağı olurum. Benden bir şey isterse onu veririm ve bana sığınacak olsa, mutlaka onu korurum.\" (Buharı)  ALLAH'IN KULUNU SEVMESİNİN ALAMETLER VE ALAMETLERLE...", source: "Hadis-i Şerif" },
    { id: 208, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yüce Allah bir kulu sevdiği zaman Cebrail'i seslenir; 'Allah (c.c) falanı seviyor, o halde sen de sev' buyurur. Böylelikle o kulu Cebrail de sever ve gök ehline seslenir; 'Allah (c.c) falanı seviyor, ben de seviyorum, o halde siz de sevin' der. Böylelikle onu gök ehli de sever. Sonra da onun kabulü-sevgisi- yeryüzüne yerleşir,\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 209, text: "Hz. Âişe (r.a)'dan, şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)- askeri- birliğin başına bir adamı göndermiş idi. Bu kişi, namazda arkadaşlarına Kur'an okur ve İhlas -Kul hüvellahü ehad-sûresi ile bitirirdi. Birlik döndüğü zaman, bu durumu Resûlallah (s.a.v)'e ilettiler. O da şöyle buyurdu: 'Ona sorun bakalım; niçin böyle yapmıştır?' Ona bunu sorduklarında dedi ki: 'Çünkü o sûre, Rahmân'ın sıfatıdır. Bundan dolayı ben, onu okumayı seviyorum.' Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Ona haber verin; şüphesiz Allah da onu sevmektedir.\" (Buhari ve Müslim)   İYİLERE, ZAYIFLARA VE YOKSULLARA EZİYET ETMEKTEN SAKINDIRMA", source: "Hadis-i Şerif" },
    { id: 210, text: "Cündüb b. Abdullah (r.a)'dan, Resûlüllah (s.a.v)in şöyle buyurduğu rivayet edilmiştir: \"Kim sabah namazını kılarsa, o kişi Allah'ın koruması altındadır. Sakın Allah sizden, zimmetinden dolayı bir şey istemesin. Çünkü O, zimmetinden dolayı kimden bir şey isterse onu yakalar, sonra da onu yüz üstü cehennem ateşine atar.\" (Müslim) İNSANLARIN ZAHİRİNE BAKARAK HÜKÜM VERMEK, GİZLİ HALLERİNİ ALLAH'A HAVALE ETMEK", source: "Hadis-i Şerif" },
    { id: 211, text: "İbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  İNSANLARIN ZAHİRÎNE BAKARAK HÜKÜM VERMEK \"İnsanlarla, Allah'tan başka ilah olmadığına ve Muhammed'in O'nun peygamberi olduğuna şehadet edinceye, namaz kılıncaya ve zekat verinceye kadar savaşmakla emredildim. Bunları yaptıkları zaman, İslam'ın hakkı hariç, kanlarını ve mallarını benden korumuş olurlar. Onların -gizli hallerinin- hesabı ise Allah'a aittir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 212, text: "Ebu Abdullah Târik b. Üşeym (r.a)'dan, Resûlüllah (s.a.v)'i şöyle söylerken işittiği rivayet edilmiştir: \"Kim, 'Allah'tan başka ilah yoktur' deyip, Allah'tan başka tapınılanları inkar ederse, o kimsenin malı ve kanı haramdır. Gizli hallerinin hesabı ise, Allah'aittir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 213, text: "Abdullah b.Utbe b. Mes'ud (r.a)'dan, Ömer b. Hattâb (r.a)'ı şöyle söylerken işittiği rivayet edilmiştir: \"İnsanlar, Resûlüllah (s.a.v) devrinde vahiy ile sorgulanırdı. Oysa artık vahiy kesilmiştir. Dolayısıyla şimdi biz sizi, açığa çıkan amellerinizle sorguluyoruz. Artık kim bize hayır gösterirse, onu emin kabul ederiz ve ona yaklaşırız.   Onun gizli hallerini araştırmak üzerimize vazife değildir. Allah onu, gizli halleri sebebiyle sorguya çeker. Kim de bize kötülük gösterirse, ona güvenemeyiz. Her ne kadar, sakladıklarının güzel şeyler olduğunu söylese de, onu tasdik edemeyiz.\" (Buharı) . ALLAH'TAN KORMAK", source: "Hadis-i Şerif" },
    { id: 214, text: "İbn-i Mes'ud (r.a)'dan, şöyle rivayet edilmiştir: \"Doğru ve doğruluğu herkesçe tasdik edilen Resûlüllah (s.a.v), bize şunları anlatı: Sizden birinizin yaratılması, annesinin karnında kırk gün nutfe olarak toplanır. Sonra, bu kadar bir süre içinde pıhtılaşmış kan olur. Sonra, bu kadar daha bir sürede et parçası halini alır. Sonra bir melek gönderilir; ona ruh üfler ve şu dört kelimeyi; Rızkını, ecelini, amelini ve iyi mi yoksa kötü mü olacağını yazmakla emredilir. Kendinden başka ilah olmayana yemin ederim ki, sizden biriniz cennet ehlinin ameli gibi amel yapar, hatta kendisi ile cennet arasında bir arşın kadar bir mesafe kalır, ama -kader- yazısı öne geçer, bu sefer cehennem ehlinin ameli gibi amel yapar ve cehenneme girer,  ALLAH'TAN KORMAK Sizden biri, cehennem ehlinin ameli gibi amel yapar, hatta kendisi ile cehennem arasında bir arşın bir mesafe kalır, ama -kader- yazısı öne geçer, bu sefer cennet ehlinin ameli gibi amel yapar ve böylelikle cennete girer.\" (Buharı ve Müslim) .", source: "Hadis-i Şerif" },
    { id: 215, text: "Ibn-i Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kıyamet günü cehennem, yetmiş bin dizgini ve herbir dizgin ile beraber onu çeken yetmiş bin melek bulunduğu halde -ortaya-getirilir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 216, text: "Nûman b. Beşîr (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğunu işttiği rivayet edilmiştir: \"Kıyamet günü ateş ehlinin en hafif azap edileni, iki ayağının -taban- boşluğuna beynini kaynatacak derecede ateşten iki kor koyulanıdır. Hiçbir kimsenin kendisinden daha şiddetli bir azaba çaptırıldığım kabul etmez. Oysa kendisi, onların en hafif azap edilenidir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 217, text: "Semure b Cündüb (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Onlardan bir kısmını cehennem ateşi topuğuna kadar, bir kısmını dizlerine kadar, bîr kısmını beline kadar, bir kısmını da boynu na kadar sarar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 218, text: "Ibn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İnsanlar, Âlemlerin Rabbine -hesap vermek- için kabirlerinden kalkarlar. Öyle ki, onların bir kısmı kulaklarının yarısına kadar ter içinde kaybolur.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 219, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kıyamet günü insanlar o kadar terlerler ki, terleri yetmiş arşın yerin içine işler.  ALLAH'TAN KORMAK Kulaklarına varıncaya kadar ter onları kaplar.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 220, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Biz Resûlüllah (s.a.v) ile beraberken birden bir gürültü duyduk. Resûlüllah (s.a.v); 'Bu gürültünün ne olduğunu biliyor musunuz?' diye sordu. Biz de dedik ki: 'En iyi Allah ve Resulü bilir.' Buyurdular ki: Bu, yetmiş sene önce cehenneme atılan bir taştır; şu ana kadar durmadan ateşe yuvarlanıyordu. Sonunda cehennemin dibine ulaştı, siz de onun gürültüsünü işittiniz.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 221, text: "Ebu Berze b. Ubeyd el- Eslemî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kıyamet günü hiç bir kul, ömrünü nerede tükettiğinden, ilmiyle ne amel yaptığından, malını nereden kazanıp nereye harcadığından, bedenini nerede ve nasıl yıprattığından sorguya çekilmeden bir adım attırılmaz.\" (Tirmizi rivayet etmiş ve Hadis hasendir, sahihtir demiştir.)   ALLAH'IN RAHMETİNİ UMMAK", source: "Hadis-i Şerif" },
    { id: 222, text: "Übâde b. Sâmit (r.a)'dan, Resâiüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim, ortağı olmayan Allah'tan başka ilah olmadığına ve Mu- hammed'in, O'nun kulu ve elçisi olduğuna, İsa'nın Allah'ın kulu ve elçisi, Meryem'e bıraktığı kelimesi ve Allah'tan -gelen-bir ruh ol duğuna, cennetin hak olduğuna, cehennemin gerçek olduğuna şeha- det ederse, Allah o kişiyi ameline göre cennetine koyar.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 223, text: "Ebu Zer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah (c.c) şöyle buyuruyor: Kim bir iyilik işleyerek gelirse, ona on kat sevap vardır, ya da daha artırırım. Kim bir kötülükle gelirse, onun da cezası sadece bir kötülük kadardır, ya da affederim. Kim bana bir karış yaklaşırsa, ben ona bir arşın yaklaşırım. Kim ba-  ALLAH'IN RAHMETİNİ UMMAK na bir arşın yaklaşırsa, ben ona bir kulaç yaklaşırım. Kim bana yürüyerek gelirse, ben ona koşarak giderim. Kim bana, şirk koşmadan yeryüzü dolusu kadar hatalarla kavuşursa, ben de kendisini bir o kadar bağışla karşılarım.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 224, text: "Câbir (r.a)'dan, şöyle rivayet edilmiştir: \"Bir bedevî Resûlüllah (s.a.v)'e gelerek dedi ki: 'Ey Allah'ın Resulü - cehenneme girmeyi- gerektiren sebepler nelerdir? Resûlüllah (s.a.v) şöyle buyyurdu: Kim Allah'a şirk koşmadan ölürse cennete girer; kim O'na şirk koştuğu halde ölürse ateşe girer.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 225, text: "Ömer b. Hattab (r.a.)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'in huzuruna bir grup esir getirilmişti. Birden, esirlerin arasından bir kadın koşmaya başladı. Çünkü esirler arasında bir çocuk bulmuştu; onu tuttu, bağrına bastı ve hemen emzirdi. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Bu kadın çocuğunu ateşe atar mı, ne dersiniz? Dedik ki: 'Allah'a yemin olsun ki hayır-atamaz!' Bu sefer Resûlüllah (s.a.v) şöyle buyurdu:   Allah kullarına, bu kadının çocuğuna olan merhametinden daha çok acıyı cıdır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 226, text: "Ebu Hureyre (r.a)'dan, Resûlüilah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Allah, yaratıkları yarattığında Arş'ın üzerinde kendi katındaki bir kitaba; 'Muhakkak rahmetim, öfkeme galip gelmiştir. ' diye yazmıştır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 227, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Nefsim -kudret- elinde olan Allah'a yemin olsun ki, eğer siz hiçbir günah işlememiş olsaydınız, Allah sizi gönderir, akabinde de günah işleyen, ama Allah'dan af dileyen ve Allah'ın da kendilerini affettiği bir toplumu -sizin yerinize- getirirdi.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 228, text: "Ebu Eyyub Halid b. Zeyd (r,a)'dan şöyle rivayet edilmiştir; \"Resûlüilah (s.a.v)'i şöyle buyururken işittim: Eğer siz günah işlememiş olsaydınız, elbette Allah günah işleyen kimseler yaratırdı.  ALLAH'IN RAHMETİNİ UMMAK Onlar Allah'dan bağışlanmalarını isterler, O da onları bağışlardı,\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 229, text: "Ebu Hureyre (r.a)'ın şöyle dediği rivayet edilmiştir: \"Biz Resûlüllah (s.a.v) ile birlikte oturuyorduk. Bizimle beraber toplulukta Ebu Bekir, Ömer (r.a) da bulunuyordu. Birden Resûlüllah (s.a.v) kalkıp aramızdan ayrıldı. Yanımıza dönmesi gecikince, bir şey oldu sanarak telaşlandık, korktuk ve hep beraber ayağa kalktık. Korkup telaşlananların ilki ben idim. Hemen Resûlüllah (s.a.v)'i aramağa koyuldum. Nihayet Ensar'a ait bir -bahçe-duvarına gelmiştim.\" Rivayeti yapan zat, hadisi uzunca anlattıktan sonra sözü Resûlüllah (s.a.v)' in şu sözüne getirdi: \"Git, şu duvarın arkasında karşılaştığın Allah'tan başka ilah olmadığına kalben inanan herkesi cennetle müjdele!\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 230, text: "Muaz b. Cebel (r.a)'dan şöyle rivayet edilmiştir; \"Ben, merkep sırtında Peygamber (a.s)'ın arkasında bulunuyordum. Şöyle buyurdu: Ey Muaz, Allah'ın kulları üzerindeki hakları ile kulların Allah üzerindeki hakları nelerdir, biliyor musun? Dedim ki: 'Allah ve Resulü en iyi bilir.' Buyurdu ki: Allah'ın kullar üzerindeki hakları; O'na ibadet etmeleri ve kendisine hiçbir şeyi ortak koşmamalarıdır. Kulların Allah üzerindeki hakkına gelince; Allah'a ortak koşmayan kimseye azap etmemesdir. Ben de dedim ki: 'Ey Allah'ın Resulü, İnsanlara müjdeleyeyim mi?' Buyurdu ki: Onlara müjdeleme! Aksi halde tembellik ederler.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 231, text: "Berâ b. Âzib (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Müslüman kabirde sorgulandığında Allah'tan başka ilah olmadığına ve Muhammed'in, Allah'ın peygamberi olduğuna şehadet eder. Bu durum, şu ayetin isbatıdır: Allah iman edenleri, dünya hayatında da ahiret hayatında da o sabit sözde-Kelime-i Tevhidde- sebat ettirir,\" İbrahim: 27 (Buhari ve Müslim rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 232, text: "Câbİr (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  ALLAH'İN RAHMETİNİ UMMAK \"Beş vakit namazın misali, sizden birinizin kapısının önünde akan, her gün beş defa girip yıkandığı, suyu bol bir nehir gibidir\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 233, text: "İbn-i Abbas (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim: Hangi bir müslüman ölür de, cenazesi üzerine Allah'a hiçbir şeyi ortak koşmayan kırk kişi -namaza- durursa, Allah o insanları ölen o kişiye şefaatçi kılar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 234, text: "İbn-i Mes'ud (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam kadının birini öpmüş, sonra da durumu gelip Resûlüllah (s.a.v)'e haber vermişti. Allah (c.c) hemen şu ayeti indirdi: 'Gündüzün her iki tarafında ve gecenin -gündüze- yakın saatlerinde namaz kıl; şüphesiz ki iyilikler, kötülükleri giderir.' Hud:114 O adam dedi ki: 'Ey Allah'ın Resulü, bu hüküm sırf benim için mi?' Resûlüllah şöyle buyurdu: Ümmetimin hepsi için gecerlidir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 235, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah (c.c) şöyle buyuruyor: Ben, kulumun bana olan zannı üzereyim. Beni nerede anarsa, onunla beraberim. Vallahi, kulunun tevbe etmesinden dolayı Allah'ın sevinci, sizden birinizin ıssız bir çölde kaybettiği hayvanını bulduğundaki sevincinden daha fazladır. Kim bana bir karış yaklaşırsa, ben ona bir arşın yaklaşırım. Kim bana bir arşın yaklaşırsa, ben ona bir kulaç yaklaşırım. Bana yürüyerek gelirse, ben ona koşarak giderim.\" (Buhari ve Müslim. Bu, Müs lim'in rivayetlerinden birinin lafızıdır.)", source: "Hadis-i Şerif" },
    { id: 236, text: "Câbir b. Abdullah (r.a)'ın, Resûlüllah (s.a.v)'in vefatından üç gün önce şöyle buyurduğunu işittiği rivayet edilmiştir: \"Sizden biriniz, Allah (c.c.) hakkında hüsn-ü zan etmedikçe sakın ölmesin.\" (Müslim)  KORKU İLE ÜMİT ARASINDA OLMAK", source: "Hadis-i Şerif" },
    { id: 237, text: "Enes (r.a)'dan, Resûlüllah (s.a.v) 'in şöyle buyurduğu rivayet edilmiştir: \"Allah (c.c) şöyle buyurdu: Ey Adem oğlu, sen bana dua ettiğin ve affımı ümid ettiğin sürece, hiç aldırmam senin günahını affederim. Ey Adem oğlu, şayet senin günahın gökleri dolduracak kadar çok olsa, sonra benden af dilesen, hiç aldırmam seni affede rim. Ey Adem oğlu, eğer sen bana yeryüzü dolusu hatalarla gelsen, yeter ki bana hiçbir şeyi ortak koşma, ben de sana yeryüzü dolusu bağışlama ile gelirim.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.) KORKU İLE ÜMİT ARASINDA OLMAK", source: "Hadis-i Şerif" },
    { id: 238, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Mü'min, eğer Allah'ın katındaki azabı bilseydi, hiç biri cenneti ümit edemezdi. Kafir de eğer Allah'ın katındaki rahmeti bilseydi, hiç biri cennetinden ümit kesmezdi.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 239, text: "Ebu Saîd el- Hudrî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Cenaze -tabuta- konup da insanlar -veya erkekler- onu omuzlarına yüklediklerinde, eğer iyi bir kimse ise der ki: 'Beni çabuk yerime ulaştırın, beni çabuk yerime ulaştırın!' Eğer kötü bir kimse ise der ki: 'Eyvah! Nereye götürüyorsunuz!' Onun bu çığlığını insanların dışında herşey işitir. Eğer insanlar onu işitse, bayılıp düşerdi.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 240, text: "İbn-i Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Cennet, sizden birinize ayakkabısının bağından daha yakındır. Ateş de aynı şekildedir.\" (Buhari) ALLAH KORKUSUNDAN AĞLAMAK", source: "Hadis-i Şerif" },
    { id: 241, text: "Ibn-i Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in kendisine şöyle dediği rivayet edilmiştir:  ALLAH KORKUSUNDAN AĞLAMAK \"Resûlüllah (s.a.v) 'Bana Kur'an oku' dedi. Ben de dedim ki: 'Ey Allah'ın Resulü, Kur'an size inidirilmiş iken ben mi size Kur'an okuyacağım?' Şöyle buyurdu: 'Ben Kur'an'ı başkasından dinlemeyi çok seviyorum.' Bunun üzerine kendisine Nisa sûresini okudum. Nihayet 'Her ümmetten birer şahit getirip, seni de onların üzerine şahit getirdiğimizde onların halleri ne olacak?' (Nisa: 41) âyetine geldiğimde buyurduki: 'Şimdilik bu kadar -okumak- sana kafidir.' Ona döndüğümde, bir de baktım ki gözleri yaş döküyor.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 242, text: "Enes (r.a)'ın şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bize Öyle bir hutbe okudu ki, şimdiye kadar böylesini hiç işitmemiştim. Buyurdu ki: 'Eğer benim bildiğimi bilseydiniz, elbette az güler çok ağlardınız.' Enes dedi ki: Bunun üzerine Resûlüllah'ın ashabı yüzlerini Örttüler ve çok ağladılar.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 243, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah korkusundan dolayı ağlayan kişi, süt memeye geri dönmedikçe ateşe girmez. Allah yolunda bulaşan toz ile cehennemin   dumanı bir arada toplanmaz.\" (Tirmizi rivayet etmiş ve Hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 244, text: "Abdullah b. Şihhîr (r.a)'dan söyle rivayet edilmiştir: \"Allah Resulünün yanına gelmiştim; o ise namaz kılıyordu. Ağlamaktan dolayı göğsünden, tencerenin kaynama sesi gibi ses geliyordu.\" (Ebu Davud rivayet etmiştir, Tirmizi ise; Şemail'de sahih bir isnatla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 245, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Resûlüllah (s.a.v), Übey b. Ka'b (r.a)'a şöyle dedi: 'Allah (c.c) sana, Lem yekünillezîne Keferû... sûresini okumamı emretti.' Übeyy dedi ki: İsmimi de andı mı? Resûlüllah buyurdu ki: 'Evet.' Bunun üzerine Übeyy ağlamaya başladı.\" (Buharı ve Müslim)  ALLAH KORKUSUNDAN AĞLAMAK", source: "Hadis-i Şerif" },
    { id: 246, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a,v)'ın ağrısı şiddetlenince, kendisine namazın kim tarafından kıldırılacağı soruldu. Buyurdu ki: 'Ebu Bekir'e emrimi söyleyin, insanlara namazı kıldırsın.' Hz. Âişe (r.a); 'Ebu Bekir çok hassas insandır, Kur'an okuduğu zaman kendisini bir ağlama kaplar.'dedi. Resûlüllah (s.a.v) buyurmuştur ki: Ona emrimi söyleyin, namazı kıldırsın.\"", source: "Hadis-i Şerif" },
    { id: 247, text: "Ebu Ümame Suday b. Aclân el-Bahîlî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah (c.c) göre hiçbir şey, iki damladan ve iki izden daha sevimli değildir; bunlar- Allah korkusundan dolayı akıtılan göz yaşı ile Allah yolunda dökülen kan damlasıdır. İki ize gelince; Allah yolunda -savaşırken- alınan -yara- izi ile Allah (c.c)'in farzlarından bir farz yerine getirilirken oluşan izdir.\" (Tirmizi rivayet etmiş ve Hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 248, text: "îrbâz b. Sâriye (r.a)'in şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bize öyle bir nasihatta bulundu ki, ondan dolayı kalpler ürperdi, gözler yaşardı.\"   DÜNYA MALINA RAĞBET ETMEK", source: "Hadis-i Şerif" },
    { id: 249, text: "Ömer b. Avf el- Ensarî (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v), Ebâ Ubeyde b. El- Cerrah (r.a)'ı Bahreyn'e cizyelerini almak için gönderdi. Bahreyn'den bir miktar mal ile geri döndü. Ensar, Ebu Ubeyde'nin döndüğünü işitince, sabah namazını Resûlüllah (s.a.v) ile beraber kılmaya geldiler. Resûlüllah (s.a.v), namazı kılınca döndü -gidiyordu ki- hemen O'nun önüne durdular. Resûlüllah (s.a.v) onları böyle görünce gülümsedi, sonra şöyle buyurdu: 'Sanıyorum, Ebu Ubeyde'nin Bahreyn'den birşeylerle döndüğünü işittiniz.' Dediler ki: 'Evet, Ey Allah'ın Resulü.' Bu sefer şöyle buyurdu: Müjde! Sizi sevince gark edecek şeyleri bekleyin! Allah'a yemin olsun ki, sizin için fakirlikten korkmuyorum; ama tıpkı sizden öncekilere serildiği gibi sizin önünüze de dünya malının serilmesinden, onların -dünya malına- rağbet ettikleri gibi sizinde ona rağbet ederek, onların helak oldukları gibi sizin de helak olmanızdan korkuyorum.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 250, text: "Ebu Saîd el- Hudrî (r.a.)'dan, şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) minber üzerine oturdu, biz de etrafında oturuyorduk. Buyurdu ki: Benden sonra sizin İçin taşıdığım endişe; dünya zinetlerinin ve süslerinin üzerinize -saçılıp- açılmasıdır.\" (Buharı ve Müslim)  DÜNYA MALINA RAĞBET ETMEK", source: "Hadis-i Şerif" },
    { id: 251, text: "Ebu Saîd el-Hudrî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Dünya tatlı ve güzel manzaralıdır. Şüphesiz ki Allah, sizi oraya halife yapacak ve nasıl hareket edeceğinize bakacaktır. O halde dünyadan sakının, kadınlardan sakının.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 252, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah'ım! Hayat ancak ahiret hayatıdır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 253, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Üç şey ölünün peşinden gider; ailesi, malı ve ameli. İkisi geri döner, biri kalır. Ailesi ve malı geri döner ve ameli -ile başbaşa-kalır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 254, text: "Müstevrid b. Şeddâd (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ahirete göre dünyanın misali, sizden birinin deryaya parmağını daldırıp çıkarması gibidir. Baksın bakalım -parmağı- ne kadar -su- ile geri dönebilecektir?\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 255, text: "Cabir (r.a)'dan, şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v), beraberindeki insanlarla birlikte çarşıya uğramıştı. Kısa kulaklı bir oğlak ölüsüne rastladı. Yanına varıp kulağından tuttu, sonra da şöyle buyurdu: 'Hanginiz bunun bir dirhem karşılığında kendisinin olmasını ister?' Dediler ki: 'Onun bir şey karşılığında bizim olmasını istemeyiz, onu ne yapabilirizki? Resûlüllah (s.a.v) sonra şöyle buyurdu: 'Onun sizin olmasını ister misiniz?' Dediler ki: 'Allah'a yemin olsun ki, diri bile olsa yine de ayıplıdır, onun kulağı kesiktir. Ölü hali ile nasıl-alalım?' Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Allah'a yemin olsun ki, Allah'a göre dünya, yanınızdaki bu -oğlak Ölüsünden- daha değersizdir.\" (Müslim)  DÜNYA MALINA RAĞBET ETMEK", source: "Hadis-i Şerif" },
    { id: 256, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Eğer benim Uhud dağı kadar altınım olsa, borç için alıkonulanı hariç, ondan bende bir şey bulunduğu halde üzerimden üç gecenin geçmemesi beni mutlu eder,\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 257, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Altının, gümüşün, kadifenin ve yünlü kumaşın kulu -olan-helak oldu. Eğer kendilerine -bunlar- verilirse hoşnut olur, verilmezse hoşnut olmazlar.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 258, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Suffe ehlinden yetmiş kişi gördüm; onlardan hiçbirinde hırka yoktur. Ya bir gömlek, ya da kısa bir örtü vardı; onları da- boyunlarına bağlamışlardı. Giydiklerinin bir kısmı diz kapaklarına kadar ulaşır, bir kısmı da topuklara kadar ulaşırdı. Avret yerlerinin görünmesini istemedikleri için onu eliyle toplayıp bir araya getiriyordu.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 259, text: "Hz. Âişe (r.a) demiştir ki: \"Resulüllah (s.a.v) vefat ettiğinde, benim rafımda birazcık arpadan başka bir canlının yiyeceği hiçbir şey bulunmuyordu. Uzun zaman hep onu yedim; sonunda ölçtüğümde tükenivermişti.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 260, text: "Sehl b. Sa'd es-Sâidi (r.a)'dan, Resulüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Eğer dünyanın Allah indinde sivrisineğin kanadı kadar bir değeri olsaydı, kafire ondan bir yudum su bile içirmezdi.\" (Tirmizi rivayet etmiş ve Hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 261, text: "Abdullah b. Mes'ud (r.a)'dan, Resulüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir takım akarlar -dünya malı- edinmeyiniz; sonra dünyaya dalarsınız.\" (Tirmizi rivayet etmiş ve Hadis hasendir demiştir.)  DÜNYA MALINA RAĞBET ETMEK", source: "Hadis-i Şerif" },
    { id: 262, text: "Ka'b b. lyâz (r.a), Resûlüllah (s.a.v)'ın şöyle söylediğini işittiğini söylemiştir: \"Her ümmet için bir fitne-imtihan- vardır; benim ümmetimin fitnesi de maldır.\" (Tirmizi rivayet etmiş ve Hadis hasendir, sahihtir demiştir.) AÇLIĞIN, SADE HAYATIN, NEFSİN ARZULARINI TERK ETMENİN FAZİLETLERİ", source: "Hadis-i Şerif" },
    { id: 263, text: "Hz. Âişe (r.a) demiştir ki: \"Muhammed (as.)'ın ailesinin karnı peşpeşe iki gün arpa ekmeği ile doymamış; nihayet bu dünyadan göçüp gitmiştir,\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 264, text: "Ebu Saîd el-Makberî, Ebu Hureyre (r.a)'dan şöyle rivayet etmiştir: \"Ebu Hureyre (r.a), önlerinde koyun kebabı bulunan bir kavmin yanından geçerken onu yemeğe davet ettiler. Yemekten yüz çevirdi ve dedi ki: Resûlüllah (s.a.v)t arpa ekmeğinden doymadan bu dünayadan çıkıp gitti.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 265, text: "Nûman b. Beşîr (r.a) şöyle demiştir: \"Ben sizin Peygamberinizi (s.a.v), karnını doyuracak kadar âdî hurmayı bile bulamadığına şahit oldum.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 266, text: "Sehl b. Sa'd (r,a) şöyle demiştir: \"Resûlüllah (s.a.v), Yüce Allah'ın kendisini peygamber olarak gönderdiği zamandan ruhunu alıncaya kadar eleklenmiş un görmemiştir. Sehl'e; 'Resûlüllah (s.a.v) zamanında sizin elekleriniz var mıydı?' diye sorulduğunda şöyle dedi: 'Resûlüllah (s.a.v), Allah kendisini peygamber olarak gönderdiği zamandan, Allah onun ruhunu alıncaya kadar elek görmemiştir.' Sehl ’e denildi ki: 'Eleklenmemiş unu nasıl yiyiyordunuz?' O da şöyle dedi: Biz onu öğütüp savururduk. Uçan -kepek- uçardı; geriye kalanı da ıslatıp hamur yapardık.\" (Buharı)  AÇLIĞIN, SÂDE HAYATIN, NEFSİN ARZULARINI TERK ETMEK", source: "Hadis-i Şerif" },
    { id: 267, text: "Ebu Musa el-Eşarî (r.a) şöyle demiştir: \"Hz. Âişe bizim karşımıza kalım bir gömlek ve peştamal çıkarıp -gösterip- şöyle demiştir: Resûlüllah (s.a.v) bunların içinde iken ruhu alındı.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 268, text: "Sa'd b. Ebu Vakkâs (r.a) şöyle demiştir: \"Ben, Allah yolunda ok atan ilk Arabım. Andolsun ki, Resûlüllah (s.a.v) ile birlikte savaşırdık da asma yaprağından başka bir yiyeceğimiz olmazdı. Hatta birimiz def-i hacetini yaptığında, koyun gibi katı, birbirine karışmayan def-i hacet yapardı.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 269, text: "Muhammed b. Sîrîn, Ebu Hureyre (r.a)'dan şöyle rivayet etmiştir: \"Ben kendimi, Resûlüllah (s.a.v)'in minberi İle Hz.Âİşe (r.a)'ın odası arasında bayılıp yere düşmüş gördüm. Gelip geçen ayağını boynuma basıyordu. Beni deli sanıyor, ama bende açlıktan başka delilikten yana bir belirti yoktu.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 270, text: "Enes (r.a) şöyle demiştir: \"Resûlüllah (s.a.v) zırhını, arpa karşılığında rehin bırakmıştı. Ben, Resûlüllah (s.a.v)'e arpa ekmeği ile erimiş bayat iç yağı götürdüm. Andolsun ki ben O'nun şöyle buyurduğunu işitmişimdir: Muhammed ailesi dokuz hane olduğu halde, bir sa' yiyecek ile ne sabahladı, ne de akşamladı!\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 271, text: "Ebu Hureyre (r.a) şöyle demiştir: \"Suffe ehlinden yetmiş kişi gördüm; onlardan hiç birinin üzerinde hırka yoktu. Ya uzun bir gömlek, ya da vücuda sarılan peşte-mal türü bir giyecek vardı; uçlarını boyunlarına bağlıyorlardı. Onların kimi diz kapaklara, kimi de topuklara kadar uzanıyordu. Avret yerlerinin görünmesini istemediklerinden dolayı -elbisenin uçlarını- elleriyle bir araya topluyorlardı.\" (Buhari)  AÇLIĞIN, SÂDE HAYATIN, NEFSİN ARZULARINI TERK ETMEK", source: "Hadis-i Şerif" },
    { id: 272, text: "Ebu Umame (r.a)'dan, Resûlüllah (s.a,v)'in şöyle buyurduğu rivayet edilmiştir: \"Ey Âdem oğlu, İhtiyacından fazla olanı dağıtman hakkında hayırlı, onu yanında tutman ise hakkında kötülüktür. Sana yetecek kadar-dünyalıktan- dolayı k ınanmazsın. Dağıtmaya ise, bakmakla yükümlü olduğun yakınlarından bağışla.\" (Tirmizi rivayet etmiş ve hadis basendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 273, text: "Abdullah b. Ömer b. Âs (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Müslüman olup da kendisine yetecek kadar rızkı bulunan ve Allah'ın kendisine lütfettiği nimetlere kanaat getiren kimse muhakkak kurtuluşa ermiştir.\" (Müslim) KANAAT ETMEK, SADAKA VERMEK VE MECBUR OLMADIKÇA DİLENMEMEK", source: "Hadis-i Şerif" },
    { id: 274, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Zenginlik, mal çokluğundan değildir. Esas zenginlik gönül zenginliğidir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 275, text: "Abdullah b. Amr (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Müslüman olup da kendisine yetecek kadar rızkı bulunan ve Allah'ın kendisine ihsan ettiğine kanaat eden kimse kurtuluşa ermiştir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 276, text: "Hakîm b. Hızâm (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Üstteki el, alttaki elden -veren el isteyen elden- daha hayırlıdır. Dağıtmaya, bakmakla yükümlü olduğun kimselerden başla. Sadakaların en hayırlısı, mal çokluğundan verilenidir. Kim bir şey istemekten utanırsa, Allah kendisini iffetli kılar. Kim kendini muhtaç hissetmezse, Allah da onu zengin kılar.\" (Buhari ve Müslim, Bu Bu-hari'nin lafzıdır. Müslim'in lafzı İse çok kısadır.)", source: "Hadis-i Şerif" },
    { id: 277, text: "İbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  KANAAT ETMEK, SADAKA VERMEK VE MEÇ. OLMADIKÇA DİLENMEMEK \"Resûlüllah (s.a.v) minberde, sadakanın fazileti ve dilenmekten kaçınma hakkında birşeyler anlatırken şöyle buyurdu: Üstteki el, alttaki elden daha hayırlıdır. Üstteki el; hayra- harcayandır. Alttaki el ise; isteyen eldir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 278, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim mal artırmak için insanlardan dilenirse, o sadece ateş dilenmiş olur. Artık isterse dilenmeyi artırsın, isterse azaltsın.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 279, text: "îbn-i Mes'ud(r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kime bir yokluk isabet eder de onu insanlara açarsa, yokluğu düzelmez. Kim de onu Allah'a arz ederse, Allah'ın ona er veya geç bir rızık kapısı açacağı umulur.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 280, text: "Sevbân (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bana, insanlardan hiçbir şey istemeyeceğine söz verirse, ben de onun cennete girmesine kefil olurum. Sevbân dedi ki: Ben, bundan sonra- kimseden bir şey istemedim.\" (Ebu Davud sahih bir isnatla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 281, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yoksul, insanları dolaşıp da kendisine bir iki lokma ve bir iki hurma verdiğin kimse değildir. Asıl yoksul, kendisini ihtiyaçsız kılacak bir varlık bulamayan, hali anlaşılıp da kendisine sadaka verilemeyen, insanlardan bir şey dilenmek için dikilmeyen kimsedir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 282, text: "Salim b. Abdullah'tan b. Ömer'den, onun babası Abdullah b. Ömer'den, o da Hz. Ömer (r.a)'dan şöyle rivayet etmiştir:  KANAAT ETMEK, SADAKA VERMEK VE MEÇ. OLMADIKÇA DİLENMEMEK \"Resûlüllah (s.a.v) bana, ganimet malından veriyordu. Dedim ki; 'Onu, benden daha fakir olan birine veriniz.' Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Onu al! Sen göz dikmeden ve istemeden bu maldan sana bir şey verilirse, onu al ve kendi malın edin. İstersen onu ye, istersen onu sadaka olarak dağıt. Böyle bir durum yoksa, o malın peşine takılma.\" Salim dedi ki: Abdullah, hiç kimseden bir şey istemezdi, kendisine verileni de geri çevirmezdi. (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 283, text: "Ebu Abdullah Zübeyr b. Avvâm (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Sizden birinizin ipini alıp sonra dağa çıkması ve arkasına bir kucak odun yüklenerek getirip onu satması, böylelikle Allah'ın o kişinin yüzünü kızarmaktan- alıkoyması, kendisine versinler veya vermesinler insanlardan dilenmesinden daha hayırlıdır.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 284, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden birinizin sırtına bir kucak odun yüklenip-onu satması-versin veya vermesin birinden bir şey dilenmesinden daha hayırlıdır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 285, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a,v)'in şöyle buyurduğu rivayet edilmiştir: \"Davud (a.s) elinin emeğinden başka bir şey yemezdi.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 286, text: "Mikdâd b. Ma'dîkerib (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Hiçbir kimse, elinin emeğinden daha hayırlı bir yemek asla yememiştir. Zira Allah'ın peygamberi Davud (a.s) bile elinin emeğini yerdi.\" (Buharı) İYİLİK, CÖMERTLİK VE ALLAH'A GÜVENEREK HAYIR YOLLARINDA HARCAMAK T", source: "Hadis-i Şerif" },
    { id: 287, text: "İbn-i Mes'ud(r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir;  İYİLİK, CÖMERTLİK VE ALLAH'A GÜVENEREK HAYİR YOLLARINDA . \"Ancak iki kişiye imrenilir; Allah'ın kendisine mal verip de o malı Hak yolda tüketmeye muvaffak kıldığı kimse ile Allah'ın kendisine hikmet -ilim.irfan- verdiği, onunda o hikmetle hüküm verip, çevresine onu öğrettiği kimsedir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 288, text: "Cabir (r.a) demiştir ki: \"Resûlüllah (s,a.v)'den bir şey istenip de 'Hayır' dediği asla vaki olmamıştır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 289, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Yüce Allah şöyle demiştir: Ey Adem oğlu, Allah yolunda-sen harca ki sana da harcansın.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 290, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'den İslam -dini- için her ne istendiyse,   onu mutlaka vermiştir. Andolsun ki, Resûlüllah (s.a.v)'e bir adam gelmişti. Ona iki dağ arasını dolduracak kadar koyun verdi. Bu adam kavmine dönünce dedi ki: 'Ey Milletim, Müslüman olunuz. Çünkü Muhammed, fakirliğe düşeceğinden korkmayan bir adamın verdiği gibi veriyor.' Eğer bir adam, dünya-malını- elde etmek için müslüman olduysa, çok geçmeden İslam ona, dünyadan ve dünyanın üzerindeki her şeyden daha sevimli oluyordu.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 291, text: "Ömer (r.a) 'dan söyle rivayet edilmiştir: \"Resûlüllah (s.a.v) bir taksim yapmıştı. Ben dedim ki: 'Ey Allah'ın Resulü, bunların dışında bulunanlar, taksim edilen bu mala bunlardan daha layık kişilerdir.' Resûlüllah (s.a.v) şöyle buyurdu: Onlar beni, ya benden kötülükle isteyip almakla, ya da cimri olma-, dığım halde benî cimrilikle itham etmeleri arasında- serbest bıraktılar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 292, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sadaka vermek malı eksiltmez. Allah (c.c.) affeden kulun şerefini artırır. Allah (c.c) için tevazu yapan bir kişiyi, Allah (c.c) mutlaka yüceltir.\" (Müslim)  İYİLİK, CÖMERTLİK VE ALLAH'A GÜVENEREK HAYIR YOLLARINDA ...", source: "Hadis-i Şerif" },
    { id: 293, text: "Hz. Âişe (r.a) şöyle rivayet etmiştir; \"Kendileri bir koyun kesmişlerdi. Resûlüllah (s.a.v); 'Ondan-koyundan- geri ne kaldı?'buyurdu. Hz. Âişe dedi ki: 'Ondan, kürek kemiğinden başka bir şey geriye kalmadı.' Bunun üzerine Resûlülîah (s.a.v) şöyle buyurdu: O zaman, kürek kemiğinin dışındakiler -bize- kaldı.\" (Tİrmizi rivayet etmiş ve Hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 294, text: "Ebu Bekir (r.a)'in kızı Esma'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) bana dedi ki: Elini-cimrilik yaparak- bağlama; yoksa sana da -rızık kapısı- bağlanır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 295, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim, helal kazancından bir hurma sadaka verirse, kaldı ki Allah sadece temiz -helal- olanı kabul eder, Allah o sadakayı bere-ketiyle kabul eder. Sonra da onu, sizden birinizin tayını büyüttüğü   gibi, sahibi için büyütür de sonunda dağ gibi olur.\" (Buharı ve Müslim) CİMRİLİK VE MALA DÜŞKÜNLÜKTEN MEN", source: "Hadis-i Şerif" },
    { id: 296, text: "Cabir (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Zulümden kaçınınız; çünkü zulüm kıyamet günü -zulmedeni saran- karanlıklar olur. Cimrilikten de sakınınız; çünkü cimrilik sizden öncekileri helak etti. Onları birbirlerinin kanlarını akıtmaya ve haramları helal addetmeye sevk etti. \" (Müslim) BAŞKALARINI KENDİNE TERCİH VE HALKA YARDIM ETME", source: "Hadis-i Şerif" },
    { id: 297, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmişir:  BAŞKALARINI KENDİNE TERCİH VE HALKA YARDIM ETME \"İki kişinin yemeği üç kişşiye, üç kişinin yemeği de dört kişiye yeterli gelir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 298, text: "Ebu Musa (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Eş'rîler, savaşta yiyecekleri bitse veya Medine'de ki ailelerinin yiyeceği azalsa, yanlarında bulunan -erzakları- bir bezin içine toplarlar; sonra da onları bir kapla ölçüp aynı seviyede aralarında paylaşırlardı. Onlar benden, ben de onlardanım.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 299, text: "Sehl b. Sa'd (r.a) şöyle rivayet etmiştir: \"Resûlüllah (s.a.v)'e içecek bir şey getirmişler, O da ondan içmişti. Sağında bir genç, solunda ise yaşlılar vardı. Genç olana; 'Bunları o yaşlılara vermeme müsaade eder misin?' buyurdu. Genç dedi ki: 'Hayır Ey Allah'ın Resulü! Allah'a yemin ederim ki, senden gelen nasibimi kimseye -vermeye- niyetim yok. ' Bunun üzerine Resûlüllah (s.a.v) onu o gencin eline verdi.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 300, text: "Ebu Hureyre (r,a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir ara Eyyûb (a.s) çıplak olarak yıkanırken üzerine altından çekirge sürüsü üşüştü. Eyyûb (a.s) da avuçlayıp elbisesini doldurmaya başladı. Bunun üzerine Yüce Allah kendisine şöyle seslendi: 'Ey Eyyûb, ben seni şu gördüklerinden zengin kılmamış mıydım?' Eyyûb; Evet, izzetine yemin olsun ki, senin bereketinden kendimi ihtiyçsız hissedemezdim.\" (Buharı) HELALİNDEN KAZANIP, HAYIRLI YERLERE HARCAYARAK ŞÜKREDEN ZENGİN", source: "Hadis-i Şerif" },
    { id: 301, text: "Abdullah b. Mes'ud (r.a)'an, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ancak iki kişiye imrenilir. Bunlar; Allah'ın kendisine mal verip de onu Hak yolda tüketmeye muvaffak kıldığı kimse ile, Allah tarafından kendisine hikmet ilim, irfan- verilip onunla hükmeden ve onu öğreten kimsedir.\" (Buharı ve Müslim)  ÖLÜMÜ HATIRLAMAK VE ARZULARI AZALTMAK", source: "Hadis-i Şerif" },
    { id: 302, text: "İbn-i Ömer (r.a)'dan, Resûlüiiah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İki şeye imrenilir. Bunlar; Allah'ın kendisine Kur'an verip de gece gündüz onunla meşgul olan kimse ile, Allah'ın kendisine mal verip de onu gece gündüz -Allah yolunda- harcayan kimsedir.\" (Buharı ve Müslim) ÖLÜMÜ HATIRLAMAK VE ARZULARI AZALTMAK", source: "Hadis-i Şerif" },
    { id: 303, text: "İbn-i Ömer (r.a) şöyle rivayet etmiştir: \"Resûlüllah (s.a.v) omuzumu tuttu ve şöyle buyurdu: Dünyada sanki bir garip gibi veya bir yolcu gibi yaşa!\" İbn-i Ömer (r.a) şöyle derdi: Akşamladığın zaman sabahı bekleme, sabahladığın zaman da akşamı bekleme. Sıhhatli zamanından hastalıklı günlerin için, hayatından da ölümün için istifade etmeye bak. (Buharı)", source: "Hadis-i Şerif" },
    { id: 304, text: "İbn-i Mes'ud (r.a) şöyle demiştir: \"Resûlüllah (s.a.v) bir dörtgen çizdi. Ortasından dışarıya doğru bir çizgi daha çizdi. Ortada bulunan bu çizgiye doğru orta tarafından küçük bir takım çizgiler daha ekledi. Sonra şöyle buyurdu: Şu insan, şu da onu kuşatan -veya kuşatmış -ecelidir. Şu dışarıya uzanan insanın arzusudur. Şu küçük çizgiler de arızalardır. Bunların birinden kurtulsa diğeri onu yakalar. Ondan kurtulsa, bu sefer öbürü onu yakalar.\" (Buharı rivayet etmiştir. Bu, onun çizdiği bir şekildir.)", source: "Hadis-i Şerif" },
    { id: 305, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yedi şey-başınıza-gelmeden evvel acele ediniz; Yoksa siz, insana unutkanlık getiren fakirliği mi, azdıran zenginliği mi, insanın dengesini bozan hastalığı mı, aniden gelen ölümü mü, şerli gaip olarak beklenilen Deccali mi, ya da daha acıklı ve belalı kıyameti mi bekliyorsunuz?\" (Tirmizi rivayet etmiş ve Hadis hasendir demiştir.)  ÖLÜMÜ HATIRLAMAK VE ARZULARI AZALTMAK", source: "Hadis-i Şerif" },
    { id: 306, text: "Büreyde (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ben sizi kabirleri ziyaret etmekten men etmiştim; artık ziyaret edebilirsiniz.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 307, text: "Büreyde (r.a)'dan şöyle rivayet edilmiştir; \"Resûlüllah (s.a.v) arkadaşlarına, kabristana gittikleri zaman şöyle demelerini öğretiyordu: Ey ahiret yurduna göçen mü'minler, müslümanlar! Selam sizlerin üzerine olsun. înşaallah biz de sizlere kavuşacağız. Allah'dan bize de size de afiyet diliyorum.\" (Müslim) BAŞA GELEN BELADAN DOLAYI ÖLÜMÜ İSTEMEMEK", source: "Hadis-i Şerif" },
    { id: 308, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir;   \"Sizden biriniz ölümü arzulamasın. Çünkü eğer iyi biri ise iyilikleri artmış olur, eğer kötü biri ise olur ki tevbe eder.\" (Buharı ve Müslim. Bu lafız Buharı'nin lafzıdır.)", source: "Hadis-i Şerif" },
    { id: 309, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz, kendisine dokunan bir beladan dolayı ölümü arzulamasın. Eğer mutlaka yapacaksa şöyle desin: Allah'ım! Yaşam benim için hayırlı olduğu sürece beni yaşat; ölüm benim için hayırlı olduğu zaman ise beni öldür.\" (Buhari ve Müslim) GÜNAHTAN SAKINMAK VE ŞÜPHELİ ŞEYLERİ BIRAKMAK", source: "Hadis-i Şerif" },
    { id: 310, text: "Nu'man b. Beşîr (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim; Şüphesiz helal  GÜNAHTAN SAKINMAK VE ŞÜPHELİ ŞEYLERİ BIRAKMAK da bellidir, haram da bellidir. Bu ikisinin arasında insanların çoğunun bilmediği şüpheli şeyler vardır. Şimdi, kim şüpheli şeylerden kaçınırsa dinini ve ırzını kurtarmış olur. Kim de şüpheli şeylere dalarsa, harama düşer. Tıpkı korunun etrafında hayvalarını otlatan ve uçuruma düşmesi muhtemel olan çoban gibi. Dikkat edin; her hükümdarın bir korusu vardır. Dikkat edin; Allah'ın korusu da haramlarıdır. Haberiniz olsun; cesedin içinde bir parça et vardır ki, o düzgün olursa cesedin hepsi düzgün olur. Eğer o bozuksa, cesedin hepsi bozuk olur. Biliniz ki o, kalptir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 311, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) yolda bir hurma bulmuştu. Şöyle buyurdu: Eğer ben, bunun sadaka olmasından korkmasaydım mutlaka onu yerdim.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 312, text: "Nevvâs b. Sem'an (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İyilik güzel ahlaktır. Günah ise, içine bir şüphe düşüren ve insanların haberdar olmalarını istemediğin şeydir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 313, text: "Hasan b. Ali (r,a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'den şunu ezberledim: Seni şüpheye düşüren şeyi, şüphe vermeyen şeyle değiş.\" (Tirmizi rivayet etmiş ve Hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 314, text: "Atıyye b. Urve es-Sa'di es-Sahabi (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir kul, sakıncalı olandan kaçınmak için, sakıncası olmayan şeyi terk etmedikçe muttakîlerden -Allah'dan korkanlardan- olamaz.\" (Tirmizi rivayet etmiş ve Hadis hasendir demiştir.) FİTNEDEN VE HARAMDAN SAKINMAK", source: "Hadis-i Şerif" },
    { id: 315, text: "Said el-Hudri (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam; 'Ey Allah'ın Resulü, hangi insan daha üstündür?'diye sordu. Resûlüllah (s.a.v) şöyle buyurdu: Allah yolunda canıyla malıyla cihat eden mü'mindir. Adam; 'Sonra kim?'dedi. Resûlüllah (s.a.v) şöyle buyurdu: Sonra, dağ aralıklarından bir aralığa çekilip Rabbine ibadet eden kimsedir.\"  FİTNEDEN VE HARAMDAN SAKINMAK", source: "Hadis-i Şerif" },
    { id: 316, text: "Ebu Said el-Hudrî (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yakında-öyle fitneler olacaktır ki- bir müslümanın en hayırlı malı, dağ başında birikmiş yağmur suları etrafında otlattığı koyunları olacaktır. Böylelikle dinine uyarak fitnelerden kaçınmış olacaktır.\" (Buhari) TEVAZU VE MÜ'MİNLERE ŞEFKATLE MUAMELE ETMEK", source: "Hadis-i Şerif" },
    { id: 317, text: "lyaz b. Hımâr (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki Allah bana, birbirinize tevazu göstermenizi, hiçbir kimsenin diğerine karşı böbürlenmemesini, kimsenin bir başkasına haksızlıkta bulunmamasını vahyetti.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 318, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)' in şöyle buyurduğu rivayet edilmiştir:   \"Sadaka, malı eksiltmez. Allah, affeden kulun şerefini artırır. Kim Allah için tevazu gösterirse, Allah da onu yüceltir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 319, text: "Enes (r.a)'dan, şöyle rivayet edilmiştir: \"Medine cariyelerinin-kız çocuklarından-biri Resûlüllah (s.a.v)'in elini tutar, onunla birlikte istediği yere giderdi.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 320, text: "Ebu Rifâa Temim b. Üseyd (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) hutbe verirken, yanına kadar sokuldum ve dedim ki: 'Ey Allah'ın Resulü, dinini bilmeyen ama diniyle ilgili bir şeyler sormak için gelen garip bir adam-ım.' Bunun üzerine Resûlüllah (s.a.v) bana döndü, hutbesini bırakıp yanıma kadar geldi. Bir sandalye getirdiler, hemen ona oturdu ve bana Allah'ın kendisine öğrettiklerinden öğretmeye başladı. Sonra da hutbesini -okumaya- gitti ve hutbeyi sonuna kadar tamamladı.\" (Müslim)  TEVAZU VE MÜ'MİNLERE ŞEFKATLE MUAMELE ETMEK", source: "Hadis-i Şerif" },
    { id: 321, text: "Enes (r.a)'in şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bir yemek yediğinde üç parmağını da yalardı. Kendisi (s.a.v); 'Sizden birinizin lokması yere düştüğü zaman, üzerine bulaşmış zararlı şeyi giderip temizlesin ve onu yesin; o lokmayı şeytana bırakmasın' buyurmuştur. Yemek tabağının -sünnetlenmesini- silinmesini emretmiş ve şöyle devam etmiştir: Çünkü siz, bereketin yemeğinizin neresinde olduğunu bilemezsiniz.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 322, text: "Abdullah b. Mes'ud (r,a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet etmiştir: \"Kalbinde zerre kadar kibir bulunan kimse cennete giremez. Ashaptan biri dedi ki: 'Şüphesiz kişi, elbisesinin ve ayakkabısının güzel olmasını sever.' Resûlüllah (s.a.v) da şöyle buyurdu: Allah güzeldir; güzeli sever. Kibir ise, hakkı kabul etmemek ve insanları küçümsemektir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 323, text: "Seleme b. Ekva' (r,a)'dan şöyle rivayet edilmiştir: \"Bir adam Resûlüllah (s.a.v)'in huzurunda sol eliyle yedi. Resûlüllah (s.a.v); 'Sağ elinle ye'buyurdu. Adam; 'Gücüm yetmi-   yor'dedi. Bunun üzerine Resûlüllah (s.a.v);Güç yettiremez ol'bu-yurdu. Onu, sağ eliyle yemekten sadece kibri alıkoymuştu. Seleme; O kişi artık elini ağzına götüremedi, dedi.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 324, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kibrinden dolayı elbisesinin eteğini sürükleyen kimseye, Allah kıyamet günü -rahmet- nazarıyla bakmayacaktır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 325, text: "Ebu Hureyre (r.a)' dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Üç sınıf insanla Allah kıyamet günü konuşmayacak, onları temizlemeyecek, onlara -rahmet- nazarı ile bakmayacak ve onlar için gayet acıklı bir azap vardır. Bunlar; zina eden ihtiyar, yalancı idareci ve kibirli fakirdir,\" (Müslim) GÜZEL AHLAK  GÜZEL AHLAK", source: "Hadis-i Şerif" },
    { id: 326, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) insanların en güzel ahlaklısı idi.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 327, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Ben, Allah Resulünün (s.a.v) elinden daha yumuşak ne bir atlas, ne de bir ipeğe dokunmadım. Resûlüllah (s.a.v)'in kokusundan daha hoş hiçbir koku da koklamadım. Andolsun ki, ben Resûlüllah (s.a.v)'in on yıl hizmetinde bulundum; ama bana asla 'Öf! 'bi-le demedi. Yaptığım bir şey için; Niçin yaptın?, yapmadığım bir şey için de; Şöyle yapsaydın ya! dememiştir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 328, text: "Nevvâs b. Semân (r.a)'dan, şöyle rivayet edilmiştir. \"Resûlüllah (s.a.v)'e, iyilik ve günahtan sordum. O da şöyle buyurdu: İyilik; güzel ahlaktır. Günah ise; kalbinde şüphe uyandıran ve insanların haberdar olmalarını istemediğin şeydir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 329, text: "Abdullah b. Ömer b. El-Âs (r.a)'dan, şöyle rivayet edilmıştır:   \"Resûlüllah (s.a.v) kötü sözlü olmamıştır, kötü söz söylemeye de hiç özenmemiştir. O, şöyle buyururdu: Şüphesiz sizin en hayırlılarınız, ahlakça en güzel olanlarınızdır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 330, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'a, insanları cennete en çok sokan sebeplerin ne olduğu soruldu? Resûlüllah (s.a.v) şöyle buyurdu: 'Allah korkusu ve güzel ahlaktır.' Yine, insanları cehenneme en çok sokan sebeplerin ne olduğu sorulduğunda ise şöyle buyurmuştur: Ağız ve avret yeri.\" (Tirmizi rivayet etmiş ve hasendir sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 331, text: "Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in şöyle buyurduğunu işittim; Mü'min, güzel ahlakı sayesinde gündüz oruçlu, gece -ibadetten dolayı- ayakta bulunan kimsenin derecesine erer.\" (Ebu Davud) HİLİM, ACELECİ OLMAMAK VE MERHAMET  HİlİM, ACELECİ OLMAMAK VE MERHAMET", source: "Hadis-i Şerif" },
    { id: 332, text: "lbn-i Abbas (r.a)'dan, Resûlüllah (s.a.v)'in Eşec Abdülkays'e şöyle buyurduğu rivayet edilmiştir: \"Sende, Allah'ın beğendiği iki haslet vardır; Bunlar- yumuşaklık ve aceleci olmamaktır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 333, text: "Hz. Âişe (r.a)'dan, Resûlüllah (s,a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah -kullarına karşı-yumuşaktır; yumuşak huyluluğu sever. Sertlik ve onun haricindekilere vermediğini, yumuşaklıkla yapılana verir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 334, text: "Hz. Âişe (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yumuşaklık, nerede bulunursa onu süsler. Hangi şeyden soyulup alınırsa, ona da utanma vardır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 335, text: "Enes (r.a)'dan, Resûlüllah (s,a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Kolaylaştırın, zorlaştırmayın. Müjdeleyin, nefret ettirmeyin.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 336, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) iki şey arasında tercih yapmakta serbest kılındığında, bir günah olmadıkça mutlaka onun en kolay olanını alırdı. Eğer bir günah varsa, ona da İnsanların en uzak duranı olurdu. Resûlüllah (s.a.v) kendisi için asla intikam almamıştır. Ancak Allah'ın haram kıldığı hususlar çiğnenmeye başlandığında, işte o zaman Allah İçin intikam alırdı.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 337, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v), Allah yolunda cihattan başka hiçbir kimseye, hiçbir kadın veya hizmetçiye eliyle vurduğu asla vaki değildir. Kendisine dokunan bir şeyden dolayı asla intikam almamıştır. Ancak Allah'ın haram kıldığı hususlar çiğnenmeye başlandığında, işte o zaman Allah için intikam alırdı.\" (Müslim)  HİLMİ, ACELECİ OLMAMAK VE MERHAMET", source: "Hadis-i Şerif" },
    { id: 338, text: "Ibn-i Mes'ud (r.a)'dan şöyle dediği rivayet edilmiştir: \"Sanki ben, Resûlüllah (s.a.v)'i peygamberlerden bir peygamberin (a.s) başından geçenleri anlatırken görür gibiyim; kavmi o peygamberi dövmüş, kan revan halinde bırakmış, o da yüzünden kanları siliyor ve şöyle dua ediyordu; Allah'ım, kavmimi bağışla, çünkü onlar -ne yaptıklarını- bilmiyorlar!\" (Buhari ve Müslim) EZİYETLERE KATLANMAK", source: "Hadis-i Şerif" },
    { id: 339, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam Resûlüllah (s.a.v)'e şöyle dedi: Ey Allah'ın Resulü, benim bir takım akrabalarım var; ben onlara gidip geliyorum, onlar ise benimle ilişkiyi kesiyorlar. Ben onlara iyilik yapıyorum, onlar ise bana kötülük yapıyorlar. Ben onlara yumuşak davranıyorum, onlar ise bana cahilce hareket ediyorlar! Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Eğer durum söylediğin gibi ise, sen onlara kızgın kül yedirmiş gibisin. Sen böyle yapmaya devam ettiğin sürece Allah'ın yardımı seninle olmayı sürdürecektir.\" (Müslim)   DİNİN KESİN EMİRLERİNİ ÇİĞNEMEMEK", source: "Hadis-i Şerif" },
    { id: 340, text: "Ebu Mes' ud Ukbe b. Amr el-Bedrî (r.a)' dan şöyle dediği rivayet edilmiştir: \"Bir adam Resûlüllah (s.a.v)'e gelip şöyle dedi: Ben, falan adamın namazı uzatmasından dolayı sabah namazında bulunamıyorum. Ben Resûlüllah (s.a.v)'i o günkü vaazında hiddetlendiği gibi hiçbir vaazda hiddetlendiğini asla görmedim. Şöyle buyurdu: Ey insanlar, şüphesiz sizin içinizde nefret ettirenler bulunmaktadır! Sizden hanginiz insanlara imam olursa kısa tutsun; çünkü arkasında yaşlı, küçük ve ihtiyaç sahibi kimseler bulunmaktadır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 341, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir; \"Resûlüllah (s.a.v) bir gün yolculuktan dönmüştü. Ben, kapının girişine üzerinde bir takım resimler bulunan perde örtmüştüm. Resûlüllah (s.a.v) onu görünce perdeyi yırttı, yüzünün rengi değişti  İDARECİLERİN TEBALARINA YUMUŞAK DAVRANMALARI ve şöyle buyurdu: Ey Âişe, kıyamet günü insanların en şiddetli azaba çarptırılacak olanları, Allah'ın yaratıkları hususunda O'nunla boy ölçüşmeye kalkışanlardır.\" (Buharı ve Müslim) İDARECİLERİN TEBALARINA YUMUŞAK DAVRANMALARI", source: "Hadis-i Şerif" },
    { id: 342, text: "Ibn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken duydum: Hepiniz çobansınız ve hepiniz idareniz altındakilerden sorumlusunuz. Halife çobandır ve idaresi altındakilerden sorumludur. Bir erkek ailesinin çobanıdır ve idaresi altında bulunanlardan sorumludur. Kadın, kocasının evinde çobandır ve korumakla mükellef olduğu şeylerden sorumludur. Hizmetçi, efendisinin malının çobanıdır ve korumakla yükümlü olduğu şeylerden sorumludur. Velhasıl hepiniz çobansınız ve hepiniz idareniz altındakilerden sorumlusunuz.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 343, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir. \"İsrailoğullarını peygamberler idare etmekte idi. Bir peygamber Ölünce diğer bir peygamber onun yerine geçerdi. Oysa benden sonra peygamber gelmeyecektir. Benden sonra sayıları çok olan halifeler bulunacaktır. Ashab dediler ki: 'Ey Allah'ın Resulü, o zaman bize ne emir buyurursunuz?' Resûlüllah (s.a.v) şöyle buyurdu: İlkinden başlamak üzere sırasıyla gelenlerin biatına uyunuz. Sonra da onların hakkını yerine getiriniz. Sizinle ilgili olan şeyleri de Allah'dan isteyiniz. Şüphesiz ki Allah onları, yerine getirmek zorunda oldukları vazifelerden dolayı hesaba çekecektir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 344, text: "Aiz b. Amr (r.a)'dan şöyle rivayet edilmiştir: \"Kendisi Ubeydullah b. Ziyâd'ın yanına varıp demiştir ki: 'Ey oğlum, ben Resûlüllah (s.a.v)'in şöyle buyurduğunu işittim: Şüphesiz idarecilerin en kötüsü, katı kalpli-sert- olanlarıdır. Sakın ha, sizi onlardan olmaktan sakındırırım!\" (Müslim) ÂDİL İDARECİLERE İTAAT", source: "Hadis-i Şerif" },
    { id: 345, text: "Abdullah b.Amr b.As (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  ÂDİL İDARECİLERE İTAAT \"Halkına, ehline ve idare ettikleri kimselere adaletle hükmedenler, Allah katında nurdan minberler üzerinde bulunacaklardır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 346, text: "Iyâz b. Hımâr (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in şöyle buyurduğunu işittim: Cennet ehli üç çeşittir; Âdil, başarılı hükümdar, bütün müslümanlara ve yakınlarına karşı merhametli, ince kalpli olan kimse ve aile sahibi olduğu halde haya sahibi, istemekten utanan kimse.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 347, text: "İbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Müslüman bir kimsenin, hoşlandığı ve hoşlanmadığı meselelerde, isyan ile emrolunmadığı sürece -başındaki idareciyi- dinleyip itaat etmesi gerekir. Ama Allah'a-isyan İle emrolunursa, işte o zaman dinleyip itaat etmesi olmaz.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 348, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz Resûlüllah (s.v.a)'e, kendisini dinleyip itaat edeceğimiz hususunda biat verdiğimiz zaman bize şöyle demiştir: Tabii ki gücünüz yettiği kadarıyla.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 349, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Sizin üzerinize, başı kuru üzüm gibi olan Habeş'li bir köle idareci olarak tayin edilmiş olsa , yine de dinleyin ve itaat edin.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 350, text: "Abdullah b. Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yakında benden sonra adam kayırma ve hoş karşılamadığınız bir takım işler olacaktır. Ashab dediler ki: Ey Allah'ın Resulü, bizden onlara yetişenlere ne yapmalarını emredersin? Resûlüllah (s.a.v) şöyle buyurdu: Onların-Sizin üzerinizde bulunan hakları yerine getirirsiniz ve kendi haklarınızı da- Allah'dan istersiniz.\" (Buhari ve Müslim)  ÂDİL İDARECİLERE İTAAT", source: "Hadis-i Şerif" },
    { id: 351, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s,a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bana itaat ederse, şüphesiz Allah'a itaat etmiş olur. Kim de bana isyan ederse muhakkak Allah'a isyan etmiş olur. Kim halifeye itaat ederse, şüphesiz bana itaat etmiş olur. Kim de halifeye isyan ederse, muhakkak bana isyan etmiş olur.\" (Buharı ve Müslim) KENDİSİNE TEVDİ EDİLMEDİKÇE İDARECİLİĞİ İSTEMEMEK", source: "Hadis-i Şerif" },
    { id: 352, text: "Ebu Saîd Abdurrahman b. Semure (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bana şöyle buyurmuştur: Ey Abdurrahman, Amirlik talep etme! Çünkü, eğer sana sen istemeden verilirse, yardım olunursun. Eğer vazife sana, sen istediğin için verilirse o istediğin şeyle yalnız başına bırakılırsın. Bir mesele hakkında yemin edip de, daha sonra başka bir şeyi ondan daha hayırlı görürsen, o hayırlı   gördüğünü yerine getir ve yemininden dolayı da keffaretini ver.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 353, text: "Ebu Zer (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bana şöyle buyurdu: Ey Eba Zer! Ben seni zayıf görmekteyim. Şüphesiz ki ben, kendim için istediğimi senin için de istiyorum. Sakın, iki kişiye dahi olsa idareci olma! Sakın yetim malına yanaşma!\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 354, text: "Ebu Said ve Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle 3 buyurduğu rivayet edilmiştir: llah (c.c) kimi peygamber göndermişse, kimi halife tayin etmişse, \"A mutlaka onun iki yardımcısı bulunur. Yardımcının biri ona iyiliği emreder ve iyilik yapmasını teşvik eder; diğer yardımcı ise kötülüğü emreder ve onu kötülüğe teşvik eder. Masum; Allah'ın koruduğu kişidir.\" (Buharı)  UTANMA HİSSİNE SA İP OLMAYA TEŞVİK H 3", source: "Hadis-i Şerif" },
    { id: 355, text: "Ebu Musa el-Eş'arî (r.a)'dan şöyle dediği rivayet edilmiştir: esûlüllah (s.a.v)'in huzuruna ben ve iki amca oğlu ile birlikte girdik. \"R Onlardan biri dedi ki: 'Ey Allah'ın Resulü, Yüce Allah'ın size emanet ettiği bazı vazifelere bizi âmir teyin ediverseniz!' Diğeri de ona benzer bir şeyler söyledi. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: A tayin etmiyoruz.\" (Buharı ve Müslim) llah'a yemin olsun ki, biz bu işe isteyeni veya ona düşkün olan birini UTANMA HİSSİNE SAHİP OLMAYA TEŞVİK 3", source: "Hadis-i Şerif" },
    { id: 356, text: "Ibn-i Ömer (r.a)'dan, şöyle rivayet edilmiştir: esûlüllah (s.a.v), Ensardan bir kişinin yanından geçmişti. O kişi, \"R kardeşine haya hakkında nasihatte bulunuyordu. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Onu bırak, şüphesiz haya imandandır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 357, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet 3 edilmiştir:   \"İman yetmiş veya altmış küsur şubedir. Onların en üstünü; 'Allah'tan başka hiçbir ilah yok' sözüdür. En aşağı derecesi ise, yoldan -geçenlere- eziyet verecek şeyi kaldırmaktır. Haya ise imandan bir şubedir.\" (Buharı ve Müslim) SIRRI MUHAFAZA ETMEK", source: "Hadis-i Şerif" },
    { id: 358, text: "Ebu Saîd el-Hudri (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Kıyamet günü Allah katında derece bakımından insanların en kötüsü, erkek karısına, karısı erkeğine cinsi münasebette bulunup da, sonra bunu yayan kimsedir,\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 359, text: "Sabit, Enes(r.a)'ın şöyle dediğini rivayet etmiştir: \"Ben çocuklarla oynarken Resûlüllah (s.a.v) yanıma geldi. Bize selam verdi ve beni bir işini görmeye gönderdi. Bunun üzerine  SIRRI MUHAFAZA ETMEK - SÖZÜNDE DURMAK ben, anneme dönmekte biraz geciktim. Annemin yanına vardığımda dedi ki: 'Seni geç bırakan da ne?' Ben de dedim ki; 'Resûlüllah (s.a.v) beni bir ihtiyacı için gönderdi.' Annem; 'O'nun ihtiyacı neydi?' dedi. Ben de dedim ki: 'O bir sırdır.O zaman annem; 'Resûlüllah (s.a.v)'in sırrını hiçbir kimseye anlatma!' dedi. Enes -Sabit'e- şöyle dedi: Allah'a yemin olsun ki, eğer ben onu birine anlatacak olsaydım, elbette sana anlatırdım ey Sabit!\" (Müslim rivayet etmiştir. Buharı ise bir kısmını kısaca rivayet etmiştir.) SÖZÜNDE DURMAK", source: "Hadis-i Şerif" },
    { id: 360, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Münafığın alameti üçtür; konuştuğu zaman yalan söyler, söz verdiği zaman sözünden cayar ve bir şey emanet edildiği zaman hainlik eder.\" (Buharı ve Müslim) HAYIRLI İŞLERE DEVAM ETMEK", source: "Hadis-i Şerif" },
    { id: 361, text: "Abdullah b. Amr b. Âs (r.a)'dan, şöyle dediği rivayet edilmiştir:   \"Resûlüllah (s.a.v) bana şöyle buyurdu: Ey Abdullah, sakın falanca gibi olmayasın; o, gece -teheccüd- namazına kalkardı, ama gece kalkmayı bıraktı!\" (Buharı ve Müslim) GÜLER YÜZ GÖSTERİP, TATLI DİLLİ OLMAK", source: "Hadis-i Şerif" },
    { id: 362, text: "Adiy b. Hatim (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Velevki yarım hurma ile de olsa, cehennemden korununuz! Onu da bulamayan kimse, güzel bir sözle -korunsun.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 363, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hoş bir kelime dahi sadakadır.\" (Buharı ve Müslim) MUHATABA AÇIK SÖZLE KONUŞMAK, GEREKİRSE TEKRARLAMAK  NASİHAT VE ONDA ORTA YOLLU OLMAK", source: "Hadis-i Şerif" },
    { id: 364, text: "Enes (r.a)'ın şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bir kelime konuştuğu zaman, onu üç kere tekrar ederdi; taa ki anlaşılsın. Bir topluluğun yanına geldiği zaman da onlara selam verir ve selamı üçlerdi.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 365, text: "Hz. Âişe (r.a) dan, şöyle dediği rivayet edilmiştir. \"Resûlüllah (s.a.v)'in konuşması çok açıktı. Dinleyen herkes onun konuşmasını anlayabiliyordu.\" (Ebu Davud)", source: "Hadis-i Şerif" },
    { id: 366, text: "Cerir b. Abdullah (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) Veda haccında bana 'insanları sustur' dedi ve sonra şöyle devam etti: Sakın benden sonra birbirinizin boynunu vurarak küfre dönmeyiniz!\" (Buhari ve Müslim) NASİHAT VE ONDA ORTA YOLLU OLMAK", source: "Hadis-i Şerif" },
    { id: 367, text: "Ebu Vâil Şakik b. Seleme (r.a)'dan, şöyle dediği rivayet edilmiştir: \"İbn-i Mes'ud (r.a), her Perşembe bize nasihatte bulunuyordu. Bir adam ona dedi ki: 'Ey Ebâ Abdurrahman, senin bize her gün nasihatte bulunmanı arzu ediyorum.' Bunun üzerine İbn-i Mes'ud şöyle dedi: Beni bundan alıkoyan şey, sizi usandırmış olma endişesidir. Bunun için, tıpkı Resûlüllah (s.a.v)'in bize usanç verme korkusuyla arada bir nasihatte bulunduğu gibi, ben de size arada bir nasihatte bulunuyorum.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 368, text: "Ebu Yekzân Ammâr b. Yâsir (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Ben, Resûlüllah (s.a.v)'i şöyle buyururken işittim; kişinin namazının uzun hutbesinin kısa olması anlayışlı olmasının alametidir. O halde namazı uzatınız, hutbeyi kısaltınız. (Müslim) VAKAR VE AĞIRBAŞLI OLMAK", source: "Hadis-i Şerif" },
    { id: 369, text: "Hz. Âişe (r.a)'dan, şöyle dediği rivayet edilmiştir:  VAKAR VE AĞIRBAŞLI OLMAK \"Ben Resûlüllah (s.a.v)'i, küçük dili görünecek şekilde güldüğünü asla görmedim. O sadece gülümsüyordu.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 370, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'i şöyle buyururken işittiği rivayet edilmiştir: \"Namaza kalkıldığı zaman ona koşarak gelmeyiniz; yürüyerek geliniz.Size ağırbaşlılık yaraşır. Yetiştiğiniz -rekatleri- kılar, kaçırdığınız -rekatleri de- tamamlarsınız.\" (Buharİ ve Müslim) Müslim, rivayetinde şunu eklemiştir: \"Sizden biriniz namaz kılmaya niyetlendiği zaman; artık o namazdadır.\"", source: "Hadis-i Şerif" },
    { id: 371, text: "İbn-i Abbas (r.a)'dan şöyle rivayet edilmiştir: \"Ârefe günü Resûlüllah (s.a.v) ile birlikteydik. Birden Resûlüllah (s.a.v) arkadan şiddetli bir gürültü, dayak ve deve sesi işitti. Bunun üzerine kamçı ile onlara işaret ederek şöyle buyurdu: Ey insanlar, ağırbaşlı olunuz. Çünkü İyilik, acele davranmakta değildir.\" (Buhari rivayet etmiş; Müslim ise bir kısmını rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 372, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim Allah'a ve ahiret gününe iman ediyorsa misafirine ikram etsin. Kim Allah'a ve ahiret gününe iman ediyorsa akrabasıyla ilişkilerini sürdürsün. Kim Allah'a ve ahiret gününe iman ediyorsa ya hayır söylesin veya sussun,\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 373, text: "Ebu Şureyh Huveylid b. Amr el-Huzâî (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in şöyle buyurduğunu işittim: Kim Allah'a ve ahiret gününe inanıyorsa misafirine caizesini versin. Dediler ki: 'Ey Allah'ın Resulü, misafirin caizesi de nedir?' Resûlüllah şöyle buyurdu: Günlüğü ve geceliğidir-ağırlanmasıdır. Misafirlik üç gündür. Bundan fazlası o kişiye sadaka sayılır.\" (Buhari ve Müslim) HAYIRLI ŞEYLERİ MÜJDELEMEK VE TEBRİK ETMEK  HA YIRLI ŞEYLERİ MÜJDELEMEK VE TEBRİK ETMEK", source: "Hadis-i Şerif" },
    { id: 374, text: "Ebu Musa Eş'arî (r.a)'dan şöyle rivayet edilmiştir: \"Bu kişi evinde abdest aldıktan sonra dışarı çıktı ve dedi ki: 'Bu gün Resûlüllah (s.a.v)'in yanından ayrılmayacak, onunla beraber olacağım.' Böylelikle mescide gitti ve Peygamber (a.s) 'ı sordu. Dediler ki: Şu tarafa doğru gitti. Ebu Musa şöyle devam ediyor; Ben de O'nun izi üzere, kendisini sorarak yola çıktım. Erîs kuyusunun -olduğu bahçeye- girince kapının yanında oturdum. Bu sırada Resûlüllah (s.a.v) def-i hacet yapıp abdest aldı. Ben de kalkıp yanına vardım. O, kuyunun başındaki taşın tam ortasına oturmuştu. Paçalarını sıvayıp, ayaklarını kuyuya sarkıtmıştı. Ben O'na selam verdim ve sonra dönüp kapının yanına oturdum ve -içimden- dedim ki: 'Bu gün Resûlüllah   (s.a.v)'in kapıcısı olacağım.' Derken Ebu Bekir (r.a) geldi ve kapıyı vurdu. Ben dedim ki: - Kim o? O da: - Ebu Bekir, dedi. Bu sefer ben de dedim ki: - Biraz müsaade ediver. Sonra gidip şöyle dedim: - Ey Allah'ın Resulü, bu -gelen-Ebu Bekir'dir, izin istiyor. Resûlüllah: - Ona izin ve kendisini cennetle müjdele! buyurdu. Ben de dönüp Ebu Bekir'e dedim ki: - Giriver. Allah Resulü sizi cennetle müjdeliyor! Ebu Bekir girdi ve Peygamber (a.s)'ın sağındaki ağız taşına oturdu. Resûlüllah (s.a.v)'in yaptığı gibi paçalarını sıvayıp ayaklarını kuyuya sarkıttı. Sonra ben döndüm ve -kapının yanına- oturdum. Ben kardeşimi abdest alıp bana yetişmek için uğraşırken bırakmıştım. İçimden kardeşimi kastederek dedim ki: 'Eğer Allah falanca hakkında hayır diliyorsa onu buraya getirir.' Birde ne göreyim! Bir kişi kapıyı sallıyor! Ben dedim ki: - Kim o? Dedi ki: - Ömer b. Hattab. Dedim ki: - Biraz müsaade ediver. Sonra Resûlüllah (s.a.v)'e gittim, kendisine selam verdim ve dedim ki: - Bu -gelen- Ömer'dir, izin istiyor. Resûlüllah: - Ona izin ver ve kendisini cennetle müjdele! Derhal Ömer'in yanına gittim ve dedim ki: - Resûlüllah (s.a.v) izin verdi ve seni cennetle müjdeledi! Ömer içeri-girdi ve Resûlüllah (s.a.v)'in solundaki taşa O'nunla beraber oturdu ve ayaklarını kuyuya sarkıttı. Sonra ben- yine kapıya-döndüm ve kardeşimi kastederek dedim ki: 'Eğer Allah falanca hakkında hayır diliyorsa onu buraya getirir.' Bir de baktım ki, bir kişi kapıyı sallıyor! Dedim ki:  HAYIRLI ŞEYLERİ MÜJDELEMEK VE TEBRİK ETMEK- Kim o? Dedi ki: - Osman b. Affân. Dedim ki: - Biraz müsaade ediver. Ben hemen peygamber (a.s.)'a gittim ve onun geldiğini haber verdim. Buyurdu ki: - Ona izin ve onu, kendisine isabet edecek belalarla birlikte cennetle müjdele! Ben de gittim ve dedim ki: - Giriver. Reûlüllah (s.a.v) seni, sana isabet edecek belalarla birlikte cennetle müjdeliyor! O da girdi ve kuyunun ağız taşını dolmuş olarak buldu. Bunun üzerine karşılarında başka bir yere oturdu.\" Saîd b. Müseyyeb dedi ki: Ben onların -bu duruşlarını- kabirlerine yorumladım. (Buharı ve Müslim) YOLCULUĞA ÇIKARKEN ARKADAŞI İLE VEDALAŞMAK, ONA DUA ETMEK VE ONDAN DUA İSTEMEK", source: "Hadis-i Şerif" },
    { id: 375, text: "Ömer b. Hattab (r.a)'dan, söyle dediği rivayet edilmiştir: \"Ben, umre için Resûlüllah (s.a.v)'den izin istedim; o da izin verdi ve şöyle buyurdu: Ey kardeşim, sakın bizi de dualarında unutma! Eğer dünya benim olsa, bu kelime kadar beni memnun edemeyecekti.\" (Ebu Davud ve Tirmizi)", source: "Hadis-i Şerif" },
    { id: 376, text: "Salim b. Abdullah b. Ömer'den rivayette, Abdullah b. Ömer (r.a), yolculuğa çıkmak isteyen bir adam şöyle derdi: \"Bana yaklaş da, Resûlüllah (s.a.v)'in bizi uğurladığı gibi seni uğurlayayım. Sonra şöyle derdi; Dinini, emanetini ve işlerinin sonuçlarını Allah'a emanet ediyorum.\" (Tirmizî rivayet etmiş ve Hadis hasendir, sahihtir demiştir.) İSTİHARE VE MÜŞAVERE ETMEK", source: "Hadis-i Şerif" },
    { id: 377, text: "Cabir (r.a)'ın, şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bize, tıpkı Kur'an'dan bir sûre öğretir gibi bütün işlerde istihareyi öğretiyordu. Şöyle buyururdu: Sizden biriniz bir iş yapmaya karar verirse, farzlardan başka i-ki rekat namaz kılsın ve sonra şöyle desin; 'Allah'ım, senin ilminle  İSTİHARE VE MÜŞAVERE ETMEK hakkımda hayırlı olanı bana bildirmeni, kudretinle bana güç ve kuvvet vermeni diliyor; senin büyük lütfunu istiyorum. Çünkü sen kudret sahibisin; benim kudretim yoktur. Sen bilirsin; ben bilemem. Sen; gaybleri layıkıyla bilensin. Allah'ım, eğer sen bu işin benim dinim, yaşamım ve işimin sonucu, ya da dünya ve ahiretim hakkında hayırlı olduğunu biliyorsan- ki mutlaka bilirsin- onu bize takdir et, kolay kıl ve bereketli eyle. Eğer sen, bu işin benim dinim, yaşamım ve işimin sonucu, ya da dünya ve ahiretim hakkında şerli olduğunu biliyorsan -ki mutlaka bilirsin- onu benden çevir, beni de ondan çevir. Benim için hayır nerede ise, onu bana takdir et, sonra da ona razı eyle.' Resûlüllah (s.a.v); duanın akabinde- hacetini aktarır, buyurdu.\" (Buharı) İBADET SEVABI ÇOK OLSUN DİYE MESCİTLERE AYRI YOLLARDAN GİDİP GELME", source: "Hadis-i Şerif" },
    { id: 378, text: "Cabir (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bayram günü olduğunda -mescide gidip gelirken- yolu değiştirirdi.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 379, text: "Ibn-i Ömer (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) -Medine'den- Şecere yolundan çıkar, Mu-arras yolundan girerdi. Mekke'ye girdiği zaman ise Seniyyetil-Ul-yâ'dan girer, Seniyyetis-Süflâ'dan çıkardı.\" (Buharı ve Müslim) SAĞDAN VE SOLDAN BAŞLAMANIN MÜSTEHAP OLUŞU", source: "Hadis-i Şerif" },
    { id: 380, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in sağ eli yemek ve temizlik içindi. Sol eli ise hela ve rahatsız edici şeyleri gidermek içindi.\" (Hadis sahihtir. Ebu Davud sahih bir isnatla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 381, text: "Ümmü Atiyye (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) kızı Zeyneb'in -cenazesini- yıkayacakları zaman yıkayıcılara şöyle buyurmuştur: Sağdan ve abdest azalarından başlayınız.\" (Buharı ve Müslim)  SAĞDAN VE SOLDAN BAŞLAMANIN MÜSTEHAP OLUŞU", source: "Hadis-i Şerif" },
    { id: 382, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz ayakkabı giyeceği zaman sağından başlasın, Çıkaracağı zaman da solundan başlasın. Böylelikle sağ ayak ilk giyilen ve en son çıkarılan ayak olsun.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 383, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Giydiğiniz zaman da, abdest aldığınız zaman da sağ taraflarınızla başlayınız.\" (Ebu Davud ve Tirmizi sahih bir isnatla rivayet etmiştir.) YEMEK YEMENİN ADABI", source: "Hadis-i Şerif" },
    { id: 384, text: "Amr b. Ebu Seleme (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Resûlüllah (s,a.v) bana şöyle buyurdu: Allah'ın adını an ve sağ elinle ye, bir de önünden ye.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 385, text: "Hz. Aişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) arkadaşlarından altı kişi ile bir yemek yiyordu. Bedevinin biri gelip iki lokmada -yemeği- bitirdi. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Eğer o besmele çekseydi, mutlaka hepinize yetecekti.\" (Buharı rivayet etmiş ve hadis hasen-dir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 386, text: "Ebu Umâme (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) sofrasını kaldırdığı zaman şöyle buyururdu: Hamd Allah'a mahsustur. Rabbimiz! Temiz, mübarek, ihityaçsız kalınamayan, reddolunmayan ve kabule şâyân bir hamd ile seni çok hamd ederiz,\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 387, text: "Muâz b. Enes (r,a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim yemek yer de 'Beni bu -nimetlerle- doyuran, güç ve kuvvetim olmadığı halde beni bunlarla rızıklandıran Allah'a hamd olsun derse, geçmiş günahlarından bağışlanır.\" (Ebu Davud ve Tir-mizi rivayet etmiş ve Tirmizİ; hadis hasendir demiştir,)  YEMEK YEMENİN ÂDABI", source: "Hadis-i Şerif" },
    { id: 388, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) herhangi bir yemeği asla ayıplamazdı. Eğer iştahı çekerse onu yerdi; canı çekmiyorsa onu bırakırdı.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 389, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz davet edildiği zaman hemen icabet etsin. Eğer oruçlu ise -davet sahibine- dua etsin; eğer oruçlu değilse yesin.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 390, text: "Ebu Mes'ud el-Bedrî (r.a)'dan şöyle dediği rivayet edilmiştir: \"Adamın biri, Resûlüllah (s.a.v)'i hazırladığı yemeğe beş kişinin beşincisi olarak davet etti. Sonra onlara bir kişi daha katıldı. Resûlüllah (s.a.v); 'Bu adam da peşimize takıldı. Eğer dilersen ona izin ver, istersen -geri- dönsün'buyurdu. Adam; bilakis ona izin veriyorum Ey Allah'ın Resulü, dedi.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 391, text: "Ömer b. Ebu Seleme (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Ben, Resûlüllah (s.a.v)'in himayesinde küçük bir çocuktum. Sofrada elim tabağın içinde dolaşıyordu. Bunun üzerine Resûlüllah (s.a.v) bana şöyle buyurdu: Ey çocuk, Allah'ın adını an, sağından ye, bir de önünden ye.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 392, text: "Cebele b. Suhaym (r.a)'dan şöyle dediği rivayet edilmiştir: \"İbn-i Zübeyr ile beraber bulunuyorken bize kıtlık senesi isabet etmiş, biz bir miktar hurma ile rızıklandırılmıştık. Biz onları yerken Abdullah b. Ömer (r.a) yanımızdan geçiyordu. Bize şöyle dedi: 'İkişer ikişer yemeyin; çünkü Resûlüllah (s.a.v) ikişer ikişer yemeyi yasakladı.' Sonra şöyle devam etti: Ancak kişi kardeşinden izin isterse-yiyebilir.\" (Buharı ve Müslim)  YEMEK YEMENİN ÂDABI", source: "Hadis-i Şerif" },
    { id: 393, text: "Vahşi b. Harb (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'in ashabı dediler ki: Ey Allah'ın Resulü, biz yiyoruz ama doymuyoruz. Resûlüllah (s.a.v): Belki de siz ayrı ayrı yiyorsunuz, buyurdu. Dediler ki: Evet. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Yemeğinizin başında toplanınız ve Allah'ın adını anınız ki yemeğiniz sizin için bereketli kılınsın.\" (Ebu Davud)", source: "Hadis-i Şerif" },
    { id: 394, text: "İbn-i Abbas (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Bereket yemeğin ortasına iner. Onun için yemeğin kenarından yiyiniz, ortasından yemeyiniz.\" (Ebu Davud ve Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 395, text: "Ebu Cuhfe Vehb b. Abdullah (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ben, yan gelip yaslanarak yemek yemem.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 396, text: "Ibn-i Abbas (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz yemek yediği zaman, parmaklarını yalamadıkça veya yalatmadıkça silmesin.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 397, text: "Ka'b b. Mâlik (r.a)'dan, Resûlüllah (s.a.v)'in şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i üç parmakla yemek yerken gördüm. Yemekten ayrılınca parmaklarını yaladı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 398, text: "Câbir (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) parmakların yalanmasını ve tabakların sıyrılmasını emretti ve şöyle buyurdu: Siz, bereketin yemeğinizin neresinde olduğunu bilemezsiniz.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 399, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  SU İKRAM ETMENİN VE SU İÇMENİN ÂDABI \"İki kişinin yemeği üç kişiye, üç kişinin yemeği de dört kişiye yeterli gelir,\" (Buharı ve Müslim) SU İKRAM ETMENİN VE SU İÇMENİN ÂDABI", source: "Hadis-i Şerif" },
    { id: 400, text: "Enes (r.a)'dan söyle rivayet edilmiştir: \"Resûlüllah (s.a.v) bir şey içerken üç kere nefeslenirdi.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 401, text: "İbn-i Abbas (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğ rivayet edilmiştir: \"Devenin içtiği gibi bir defada içmeyiniz. Bilakis ikişer ve üçer -nefeste- içiniz. Bir şey içeceğiniz zaman besmele çekiniz ve kaldırdığınızda da hamd ediniz.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 402, text: "Ebu Saîd el-Hudrî (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) ağzı kırık kaplardan bir şey içmeyi yasaklamıştır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 403, text: "Ebu Saîd el-Hudrî (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) içilen şeyin içine üflemeyi yasaklamıştır. Bir adam dedi ki: Kabın içinde bîr çöp görürsem ne buyurursunuz? Resûlüllah: Onu döküver, buyurdu. Adam; Ben bir nefeste içemiyorum, dedi. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Nefes alacağın zaman kabı ağzından uzaklaştır.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 404, text: "Ibn-i Abbas (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a,v)'e zemzem ikram ettim. Ayakta iken içti.\" (Buharı ve Müslim)  ALTIN VE GÜMÜŞ KAP KULLANMANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 405, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz Resûlüllah (s.a.v) zamanında yürürken yerdik, ayakta iken içerdik.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 406, text: "Ebu Katâde (r,a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir topluma su ikram eden, en son içen olmalıdır.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.) ALTIN VE GÜMÜŞ KAP KULLANMANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 407, text: "Abdullah b. Zeyd (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bize gelmişti. Biz de kendisine bakır kap içinde su çıkardık. Onunla-abdest aldı.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 408, text: "Huzeyfe (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) bizi, ipek ve atlas-elbise giymekten, altın ve gümüş kaptan -yiyip içmekten- men etti ve şöyle buyurdu: Bunlar dünyada onların; ahirette ise sizin olacaktır.\" (Buharı ve Müslim) BEYAZ GİYİNMENİN MÜSTEHAB OLUŞU", source: "Hadis-i Şerif" },
    { id: 409, text: "İbn-i Abbas (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Beyaz elbisenizi giyiniz; çünkü onlar, elbiselerinizin en hayırlısıdır. Ölülerinizi de onunla kefenleyiniz.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 410, text: "Semüre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Beyaz elbise giyiniz. Çünkü o daha temiz ve daha hoştur. Ölülerinizi de onunla kefenleyiniz.\" (Neseî ve Hâkim rivayet etmiş; hadis sahihtir demiştir.)  BEYAZ GİYİNMENİN MÜSTEHAB OLUŞU", source: "Hadis-i Şerif" },
    { id: 411, text: "Cabir (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) Fetih günü Mekke'ye üzerinde siyah sarık olduğu halde girmiştir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 412, text: "Hz. Aişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) Yemen malı üç parça pamuklu bezle kefenlenmiştir. Bunların arasında gömlek ve sarık bulunmuyordu.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 413, text: "Ümme Seleme (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in en çok sevdiği elbise gömlek idi.\" (Ebu Davud ve Tirmizi rivayet etmiş ve hadis hasendir demiştir.) GÖMLEK YENLERİNİN VE İZARIN KİBİR VE GURUR İÇİN UZATILIŞI", source: "Hadis-i Şerif" },
    { id: 414, text: "Esma b. Yezid el-Ensarî(r.a)'ın şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in gömleğinin kolu, bileklere kadardı \"(Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 415, text: "İbn-i Ömer (r.a) ' dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim elbisesini kibir için yerde sürürse, Allah kıyamet günü kendisine rahmet- nazarıyla bakmaz. Ebu Bekir dedi ki: Ey Allah'ın Resulü, ben dikkat etmesem elbisem aşağı sarkar. Resûlüllah (s.a.v) ona şöyle buyurdu: Sen bunu, kibir için yapanlardan değilsin.\" (Buharı tamamını, Müslim de bazısını rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 416, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah (c.c), elbisesini kibir için süründürene kıyamet günü -rahmet- nazarıyla bakmaz.\" (Buharı ve Müslim)  GİYİMDE ORTA YOL TUTTURMAK", source: "Hadis-i Şerif" },
    { id: 417, text: "lbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yerlerde süründürme, elbise, gömlek ve sarıkta olur. Bunları kim kibir için uzatırsa, kıyamet günü Allah o kişiye -rahmet-naza-rıyla bakmaz.\" (Ebu Davud ve Nesei sahih isnatlarla rivayet etmişlerdir.)", source: "Hadis-i Şerif" },
    { id: 418, text: "Ebu Saîd el-Hudri (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Müslümanın entarisi, dizi ile ayağı arasının yarısına kadar -uzamalıdır. Buradan topuklara kadar -uzun- olmasında bir sakınca veya bir günah yoktur. Topuklardan daha aşağısı ise ateştir. Kim de elbisesini kibirden dolayı sürürse, Allah ona -rahmet- nazarıyla bakmaz.\" (Ebu Davud) GİYİMDE ORTA YOL TUTTURMAK", source: "Hadis-i Şerif" },
    { id: 419, text: "Amr b. Şuayb babasından, o da dedesinden (r.a) yaptığı rivayette, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki Allah nimetinin eserini kulunun üzerinde görmeyi sever.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.) İPEK GİYMENİN ERKEĞE HARAM KILINMASI", source: "Hadis-i Şerif" },
    { id: 420, text: "Ömer b. Hattâb (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İpek giymeyiniz. Çünkü kim dünyada ipek giyerse, ahirette onu giyemeyecektir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 421, text: "Ali (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'ı ipeği sağ eline, altını da sol eline alıp; 'Şüphesiz bu ikisi ümmetimin erkeklerine haramdır' dediğini gördüm.\" (Ebu Davud hasen bir isnatla rivayet etmiştir.)  UYUZ HASTASININ İPEKLİ GİYMESİNİN CAİZ OLMASI UYUZ HASTASININ İPEKLİ GİYMESİNİN CAİZ OLMASI", source: "Hadis-i Şerif" },
    { id: 422, text: "Enes (r.a)'dan, şöyle dediği rivayet olunmuştur: \"Resûlüllah (s.a.v),Zübeyr ve Abdurrahman b. Avf (r,a)'a uyuz hastalığına mübtelâ oldukları İçin ipek giymeye ruhsat verdi.\" (Buhari ve Müslim) KAPLAN DERİLERİNDEN YATAK VE EĞER YAPMANIN, ÜZERİNDE YATMANIN NEHYİ", source: "Hadis-i Şerif" },
    { id: 423, text: "Muaviye (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İpekli ve kaplan derisinden imal edilmiş eyere binmeyiniz.\" (Hadis hasendir. Ebu Davud ve diğerleri hasen bir isnatla rivayet etmiştir.)   YENİ ELBİSE GİYİLDİĞİ ZAMAN YAPILACAK DUA", source: "Hadis-i Şerif" },
    { id: 424, text: "Ebu Saîd el-Hudri (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) yeni bir elbise giydiği zaman onu ismiyle -sarık, gömlek veya elbise-diye isimlendirip şöyle buyururdu: Allah'ım, hamd sana mahsustur. Onu bana sen giydirdin. Senden o-nun hayrını ve ona takdir olunanın hayrını dilerim. Onun şerrinden ve ona takdir olunanın şerrinden de sana sığınıyorum.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.) UYUMA, YASLANMA, OTURMA, MECLİS VE RÜYA ÂDABI", source: "Hadis-i Şerif" },
    { id: 425, text: "Berâ b. Azib (r.a)'dan şöyle dediği rivayet edilmiştir:  UYUMA, YASLANMA, OTURMA, MECLİS VERÜYAÂDÂB! \"Resûlüllah (s.a.v) yatağına uzandığı zaman sağ tarafı üzerine yatar, sonra şöyle dua ederdi: Allah'ım, kendimi sana teslim ettim, yüzümü sana çevirdim, işimi sana havale ettim, senden korkarak ve seni arzulayarak sırtımı sana dayadım. Senden başka sığınacak, senden sığınılacak başka bir yer yok; ancak sen varsın. Senin indirdiğin kitaba, gönderdiğin peygambere iman ettim.\" (Buharı, Sahih' indeki Edeb kitabında bu lafızla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 426, text: "Berâ b. Âzib (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bana şöyle buyurdu; Yatağına geldiğin zaman namaz için aldığın abdest gibi abdest al, sonra sağ tarafına yat ve şöyle dua et... (Yukarıdaki duanın benzeri bir dua okudu.) Bu dua, söylediğin en son söz olsun.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 427, text: "Yaîş b. Tıhfe el-Gıfarî(r.a)'dan şöyle dediği rivayet edilmiştir: \"Babam şöyle söyledi; Bir ara ben mescitte karnımın üzerine uzanmıştım. Birden, bir adam beni ayağıyla sallıyor ve şöyle diyordu: 'Bü, Allah'ın kızdığı bir yatış tarzıdır. ' Bir de baktım ki ne göreyim! Allah Resulü (s.a.v).\" (Ebu Davud sahih isnatla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 428, text: "Abdullah b.Zeyd (r.a)'dan şöyle dediği rivayet edilmiştir: \"Bu zat, Resûlüllah (s.a.v)'i mescitte bir ayağını diğerinin üzerine atmış vaziyette sırt üstü yatarken gördüğünü haber verdi.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 429, text: "Cabir b. Semure (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) sabah namazını kıldığı zaman, güneş iyice doğuncaya kadar bağdaş kurup otururdu.\" (Hadis sahihtir, Ebu Davud ve diğerleri sahih isnatlarla rivayet etmişlerdir.)", source: "Hadis-i Şerif" },
    { id: 430, text: "Ibn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i Ka'be'nin avlusunda -dizlerini dikip- elleriyle dizlerini tutup oturduğunu gördüm. İbn-i Ömer eliyle; karnını uyluklarına dayayıp, kaba etleri üzerine oturarak ihtibâyı anlattı.\" (Buharı)  MECLİS VE OTURMA ÂDABI MECLİS VE OTURMA ÂDABI", source: "Hadis-i Şerif" },
    { id: 431, text: "İbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz, sakın bir adamı yerinden kaldırıp da sonra onun yerine oturmasın. Ama genişletiniz ve yer açınız. İbn-i Ömer kendisine yer vermek için kalkan birinin yerine oturmazdı.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 432, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz yerinden kalktığı zaman tekrar yerine dönerse, oraya oturmaya kendisi daha layıktır,\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 433, text: "Ebu Abdullah Selmân el-Fârisî (r.a)'dan, Resûlüllah (s.a.v)'İn şöyle buyurduğu rivayet edilmiştir:   \"Bir kişi Cuma günü gusül abdestini alır ve gücünün yettiği kadar tam manasıyla temizlenir, yağından biri ile yağlanır veya evi'nin kokularından birini sürer, sonra evinden çıkar ve iki kişinin arasını açmaz, sonra kendisine farz kılınan namazı kılar, sonra da i-mam konuşmaya başladığı zaman susarsa, o Cuma ile diğer Cuma arasındaki günahları mutlaka affolunur.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 434, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir topluluk, içinde Allah'ın anılmadığı ve orada peygamberlerine salât-ü selâm getirilmediği bir meclise oturursa, bu kendi aleyhlerine bir noksanlık olur. Allah-dilerse onlara azap eder, dilerse onları bağışlar.\" (Tirmizi rivayet etmiş ve hadîs hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 435, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bir yerde oturur da orada Allah'ı anmazsa, Allah tarafından ona karşı -lütufta- bir noksanlık olur. Kim bir yere yatar da orada Allah'ı anmazsa, Allah tarafından ona karşı -ihsanda- bir noksanlık olur.\" (Ebu Davud)  RÜYA", source: "Hadis-i Şerif" },
    { id: 436, text: "Ebu Hureyre(r.a)'dan şöyle dediği rivayet edilmiştir: \"Resulüllah (s.a.v)'i şöyle buyururken işittim: Peygamberlikten geriye ancak mübeşşirat kalmıştır.Dediler ki: 'Mübeşşirat nedir Ey Allah'ın Resülü?' şöyle buyurdu: Salih rüyadır.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 437, text: "Ebu Hureyre (r.a)'dan Resulüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir.' \"Kim beni rüyada görürse, yakında beni uyanık iken de görecektir. Ya da sanki beni uyanık iken görmüş gipidir. şeytan benim suretimegiremez.\" (Buharive Müslim),", source: "Hadis-i Şerif" },
    { id: 438, text: "Ebu Katade (r.a)' dan Resulüllah (s.a.v) 'in şöyle buyurduğu rivayet edilmiştir.: \"Salih rüya, başka bir rivayette de güzel rüya Allah'tandlr.   Kötü rüya ise şeytandandır. Kim hoşlanmadığı bir rüya görürse hemen sol tarafına üç defa tükürsün ve şeytandan -Allah'a- sığınsın. Çünkü ancak böylelikle ona bir zarar veremez.\" (Buharı ve Müslim) SELAM VERMENİN VE ONU YAYMANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 439, text: "Abdullah b.Amr el-Âs (r.a)'dan şöyle rivayet edilmiştir: \"Adamın biri Resûlüllah (s.a.v)'e 'İslam'ın en hayırlı ameli nedir?' diye bir soru sordu. Resûlüllah (s.a.v) şöyle buyurdu: Yemek yedirmen, tanıdığına ve tanımadığına selam vermendir,\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 440, text: "Ebu Umâre Berâe b.Azib (r.a) 'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bize yedi hususta emir buyurdu; hastayı ziyaret etmek, cenazeyi takip etmek, aksırana 'Allah sana merhamet etsin' demek, zayıfa yardım etmek, mazluma destekçi olmak, sela mı yaymak ve yemin edenin  SELAM VERMENİN VE ONU YAYMANIN FAZİLETİ yeminini yerine getirmesine yardımcı olmak.\" (Buharı ve Müslim rivayet etmişlerdir. Bu, Buhari rivayetlerinin lafızlarından biridir.)", source: "Hadis-i Şerif" },
    { id: 441, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İman etmedikçe cennete giremezsiniz. Birbirinizi sevmedikçe de iman etmiş olamazsınız. Yaptığınız takdirde birbirinizi seveceğiniz bir şeyi size bildireyim mi? Selâmı aranızda yayınız.\" (Müslim) SELAMLAŞMANIN ŞEKLİ", source: "Hadis-i Şerif" },
    { id: 442, text: "İmrân b. Husayn (r.a)'dan şöyle dediği rivayet edilmiştir: \"Bir adam Peygamber (a.s)'a gelip dedi ki: 'Esselâmü Aley-küm.' Peygamber (a.s) ' da onun selamını aldı. Sonra oturdu. Resûlüllah (s.a.v) buyurdu ki:   'On-sevap.' Sonra bir başkası geldi ve 'Esselâmü Aleyküm ve Rahmetüllâhi ' dedi. Peygamber (a.s) onun da selamım aldı ve adam oturdu. ResûlüIIah (s.a.v) buyurdu ki: 'Yirmi-sevap.' Sonra diğer bir adam geldi ve 'Esselâmü Aleyküm ve Rahmetüllâhi veberakâtühü'dedi. Peygamber (a.s) onun da sela mını aldı. Adam oturdu. Bu sefer ResûlüIIah (s.a.v) şöyle buyurdu: Otuz-sevap aldı.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 443, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"ResûlüIIah (s.a.v) bir söz söylediği zaman, anlaşılıncaya kadar onu üç defa tekrar ederdi. Bir topluluğa geldiği zaman da onlara selam verir ve selamı üç defa tekrar ederdi.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 444, text: "Mikdad (r.a)'dan rivayet edilen uzun bir hadiste şöyle demiştir: \"Biz, ResûlüIIah (s.a.v)'in hissesi olan sütü kaldırır-ayırırdık. Peygamber (a.s) gece gelir, uyuyanı uyandırmayacak, uyanık olana da duyuracak kadar bir sesle selâm verirdi. Peygamber (a.s) -yine-geldi, eskiden olduğu gibi selâm verdi.\" (Müslim)  SELÂMIN ÂDABI SELÂMIN ÂDABI", source: "Hadis-i Şerif" },
    { id: 445, text: "Ebu Umâme Suday b. Aclân el-Bâhili (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"insanların Allah'a en yakın olanı selâm vermeye ilk önce başlayandır.\" (Ebu Davud iyi bir isnatla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 446, text: "Ebu Hureyre (r.a)'dan, namazını âdâbıyla kılmayan kimseyle alakalı hadisde şöyle rivayet edilmiştir; \"Bir adam -mescide- gelip namaz kıldı. Sonra Resûlüllah (s.a.v)'in yanına varıp O'na selam verdi. Peygamber (a.s) onun selamını aldı ve şöyle buyurdu: Dön ve -tekrar- namaz kıl; çünkü sen namaz kılmadın! Adam hemen döndü ve namazı yeniden kıldı. Sonra geldi ve Peygamber (a.s)'a selam verdi. Nihayet bu durumu üç defa tekrar etti.\" (Buhari ve Müslim) EVİNE GİRDİĞİNDE SELAM VERMENİN MÜSTEHABLIĞI", source: "Hadis-i Şerif" },
    { id: 447, text: "Enes (r.a), Resûlüllah (s.a.v)'in kendisine şöyle buyurduğunu rivayet etmiştir: \"Ey oğulcağızım! Ehlinin yanına girdiğin zaman selam ver ki, senin ve ailenin üzerine bereket olsun.\" (Tirmizi rivayet etmiş ve hadis hasendİr, sahihtir demiştir.) ÇOCUKLARA SELAM VERMEK", source: "Hadis-i Şerif" },
    { id: 448, text: "Enes (r.a)'dan, şöyle rivayet edilmiştir: \"Enes, çocukların yanına uğradı. Onlara selam verdi ve dedi ki: Resûlüllah (s.a.v) böyle yapıyordu.\" (Buhari ve Müslim) ERKEĞİN MAHREMİNE VEYA FİTNEDEN UZAK OLAN YABANCI KADINLARA SELAM VERMESİ", source: "Hadis-i Şerif" },
    { id: 449, text: "Sehl b. Sa'd (r.a)'dan şöyle dediği rivayet edilmiştir: \"Aramızda bir kadın -başka bir rivayette; ihtiyar bir kadın-bulunuyordu. Pazı köklerini toplar, çömleğe koyup pişirir, biraz da arpa öğütürdü.  KAFİRLERE İLK ÖNCE SELAM VERMENİN HARAM OLUŞU,... Biz Cuma'yı kılıp döndüğümüz zaman kendisine selam verirdik, o da hazırladığı yemeklerden bize takdim ederdi.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 450, text: "Ümmü Hânî Fâhita b. Ebu Talih (r.a)'dan şöyle dediği rivayet edilmiştir: \"Mekke'nin fethi günü Resûlüllah (s.a.v)'e geldim. Peygamber (a.s) yıkanıyor, Fâtıma da onu bir elbise ile örtüyordu. Ben kendisine selam verdim.\" (Müslim) KAFİRLERE İLK ÖNCE SELAM VERMENİN HARAM OLUŞU, ONLARIN SELAMININ ALINIŞI, MÜSLÜMAN VE KAFİRLERDEN OLUŞAN TOPLULUĞA SELAM VERMENİN MÜSTEHAB OLMASI HAKKINDADIR", source: "Hadis-i Şerif" },
    { id: 451, text: "Ebu Hureyre (r.a) 'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu riayet edilmiştir: \"Yahudi ve Hristiyanlara selam vermeye ilk önce siz başlamayınız. Yolda   onlardan biri ile karşılaştığınızda da, yolun kenarından yürümeleri için onları sıkıştırınız.\" (Müslim) MECLİSTEN KALKARKEN SELAM VERMENİN MÜSTEHABLIĞI", source: "Hadis-i Şerif" },
    { id: 452, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz bir meclise vardığı zaman selam versin. Oradan ayrılmayı arzuladığı zaman da selam versin. İlk önce verilen selam, sonrakinden daha üstün değildir.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.) İZİN İSTEMENİN ÂDABI", source: "Hadis-i Şerif" },
    { id: 453, text: "Ebu Musa el-Eş'ari (r.a)'dan, Resûlüilah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İzin istemek üç defadır. Eğer sana izin verilirse-girersin, ama izin verilmezse hemen dönersin.\" (Buhari ve Müslim)  İZİN İSTEMENİN ÂDABI", source: "Hadis-i Şerif" },
    { id: 454, text: "Kilde b, Hanbel (r.a)'dan şöyle rivayet edilmiştir: \"Ben, Resûlüllah (s.a.v)'e gitmiş ve selam vermeden huzuruna girmiştim. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Dön ve; Eselâmü Aleyküm, gireyim mi?de.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 455, text: "Enes (r.a)'dan, Isrâ ile ilgili meşhur hadisinde şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) şöyle devam etti; sonra Cebrail beni dünya semasına çıkardı ve kapının açılmasını İstedi. Denildi ki. 'Kim o?' O da şöyle dedi: 'Cebrail.' Denildi ki: 'Senin yanındaki kim?' Cebrail; 'Muhammed' dedi. Sonra ikinci, üçüncü, dördüncü ve diğer semalara çıkıldı. Her semanın kapısında; 'Kim o? ' diye sorulduğunda, 'Cebrail' diyordu.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 456, text: "Ebu Zer (r.a)'dan şöyle dediği rivayet edilmiştir:   \"Gecelerden birinde dışarıya çıkmıştım. Bir de ne göreyim, Resûlüllah (s.a.v) yalnız başına yürüyor! Ben de ayın gölgesinde yürümeye başladım. Resûlüllah (s.a.v) dönünce beni gördü ve şöyle buyurdu: Kim o? Ben de dedim ki: Ebu Zer.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 457, text: "Cabir (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben, Resûlüllah (s.a.v)'e geldim ve kapıyı çaldım. Buyurdu ki: Kim o? Ben de dedim ki: Benim. Bunun üzerine sanki hoşlanmayarak şöyle buyurdu: Ben, Ben - neymiş?\" (Buharı ve Müslim) AKSIRAN 'ELHAMDÜLİLLAH' DEDİĞİNDE 'YERHAMÜKELLAH' DEMEK", source: "Hadis-i Şerif" },
    { id: 458, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah aksırmayı sever, esnemekten ise hoşlanmaz. Sizden biriniz aksırdığı ve Allah'a hamd ettiği zaman, onu işiten her müslümanın üzerine 'Allah sana merhamet etsin' demek bir haktır. Esnemek ise ancak şeytandandır. Sizden biriniz esnemeye başladığında, elinden geldiği kadar onu geri çevirmeye  MUSAFAHA VE GÜLER YÜZLÜ OLMAK çalışsın. Çünkü sizden biriniz esnediğinde şeytan ona güler.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 459, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz aksırdığı zaman 'Elhamdülillah' desin. Kardeşi veya arkadaşı da ona 'Allah sana merhamet etsin' desin. Aksırana 'Yerhamükellah' dendiğinde de 'Yehdîkümullah ve yuslihu bâleküm' diye mukabelede bulunsun.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 460, text: "Ebu Musa (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim: Sizden biriniz aksırıp da 'Elhamdülillah' dediği zaman, sizde ona 'Yerhamükallah' deyiniz. Eğer Allah'a hamd etmemişse, siz de ona 'Yerhamükallah'demeyiniz. (Müslim) MUSAFAHA VE GÜLER YÜZLÜ OLMAK", source: "Hadis-i Şerif" },
    { id: 461, text: "Ebu Hattab Katâde (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben Enes'e dedim ki: Resûlüllah (s.a.v)'in ashabı arasında musafaha olur muydu? Dedi ki: Evet.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 462, text: "Berâ (r.a) ' dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İki müslüman karşılaştıklarında musafaha yaparlarsa, ayrılmadan önce günahları bağışlanır.\" (Ebu Davud)", source: "Hadis-i Şerif" },
    { id: 463, text: "Enes (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Bir adam 'Ey Allah'ın Resulü, bizden biri kardeşiyle veya arkadaşıyla karşılaştığında ona eğilebilir mi?' dedi. Resûlüllah: 'Hayır'dedi. Adam: Peki ona sarılıp öpebilir mi?' Resûlüllah : 'Hayır'dedi. Adam: 'Elini tutup musafaha edebilir mi?' Resûlüllah: Evet, dedi.\" (Tirmizi rivayet etmiş ve hadis hasendİr demiştir.)  HASTAYI ZİYARET", source: "Hadis-i Şerif" },
    { id: 464, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) Hz. Ali'nin oğlu Hasan'ı (r.a) öptü. Akra' b. Habis dedi ki: Benim on tane evladım var; hiç birini öpmedim. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Merhamet etmeyen, merhamet olunmaz.\" (Buharı ve Müslim) HASTAYI ZİYARET", source: "Hadis-i Şerif" },
    { id: 465, text: "Berâ b. Azib (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bize hasta ziyaretini, cenazeyi takip etmeyi, aksırana 'Yerhamükallah' demeyi, yemin edenin yeminini yerine getirmesi için yardım etmeyi, mazluma yardım etmeyi, davete icabet etmeyi ve selamı yaymayı emretti.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 466, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir müslümanın diğer bir müslüman Üzerine olan hakkı beştir; Selamı almak, hastayı ziyaret etmek, cenazeyi takip etmek, davete katılmak ve   aksırana 'Yerhamukellah' demek.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 467, text: "Ebu Musa (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurdğu rivayet edilmiştir: \"Hastayı ziyaret ediniz, açı doyurunuz ve esirin -bağını çözünüz- hürriyetini veriniz.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 468, text: "Sevbân (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir müslüman diğer bir müslüman kardeşini ziyaret ettiğinde, dönünceye kadar cennet hurfesi toplamaya devam eder. Denildi ki: Ey Allah'ın Resulü, cennet hurfesi de nedir? Buyurdu ki: Cennetin olgunlaşmış hurmalarıdır.\" (Müslim)  HASTAYA OKUNAN DUALAR", source: "Hadis-i Şerif" },
    { id: 469, text: "Ali (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim: Hangi bir müslûman, diğer bir müslümanı sabahleyin ziyaret etse, akşamlayıncaya kadar yetmiş bin melek ona istiğfar eder. O hastayı akşam vakti ziyaret ederse, sabah oluncaya kadar yetmiş bin melek ona istiğfar eder. Ayrıca onun için cennette derilmiş meyveler vardır.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 470, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v), bir insan bir yerinden şikayet ettiğinde, ya da bir yerinde yara bere çıktığında parmağını şöyle yaparak -Râvî Süfyân b. Uyeyne şehadet parmağını yere koyup kaldırdı- buyururdu ki: 'Bismillahi türbetü erdina, bi-rîkati ba'dina, yüşfâ bihi seki-munâ bi-izni Rabbinâ-Allah'ın ismiyle başlıyorum; yeryüzümüzün toprağı, bazımızın tükürüğü ve Allah'ın izniyle hastamız şifa bulur.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 471, text: "Hz. Âişe (r,a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) ehlinden hastalanan bazı kimseleri ziyaret edip sağ eliyle mesheder ve şöyle buyururdu: İnsanların Rabbi olan Allah'ım, bu hastanın sıkıntısını gideriver ve şifa ihsan eyle. Sen şifa verensin, senin şifadan başka şifa yoktur, hiçbir hastalık kalmayacak şekilde şifa ihsan eyle.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 472, text: "Enes (r.a)'dan, kendisinin Sabit'e (r.a) şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in hastaya yaptığı dua ile sana dua edeyim mi? Sabit; Evet, dedi. Enes; İnsanların Rabbi olan, sıkıntı ve acıyı gideren Allah'ım, şifa ihsan eyle! Sen şifa verensin. Senden başka şifa veren yoktur. Hiçbir hastalık kalmayacak şekilde şifa ihsan eyle.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 473, text: "İbn-i Abbas (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) bir bedevinin yanına girip kendisini ziyaret etti. Ziyaret ettiği hasta kimselere buyurduğu gibi şöyle buyurdu: Geçmiş olsun, İnşaallah günahlardan temizlenmeye vesile olur.\" (Buhari)  HASTAYA OKUNAN DUALAR", source: "Hadis-i Şerif" },
    { id: 474, text: "Ebu Saîd el-Hudrî (r.a)'dan şöyle rivayet edilmiştir: \"Cebrail (a.s) Peygamber (s.a.v)'e gelerek şöyle dedi: Ey Muhammed! Hastalığından-şikayetin mi var? Resûlüllah: Evet, buyurdu. Bunun üzerine Cebâİl şöyle dua etti: Allah'ın ismiyle sana dua ediyorum. Sana eziyet veren her şeyden, herhangi bir kişinin kötülüğünden veya hasedçinin göz değmesinden Allah sana şifa versin. Allah'ın adıyla sana okuyorum.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 475, text: "İbn-i Abbas (r.a)'dan şöyle rivayet edilmiştir: \"Hz. Ali b. Tâlib (r.a), Resûlüllah (s.a.v)'in vefat ettiği hastalığı sırasında huzurundan ayrıldığı zaman insanlar dediler ki: Ey Hasan'ın babası, Resûlüllah (s.a.v) nasıl sabahladı? Hz. Ali: Allah'a hamd olsun ki, sabaha iyi olarak ulaştı, dedi.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 476, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben Resûlüllah (s.a.v)'i ölümü esnasında gördüm; yanında içi su dolu bir bardak bulunuyordu. Elini bardağa sokuyor, sonra su ile yüzünü mesh ediyor ve şöyle buyuruyordu: Allah'ım, Ölüm sıkıntılarına ve ölüm baygınlıklarına karşı bana yardım et.\" (Tirmizi)", source: "Hadis-i Şerif" },
    { id: 477, text: "Imrân b. Husayn (r.a)'dan şöyie rivayet edilmiştir: \"Cüheyne kabilesinden bir kadın, zinadan hamile kalmış bir halde Resûlüllah (s.a.v)'e geldi ve dedi ki: Ey Allah'ın Resulü, Had cezasını gerektiren bir suç yaptım, o cezayı bana uygula! Resûlüllah (s.a.v) kadının velisini çağırdı ve ona şöyle buyurdu: Ona iyi bak; çocuğunu doğurunca bana getir. Velisi de- kendisine denileni yaptı. Bunun üzerine Resûlüllah (s.a.v) kadının elbisesinin üzerine iyice bağlanmasını emretti. Sonra emir verdi de recm olundu. Daha sonra da üzerine -cenaze- namazı kıldı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 478, text: "Ibn-i Mes'ud (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) sıtmaya yakalandığı bir sırada huzuruna girdim, kendisine dokundum ve dedim ki: Şüphesiz sen çok şiddetli bir sıtmaya tutulmuşsun! Buyurdu ki: Evet, ben sizden iki kişinin sıtmaya tutulduğu gibi bir sıtmaya tutuldum!\" (Buharı ve Müslim) ÖLÜMÜ YAKLAŞAN BİRİNE 'LÂ İLAHE İLLALLAH' TELKİNİ  ÖLÜNÜN GÖZÜ YUMULUNCA OKUNACAK DUA", source: "Hadis-i Şerif" },
    { id: 479, text: "Muaz (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kimin en son sözü 'Lâ ilahe illallah' olursa cennete girer.\" (Ebu Davud ve Hakim rivayet etmiş; isnadı sahihtir demiştir.) ÖLÜNÜN GÖZÜ YUMULUNCA OKUNACAK DUA", source: "Hadis-i Şerif" },
    { id: 480, text: "Ümmü Seleme (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) Ebu Seleme -vefat ettiğinde- yanına vardı ve açık olan gözünü kapadı, sonra şöyle buyurdu: Şüphesiz ki ruh alınınca göz onun peşi sıra baka kalır. Ailesinden bir kısmı feryad-ı figan ettiler. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Kendinize ancak hayır duada bulununuz. Çünkü melekler, sizin yaptığınız duaya âmin derler. Sonra şöyle devam etti: Allah'ım, Ebu Sele-me'yi affet. Hidayete ermiş kullar arasında derecesini yükselt. Geride kalanlar arasından ona iyi bir halef kıl. Ey âlemlerin Rabbi olan Allah'ım, bizi ve onu affeyle. Kabrini genişlet, kabrini nurlandır.\" (Müslim)   ÖLÜNÜN YANINDA SÖYLENECEKLER", source: "Hadis-i Şerif" },
    { id: 481, text: "Ümmü Seleme (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Siz bir hastanın veya bir ölünün yanında hazır bulunduğunuz zaman hayır konuşun. Çünkü melekler, sizin söylediklerinize âmin diyorlar. Ümmü Seleme dedi ki: Ebu Seleme vefat ettiği zaman Resûlüllah (s.a.v)'e gittim ve dedim ki: Ey Allah'ın Resulü, Ebu Seleme vefat etti. Resûlüllah (s.a.v) şöyle buyurdu: Allah'ım, beni ve onu affeyle, onun yerine bana güzel bir karşılık ihsan eyle, diye dua et. Ben de bunu söyledim ve Allah bana ondan daha hayırlı karşılığı, Muhammed'i verdi.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 482, text: "Ebu Musa (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir kulun çocuğu öldüğü zaman Yüce Allah meleklere şöyle buyurur:  ÖLÜNÜN YANINDA SÖYLENECEKLER Kulumun çocuğunu aldınız mı? Onlar: Evet, derler. Yüce Allah: Kulumun kalbinin meyvesini aldınız öyle mi?buyurur. Onlar: Evet, derler. Bu sefer yüce Allah: Kulum ne dedi?diye sorar. Derler ki: Sana hamd etti ve 'İnnâ lillâhi ve innâ ileyhi râciûn- Biz Allah'dan geldik yine ona dönücüleriz- dedi. Bunun üzerine Yüce Allah şöyle buyurur: Kuluma cennette bir köşk bina ediniz ve o binanın adını 'Hamd Evi'diye isimlendiriniz.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 483, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yüce Allah şöyle buyurur: Mü'min kulumun dünya ehlinden en çok sevdiği birini aldığım zaman sabredip de karşılığını benden beklerse, benim katımda ona verilecek mükafat ancak cennettir.\" (Buharı) BAĞIRIP ÇAĞIRMADAN ÖLÜYE AĞLAMANIN CAİZ OLUŞU", source: "Hadis-i Şerif" },
    { id: 484, text: "Ibn-i Ömer (r.a)'dan şöyle rivayet edilmiştir;   \"Resûlüllah (s.a.v), beraberinde Abdurrahman b. Avf, Sa'd b. Ebu Vakkâs ve Abdullah b. Mesûd (r.a) olduğu halde Sa'd b. Ubâ-de'yi hastalığında ziyaret etti. Resûlüllah (s.a.v) ağladı; Resûlüllah (s.a.v)'in ağladığını gören topluluk da ağladı. Bunun üzerine Peygamber (a.s) şöyle buyurdu: Işitiyor musunuz? Allah göz yaşının akması ve kalbin hüzünlenmesi sebebiyle -kulunu- azaba çarptırmaz, Ama -dilini işaret ederek- bunun yüzünden ya azap eder, ya da merhamet eder.\" (Buharı ve Müslim) ÖLÜDE GÖRÜLEN ÇİRKİN DURUMLARIN SÖYLENMEMESİ", source: "Hadis-i Şerif" },
    { id: 485, text: "Resûlüllah (s.a.v)'in azatlı kölesi Ebu Râfi' Esleme (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Kim bir ölüyü yıkar da -onda gördüğü çirkin halleri- saklarsa, Allah o kimseyi kırk defa bağışlar.\" (Hakim rivayet etmiş ve Müslim şartı üzere sahihtir demiştir.) CENAZE NAMAZINI KILMAK, KABRE KADAR YOLCU ETMEK VE KADINLARIN CENAZEYİ TAKİP ETMELERİNİN MEKRUH OLUŞU  ÖLÜDE GÖRÜLEN ÇİRKİN DURUMLARIN SÖYLENMEMESİ", source: "Hadis-i Şerif" },
    { id: 486, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim, namazı kılana kadar cenazede hazır bulunursa ona bir kırat; kim de defnedilînceye kadar cenazede hazır bulunursa ona da iki kırat vardır. Denildi ki: İki kırat nedir, Ey Allah'ın Resulü? Resûlüllah (s.a.v) şöyle buyurdu: İki büyük dağ kadardır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 487, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim inanarak ve sevabını Allah'dan umarak bir müslümanın cenazesini takip eder, hatta cenaze namazını kılar ve defnedilinceye kadar ayrılmazsa, her bir Uhud dağı kadar olan iki kırat mükafatla döner. Kim cenaze namazını kılar ve defnedilmeden geri dönerse o da bir kırat mükafatla döner.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 488, text: "Ümmü Atiyye (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz, cenazeyi takip etmekten men edildik, ama bu hususta bize bir zorlama yapılmadı.\" (Buharı ve Müslim)   CENAZE NAMAZI KILANLARIN ÇOKLUĞU, SAFLARI ÜÇ VEYA DAHA FAZLA YAPMALARI", source: "Hadis-i Şerif" },
    { id: 489, text: "Hz. Âişe (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Herhangi bir cenaze üzerine, müslümanlardan sayıları yüze ulaşan bir cemaat namaz kılıp şefaat getirirlerse, mutlaka ona yaptıkları şefaat kabul olunur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 490, text: "Ibn-i Abbas (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (sa.v)'i şöyle buyururken işittim: Her hangi bir müslüman ölür de, cenazesine Allah'a hiçbir şeyi ortak koşmayan kırk kişi katılırsa, Allah onların ölen kimse hakkındaki şefaatlerini mutlaka kabul eder.\" (Müslim) CENAZE NAMAZINDA OKUNACAK DUALAR  CENAZE NAMAZINDA OKUNACAK DUALAR", source: "Hadis-i Şerif" },
    { id: 491, text: "Ebu Hureyre (r.a) şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) cenaze namazı kılarken şu duayı yapmıştır: Allah'ım! Sen onun Rabbisin, onu sen yarattın, onu Islam'a sen ilettin, onun ruhunu sen aldın, onun gizli ve aşikar yaptıklarını sen bilirsin; ona şefaat etmek için senin huzuruna geldik.\" (Ebu Davud)", source: "Hadis-i Şerif" },
    { id: 492, text: "Abdullah b. Ebu Avfâ (r.a)'dan şöyle rivayet edilmiştir: \"Bu zat, kendi kızının cenaze namazını dört tekbirle kıldı. Dördüncü tekbiri aldıktan sonra iki tekbir arasındaki süre kadar ayakta kalıp, onun için istiğfar diledi ve duada bulundu. Sonra da şöyle dedi: Resûlüllah (s.a.v) aynı şekilde yapardı.\" (Hakim rivayet etmiş ve hadis sahihtir demiştir.) CENAZEDE ACELE ETMEK", source: "Hadis-i Şerif" },
    { id: 493, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Cenazeyi -yerine ulaştırmada- acele ediniz! Eğer iyi kimse ise, kendisine bir an Önce hayrı takdim etmiş olursunuz. Eğer böyle değilse, bir an önce şerri omuzlarınızdan atmış olursunuz.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 494, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Mü'minin ruhu, borcu ödeninceye kadar borcundan dolayı bağlı kalır.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.) KABRİSTANDA NASİHAT", source: "Hadis-i Şerif" },
    { id: 495, text: "Hz. Ali (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz, Bakî' el-Gurkad mezarlığında bir cenazede idik. Resûlüllah (s.a.v) geldi ve oturdu; biz de onun etrafına oturduk. Yanında bir asa vardı. Başını önüne eğmiş, asası ile yere bir takım şeyler çiziyordu. Sonra şöyle buyurdu: Sizden her birinizin cehennemdeki yeri de, cennetteki yeri de mutlaka yazılmıştır. Bunun üzerine ashab dediler ki: Ey Allah'ın Resûlü,o zaman alın yazımıza bakıp her şeyden elimizi çekelim mi? Resûlüllah (s.a.v) şöyle buyurdu: Çalışınız; hepinize kendiniz için yaratılan şey neyse o müyesser olur.\" (Buhari ve Müslim)  ÖLÜYÜ DEFNETTİKTEN SONRA BİRAZ OTURUP DUA YAPMAK ÖLÜYÜ DEFNETTİKTEN SONRA BİRAZ OTURUP DUA YAPMAK", source: "Hadis-i Şerif" },
    { id: 496, text: "Ebu Amr dan, veya Abu Abdullah, ya da Ebu Leyla diye anılan Osman b. Affan (r.a)'dan söyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) ölüyü defin işi bittikten sonra başında durdu ve şöyle buyurdu: Kardeşiniz için bağışlanma dileyiniz. Sorulan sorulara-dayanma kuvveti dileyiniz; çünkü o şu an sorgulanmaktadır.\"\" (Ebu Davud) ÖLÜ İÇİN SADAKA VERMEK, DUA ETMEK VE İNSANLARIN ÖLÜYÜ ÖVMELERİ", source: "Hadis-i Şerif" },
    { id: 497, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam Resûlüllah (s.a.v)'e şöyle dedi: Annem birden vefat etti. Tahminime göre eğer konuşabilseydi sadaka verecekti. Şimdi benim onun namına sadaka vermemden kendisine bir sevap olur mu? Resûlüllah (s.a.v): Evet, olur buyurdu.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 498, text: "Enes (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Peygamberimiz (a.s)'ın önünden bir cemaat- cenaze ile geçtiler. Orada bulunanlar cenazeyi iyilikleriyle övdüler. Bunun üzerine Resûlüllah (s.a.v); Vacip oldu, buyurdu. Sonra başka bir cenaze geçti. Resûlüllah (s.a.v) bu sefer de; Vacip oldu, buyurdu. Ömer b.Hattab (r.a) dedi ki: Ne vacip oldu? Resûlüllah (s.a.v) şöyle buyurdu: Şu, hayırla andığınız kimse ki artık ona cennet vacip oldu. Şu da, kendisini kötülükle andığınız kimse ki,ona da ateş vacip oldu. Çünkü siz, Allah'ın yeryüzündeki şahitlerisiniz.\" (Buharı ve Müslim) KÜÇÜK ÇOCUĞU ÖLENLERİN FAZİLETLERİ", source: "Hadis-i Şerif" },
    { id: 499, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hangi bir müslümanın buluğ çağına ulaşmamış üç çocuğu ölürse, Yüce Allah ölen o çocuklara olan rahmetinden dolayı onu cennete koyar.\" (Buharı ve Müslim)  KÜÇÜK ÇOCUĞU ÖLENLERİN FAZİLETLERİ", source: "Hadis-i Şerif" },
    { id: 500, text: "İbn-i Ömer (r.a)'ın rivayetine göre, Resûlüllah (s.a.v) Semûd diyarındaki Hıcr denilen mevkie ulaştığında ashabına şöyle buyurmuştur: \"Şu azaba uğratılmış kavmin diyarına girmeyiniz; ancak ağlayarak girebilirsiniz. Eğer ağlayamıyorsanız oraya girmeyin ki, onlara isabet eden -belalar- size de isabet etmesin.\" (Buharı ve Müslim) YOLCULUK VE KONAKLAMAK", source: "Hadis-i Şerif" },
    { id: 501, text: "Ka'b b. Mâlik (r.a)'dan şöyle rivayet edilmiştir: \"Peygamber (a.s) Tebûk savaşına Perşembe günü yola çıkmıştır. O, Perşembe günü yola çıkmayı seviyordu.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 502, text: "İbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Eğer insanlar, tek başına yolculuğa çıkmaktaki mahzurları benim bildiğim gibi bilselerdi, hiç biri geceleyin yalnız başına yürümezdi.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 503, text: "Amr b. Şuayb babasından, o da dedesinden (r,a), Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir yolcu şeytandır-onunla beraberdir. İki yolcu ise çift şeytandır. Üç yolcu ise bir cemaattir.\" (Ebu Davud, Tirmizi ve Nesei sahih bir isnatla rivayet etmişlerdir. Tirmizi hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 504, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yeşilliğin, otların- bol olduğu bir yerde yolculuk yaptığınızda, deveye yer yüzündeki yeşilliklerden nasip alma hakkı tanıyınız. Ama çıplak kuru bir arazide yolculuk yaparsanız, takatiniz tükenmeden süratle orayı geçiniz. Gecelediğiniz zaman yol üzerinde konaklamaktan kaçınınız. Çünkü yollar, geceleyin hayvanların ve haşaratın gelip geçtiği ve konakladığı yerledir.\" (Müslim)  YOL ARKADAŞINA YARDIM ETMEK", source: "Hadis-i Şerif" },
    { id: 505, text: "Ebu Katâde (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) yolculukta geceleyin istirahata çekildiği zaman sağ yanı üzerine uzanırdı. Sabah vaktinin girmesinden az evvel istirahat ederse, kolunu diker ve başını avucunun içine koyardı.\" (Müslim) YOL ARKADAŞINA YARDIM ETMEK", source: "Hadis-i Şerif" },
    { id: 506, text: "Ebu Saîd el-Hudri (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz bir ara yolculukta iken hayvanının üzerinde bir adam çıkıp geldi. Gözünü bir sağa bir sola çevirip duruyordu. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Kimin beraberinde fazla bir bineği varsa, onu bineği olmayana versin. Kimin fazla azığı varsa, onu azığı olmayana versin. Böylelikle mal sınıfından sayabildiği kadar saydı. Hatta biz, bizden birinin malının fazlasında herhangi bir hakkı olmadığını gördük.\" (Müslim)   YOLCULUK İÇİN BİNEĞE BİNİLDİĞİNDE VE YOLCULUK ESNASINDA DUA YAPMAK", source: "Hadis-i Şerif" },
    { id: 507, text: "Ibn-i Ömer (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) yolculuğa çıktığında hayvanının üzerine çıkıp üç kere tekbir getirir, sonra şöyle buyururdu: Bunları bizim emrimize veren Allah'ı noksan sıfatlardan tenzih ederim. Yoksa biz bunların üstesinden gelemezdik. Şüphesiz ki biz Rabbimize dönücüleriz. Allah'ım, şüphesiz ki biz bu yolculuğumuzda senden iyilik, takva ve razı olacağın amel diliyoruz. Allah'ım, bu seferimizi bize kolay eyle ve uzakları dürüp yakınlaştır. Allah'ım, sen yolculukta dost, aile efradımız için de vekilsin, Allah'ım, yolculuğun sıkıntısından, üzücü manzara ile karşı karşıya kalmaktan, mal, aile ve çocukta olabilecek sevimsiz değişikliklerden sana sığınıyorum. Yolculuktan döndüğü zaman bunları söyler ve şunları da eklerdi: Yolculuktan dönmüş bir halde, tövbe edici, ibadet edici ve Rabbimize hamd edicileriz.\" (Müslim)  YOLCULUK İÇİN BİNEĞE BİNİLDİĞİNDE DUA YAPMAK", source: "Hadis-i Şerif" },
    { id: 508, text: "Abdullah b. Sercis (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) yolculuk yaptığı zaman yolculuğun sıkıntısından, sevimsiz değişikliklerden, yükseldikten sonra aşağı düşmekten, mazlumun bedduasından, aile ve malda olabilecek kötü görünümlerden Allah'a sığınırdı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 509, text: "Cabir (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Biz yüksek bir yere çıkarken tekbir getirir, inerken de teşbih ederdik.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 510, text: "Ebu Musa el-Eş'arî (r.a)'dan söyle dediği rivayet edilmiştir: \"Biz bir yolculukta Resûlüllah (s.a.v) ile beraber bulunuyorduk. Bir vadiye   tırmanırken tekbir ve tahlil getiriyorduk; seslerimiz de yükseliyordu. Bunun üzerine Resûlüllah (ş.a.v) şöyle buyurdu: Ey insanlar! Sesinizi duyacağınız kadar yükseltiniz; çünkü siz sağır veya yanınızda bulunmayan birine seslenmiyorsunuz. O-Allah- sizinle beraberdir, O hakkıyla işitendir ve -size- çok yakındır.\" (Buharı ve Müslim) YOLCULUKTA DUA ETMEK", source: "Hadis-i Şerif" },
    { id: 511, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Üç dua vardır ki, kabul olunacağında hiçbir şüphe yoktur; Mazlumun duası, misafirin duası ve ana babanın evladına yaptığı duadır.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir. Ebu Davud rivayetinde 'Evladına' lafzı yoktur.) İNSANLARDAN VEYA BAŞKALARINDAN KORKULDUĞUNDA YAPILACAK DUA  İSTİRAHAT ESNASINDA OKUNACAK DUA", source: "Hadis-i Şerif" },
    { id: 512, text: "Ebu Musa el-Eş'ari (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) bir topluluktan ürperdiği zaman şöyle buyururdu: Allah'ım, senin korumanı onlara karşı siper yapıyoruz ve onların şerlerinden sana sığınıyoruz.\" (Ebu Davud ve Nesai sahih bir isnatla rivayet etmiştir.) İSTİRAHAT ESNASINDA OKUNACAK DUA", source: "Hadis-i Şerif" },
    { id: 513, text: "Havle b. Hakim (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim; Kim bir yerde konaklar da sonra: 'Yaratıkların şerrinden, Allah'ın tam kelimeleriyle sığınırım' derse, bulunduğu o yerden göç edinceye kadar kendisine hiçbir şey zarar veremez.\" (Müslim) MİSAFİRİN İHTİYACINI GÖRDÜKTEN SONRA HEMEN AİLESİNE DÖNMESİNİN MÜSTAHAPLIĞI", source: "Hadis-i Şerif" },
    { id: 514, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yolculuk, azaptan bir parçadır. Çünkü sizden herhangi birinizin yemeğine, içmesine ve uyumasına mani olmaktadır. O halde herhangi biriniz yolculuktaki maksadını yerine getirdiğinde hemen ailesine dönmekte acele etsin.\" (Buhari ve Müslim) YOLCULUKTAN GÜNDÜZ DÖNMENİN MÜSTEHAB, GECE DÖNMENİN İSE MEKRUH OLMASI", source: "Hadis-i Şerif" },
    { id: 515, text: "Cabir (r.a)' dan,Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden birinizin ayrılığı çok uzadığı zaman, ailesinin yanına sakın gece dönmesin.\" (Buhari ve Müslim) YOLCULUKTAN DÖNENİN, VATANINI GÖRÜNCE YAPACAĞI DUA  YOL. DÖNENİN, MESCİDE UĞRAYIP İKİ REKAT NAMAZ KILMASI", source: "Hadis-i Şerif" },
    { id: 516, text: "Enes (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) ile birlikte -yolculuktan- dönüyorduk. Nihayet Medine'nin sırtlarına gelmiştik ki, Resûlüllah (s.a.v); 'Sıhhat afiyet içinde-tövbe ve ibadet yaparak, Rabbimize hamd ederek dönmekteyiz' buyurdu. Tâ Medine'ye gelinceye kadar böyle söylemeye devam etti.\" (Müslim) YOLCULUKTAN DÖNENİN, EVVELA MESCİDE UĞRAYIP İKİ REKAT NAMAZ KILMASININ MÜSTEHAPLIĞI", source: "Hadis-i Şerif" },
    { id: 517, text: "Ka'b b. Mâlik (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) yolculuktan döndüğü zaman doğruca mescide gider ve orada iki rek'at namaz kılardı.\" (Buhari ve Müslim) KADINLARIN YALNIZ BAŞINA YOLCULUĞUNUN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 518, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah'a ve ahiret gününe iman eden bir kadının bir gün ve bir gecelik yolculuğa, yanında bir mahremi olmadan çıkması helal değildir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 519, text: "Ibn-i Abbas (r.a)'ın, Resûlüllah (s.a.v)'i şöyle buyururken işittiği rivayet edilmiştir: \"Bir adam, yanında mahremi olmadan hiçbir kadınla yalnız başına kalmasın. Kadın, ancak mahremi ile yolculuk yapabilir. Bir adam ona; 'Ey Allah'ın Resulü, benim karım hac için yolculuğa çıktı, ben ise şu şu savaşa katılmak- için yazıldım.' Resûlüllah (s.a.v) şöyle buyurdu: Git, hanımınla beraber hac yap.\" (Buharı ve Müslim) KUR'AN OKUMANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 520, text: "Ebu Ümâme (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim: Kur'an okuyunuz; çünkü Kur'an kıyamet günü Ehl-i Kur'an'a şefaatçi olarak gelecektir.\" (Müslim)  KUR'AN OKUMANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 521, text: "Osman b. Affân (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizin en hayırlınız, Kur'an'ı öğrenen ve öğreteninizdir.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 522, text: "Hz. Âişe (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kur'an'ı okuyan ve onun hakkında maharet sahibi olan kimse, şerefli ve itaatkar olan gezici meleklerle beraberdir. Kur'an'ı okuyan ve zorlandığı için kekeleyen kimseye de iki sevap vardır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 523, text: "Ömer b. Hattab (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki Allah, bu kitapla bir takım toplumları yükseltir, diğer bir kısım toplumları da alçaltır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 524, text: "Ibn-i Mes'ud (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim Allah'ın kitabından bir harf okursa, ona bir sevap vardır. Her sevap on misli iledir. Ben 'Elif, lam, Mîm tek harftir' demiyorum. Fakat Elif bir harftir, Lam bir harftir, Mim bir harftir.\" (Tirmizi rivayet etmiş ve hadis basendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 525, text: "Ibn-i Abbas (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sinesinde Kur'an'dan hiçbir şey bulunmayan bir kimse, harap olmuş ev gibidir.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.) DEVAMLI KUR'AN OKUMAK, UNUTMAKTAN SAKINMAK  GÜZEL SESLE KUR'AN OKUMAK", source: "Hadis-i Şerif" },
    { id: 526, text: "Ebu Musa (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Şu Kur'an'la -çok okuyarak- sözleşmenizi sağlamlaştırınız. Muhammed'in canı elinde olana yemin olsun ki, Kur'an'ın unutulması, devenin bağından boşalıp kaçmasından daha çabuktur.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 527, text: "Ibn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kur'an hafızının hali, bağlanmış deve gibidir. Eğer üzerinde durursa onu tutar; ama onu serbest bırakırsa kaçar.\" (Buharı ve Müslim) GÜZEL SESLE KUR'AN OKUMAK", source: "Hadis-i Şerif" },
    { id: 528, text: "Ebu Hureyre (r.a)'dan, söyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim; Allah (c.c) hiçbir şeyi, Kur'an'ı a şikare okuyan güzel sesli Peygamberi dinlediği gibi dinlememiştir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 529, text: "Berâ b. Âzib (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i yatsı namazında 'Vet-tîni vez-zeytûni' yi okurken işittim. Ondan daha güzel sesli hiçbir kimseyi işitmemiştim.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 530, text: "Ebu Lübâbe Beşîr b. Abdülmünzir (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim Kur'an'ı tegannî ile -sesinin güzelleştirerek- okumazsa, bizden değildir.\" (Ebu Davud iyi bir isnatla rivayet etmiştir.) BELİRLİ SÛRELERİ VE ÂYETLERİ OKUMAYA TEŞVİK  BELİRLİ SÛRELERİ VE A YETLERİ OKUMAYA TEŞVİK", source: "Hadis-i Şerif" },
    { id: 531, text: "Ebu Saîd Râff b. Mualla (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) elimden tutup bana: Sana mescitten çıkmadan önce Kur'an'daki en büyük sûreyi öğreteyim mi?buyurdu. Mescitten çıkmak istediğimizde dedim ki: Ey Allah'ın Resulü, Kur'an'daki en büyük sûreyi sana öğreteyim mi?demiştiniz. Şöyle buyurdu: Elhamdülillâhi Rabbil Âlemîn; o namazda tekrarlanan yedi âyet ve bana verilmiş olan Yüce Kur'an'dır.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 532, text: "Ebu Saîd el-Hudrî (r.a)'dan, şöyle rivayet edilmiştir: \"Bir kişi, diğer bir kişiyi sürekli olarak 'Kul Hüvallâhü Ehad' sûresini tekrarlarken işitti. Sabah olunca Resûlüllah (s.a.v) geldi ve ona bu durumu anlattı. Adam, o kişinin yaptığını sanki azımsıyor. gibiydi. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Nefsim elinde olana yemin ederim ki, o-sûre- Kur'an'ın üçte birine denktir.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 533, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in kendisine şöyle buyurduğu rivayet edilmiştir: \"Kul Hüvellâhü Ehad sûresi, şüphesiz Kur'an'ın üçte birine denk gelir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 534, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam; Ey Allah'ın Resulü, ben Kul Hüvellâhü Ehad sûresini çok seviyorum, dedi. Resûlüllah (s.a.v) de şöyle buyurdu: O sûrenin sevgisi seni cennete sokar.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir. Buharı de Sahih'inde senetsiz rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 535, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Evlerinizi kabirler -gibi ıssız- hale getirmeyin. Şüphesiz ki şeytan, İçinde Bakara sûresi okunan evden kaçar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 536, text: "Ubey b. Ka'b (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ey Ebâ Münzir, Allah'ın kitabından ezberinde bulunan âyetlerden hangisi daha büyüktür, farkında mısın? Ben ' Allâhü Lâ ilahe illâ Hüvel-Hayyül Kayyûm' dedim. Bunun üzerine göğsüme vurdu ve şöyle buyurdu: Ey Ebâ Münzir, ilim sana mübarek olsun.\" (Müslim)  KUR'AN OKUMAK İÇİN TOPLANMANIN FAZİLETİ KUR'AN OKUMAK İÇİN TOPLANMANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 537, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Herhangi bir topluluk Allah'ın evlerinden bir evde toplanıp Allah'ın kitabını okurlar ve onu aralarında müzakere ederlerse, üzerlerine sekînet İner ve onları rahmet kaplar. Melekler onları kuşatır ve Allah o kimseleri katında bulunanlara anlatır.\" (Müslim) ABDESTİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 538, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim; Şüphesiz ki benim ümmetim kıyamet günü abdest uzuvları parlar bir şekilde -huzura- çağrılırlar. O halde sizden kim parlaklığını artırmaya güç yettiriyorsa hemen yapsın.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 539, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Ben, Allah Resulü (s.a.v) dostumu şöyle buyururken işittim; Mü'minin ahiretteki- ziyneti, abdest suyunun ulaştığı yere kadar uzanacaktır,\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 540, text: "Osman b. Affân (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim abdest alır; ama abdesti en güzel biçimde alırsa, tırnaklarının altına varıncaya kadar bütün hataları bedeninden çıkıp gider.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 541, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Müslüman- veya mü'min bir kul abdest alıp yüzünü yıkadığı zaman, gözüyle baktığı bütün günahlar suyla birlikte -ya da suyun en son damlasıyla- yüzünden akıp gider. Ellerini yıkadığı zaman,  EZANIN FAZİLETİ elleriyle tuttuğu bütün günahlar suyla -ya da suyun en son damla-sıyla- birlikte çıkıp gider. Ayaklarını yıkadığı zaman, ayaklarıyla yürüyerek işlediği bütün hatalar suyla -ya da suyun en son damla-sıyla- birlikte çıkıp gider. Nihayet bütün günahlardan sıyrılmış olur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 542, text: "Ömer b. Hattab (r.a)'dan, Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Sizden biri abdest alır; abdestini tamamlar ve sonra 'Eşhedü en-Lâilâhe ilallâh, ve eşhedü enne Muhammeden abdühu ve Resulüh' derse, kendisine cennetin sekiz kapısı da ardına kadar açılır; istediği kapıdan girer.\" (Müslim) EZANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 543, text: "Ebu Hureyre (r.a)'dan, şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim; Eğer insanlar ezanda ve ilk saftaki sevabı bilselerdi, sonra da kura ile buraları paylaşmaktan   başka imkanları kalmasaydı, elbette buraları kura ile paylaşırlardı. Eğer camiye-erken gitmedeki sevabı bilselerdi, oraya varmak için yarış ederlerdi. Eğer yatsı ve sabah namazlarındaki sevabı bilselerdi, sürünerek de olsalar mutlaka bu namazlara gelirlerdi.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 544, text: "Abdullah b. Abdurrahman b. Ebu Sa'saa'dan, Ebu Said el-Hudrî (r.a)'ın kendisine şöyle dediği rivayet edilmiştir: \"Görüyorum ki sen, koyunu ve kır-hayatını- seviyorsun. Eğer sen koyunlarınla veya kırlarda meşgul iken namaz için ezan okursan, sesini çok yükselt. Çünkü müezzinin sesini işiten cin, insan ve her ne şey varsa, mutlaka kıyamet günü ona şahitlik eder.\" Ebu Said dedi ki: Ben bu hadisi Resûlüllah (s.a.v)'den işittim. (Buharı)", source: "Hadis-i Şerif" },
    { id: 545, text: "Ebu Said el-Hudri (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ezanı duyduğunuz zaman, müezzinin söylediği gibi siz de söyleyiniz.\" (Buharı ve Müslim)  NAMAZIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 546, text: "Sa'd b. Ebu Vakkâs (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim müezzini duyduktan sonra 'Tek ve ortağı bulunmayan Allah'dan başka hiçbir ilah olmadığına, Muhammed (a.s)'ın O'nun kulu ve elçisi olduğuna şehadet ederim. Rab olarak Allah (c.c)'ı, Peygamber olarak Muhammed (a.s)'ı ve din olarak da İslâm'ı seçip razı oldum' derse, günahları bağışlanır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 547, text: "Enes (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ezan ile kamet arasında yapılan dua reddolunmaz.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.) NAMAZIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 548, text: "Ebu Hureyre (r.a)'dan, şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim: Söyleyin bakalım, sizden biriniz kapısının önünden akan nehirde günde beş defa yıkansa kendisinde hiç kir kalır mı? Dediler ki: ' Onda kir namına hiçbir şey kalmaz.' Bunun üzerine şöyle buyururdu: İşte beş vakit namaz da böyledir; Allah namaz sayesinde hataları yok eder.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 549, text: "Cabir (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Beş vakit namaz, sizden birinizin kapısının önünden akan ve günde beş defa girip yıkandığı suyu bol bir nehir gibidir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 550, text: "Ibn-i Mes'ud (r.a)'dan şöyle rivayet edilmiştir: \"Adamın biri bir kadını öpmüştü. Hemen Resûlüllah (s.a.v)'e gelip haber verdi. Bunun üzerine Yüce Allah şu âyeti indirdi: 'Gündüzün her iki tarafında, gecenin de gündüze yakın saatlerinde namaz kıl; çünkü iyi ameller, kötülükleri giderir.' (Hud; 114) Adam dedi ki: Bu, sadece bana mı ait? Resûlüllah (s.a.v) şöyle buyurdu: Ümmetimin hepsi içindir.\" (Buhari ve Müslim)  SABAH VE İKİNDİ NAMAZININ FAZİLETLERİ", source: "Hadis-i Şerif" },
    { id: 551, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Beş vakit namaz ve bir Cuma diğer Cumaya kadar, büyük günahlar işlenmedikçe aralarında -işlenen- günahlara keffarettir.\" (Müslim) SABAH VE İKİNDİ NAMAZININ FAZİLETLERİ", source: "Hadis-i Şerif" },
    { id: 552, text: "Ebu Musa (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim iki serinlik-sabah ve ikindi-namazlarını kılarsa, cennete girer.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 553, text: "Cündüb b. Süfyân (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim sabah namazını kılarsa o kişi Allah'ın himayesindedir.   Ey Adem oğlu bak! Sakın Allah senden, zimmetine almasından dolayı bir şey talep etmesin.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 554, text: "Büreyde (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim ikindi namazını terk ederse, şüphesiz ameli-nin sevabı-yok olmuş olur,\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 555, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim sabah veya akşam mescide gidip gelirse, sabah akşam her gidiş dönüşünde Allah kendisine cennette bir köşk hazırlar.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 556, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim evinde güzelce temizlenir, sonra Allah'ın farzlarından bir farzı eda etmek için Allah'ın evlerinden bir eve giderse, attığı adımlarından biri hata siler; diğeri ise derece yükseltir.\" (Müslim)  NAMAZ VAKTİNİ BEKLEMENİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 557, text: "Büreyde (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Karanlıklarda mescitlere sıkça yürüyüp gidenleri, kıyamet günü tam bir aydınlıkla müjdeleyiniz!\" (Ebu Davud ve Tirmizi)", source: "Hadis-i Şerif" },
    { id: 558, text: "Ebu Said el-Hudri (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir adamı mescitlere sıkça gidip gelirken görürseniz, onun imanlı olduğuna şahitlik ediniz. Çünkü Yüce Allah şöyle buyurmuştur: Allah'ın mescitlerini ancak Allah'a ve ahiret gününe iman edenler imar eder.\" Tövbe; 18 (Tirmizi rivayet etmiş ve hadis hasendir.) NAMAZ VAKTİNİ BEKLEMENİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 559, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden birinizin ailesinin yanına dönmesine namazdan başka bir mani   yok iken, namaz -vaktini- kılmak için kendisini bekletmesi, onu namazda yapar.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 560, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) bir gece yatsı namazını gece yarısına kadar geciktirmişti. Sonra namaz kıldıktan sonra yüzünü bize çevirdi ve şöyle buyurdu: İnsanlar namazlarını kıldılar ve uykuya daldılar. Siz ise namaz kılmayı beklediğiniz sürece namazda olmayı sürdürdünüz.\" (Buharı) CEMAATLE NAMAZ KILMANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 561, text: "Ibn-i Ömer (r,a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Cemaatle kılınan namaz, tek başına kılınan namazdan yirmi yedi derece daha faziletlidir.\" (Buhari ve Müslim)  CEMAATLE NAMAZ KILMANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 562, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'e bir ağma adam gelip dedi ki: 'Ey Allah'ın Resulü, mescide gidecek kadar bana yardım edecek biri yok?' Böylelikle Resûlüllah (s.a.v)'den namazını evinde kılmak için kendisine ruhsat vermesini istedi. O da ona ruhsat verdi. Dönüp gitmeye koyulduğunda onu çağırdı ve kendisine şöyle buyurdu: Namaz için yapılan çağrıyı ezanı- duyuyor musun? O da; Evet, dedi. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: O zaman icabet et.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 563, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Nefsim -kudret- elinde olana yemin ederim ki, şuna niyetlendiğim oluyor; Odun -toplanmasını- emredeyim de bir odun yığını oluşturulsun. Sonra birine.namaz için ezan okumasını emrede- -yim, birine de insanlara imamlık yapmasını emredeyim. Daha sonra da -cemaata gelmeyen- adamların peşine düşüp evlerini başlarına yakayım!\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 564, text: "Ebu Derda (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim: Bir köyde ve beldede üç   kişi bulunup da namazlarını -cemaatle- kılmazlarsa, şeytan onlara mutlaka galip gelir. O halde size cemaati tavsiye ediyorum, Çünkü kurt, sürüden ayrılan koyunu yer.\" (Ebu Davud sahih bir isnatla rivayet etmiştir.) SABAH VE YATSI NAMAZLARINDA CEMAATE KATILMAK", source: "Hadis-i Şerif" },
    { id: 565, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: Eğer yatsı ve sabah namazlarındaki -cemaate katılmanın- sevabını bilselerdi, emekleyerek de olsa mutlaka onlara gelirlerdi.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 566, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Münafıklara sabah ve yatsı namazından daha ağır gelen hiçbir namaz yoktur. Eğer bu iki namazı -cemaatle-kılmanın sevabım bilselerdi, emekleyerek de olsa mutlaka onlara gelirlerdi.\" (Buhari ve Müslim)  FARZ NAMAZLARA DEVAM ETMEK FARZ NAMAZLARA DEVAM ETMEK", source: "Hadis-i Şerif" },
    { id: 567, text: "İbn-İ Mes'ud (r.a) 'dan şöyle buyurduğu rivayet edilmiştir: \"Resûlüllah (s.a.v)'e 'Hangi amel daha faziletlidir?'diye sordum. Buyurdular ki: Vaktinde kılınan namazdır, 'Sonra hangisi-dir?'diye sordum. Bu sefer; Ana babaya iyilikte bulunmaktır, buyurdu. 'Daha sonra hangisidir?'dedim. Allah yolunda cihat etmektir, diye cevap verdiler.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 568, text: "İbn-i Ömer (r.a) 'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İslâm, beş ana esas üzerine bina edilmiştir: Allah'dan başka hiçbir ilah olmadığına ve Muhammed (a.s)'ın O'nun Resulü olduğuna şehadet etmek, namaz kılmak, zekat vermek, Beytullah'ı haccetmek ve Ramazan orucunu tutmaktır.\" (Buhariye Müslim)", source: "Hadis-i Şerif" },
    { id: 569, text: "Cabir (r.a)'dan şöyle dediği rivayet edilmiştir: \"Kişi ile şirk ve küfür arasında namazı terk etmek vardır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 570, text: "Büyüklüğünde ittifak edilen, Tabiîn'den olan Şakîk b. Abdullah (r.a)'dan şöyle dediği rivayet edilmiştir: \"Muhammed (a.s)'ım arkadaşları, namazdan başka hiçbir amelin terk edilmesini küfür olarak görmezlerdi.\" (Tirmizi rivayet etmiş ve 'iman Kitabı'nda sahih bir isnatla rivayet etmiştir.) BİRİNCİ SAFTA NAMAZA DURMANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 571, text: "Cabir b. Semure (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) çıkıp yanımıza geldi ve şöyle buyurdu; Sizler, meleklerin Rableri huzurunda nasıl saf tutuyorlarsa öyle saf tutmayı istemez misiniz? Biz 'Ey Allah'ın Resulü, melekler Rablerinin  BİRİNCİ SAFTA NAMA2A D URMANIN FAZİLETİ huzurunda nasıl saf tutuyorlar?diye sorduk. Şöyle buyurdu: Ön safları tamamlarlar ve safları sık tutarlar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 572, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Eğer insanlar ezan ve ilk saftaki sevabı bilseler, sonra bunları elde etmeye kuradan başka çareleri kalmasa, mutlaka kura çekerlerdi.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 573, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Erkek saflarının en hayırlı olanı ilk saflar, en şerli olanı da son saflardır. Kadı saflarının en hayırlısı son saflar, en şerlisi de ilk saflardır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 574, text: "Ebu Said el-Hudri (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) ashabının geride kaldıklarını görünce kendilerine şöyle buyur-   muştur: Öne doğru ilerleyiniz ve bana Öyle uyunuz. Sizden sonra gelenler de size- göre- uysunlar. Bir topluluk böyle geri kalmaya devam ettikçe Allah da onları geri bırakır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 575, text: "Ebu Mes'ud (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) namazda omuzlarımıza dokunur ve şöyle buyururdu: Safları düzeltiniz, yamuk yumuk yapmayınız; sonra kalpleriniz de yamuk yumuk olur. Sizden aklı başında olanlar benim peşime dursun. Sonra onların peşinden gelenler; daha sonra da onların peşinden gelenler dursun.\" (Müslim) FARZ NAMAZLARLA BİRLİKTE KILINAN SÜNNETLER", source: "Hadis-i Şerif" },
    { id: 576, text: "Mü'minlerin annesi Ümmü Habîbe Remle b.Ebu Süfyan (r.a)'dan şöyle dediği rivayet edilmiştir:  FARZ NAMAZLARLA BİRLİKTE KILINAN SÜNNETLER \"Resûlüllah (s.a.v)'i şöyle buyururken işittim: Müslüman bir kul, farzların haricinde her gün Allah rızası için on iki rekat nafile namaz kılarsa, Allah (c.c) onun için cennette mutlaka bir ev yapar-ya da onun için cennette bir ev bina edilir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 577, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben Resûlüllah (s.a.v) ile beraber Öğleden evvel iki rekat, öğleden sonra da iki rekat, Cumadan sonra iki rekat, akşamdan sonra iki rekat ve yatsıdan sonra da iki rekat namaz kıldım.\" (Buhari ve Müslim) SABAH NAMAZINDAN ÖNCE KILINAN İKİ REKAT SÜNNETİN MÜEKKED -KUVVETLİ-OLUŞU", source: "Hadis-i Şerif" },
    { id: 578, text: "Hz, Âise (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) öğleden önce dört rekat ve akşamdan önce de iki rekat namaz kılmayı hiç terk etmezdi.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 579, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) nafilelerden hiç birisine sabah namazının iki rekat -sünneti- kadar devam etmemiştir.\" (Buharı ve Müslim) SABAH NAMAZININ SÜNNETİNİ HAFİFÇE KILMAK", source: "Hadis-i Şerif" },
    { id: 580, text: "Hz. Âişe (r.a)'dan, şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) sabah namazında ezanla kamet arasında iki rekat hafif bir namaz kılardı.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 581, text: "Ibn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) geceleyin ikişer ikişer namaz kılar, gecenin sonunda da bir rekat daha ekleyerek vitir kılardı. Sabah namazından  ÖĞLE NAMAZININ SÜNNETİ önce ise, sanki kamet eli kulağındaymış gibi ecele bir şekilde iki rekat sünnet- kılardı.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 582, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Sizden biriniz sabah namazının iki rekat -sünnetini- kıldığında sağ tarafı üzerine uzanıversin.\" (Ebu Davud ve Tirmizi sahih isnatlarla rivayet etmişler; Tirmizi hadis hasendir, sahihtir demiştir.) ÖĞLE NAMAZININ SÜNNETİ", source: "Hadis-i Şerif" },
    { id: 583, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben, Resûlüllah (s.a.v) ile beraber iki rekat öğleden Önce, iki rekat da öğleden sonra namaz kıldım.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 584, text: "Hz. Âi şe (r.a)'dan şöyle rivayet edilmiştir:   \"Resûlüllah (s.a.v) öğlenin-farzından- önce dört rekat namaz kılmayı asla terk etmezdi.\" (Buharı) İKİNDİ NAMAZININ SÜNNETİ", source: "Hadis-i Şerif" },
    { id: 585, text: "Ali. b. Ebu Talib (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) ikindi namazının farzından önce dört rekat sünnet kılar, ikisinin arasını -huzuru ilahiye-yakınlaştırılmış meleklerle onlara uyan müslümanlara ve mü'minlere selam vererek ayırırdı.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 586, text: "Ali b. Ebu Talib (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) ikindi namazının farzından evvel iki rekat namaz kılardı.\" (Ebu Davud) AKŞAMIN FARZINDAN ÖNCEKİ VE SONRAKİ SÜNNETLER  AKŞAMIN FARZINDAN ÖNCEKİ VE SONRAKİ SÜNNETLER", source: "Hadis-i Şerif" },
    { id: 587, text: "Abdullah b. Muğaffel (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Akşam namazından önce namaz kılın. 'Üçüncü defa tekrar edişinde; İsteyen kimse -kılsın' buyurdu.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 588, text: "Enes (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz Resûlüllah (s.a.v)'in zamanında, güneş battıktan sonra akşamın farzından önce iki rekat namaz kılardık. Denildi ki: 'Resûlüllah (s.a.v) de onları kılar mıydı?' Enes (r.a): Bizleri kılarken görürdü; bize ne kılmayı emrederdi, ne de yasaklardı, dedi.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 589, text: "Enes (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz Medine'de bulunduğumuz sırada müezzin akşam namazı için ezan okuduğu zaman, cemaat- hızla direklerin önlerine varıp iki rekat namaz kılarlardı. O kadar ki, yabancı biri mescide girse, namaz kılanların çokluğundan dolayı -farz- namaz kılınmış sanırdı.\" (Müslim) CUMANIN SÜNNETİ", source: "Hadis-i Şerif" },
    { id: 590, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz cumayı kıldığınız zaman, ondan sonra dört rekat daha namaz kılsın.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 591, text: "İbn-i Ömer (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) cumanın -farzından- sonra dönünceye kadar namaz kılmaz; eve vardığında iki rekat namaz kılardı.\" (Müslim) SÜNNET VE NAFİLE NAMAZLARININ EVDE KILINMASI", source: "Hadis-i Şerif" },
    { id: 592, text: "Zeyd b. Sabit (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ey insanlar, evlerinizde namaz kılınız. Çünkü, farzların haricinde en faziletli namaz, kişinin evinde kıldığı namazdır.\" (Buhari ve Müslim)  SÜNNET VE NAFİLE NAMAZLARININ EVDE KILINMASI", source: "Hadis-i Şerif" },
    { id: 593, text: "İbn-i Ömer (r.a)'dan, Resâlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Namazlarınızın bir kısmını evinizde kılınız. Oraları kabirlere çevirmeyiniz.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 594, text: "Cabir (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz namazını mescidde eda ettiği zaman, namazından evine de bir pay ayırsın. Çünkü Yüce Allah, kıldığı namazdan dolayı onun evinde hayır yaratır.\" (Müslim) VİTİR NAMAZINA TEŞVİK, ONUN MÜEKKED SÜNNET OLUŞU VE VAKTİNİN AÇIKLANMASI", source: "Hadis-i Şerif" },
    { id: 595, text: "Hz. Ali (r.a)'dan şöyle rivayet edilmiştir: \"Vitir, farz namazlar gibi bir farz değildir. Ama Allah Resulü (s,a.v) sünnet kılmış ve şöyle buyurmuştur: Allah tektir, teki sever; o halde Ey Kur'an Ehli, vitir namazını kılınız.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 596, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) her gece mutlaka vitir kılmıştır; ama gecenin başında, ama ortasında, ama sonunda mutlaka kılmıştır. Vitir kılması seher vaktinde sona ererdi.\" (Buharı ve Müslim) KUŞLUK NAMAZININ FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 597, text: "Ebu Hureyre (r.a)'dan, şöyle dediği rivayet edilmiştir; \"Dostum Muhammed (a.s), bana her aydan üç gün oruç tutmayı, iki rekat kuşluk namazını ve yatmadan evvel vitir kılmamı tavsiye etti.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 598, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) kuşluk namazını dört rekat olarak kılar; Allah'ın dilediği kadar da artırdığı olurdu.\" (Müslim)  MESCİDİ SELAMLAMA NAMAZI KILMAYA TEŞVİK", source: "Hadis-i Şerif" },
    { id: 599, text: "Zeyd b. Erkam (r.a)'dan şöyle rivayet edilmiştir: \"Bu kişi, kuşluk namazı kılan bir topluluk gördü ve -içinden-şöyle dedi: Bu kimseler, bu saatten başka bir zamanda namaz kılmanın daha faziletli olduğunu bilmiyorlar mı? Şüphesiz Resûlüllah (s.a.v) şöyle buyurmuştur; Evvâbîn'in namazı, deve yavrularının ayaklarının sıcaktan yandığı zamandır.\" (Müslim) MESCİDİ SELAMLAMA NAMAZI KILMAYA TEŞVİK", source: "Hadis-i Şerif" },
    { id: 600, text: "Ebu Katâde (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Sizden biriniz mescide girdiği zaman, iki rekat namaz kılmadan evvel oturmasın.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 601, text: "Cabir (r.a)'dan, şöyle dediği rivayet edilmiştir:   \"Ben, Resûlüllah (s.a.v) mescitte iken yanına gitmiştim. Bana 'iki rekat namaz kıl' buyurdu.\" (Buharı ve Müslim) ABDEST ALDIKTAN SONRA İKİ REKAT NAMAZ KILMANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 602, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in Bilal'a şöyle buyurduğu rivayet edilmiştir: \"Ey Bilal! Islâm'la müşerref olduktan sonra yaptığın en ümit verici ameli bana anlat; çünkü ben cennette benim önümde senin ayak seslerini işittim. Bilal şöyle dedi: Bana göre en ümit verici amelim şu ki; gece veya gündüz abdest aldığımda, bu abdestimle bana lütfedildiği kadar namaz kıldım.\" (Buhari ve Müslim rivayet etmiştir. Bu lafız Buhari'nin lafzıdır.) CUMA NAMAZI VE CUMA GÜNÜNÜN FAZİLETİ  CUMA NAMAZİ VE CUMA GÜNÜNÜN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 603, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Üzerine güneş doğan en hayırlı gün Cuma günüdür. Çünkü Âdem o günde yaratıldı, o gün cennete sokuldu ve o gün cennetten çıkarıldı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 604, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Beş vakit namazlar, bir Cuma ile gelecek Cuma, bir Ramazan ile gelecek Ramazan, büyük günahlardan kaçınıldığı takdirde aralarında işlenmiş günahlara keffaret olur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 605, text: "Ebu Hureyre ve İbn-i Ömer (r.a)'dan, bu iki zatın Resûlüllah (s.a.v)'i minberi üzerinde şöyle buyururken işittikleri rivayet edilmiştir: \"Topluluklar, ya Cuma-namaz-larını terk etmekten vazgeçerler, ya da Allah onların kalpleri üzerine mühür vurur da sonra gafillerden olurlar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 606, text: "Ebu Said el-Hudri (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Cuma günü yıkanmak, ergenlik çağına ulaşmış herkesin üzerine vaciptir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 607, text: "Semure (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Kim Cuma günü abdest alırsa ne iyi! Ama kim yıkanırsa, gusül abdesti alması daha faziletlidir.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 608, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) Cuma gününü anlatıp şöyle buyurdu: Onda öyle bir saat var ki, müslüman bir kul namaza kalktığında Allah'tan bir şey isterken o saate denk gelse, istediği şeyi ona mutlaka verir.\" Resûlüllah (s.a.v) bu sırada o anın çok kısa olduğunu eliyle işaret etti. (Buhari ve Müslim)  CUMA NAMAZI VE CUMA GÜNÜNÜN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 609, text: "Evs b. Evs (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz sizin en hayırlı günlerinizden biri de Cuma günüdür. O halde, o günde bana çok sık salat-ü selâm getiriniz. Çünkü sizin salat-ü selâmınız banaz arz edilir.\" (Ebu Davud sahih bir isnatla rivayet etmiştir.) NİMETE KAVUŞUNCA VEYA BELANIN DEFİ İÇİN ŞÜKÜR SECDESİ YAPMANIN MÜSTEHAPLIĞI", source: "Hadis-i Şerif" },
    { id: 610, text: "Sa'd b. Ebu Vakkas (r.a)'ın şöyle dediği rivayet edilmiştir: \"Biz, Resûlüllah (s.a.v) ile beraber Medine'ye gitmek üzere   Mekke'den çıktık. Azverâ'nın yakınlarında bir yerde bineğinden indi, sonra ellerini kaldırıp Yüce Allah'a bir süre dua etti. Sonra secdeye kapandı ve uzun bir müddet böyle kaldı. Sonra kalktı ve iki elini kaldırıp bir zaman dua etti. Sonra yine secdeye kapandı. Bu işi üç kere tekrar etti ve şöyle buyurdu: Şüphesiz ben Rabbimden istedim ve ümmetime şefaatçi oldum. Bana ümmetimin üçte birini verdi. Bunun üzerine Rabbime şükretmek için secdeye kapandım, sonra kafamı kaldırdım ve Rabbimden istedim. Bana ümmetimin üçte birini verdi. Ben de derhal Rabbime şükretmek için secdeye kapandım, sonra kafamı kaldırdım ve Rabbimden yine istedim. Bu sefer bana kalan diğerlerini verdi. Ben de Rabbim için secdeye kapandım.\" (Ebu Davud) GECE İBADETİNİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 611, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) gece ibadet için o kadar ayakta kalırdı ki nihayet ayakları şişerdi. Ben kendisine dedim ki: Ey Allah'ın Resulü, niye böyle yapıyorsun; oysa senin geçmiş-gelecek bütün hataların affedilmiştir. Şöyle buyurdu: Şükreden bir kul olmayayım mı?\" (Buhari ve Müslim)  GECE İBADETİNİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 612, text: "Hz. Ali (r.a)'den şöyle rivayet edilmiştir: \"Resûlüliah (s.a.v) Hz. Ali ve Fâtıma'nın gece kapısını çalar ve şöyle buyururdu: Namaz kılmayacak mısınız?\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 613, text: "Abdullah b. Amr b.Âs (r.a)'dan Resûlüliah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Ey Abdullah, sakın gece -ibadeti- için kalkıp da, sonra gece kalkmayı bırakan falanca gibi olma!\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 614, text: "İbn-i Mes'ud (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüliah (s.a.v)'in huzurunda gece sabaha kadar uyuyup da -sabah namazına kalkmayan- bir adamdan bahsedilince şöyle buyurdu: O adam var ya, işte onun her iki kulağına da şeytan işemiştir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 615, text: "Abdullah b. Selam (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Ey insanlar! Selâmı yayınız, yemek yediriniz, insanlar uyurken gece namaz kılınız; böylelikle cennete girersiniz.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 616, text: "Enes (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) ayın bir kısmında o kadar iftar etmeye devam ederdi ki, biz o ayda hiç oruç tutmayacak sanırdık. Ayın kimi günlerinde o kadar oruç tutardı ki, biz o ayda hiç iftar etmeyecek sanırdık. Kendisini namaz kılarken görmeyi aklımdan geçirmediğim gecenin bir vaktinde -namaz kılarken gördüm. Uyurken göreceğimi ummadığım bir vakitte de uyurken gördüm.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 617, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) geceleyin on bir rekat namaz kılardı. Kıldığı bu namazın secdesinde o kadar dururdu ki, sizden biriniz başını kaldırmadan önce elli ayet okuyabilirdi. Sabah namazının farzından evvel de iki rekat namaz kılardı. Sonra müezzin kendisine gelip namaz için  GECE İBADETİNİN FAZİLETİ çağrıda bulunmadan evvel sağ yanı üzerine uzanırdı.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 618, text: "Ibn-i Mes'ud (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben bir gece Resûlüllah (s.a.v) ile beraber namaz kılıyordum. Namazda ayakta kalmaya o kadar devam etti ki, nihayet yakışıksız bir iş yapmayı dahi aklımdan geçirdim. İbn-i Mes'ud'a; 'Aklından geçen ne idi?' denildiğinde şöyle dedi: Oturup, O'nu ayakta terk etmeyi düşündüm.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 619, text: "Cabir (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'e 'Hangi namaz daha faziletlidir?'diye sorulduğunda şöyle buyurmuştur: Ayakta kalışın uzun olduğu namazdır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 620, text: "Cabir (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in şöyle buyurduğunu işittim; Gecede öyle   bir saat vardır ki, müslüman bir kul o saate rastlar da Yüce Allah'tan dünya ve ahiret işiyle ilgili ne hayır isterse, mutlaka o istediği ona verilir. Bu saat, her gecede bulunmaktadır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 621, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) gecenin bir kısmında kalktığı zaman, namazını hafif iki rekatla açardı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 622, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz gece kalktığı zaman Kur'an diline garip gelir ve ne dediğini bilemezse, hemen yatsın.\" (Müslim) RAMAZÂN GECELERİNDE İBADET EDİP TERAVİH KILMAK  RAMAZAN GECELERİNDE İBADET EDİP TERAVİH KILMAK", source: "Hadis-i Şerif" },
    { id: 623, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim inanarak ve sevabını -Allah'dan- umarak Ramazanda -ibadete- kalkarsa, geçmiş günahları bağışlanır.\" (Buhari ve Muslini)", source: "Hadis-i Şerif" },
    { id: 624, text: "Ebu Hureyre (r.a) ' dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) zorlayıcı bir emir buyurmaksızın Ramazanda -ibadete- kalkmaya teşvik eder ve şöyle buyururdu: Kim inanarak ve sevabını Allah'dan- umarak Ramazanda-ibadete- kalkarsa, geçmiş günahları bağışlanır.\" (Müslim) KADİR GECESİNİN İHYASI VE HANGİ GECEDE OLDUĞU", source: "Hadis-i Şerif" },
    { id: 625, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Kim inanarak ve sevabını -Allah'dan- bekleyerek Kadir gecesinde ibadete- kalkarsa, geçmiş bütün günahları affolunur.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 626, text: "İbn-i Ömer (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'in ashabından bir kısım adamlar, rüyalarında Kadir gecesini son yedi -gece-de gördüler. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: Görüyorum ki rüyanız son yedi güne denk gelmektedir. O halde kim onu araştırıyorsa, son yedi günde araştırsın.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 627, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) Ramazanın son on gününde itikafa girer ve şöyle buyururdu: Kadir gecesini, Ramazanın son on gününde arayınız.\" (Buhari ve Müslim)  MİSVAKIN FAZİLETİ VE YARATILIŞ ÖZELLİĞİ", source: "Hadis-i Şerif" },
    { id: 628, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) Ramazanda, diğer aylarda gösterdiği gayretten daha fazla gayret gösterirdi. Ramazanın son on gününde ise, diğer günlerde gösterdiği çalışmadan daha fazla çalışma yapardı.\" (Müslim) MİSVAKIN FAZİLETİ VE YARATILIŞ ÖZELLİĞİ", source: "Hadis-i Şerif" },
    { id: 629, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Eğer ümmetimin veya insanların üzerine meşakkat vermeyecek olsaydım, onlara her namazla birlikte misvakı emrederdim.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 630, text: "H.z. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz Resûlüllah (s.a.v)'in misvakın ve taharet suyunu hazırlardık. Allah O'nu geceleyin ne vakit kalkmasını dilediyse o vakit kaldırırdı. O da misvak kullanır, abdest alır ve namaz kılardı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 631, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yaratılış-tan gelen- hasletler beştir veya beş şey yaratılıştandır; Sünnet olmak, avret mahallini traş etmek, tırnakları kesmek, koltuk altlarını kesmek ve bıyıkları kısaltmak.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 632, text: "Ibn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bıyıklarınızı kısaltınız, sakalınızı uzatınız.\" (Buhari ve Müslim) ZEKATIN KUVVETLİ VACİP OLUŞU VE FAZİLETİ HAKKINDADIR", source: "Hadis-i Şerif" },
    { id: 633, text: "İbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İslam, beş ana temel üzerine kurulmuştur; Allah'dan başka ilah  ZEKATIN KUVVETLİ VACİP OLUŞU VE FAZİLETİ HAKKINDADIR olmadığına ve Muhammed (a.s)'ın O'nun kulu ve Resulü olduğuna şehadet etmek, namaz kılmak, zekat vermek, Allah'ın evini ziyaret edip haccetmek ve Ramazanda oruç tutmak,\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 634, text: "İbn-i Abbas (r.a)'dan söyle rivayet edilmiştir: \"Resûlüllah (s.a.v) Muâz (r.a)'ı Yemen'e gönderdi ve şöyle tembih etti: Onları, Allah'dan başka ilah olmadığına ve benim Allah'ın Elçisi olduğuma şehadet etmeye çağır. Eğer onlar sana bu hususta itaat ederlerse, o zaman Allah'ın kendilerine her gün ve her gecede beş vakit namaz farz kıldığını bildir. Eğer onlar sana bu meselede de itaat ederlerse, o zaman Allah'ın kendilerine zenginlerinden alınıp fakirlerine verilecek sadakayı zekatı-farz kıldığını bildir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 635, text: "İbn-i Ömer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"İnsanlarla, Allah'tan başka ilah olmadığına ve Muhammed (a.s)'ın Allah'ın Elçisi olduğuna şehadet edinceye, namaz kılıp zekat verinceye kadar savaşmakla emrolundum. Bunları yaptıkları zaman, İslam'ın hakkı hariç benden kanlarını ve mallarını korumuş olurlar. Onların -gizli- hesapları ise Allah'a aittir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 636, text: "Ebu Eyyub (r.a)'dan şöyle rivayet edilmiştir; \"Bir adam Resûlüllah (s.a.v)'e şöyle dedi: Beni cennet sokacak bir ameli bana haber ver. O da şöyle buyurdu: Allah'a ibadet edersin ve O'na hiçbir şeyi ortak koşmazsın, namazı kılarsın zekatı verirsin ve akrabayla ilişkilerini sürdürürsün.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 637, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Bir bedevî Peygamber (a.s)'a gelip şöyle dedi; Ey Allah'ın Resulü, yaptığım zaman beni cennete sokacak bir ameli bana göster. Resûlüllah (s.a.v) de şöyle buyurdu: Allah'a hiçbir şeyi ortak koşmadan ibadet edersin, namaz kılarsın, farz kılınan zekatı verirsin ve Ramazan orucunu tutarsın.  RAMAZAN ORUCUNUN FARZİYETİ VE FAZİLETİ Adam dedi ki: Nefsim elinde olana yemin ederim kit bunun üzerine hiçbir şey eklemeyeceğim. Adam dönüp gidince Peygamber (a.s) şöyle buyurdu: Kimi cennet ehli bir kişiye bakmak sevindirirse şu adama baksın.\" (Buharı ve Müslim) RAMAZAN ORUCUNUN FARZİYETİ VE FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 638, text: "Sehl b. Sa'd (r.a)\"dan Peygamber (a.s)'ın şöyle buyurduğu rivayet edilmiştir: \"Cennette bir kapı vardır ki ona 'Reyyân' denilir. Kıyamet günü o kapıdan sadece oruç tutanlar girer; onlardan başkası giremez. Denilir ki: 'Oruç tutanlar nerede?' Onlar kalkarlar; onlardan başka hiçbir kimse o kapıdan giremez. Onlar girince kapı kapanır ve o kapıdan başka hiçbir kimse giremez.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 639, text: "Ebu Hureyre (r.a)'dan Peygamber (a.s)'ın şöyle buyurduğu rivayet edilmiştir: \"Kim inanarak ve sevabını -Allah'dan- umarak Ramazan orucu tutarsa, geçmiş bütün günahları affolunur.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 640, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ayı -Ramazan hilalini- gördüğünüz zaman oruç tutunuz; ayı -Şevval hilalini- gördüğünüz zaman iftar ediniz. Eğer hava üzerinize bulutlu olursa, Şaban ayını otuza tamamlayınız.\" (Buhari ve Müslim. Bu lafız Buhari'nindir.) RAMAZAN AYINDA HAYIRLARI ÇOĞALTMAK", source: "Hadis-i Şerif" },
    { id: 641, text: "Ibn-i Abbas (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) insanların en cömert olanı idi. En cömert olduğu zaman, Ramazanda Cebrail ile karşılaştığı zaman olurdu. Cebrail O'nunla Ramazanın her gecesinde buluşup O'na Kur'an'ı okurdu. Resûlüllah (s.a.v), hele Cebrail kendisiyle karşılaştığı zaman yağmur yüklü bulutlardan daha cömert olurdu.\" (Buhari ve Müslim)  ORUÇ TUTULMASI SAKINCA OLAN VE OLMAYAN GÜNLER", source: "Hadis-i Şerif" },
    { id: 642, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) Ramazanın son on günü girdiği zaman gece ibadetle geçirir, ailesini uyandırır ve onlardan elini eteğini çekerdi.\" (Buharı ve Müslim) ORUÇ TUTULMASI SAKINCA OLAN VE OLMAYAN GÜNLER", source: "Hadis-i Şerif" },
    { id: 643, text: "Ebu Hureyre (r.a)'dan Peygamber (a.s)'ın şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz Ramazanı bir gün veya iki gün önceden -oruç tutarak- karşılamasın. Ancak bir kişinin -adeti üzere- tutmayı sürdürdüğü oruç başka; o takdirde o gün orucunu tutsun.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 644, text: "İbn-i Abbas (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Ramazandan önce oruç tutmayınız. Ayı gördüğünüzde oruç tutunuz; ayı gördüğünüzde de iftar ediniz. Eğer ay bulutun arkasında kalırsa, o zaman orucu otuza tamamlayınız.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.) RAMAZAN HİLALİ GÖRÜLDÜĞÜNDE OKUNACAK DUA", source: "Hadis-i Şerif" },
    { id: 645, text: "Talha b. Ubeydullah (r.a)'dan şöyle rivayet edilmiştir: \"Peygamber (a.s) hilali gördüğü zaman şöyle buyururdu; Allah'ım, onu bize emniyet, iman, selamet ve Islam hilali kıl. Benim de Rabbim, senin de Rabbin Allah'dır. Mübarek ve hayırlı bîr ay ol.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir,) SAHUR YEMEĞİNİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 646, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  SAHUR YEMEĞİNİN FAZİLETİ \"Sahur yemeği yiyiniz; çünkü sahur yemeğinde bereket vardırr (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 647, text: "Ibn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüilah (s.a.v)'in iki tane müezzini vardı; Bilal ve İbn-i Ümmi Mektum. Resûlüllah (s.a.v) şöyle buyurmuştur; Bilal geceleyin ezan okuyor. O halde İbn-i Ümmi Mektum ezan okuyuncaya kadar yiyiniz ve içiniz.\" Ibn-i Ömer şöyle demiştir: İki ezan arasında birinin inip, diğerinin çıkmasından başka bir zaman bulunmuyordu. (Buharı ve Müslim) ORUÇ AÇMADA ACELE ETMEK", source: "Hadis-i Şerif" },
    { id: 648, text: "Sehl b. Sa'd (r.a)'dan Resûlüilah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İnsanlar, oruçlarını açmada acele ettikleri sürece hayır üzere olmayı sürdüreceklerdir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 649, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yüce Allah şöyle buyuruyor: Bana en sevimli gelen kullarım, iftar etmekte acele davrananlardır.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 650, text: "Sahabi Selman b. Amir ed-Dabıyy (r.a) 'dan Peygamber (a.s)'ın şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz orucunu açacağı zaman hurma ile açsın. Eğer hurma bulamazsa su ile açsın; çünkü su temizdir.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir, sahihtir demiştir.) ORUÇLUNUN ÇİRKİN SÖZ VE İŞLERDEN SAKINMASI  ORUÇLUNUN ÇİRKİN SÖZ VE İŞLERDEN SAKINMASI", source: "Hadis-i Şerif" },
    { id: 651, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz oruçlu iken kötü söz söylemesin, bağırıp çağırmasın. Eğer kendisine birisi söverse veya onunla kavgaya kalkışırsa 'Ben oruçluyum' desin.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 652, text: "Ebu Hureyre (r.a)'dan Peygamber (a.s)'ın şöyle buyurduğu rivayet edilmiştir: \"Kim yalan sözü ve yalanla iş yapmayı terk etmezse, onun yemesini ve içmesini bırakmasına Allah'ın bir ihtiyacı yoktur.\" (Buhari) ORUÇLA İLGİLİ MEVZULAR", source: "Hadis-i Şerif" },
    { id: 653, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz oruçlu olduğunu unutup yer ve içerse orucunu tamamlasın. Çünkü onu Allah yedirmiş ve içirmiştir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 654, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in, ailesine -yaklaşmasından- dolayı cünüp olarak tan yerinin ağardığı olurdu. Sonra yıkanır ve oruç tutardı.\" (Buharı ve Müslim) MUHARREM, ŞABAN VE HARAM AYLARDA ORUÇ TUTMAK", source: "Hadis-i Şerif" },
    { id: 655, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ramazandan sonra en faziletli oruç Allah'ın ayı olan Muharrem'de tutulan oruçtur. Farzlardan sonra en faziletli namaz da, gece namazıdır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 656, text: "H.z Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) hiçbir ayda Şaban ayında tuttuğu oruçtan daha çok oruç  MUHARREM. ŞABAN VE HARAM AYLARDA ORUÇ TUTMAK tutmazdı. Çünkü O, Şaban ayının hepsini oruçlu geçirirdi.\" Diğer bir rivayette: \"Şaban ayının çok azı hariç, o ayda hep oruç tutardı.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 657, text: "İbn-i Abbas (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Bu günlerde, yani Zilhicce'nin ilk on gününde yapılan iyi amel, Allah'a göre diğer günlerde yapılan amellerden çok daha sevimlidir. Ashab; 'Ey Allah'ın Resulü, Allah yolunda yapılan cihat da mı sevimli değil?'dediler. Resûlüllah (s.a.v) şöyle buyurdu: Allah yolunda yapılan cihat dahi değil. Ancak Allah yolunda canıyla ve malıyla cihada çıkmış, ama bunlardan hiç birisini geriye getirememiş olan başka,\" (Buhari) AREFE GÜNÜ VE MUHARREMİN DOKUZ VE ONUNCU GÜNÜ TUTULAN ORUCUN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 658, text: "Ebu Katâde (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'e Arefe günü oruç tutmaktan soruldu da şöyle buyurdu:   O gün tutulan oruç geçmiş ve gelecek senenin bütün günahlarına keffaret olur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 659, text: "Ibn-i Abbas (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) Aşure günü oruç tuttu ve o gün oruç tutulmasını emir buyurdu.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 660, text: "Ebu Katâde (r.a)'dan şöyle rivayet edilmiştir; \"Resûlüllah (s.a.v) Âşûre gününün orucundan sual edildi de şöyle buyurdu: Geçmiş senenin-günahlarına-keffaret olur.\" (Müslim) ŞEVVAL AYINDA ALTI GÜN ORUÇ TUTMANIN MÜSTEHABLIĞI", source: "Hadis-i Şerif" },
    { id: 661, text: "Ebu Eyyub (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  PAZARTESİ VE PERŞEMBE GÜNLERİ ORUÇ TUTMAK \"Kim Ramazan ayında oruç tutar sonra ona Şevval ayından altı gün daha eklerse, bütün sene oruç tutmuş gibi olur.\" (Müslim) PAZARTESİ VE PERŞEMBE GÜNLERİ ORUÇ TUTMAK", source: "Hadis-i Şerif" },
    { id: 662, text: "Ebu Katâde (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) Pazartesi günü oruç tutmaktan sual edildi de şöyle buyurdu: O öyle bir gündür ki, ben o gün dünyaya geldim,o gün ben peygamber olarak gönderildim veya o gün bana vahiy indirilmeye başlandı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 663, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Amelle-huzura- Pazartesi ve Perşembe günleri arz olunur. Ben, amelimin -Yüce Allah'a- arz olunurken oruçlu olmayı severim.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir. Müslim ise 'Oruç' lafzını zikretmeden rivayet etmiştir.)   HER AY ÜÇ GÜN ORUÇ TUTMANIN MUSTEHAB OLUŞU", source: "Hadis-i Şerif" },
    { id: 664, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Dostum Resûlüllah (s.a.v) bana üç şeyi vasiyet etti; Her aydan üç gün oruç tutmak, iki rekat kuşluk namazı ve yatmadan evvel vitir namazı kılmak.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 665, text: "Ebu Derda (r.a)'dan şöyle dediği rivayet edilmiştir: \"Dostum Resûlüllah (s.a.v) bana, yaşadığım sürece asla bıra kamayacağım üç şeyi vasiyet etti: Her aydan üç gün oruç tutmak, kuşluk namazı ve vitir namazı kılmadan uyumamam.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 666, text: "Abdullah b. Amr b.As (r.a)'dan Resûlüllah (s.a.v)'în Şöyle buyurduğu rivayet edilmiştir:  ORUÇLUYA İFTAR ETTİRMENİN FAZİLETİ \"Her aydan üç gün oruç tutmak, bütün seneyi oruçla geçirmek gibidir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 667, text: "Ebu Zer (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir aydan üç gün oruç tuttuğun zaman, on üç, on dört ve on beşinci günlerinde tut.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.) ORUÇLUYA İFTAR ETTİRMENİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 668, text: "Zeyd b. Halid el-Cüheyni (r.a)'dan, Resûlüllah (s.a.v)'İn şöyle buyurduğu rivayet edilmiştir: \"Kim bir oruçluya iftar ettirirse, oruç tutanın sevabı kadar kendisine sevap verilir; bununla beraber o oruçlunun sevabından da hiçbir şey eksilmez.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 669, text: "Ümmü Umâre el-Ensarî (r.a)'dan şöyle rivayet edilmiştir: \"Peygamber (s.a.v) onun yanına varmış, o da Resûlüllah'a yemek ikram etmişti. Peygamber (a.s); 'Sen de ye' buyuranca, kadın; 'Ben oruçluyum' demişti. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurmuştur: Oruçlunun huzurunda yemek yenince, yiyenler yemekten ayrılıncaya kadar melekler o oruçluya dua ederler.\" Ravi demiştir ki: Peygamberimiz (s.a.v) çok kere 'Doyuncaya kadar...' buyurmuştur.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.) İTİRAFIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 670, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) Ramazanın son on gününde itikafa girerdi.\" (Buhari ve Müslim)  HACCIN FAZİLETİ VE VACİPLERİ", source: "Hadis-i Şerif" },
    { id: 671, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v), Yüce Allah ruhunu alıncaya kadar Ramazanın son on günü itikafa girerdi. Ondan sonra da eşleri itikafa girmişlerdir.\" (Buharı ve Müslim) HACCIN FAZİLETİ VE VACİPLERİ", source: "Hadis-i Şerif" },
    { id: 672, text: "İbn-i Ömer (r.a) 'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İslam beş ana temel üzerine bina edilmiştir; Allah'dan başka\" ilah olmadığına ve Muhammed (a.s)'ın Allah'ın Elçisi olduğuna şehadet etmek, namaz kılmak, zekat vermek, Allah'ın evini haccetmek ve Ramazan orucunu tutmak.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 673, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir:   \"Resûlüllah (s.a.v) bize hutbe vererek şöyle buyurdu: Ey insanlar! Şüphesiz ki Allah sizin üzerinize haccı farz kıldı; o halde haccediniz. Bir adam; 'Ey Allah'ın Resulü, her sene mi?dedi. Resûlüllah (s.a.v) sustu. O adam sorusunu üç kere tekrarladı. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu: 'Eğer ben 'Evet' deseydim mutlaka vacip olurdu, ama güç yettiremezdiniz.' Sonra şöyle devam etti: Sizi kendinize bıraktığım sürece beni serbest bırakınız. Çünkü sizden öncekilerin helak olmasına sebep; çok sual sormaları ve peygamberlerine muhalefet etmeleri olmuştur. Onun için ben size bir şeyi emrettiğim zaman gücünüz yettiği kadarını yerine getiriniz. Sizi bir şeyden men ettiğimde, onu da terk ediniz.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 674, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim hacceder, kötü söz söylemez ve günah işlemezse, annesinden doğduğu gün gibi -memleketine- döner.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 675, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir umre diğer umreye kadar; arada geçen günahlara keffarettir. Kabul olunmuş olan bir haccın karşılığı İse, ancak ve ancak cennettir.\" (Buhari ve Müslim)  HACCIN FAZİLETİ VE VACİPLERİ", source: "Hadis-i Şerif" },
    { id: 676, text: "Hz. Âişe (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah'ın, Arefe gününden daha fazla cehennemden kul âzât ettiği bir gün yoktur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 677, text: "Ibn-i Abbas (r.a)'dan şöyle rivayet edilmiştir: \"Bir kadın Resûlüllah (s.a.v)'e şöyle dedi; Ey Allah'ın Resulü, Allah'ın kulları üzerine farz kıldığı hac ibadeti, babama binek üzerinde duramayacak kadar İhtiyarlamış İken yetişti. Onun yerine haccedebilir miyim? Resûlüllah (s.a.v); Evet, buyurdu.\" (Buhari ve Müslim) CİHADIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 678, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) hangi amel daha faziletlidir diye sorulduğunda şöyle buyurmuştur: Allah'a ve Resulüne iman etmektir. Sonra hangisidir,   denildiğinde; Allah yolunda cihat etmektir, buyurmuştur. Daha sonra hangisidir, denildiğinde ise; kabul olunmuş hacdır, buyurmuştur.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 679, text: "Ebu Zer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben dedim ki; Ey Allah'ın Resulü, hangi amel daha faziletlidir? Şöyle buyurdu: Allah'a iman ve O'nun yolunda cihat etmektir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 680, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'İn şöyle buyurduğu rivayet edilmiştir: \"Sabahın köründe veya akşamın karanlığında Allah yolunda yürümek, dünya ve dünyanın içindeki her şeyden daha hayırlıdır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 681, text: "Sehl b. Sa'd (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  CİHADIN FAZİLETİ \"Allah yolunda bir gün nöbet tutmak, dünyadan ve dünyanın içinde bulunan her şeyden daha hayırlıdır. Sîzden birinizin kamçısının cennetteki yeri, dünyadan ve dünyanın içindeki her şeyden daha hayırlıdır. Kulun Allah (c.c) yolunda sabah erkenden veya akşamleyin yola çıkıp yürümesi, dünyadan ve dünyanın içinde bulunan her şeyden daha hayırlıdır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 682, text: "Selman (r.a)'dan, Resûlüliah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Bir gün ve bir gece sınırlarda nöbet tutmak, bir ay oruç tutmak ve ibadete kalkmaktan daha hayırlıdır. Eğer nöbette ölürse, yaptığı amelin sevabı- kendisi için devam ettirilir. Rızkı kendisine döndürülür ve kabir azabından emin olur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 683, text: "Fedâle b. Ubeyd (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Her ölünün ameline mühür vurulur. Ancak Allah yolunda sınırlarda gözcülük yapanlar hariç. Çünkü onun ameli, kıyamet gününe kadar artırılır ve kabir azabından emin kılınır.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 684, text: "Osman (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'in şöyle buyurduğunu işittim; Allah yolunda bir gün sınırlarda nöbet tutmak diğer yerlerde bin gün nöbet tutmaktan daha hayırlıdır.\" (Tirmizİ rivayet etmiş ve hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 685, text: "Muaz (r.a)'dan \"Müslüman bir kişi Allah yolunda deve sağılacak kadar savaş etse, onu cennet vacip olur. Kim Allah yolunda bir yara alır veya bir sıkıntıya maruz kalırsa, kıyamet günü olduğundan daha kanlı bir şekilde gelir; kanının rengi zağferan rengi, kokusu ise misk kokusu gibidir.\" (Ebu Davud ve Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)  CİHADIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 686, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İnsanların hayırlı geçim şekillerinden biri de, Allah yolunda atının dizginini tutan ve her ne zaman savaş veya bir feryat işittiğinde atının sırtında uçarcasına koşan, döğüş veya ölüm ihtimali olan yerlere isteyerek atlayan adamınkidir. Ya da şu tepelerden bir tepenin veya şu vadilerden bir vadinin içinde koyun sürüsünün başına bulunup da namazını kılan, zekatını veren ve kendisine ölüm gelinceye kadar Rabbisine ibadet eden adamın yaşamıdır. İşte bu şekilde yaşayan insan ancak hayırdadır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 687, text: "Ebu Said el-Hudri (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim Allah'ı Rab, İslam'ı din ve Muhammed (a.s)'ı Peygamber olarak tanıyıp razı olursa, ona cennet vacip olur. Bu söz Ebu Said'in hoşuna gitti ve dedi ki: Ey Allah'ın Resulü, onu bize tekrarlasanız? Bunun üzerine Resûlüllah (s.a.v) onu tekrarladı, sonra şöyle buyurdu: Diğer bir iş daha var ki, Allah ondan dolayı kulunu cennette yüz derece yükseltir; her iki derece arasında yer ile gök arası kadar mesafe vardır. Ebu Said: Ey Allah'ın Resulü, o nedir?diye sorunca şöyle buyurdu: Allah yolunda cihattır, Allah yolunda cihattır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 688, text: "Ebu Abs Abdurrahman b. Cebr (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir kulun ayakları Allah yolunda tozlanırsa, artık ona cehennem ateşi dokunmaz.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 689, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah yolunda ağlayan kişiye ateş, sağılan süt tekrar memeye dönmedikçe dokunamaz. Bir kulun üzerinde, Allah yolundaki toz ile cehennem dumanı bir arada toplanmaz.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 690, text: "Ibn-i Abbas (r.a)'dan, Resûlüllah (s.a.v)'i şöyle buyururkert işittiğini söylediği rivayet edilmiştir: \"İki göz vardır ki, onlara ateş dokunmayacaktır; Allah korkusundan dolayı ağlayan göz ile, Allah yolunda nöbet tutarak geceleyen gözdür.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)  CİHADIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 691, text: "Zeyd b. Halid (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim Allah yolundaki bir gaziyi silahlandırırsa, şüphesiz gaza etmiş olur. Kim bir gazinin ailesini hayırla görüp gözetirse, şüphesiz gaza etmiş olur.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 692, text: "Abdullah b. Amr b.As (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Allah şehidin, borcu hariç bütün günahlarını affeder.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 693, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim samimiyetle şehitliği isterse, şehit olmasa bile kendisine o -sevap- verilir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 694, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sakın düşmanla karşılaşmayı temenni etmeyiniz ve Allah'dan afiyet isteyiniz. Ama düşmanla karşılaştığınız zaman da sabrediniz.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 695, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şehitler beş çeşittir; Tauna tutulmuş, ishal olmuş, boğulmuş, göçük altında kalmış ve Allah yolunda şehit olmuş kimseler.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 696, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Bir adam Resûlüllah (s.a.v)'e gelip şöyle dedi; Ey Allah'ın Resulü, bir adam gelip benim malımı almak istiyor, ne dersiniz? Resûlüllah (s.a.v); Ona malını verme, dedi. Adam; Eğer beni öldürürse?, dedi. Resûlüllah (s.a.v); Sen de onu öldür, buyurdu. Adam; Eğer o beni öldürürse?diye sorunca, Resûlüllah (s.a.v); sen o zaman şehit olursun buyurdu. Adam; Eğer ben onu öldürürsem?deyince, Resûlüllah (s.a.v); o zaman o cehennem ateşindedir\" buyurdu. (Müslim) KÖLE AZAD ETMENİN FAZİLETİ  KÖLE AZAD ETMENİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 697, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in kendisine söyle buyurduğu rivayet edilmiştir: \"Kim müslüman bir köle azad ederse, Allah da o kölenin her bir azasına karşılık o kişinin her bir azasını cehennem ateşinden azad eder; hatta kölenin avret mahalline karşılık azad edenin avret mahalli bile azad edilir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 698, text: "Ebu Zer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben dedim ki; Ey Allah'ın Resulü, hangi ameller daha faziletlidir? Resûlüllah (s.a.v) şöyle buyurdu; Allah'a iman ve Allah yolunda cihat etmektir. Dedim ki; Kölelerin hangisini azad etmek daha faziletlidir? Şöyle buyurdu: Sahibinin yanında en güzel ve en pahalı olanıdır.\" (Buhari ve Müslim) KÖLELERE İYİLİK ETMENİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 699, text: "Ma'rur b. Suveyd (r.a)'dan şöyle dediği rivayet edilmiştir:   \"Ebu Zer (r.a)'ı gördüm; kendisinin ve kölesinin üzerinde değerli bir elbise bulunuyordu. Kendisine bundan sorduğumda şöyle anlattı; O, Resûlüllah (s.a.v) zamanında bir adama sövmüş, annesini de ayıplamıştı. Bunun üzerine Peygamber (a.s); Sen, içinde cahiliyyet izleri bulunan bir kimsesin. Onlar sizin kardeşleriniz ve hizmetçilerinizdir. Allah onları elinizin altına koymuştur. Kimin elinin altında kardeşi varsa, yediğinden ona da yedirsin, giydiğinden ona da giydirsin. Başaramayacakları şeyi kendilerine yüklemeyiniz; eğer yüklemişseniz siz de onlara yardım ediniz.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 700, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Sizden birinize hizmetçisi yemeğini getirdiği zaman, onu kendisiyle beraber yemeğe oturtmuyorsa ona bir lokma veya iki lokma, ya da bir iki yemelik ikram etsin. Çünkü o yemeğin hazırlayıcısı odur.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 701, text: "Ibn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir köle efendisine karşı iyi davranır ve Allah'a karşı olan ibadetlerini en güzel biçimde yaparsa, onun sevabı iki kat daha fazla olur.\" (Buhari ve Müslim)  KÖLELERE İYİLİK ETMENİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 702, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Efendisine bağlı kalıp ona iyi davranan bir köle için iki kat sevap vardır,\" Ebu Hureyre'nin nefsi elinde bulunana yemin olsun ki, eğer Allah yolunda cihad, hac ve anneme iyilik yapmak olmasaydı, köle olarak ölmeyi yeğlerdim.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 703, text: "Ebu Musa el-Eş'arİ (r.a)'dan, Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Rabbine ibadetini güzelce yapan ve efendisine karşı üzerindeki hakkı, bağlılığı ve itaati yerine getiren köleye iki kat sevap vardır.\" (Buhari) FİTNE VE KARGAŞA DEVRİNDE İBADET YAPMAK", source: "Hadis-i Şerif" },
    { id: 704, text: "Ma'kıl b. Yesar (r,a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Anarşi ve fitne döneminde ibadet etmek, bana hicret etmek gibidir.\" (Müslim) ALIŞVERİŞ", source: "Hadis-i Şerif" },
    { id: 705, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam Peygamber (a.s)'a gelip ondan alacağını istedi ve kendisine kaba davrandı. Bunun üzerine Resûlüllah (s.a.v)'in ashabı o kişiye -hak ettiğini-bildirmeye kalkıştıklarında Resûlüllah (s.a.v) şöyle buyurdu: Onu bırakın. Çünkü hak sahibinin konuşma hakkı bulunmaktadır. Sonra şöyle devam etti; Ona devesinin yaşında benzeri bir deve veriniz. Dediler ki: Ey Allah'ın Resulü, onu bulamayız, ama daha yaşlı olanı var. Bu sefer Resûlüllah (s.a.v) şöyle buyurdu: Onu veriniz. Çünkü sizin en hayırlınız, borcunu en güzel şekilde ödeyeninizdir.\" (Buhari ve Müslim)'  ALIŞVERİŞ", source: "Hadis-i Şerif" },
    { id: 706, text: "Cabir (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Satışta, alışta ve borcunu öderken müsamahakar davranan kişiye Allah rahmet etsin.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 707, text: "Ebu Katâde (r.a)'dan Resûlüllah (s.a.v)'ı şöyle buyururken işittiği rivayet edilmiştir: \"Kimi, Allah'ın kıyamet gününün sıkıntılarından kurtarması sevindirirse, darda kalmış olan kimseye nefes aldırsın ya da borcundan indirim yapsın.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 708, text: "Ebu Safvân Suveyd b. Kays (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben ve Mahreme el-Abdi, Hacer beldesinden bir bez getirmiştik. Birden Resûlüllah (s.a.v) bize geldi ve bizden bir şalvarlık -bez- için pazarlık yaptı. Benim yanımda ise ücretle tartan bir tartıcı vardı. Resûlüllah (s.a.v) o tartıcıya şöyle buyurdu: Tart ve bir miktar da ilave et,\" (Ebu Davud ve Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)   İLMİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 709, text: "Muaviye (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kime Allah hayır dilerse, onu dinde fakih -dinin inceliklerini anlayan âlim- yapar.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 710, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İki kişiden başkasına haset -gıpta- etmek caiz değildir. Bunlar; Allah'ın kendisine mal verip de onu hak yolda harcamaya muvaffak kıldığı kimse ile Allah'ın kendisine hikmet ihsan edip de onunla hükmeden ve onu öğreten kimsedir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 711, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim ilim aramak için bir yola girerse, Allah da ona cennetin yolunu kolaylaştırır.\" (Müslim)  İLMİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 712, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim ilim öğrenmek İçin -evinden- çıkarsa, dönünceye kadar o kişi Allah yolundadır.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 713, text: "Ebu Umâme (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir âlimin ibadet eden bir kişiye olan üstünlüğü, benim sizin en aşağınıza olan üstünlüğüm gibidir. Resûlüllah (s.a.v) şöyle devam etti; Şüphesiz ki Allah ve melekleri, yer ve göklerin ehli, hatta deliğindeki karınca bile ve hatta balıklar bile insanlara hayrı öğretenler için dua ederler.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 714, text: "îbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'i şöyle buyururken işittiğini söylediği rivayet edilmiştir:   \"Bizden bir şey işitip de onu işittiği gibi ulaştıran kimsenin Allah yüzünü ağartsın. Çünkü nice ulaştırılan kimseler vardır ki, duyanlardan daha iyi anlayıp muhafaza ederler.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.) HAMD VE ŞÜKÜR", source: "Hadis-i Şerif" },
    { id: 715, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Peygamber (a.s)'a Miraç gecesi süt ve şaraptan oluşan iki kadeh getirildi. Her ikisine de baktı ve sütü aldı. Bunun üzerine Cabrâil (a.s) şöyle dedi; Seni fıtrata ulaştıran Allah'a hamd olsun. Eğer sen şarabı alsaydın ümmetin azardı.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 716, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah'a hamd olsun, cümlesi ile başlanmayan her Önemli iş -bereketten- kesiktir.\" (Hadis hasendir, Ebu Davud ve başkaları rivayet etmiştir.)  RESULÜLLAH (SA.V)'A DUA ETMEK", source: "Hadis-i Şerif" },
    { id: 717, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz Allah, bir yiyecek yiyip de kendisine hamd eden ve bir içecek içip de kendisine hamd eden kulundan mutlaka razı olur.\" (Müslim) RESULÜLLAH (S.A.V)'A DUA ETMEK", source: "Hadis-i Şerif" },
    { id: 718, text: "Abdullah b. Amr b. El-As (r.a)'ın Resûlüllah (s.a.v)'i şöyle buyururken işittiğini söylediği rivayet edilmiştir: \"Kim benim üzerime bir salat-ü selâm getirirse, Allah da kendisine bundan dolayı on defa rahmet eder.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 719, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kıyamet günü bana insanların en yakın olanları, bana en çok salat-ü selâm getirenleridir.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 720, text: "Ebu Hureyre (r.a) 'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yanında benim adım anıldığı'halde bana salat-ü selâm getirmeyen kişinin burnu -yerde- sürünsün.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 721, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kabrimi bayram yeri yapmayınız ve bana salat-ü selâm getiriniz. Çünkü sizin salat-ü selâmınız nerede olursanız olun bana ulaşır.\" (Ebu Davud sahih bir isnatla rivayet etmiştir.) ZİKRİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 722, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İki kelime var ki, dile hafif ama mizanda -tartıda- ağırdır. Rahmân'a da sevimli gelmektedir. Bunlar; Sübhânellahi ve biham-dihi, Sübhânellahil Âzim'dir.\" (Buhari ve Müslim)  ZİKRİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 723, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Benim için, Sübhânellahi, vel-hamdülillahi, velâ ilahe illâhü vallâhü ekber' demem, üzerine güneş doğan her şeyden daha sevimlidir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 724, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bir gün içinde yüz kere'Lâ ilahe illallâhü vahdehu lâ şerike leh. Lehül mülkü velehül hamdü ve hüve ala külli şey'in kadîr' derse, onun için on köle azad etmeye denk olur, ona yüz sevap yazılır ve onun yüz günahı da silinir. Bu dua, onun için o gün akşama kadar şeytandan koruyan bir sığınak olur ve hiçbir kimse bu zikri en fazla tekrar edenden daha faziletli bir amel ile gelemez.\" Şöyle devam etti: \"Kim bir gün içinde yüz kere 'Sübhânellahi ve bihamdihi' derse, deniz köpüğü kadar bile olsa onun tüm hataları silinir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 725, text: "Ebu Eyyub el-Ensarî (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim on defa 'Lâ ilahe illallahü vahdehu lâ şerîke leh. Lehül mülkü ve lehülhamdü ve hüve alâ külli şey'in kadîr' derse, İsmail (a.s)'ın evladından dört kişi azad etmiş gibi olur.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 726, text: "Ebu Zer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah'a en sevimli gelen sözü sana haber vereyim mi? Şüphesiz ki Allah'a en sevimli gelen söz, Sübhânellahi ve bihamdih'i sözüdür.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 727, text: "Ebu Malik el-Eş'arî (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Temizlik imanın yarısıdır. 'Elhamdülillah' sözü mizanı –tartıyı-  ZİKRİN FAZİLETİ doldurur. 'Siibhânellahi velhamdülillâhi' cümlesi ise, göklerin ve yerin arasını doldurur-ya da doldururlar.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 728, text: "Ka'b b. Ucre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Farz kılınan namazların arkasından otuz üç defa Sübhânellâh, otuz üç defa Elhamdülillah ve otuz üç defa Allahü Ekber diyen -veya bunu yapan- mahrum bırakılmaz.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 729, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Peygamber (a.s) rüku ve secdede sıkça şu cümleyi söylerdi; Sübhâneke Allahümme Rabbena ve bihamdike, Allahümmeğfirlî.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 730, text: "Ibn-i Abbas (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Rükua vardığınızda orada Rabbi tazim ediniz. Secdeye vardığınız da ise orada dua etmeye çalışınız; çünkü duanız orada kabul olunur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 731, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in secdede şöyle buyurduğu rivayet edilmiştir: \"Allahümmeğfirlî zenbî küllehu, dikkahu ve cillehu, ve evvelühû ve âhiruhû, ve alâniyetehû ve sirrehû.\" (Müslim) OTURARAK, YAN YATARAK, ABDESTSİZ, CÜNÜP VE ADETLİ İKEN ZİKRETMEK", source: "Hadis-i Şerif" },
    { id: 732, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) her vakit Allah'ı anardı.\" (Müslim)  UYKUNUN ADABI", source: "Hadis-i Şerif" },
    { id: 733, text: "İbn-i Abbas (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz ailesine yaklaşmak istediğinde 'Allah'ın adıyla başlarım, Allah'ım, bizi şeytandan şeytanı da bize nasip edeceğinden uzak eyle' derse ve aralarındaki bu ilişkiden bir çocuk takdir edilirse, şeytan o çocuğa asla bir zarar veremez.\" (Buhari ve Müslim) UYKUNUN ADABI", source: "Hadis-i Şerif" },
    { id: 734, text: "Huzeyfe ve Ebu Zer (r.a)'dan şöyle dedikleri rivayet edil miştir: \"Resûlüllah (s.a.v) yatağına girdiğinde 'Allah'ım senin adınla ölür, senin adınla yaşarım' der, uyandığı zaman da 'Bizleri öldürdükten sonra dirilten Allah'a hamd olsun, dönüp yine ona varacağız, buyururdu.\" (Buhari) ZİKİR HALKALARINA DEVAM VE ÖZÜRSÜZ ORADAN AYRILMAMAK", source: "Hadis-i Şerif" },
    { id: 735, text: "Ebu Hureyre ve Ebu Said (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah'ı anmak üzere oturan bir topluluğu melekler kuşatır, onları rahmet kaplar, onların üzerlerine sekinet iner ve Allah onları katında bulunanlar arasında yâd eder.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 736, text: "Ebu Vâkıd el-Haris b. Avf (r.a)'dan şöyle rivayet edil miştir: \"Bir ara Resûlüllah (s.a.v) insanlarla beraber mescidde otururken birden üç kişi çıkıp geldi. Gelenlerden ikisi Resûlüllah (s.a.v)'e yöneldi, biri ise gitti. Gelenler Resûlüllah (s.a.v)'in huzurunda durdular. Onlardan birisi halkada bir boşluk gördü ve oraya oturdu. Diğeri ise onların arkasına oturdu. Üçüncüsü ise arkasını dönüp gitti. Resûlüllah (s.a.v) meşguliyetini bitirince şöyle buyurdu; Dikkat edin! Size -gelen- şu üç kişi hakkında haber vereyim mi? Onlardan birisi Allah'a sığındı, Allah da onu korudu. Diğeri ise -halkayı sıkıştırmaktan- utandı, Allah da -onu mahrum kılmaktan- utandı. Öbürüne gelince; yüz çevirip gitti, Allah da ondan yüz çevirdi.\" (Buhari ve Müslim)  SABAH AKŞAM ALLAH'I ANMAK SABAH AKŞAM ALLAH'I ANMAK", source: "Hadis-i Şerif" },
    { id: 737, text: "Ebu Hureyre (r.a) 'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim sabaha erdiğinde ve akşama ulaştığında yüz kere 'Sübhaânellâhi ve bihamdihi' derse, kıyamet günü onun söylediğinin aynısını veya daha fazlasını söyleyen hariç, hiçbir kimse onun getirdiği mükafattan daha faziletli bir şey ile gelemez.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 738, text: "Ebu Hureyre (r.a)'dan şöyle rivayet edilmiştir: \"Peygamber (a.s) sabaha erince 'Allah'ım, senin lütfunla sabaha erdik, senin lütfunla akşama ulaştık, senin lütfunla yaşar, senin lütfunla ölürüz ve dönüşümüz sanadır' buyururdu. Akşama ulaştığında ise 'Allah'ım, senin lütfunla akşamlar, senin lütfunla yaşar, senin lütfunla ölürüz ve dönüşümüz sanadır' buyururdu.\" (E-bu Davud ve Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 739, text: "Abdullah b. Hubeyb (r.a)'dan Resûlüllah (s.a.v)'in kendisine şöyle buyurduğunu söylediği rivayet edilmiştir: \"Akşamladığın ve sabahladığın zaman üç kere 'Kul hüvallâhü ehad' ve 'Felak-Nâs' sûrelerini oku; sana her şeye karşı yeterli gelir.\" (Ebu Davud ve Tirmizi rivayet etmişlerdir. Tirmizi hadis hasendir, sahihtir demiştir.) YATARKEN OKUNACAK DUA", source: "Hadis-i Şerif" },
    { id: 740, text: "Huzeyfe ve Ebu Zer (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) yatağına uzandığı zaman şöyle buyururdu: Allah'ım, senin adınla yaşar, senin adınla ölürüm.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 741, text: "Alî (r.a)'dan, Resûlüllah (s.a.v)'in kendisine ve Fatıma'ya (r.a) şöyle buyurduğu rivayet edilmiştir: \"Yatağınıza girdiğiniz zaman -ya da yatacağınız yere uzandığınızda- otuz üç kere tekbir getiriniz, otuz üç kere tesbih ediniz ve otuz üç kere de hamd ediniz.\" (Buhari ve Müslim)  DUANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 742, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz yatağına uzanacağı zaman, elbisesinin iç tarafıyla yatağını silksin. Çünkü orada kendisinden önce -hangi canlının- dolaştığını bilemez. Sonra da şöyle desin; Rabbim, senin isminle yanım üzere yatarım ve senin isminle oradan kalkarım. Eğer ruhumu alırsan ona merhamet et. Eğer onu salıverirsen, iyi kullarını korudun gibi onu da koru!\" (Buhari ve Müslim) DUANIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 743, text: "Numan b. Beşir (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Dua etmek bir ibadettir.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 744, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s,a.v) duanın özlü olanını sever; onun dışındakileri terk ederdi.\" (Ebu Davud güzel bir senetle rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 745, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah'ım, senden hidayet, takva, iffet ve zenginlik-kanaat- istiyorum.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 746, text: "Abdullah b.Amr b.As (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kalpleri dilediği yöne çeviren Allah'ım, kalplerimizi sana itaate çevir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 747, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  DUANIN FAZİLETİ \"Allah'ım! Işimin koruyucu olan dinimi iyi eyle. İçinde yaşadığım dünyamı saadetli kıl. Dönüşümün içinde olacağı ahiretimi de hayırlı eyle. Hayatı benim için her türlü iyiliği artırmaya vesile eyle. Ölümü de benim için her türlü kötülükten rahatlama sebebi yap.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 748, text: "İbn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in dualarında şöyle buyurduğu rivayet edilmiştir: \"Allah'ım! Ihsan ettiğin nimetinin yok olmasından, verdiğin afiyetin bozulmasından, ansızın gelen belandan ve her türlü öfkenden sana sığınırım.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 749, text: "Ziyad b. Ilâka amcası Kutbe b. Malik (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu söylediği rivayet edilmiştir: \"Allah'ım! Çirkin ahlaktan, çirkin amellerden ve çirkin emellerden sana sığınıyorum.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 750, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah'ım! Açlıktan sana sığınıyorum; çünkü o ne kötü arkadaştır! Hainlikten de sana sığınıyorum; çünkü o ne çirkin bir huydur!\" (Ebu Davud, sahih bir isnatla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 751, text: "Imrân b. Husayn (r.a)'dan şöyle rivayet edilmiştir: \"Peygamber (a.s) Imrân'ın babası Husayn'a dua edeceği şu iki kelimeyi Öğretmiştir; Allah'ım! Hidayet üzere bulunmayı bana ilham eyle ve beni nefsimin şerrinden koruyuver.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 752, text: "Ibn-i Mes'ud (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v)'in dualarından biri de şudur; Allah'ım! Ben senden rahmetinin gereklerini, affının sonuçlarını, bütün günahlardan arınmayı, her türlü iyilikten paylarımı, cenneti kazanarak kurtuluşa ermeyi ve ateşten kurtulmayı istiyorum.\" (Hakim Ebu Abdullah rivayet etmiş ve hadis, Müslim'in şartı üzere sahihtir demiştir.)  ARKADAN DUA ETMENİN FAZİLETİ ARKADAN DUA ETMENİN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 753, text: "Ebu Derda (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Müslüman bir kul, kardeşinin arkasından ona dua ettiği zaman, mutlaka bir melek 'Aynısı sana da olsun' der.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 754, text: "Ebu Derdâ (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kişinin müslüman kardeşinin arkasından yaptığı dua kabul edilir. Yanı başında görevli bir melek, her ne zaman kardeşi için dua ederse; Âmin, aynısı sana da olsun, der.\" (Müslim) DUAYA MAHSUS MESELELER", source: "Hadis-i Şerif" },
    { id: 755, text: "Usâme b. Zeyd (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Kim, kendisine bir iyilik yapıldığında yapan kişiye 'Allah seni hayır ile mükafatlandırsın' derse, şüphesiz fazlasıyla teşekkür etmiş olur.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 756, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kulun Rabbine en yakın olduğu hal secde halidir. O halde secdede iken çok dua yapınız.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 757, text: "Ebu Umâme (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüliah (s.a.v)'e 'Hangi dua kabul edilmeye daha layıktır? ' diye sorulduğunda şöyle buyurmuştur; Gecenin son üçte birinde ve farz namazların arkasından yapılan dualar kabul edilmeye daha layıktır.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.) EVLİYANIN KERAMETİ VE ONLARIN FAZİLETİ  EVLİYANIN KERAMETİ VE ONLARIN FAZİLETİ", source: "Hadis-i Şerif" },
    { id: 758, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz sizden önceki ümmetler arasında kendilerine ilham olunan insanlar bulunmaktaydı. Eğer onlardan benim ümmetimin içinde de biri varsa, muhakkak o Ömer'dir.\" (Buhari) Müslim de Hz. Âişe'den rivayet etmiştir.", source: "Hadis-i Şerif" },
    { id: 759, text: "Cabir b. Abdullah (r.a)'dan şöyle dediği rivayet edilmiştir: \"Uhud savaşı başlarken bir gece babam beni çağırdı ve dedi ki; Ben kendimi, Peygamber (a.s)'ın ashabı arasından ilk öldürülecekler arasında görmekteyim. Şüphesiz ki ben, Resûlüllah (s.a.v)'in zatından başka bana senden daha yakın birini ardıma bırakmıyorum. Üzerimde kalan borç var; onu Öde. Kız kardeşlerine hayrı tavsiye et. Sabaha ulaştığımızda -babam- ilk öldürülen kişi oldu. Onunla beraber kabrine başka birini daha defnettim. Sonra, babamı kabrinde başka birisiyle beraber bırakmayı içim almadı ve ben tam altı ay sonra onu kabrinden- çıkardım. Bir de ne göreyim; kulağı haricinde o -ilk gün ki kabre- koyduğumuz gibi! Onu tek başına başka bir kabre koydum.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 760, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Karanlık bir gecede, Peygamber (a.s)'ın arkadaşlarından iki kişi Peygamber (a.s)'ın yanından çıktılar. Onlarla birlikte önlerinde kandile benzer iki ışık bulunuyordu. Ayrıldıklarında, ailelerinin yanına varıncaya kadar her biriyle beraber bir ışık onları aydınlattı.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 761, text: "Ibn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ben -babam- Ömer (r.a)'ın bir şeyle ilgili olarak; Ben onu şöyle zannediyorum, deyip de o şeyin öyle olmadığını hiç duymadım.\" (Buhari) GIYBETİN HARAMLIĞI  GIYBETİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 762, text: "Ebu Hureyre (r.a)'dan Peygamber (a.s)'ın şöyle buyurduğu rivayet edilmiştir: \"Allah'a ve ahiret gününe iman eden kimse, ya hayır söylesin, ya da sussun.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 763, text: "Sehl b. Sa'd (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Kim bana iki dudağının arasıyla iki bacağının arasını garanti -ederse, ben de ona cenneti garanti ederim.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 764, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'ı şöyle buyururken işittiği rivayet edilmiştir: \"Bir kul düşünmeden bir kelime konuşur da, ondan dolayı cehennemin doğusuyla batısı arası mesafeden daha uzak bir yere kayar gider,\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 765, text: "Ibn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   'Allah'ı anmaktan başka çok söz konuşmayınız. Çünkü Allah'ı anmaksızın çok konuşmak, kalbin katılaşmasına sebep olur. Şüphesiz insanların Allah'a en uzak olanı katı kalpli olanlarıdır.\" (Tirmizi)", source: "Hadis-i Şerif" },
    { id: 766, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah kimi, iki dudağı arasında bulunan -dilinin- şerriyle iki bacağı arasında bulunan -azalarının- şerrinden korursa, cennete girer.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 767, text: "Ebu Said el-Hudri (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Âdem oğlu sabaha eriştiğinde uzuvlarının hepsi dilin -şerrini- örtmek için derler ki; Bizim hakkımızda Allah'dan kork, çünkü biz sana bağlıyız. Eğer sen doğru olursan, biz de doğru oluruz. Eğer sen eğri büğrü olursan, biz de eğri büğrü oluruz!\" (Tirmizi)  GIYBET DİNLEMENİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 768, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Her müslümanın kanı, namusu ve malı diğer müslümana haramdır.\" (Müslim) GIYBET DİNLEMENİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 769, text: "Ebu Derdâ (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bir kardeşinin haysiyet ve namusunun çiğnenmesine karşı çıkarsa, Allah da kıyamet günü cehennem ateşini onun yüzünden uzaklaştırır.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 770, text: "İtbân b. Mâlik (r.a)'dan 'Ümit ehli olma' kısmında anlatılan meşhur uzun hadiste şöyle rivayet edilmiştir: \"Peygamber (a.s) namaza kalktığında; Mâlik b. Duhşüm nerede?diye sual buyurdu. Bir adam dedi ki; O Allah'ı ve Resulünü sevmeyen bir münafıktır. Bunun üzerine Peygamber (a.s) şöyle buyurdu:   Öyle söyleme! Sen onun Allah rızasını gözeterek 'Lâ ilahe illallah' dediğini görmüyor musun? Şüphesiz ki Allah, rızasını kazanma maksadıyla 'Lâ ilahe illallah' diyene cehennem ateşini haram kılmıştır.' (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 771, text: "Ka'b b. Mâlik (r.a)'dan Tövbe kıssasını anlatan uzun hadisinde tövbe bölümünde geçmiştir- şöyle rivayet edilmiştir: \"Peygamber (a.s) Tebûk harbine katılan bir toplulukla otururken; 'Ka'b b. Mâlik ne yaptı?' buyurdu? Seleme oğullarından bir adam dedi ki; Ey Allah'ın Resulü, hırkalarını giyinerek etrafa bakınıp durması onu -savaşa katılmaktan- alıkoydu. Bunun üzerine o kişiye Muaz b. Cebel (r.a); 'Ne kötü bir söz söyledin! Ey Allah'ın Resulü, Allah'a yemin olsun ki onun hakkında hayırdan başka bir şey bilmiyoruz' dedi. O zaman Resûlüllah (s.a.v) sükut eyledi.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 772, text: "Hz. Âişe (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ben şu kişiyle şu kişinin dinimiz hakkında bir şey bildiklerini sanmıyorum.\" (Buharı) Bu hadisi rivayet edenlerden biri olan Leys b. Sa'd dedi ki; O iki kişi münafıklardandı.  GIYBET DİNLEMENİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 773, text: "Fâtıma b. Kays (r.a)'dan şöyle dediği rivayet edilmiştir: \"Peygamber (a.s)'a geldim ve dedim ki; Ebu Cehm ve Muaviye bana evlenme teklif etti-ne buyurursunuz? Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu; Muaviye'ye gelince, malı olmayan bir fakirdir. Ebu Cehm ise, asayı omuzundan indirmez.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 774, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir. \"Ebu Süfyan'ın karısı Hind Peygamber (a.s)'a gelip; 'Şüphesiz Ebu Süfyan cimri bir adamdır. Benim kendisinin bilgisi dışında aldığımdan başka, bana ve çocuklarıma yetecek kadar bir şey bana vermiyor?diye şikayet etti. Peygamber (a.s); Sana ve çocuklarına yetecek kadarını iyilikle al, buyurdu.\" (Buhari ve Müslim) SÖZ GEZDİRMENİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 775, text: "Ibn-i Abbas (r.a)'dan, Resûlüllah (s.a.v)'in iki kabre uğrayıp şöyle buyurduğu rivayet edilmiştir: \"Hiç şüphesiz bu iki kabirde yatanlar azap olunuyorlar. Kendilerine göre- büyük bir suçtan dolayı azap olunmuyorlar. Evet, onların işledikleri suç çok büyüktür. Onlardan birisi; söz gezdirirdi. Diğeri ise; idrar sıçramasından sakınmazdı.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 776, text: "Ibn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Adh'ın ne olduğunu size haber vereyim mi? O, insanların arasını bozmak- için söylenmiş sözdür, nemîmedir,\" (Müslim) KORKU, ANARŞİ VE BENZERİ BİR SEBEP OLMADAN HALKIN KONUŞMALARINI İDARECİLERE JURNALLEMEK", source: "Hadis-i Şerif" },
    { id: 777, text: "lbn-i Mes ud (r.a) 'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir. \"Kimse bana, sahabilerimle ilgili hiçbir söz taşımasın. Çünkü ben,  İKİ YÜZLÜLÜĞÜN KÖTÜLENMESİ sizin karşınıza kırgın olmayan bir kalp ile çıkmayı seviyorum\" (Ebu Davud ve Tirmizi) İKİ YÜZLÜLÜĞÜN KÖTÜLENMESİ", source: "Hadis-i Şerif" },
    { id: 778, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İnsanları madenler gibi -çok farklı değerde- bulursunuz. Onların cahiliyet devrinde hayırlıları, Islam'ı iyi anladıkları takdirde Islamda da hayırlıdırlar. Insanların -devlet- işlerinde en hayırlı olanları, oralara karşı en isteksiz olanları bulacaksınız. İnsanların en şerlilerini de, ötekilere karşı başka bir yüzle, berikilere karşı da başka bir yüzle davranan iki yüzlüleri bulacaksınız.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 779, text: "Muhammed b. Zeyd'den şöyle rivayet edilmiştir: \"Bir kısım insanlar dedesi Abdullah b. Ömer (r.a) 'a dediler ki; Biz sultanlarımızın yanına girdiğimiz zaman onlara, yanlarından ayrıldığımızda yaptığımız konuşmanın aksini söylüyoruz. Abdullah   b. Ömer (r.a)'da dedi ki; Biz bunu, Resûlüllah (s.a.v) zamanında münafıklık sayardık.\" (Buharı) YALANIN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 780, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki doğruluk iyiliğe, iyilik de cennete ulaştırır. Bir adam, doğru konuşa konuşa nihayetinde Allah indinde çok doğru yazılır. Yalan günaha, günah da ateşe ulaştırır. Bir adam yalan konuşa konuşa nihayetinde Allah indinde çok yalancı yazılır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 781, text: "Abdullah b.Amr b.Âs (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Dört haslet vardır ki, kimde onlar bulunursa halis münafık olur.  SÖYLEYECEĞİ ŞEYLERİ SAĞLAM KAYNAĞA DAYAMAK Kimde bunlardan biri bulunursa, onu bırakıncaya kadar münafıklıktan bir haslet kendinde bulunmuş olur. Bunlar; Kendisine bir şey emanet edilince hainlik eder, konuştuğunda yalan konuşur, söz verdiğinde sözünden cayar ve muhakeme olduğu zaman doğruluktan sapar.\" (Buharı ve Müslim) SÖYLEYECEĞİ VE HİKAYE EDECEĞİ ŞEYLERİ SAĞLAM KAYNAĞA DAYAMAK", source: "Hadis-i Şerif" },
    { id: 782, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Her duyduğunu anlatması, kişiye yalan olarak yeter.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 783, text: "Semure (r.a) 'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yalan olduğunu göre göre kim benden bir hadis anlatırsa, o da yalancılardan biridir.\" (Müslim)   YALAN ŞAHİTLİK ETMEK BÜYÜK HARAMDIR", source: "Hadis-i Şerif" },
    { id: 784, text: "Ebu Bekre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Dikkat edin! Size büyük günahların en büyüğünü haber vereyim mi? Biz de dedik ki; 'Evet Ey Allah'ın Resulü.' Şöyle buyurdu; 'Allah'a şirk koşmak ve anne babaya isyan etmektir.' Bunun söylerken dayanmakta idi. Doğrulup oturdu ve şöyle buyurdu; 'Dikkat edin! Bir de yalan söz ve yalan şahitliktir.' Bunu o kadar tekrar ediyordu ki, nihayet biz; 'Keşke sussa' dedik.\" (Buhari ve Müslim) İNSANA VEYA HAYVANA LANET ETMENİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 785, text: "Ebu Zeyd Sabit b. Dahhâk el-Ensarî (r.a)'dan -bu zat Rıdvan biatını yapanlardandı- Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Kim yalan yere Islam milletinden -dininden- başka bir millet-din-üzerine  İNSANA VEYA HAYVANA LANET ETMENİN HARAMLIĞI yemin ederse, o kişi dediği gibi olur. Kim kendi canına bir şeyle kıyarsa, kıyamet günü onunla azap olunur. Bir kişinin, sahibi olmadığı bir şeyi adaması olmaz. Mü'mine lanet okumak, onu öldürmek gibidir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 786, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sıddık -çok doğru- olana lanetçi olması yakışmaz.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 787, text: "Semure b. Cündüb (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Allah'ın laneti, gazabı ve ateşi ile birbirinize lanet edip durmayınız.\" (Ebu Davud ve Tirmizi rivayet etmiş ve Tirmizi, hadis hasendir, sahihtir demiştir.) HAKSIZ YERE MÜSLÜMANA SÖVMENİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 788, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Müslümana sövmek fasıklıktır-haktan sapmadır, onu öldürmek ise küfürdür.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 789, text: "Ebu Zer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Bir kişi diğer bir kişiye fasıklık veya küfür isnat ettiği zaman, eğer onda böyle bir haslet yoksa, o isnat ettiği şeyler kendisine döner.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 790, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Birbirine sövmeye başlayan iki kişinin söyledikleri, mazlum olan haddi aşmadığı sürece, sövmeye ilk başlayanın üzerinedir.\" (Müslim) HAKSIZ YERE VE DİNİ BİR MASLAHAT OLMADAN ÖLÜYE SÖVMEK  YARATIKLARA EZİYET ETMEKTEN MEN", source: "Hadis-i Şerif" },
    { id: 791, text: "Hz. Âişe (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sakın Ölülere sövmeyiniz. Çünkü onlar önden gönderdiklerine kavuşmuşlardır.\" (Buharı ve Müslim) YARATIKLARA EZİYET ETMEKTEN MEN", source: "Hadis-i Şerif" },
    { id: 792, text: "Abdullah b. Amr b.As (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Müslüman; müslümanların elinden ve dilinden emniyette olduğu kimsedir. Muhacir ise; Allah'ın yasakladıklarından kaçınan kimsedir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 793, text: "Abdullah b. Amr b. As (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim cehennemden uzaklaştırılıp cennete sokulmayı arzuluyorsa, ölümü kendisine Allah'a ve ahiret gününe iman eder bir halde gelsin. Bir de kendisine yapılmasını istediği şeyi insanlara yapsın.\" (Müslim)   BİRBİRİNE BUĞZ ETMEK, İLİŞKİYİ KESMEK VE SIRT ÇEVİRMEKTEN MEN", source: "Hadis-i Şerif" },
    { id: 794, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Biribirinize karşı kin beslemeyiniz, birbirinize haset etmeyiniz, birbirinize sırt çevirmeyiniz ve ilişkilerinizi kesmeyiniz; Allah'ın kulları kardeş olunuz! Bir müslümana, kardeşinden üç gün ayrı -dargın- kalması helal değildir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 795, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Pazartesi ve Perşembe günleri cennet kapıları açılır. Kardeşiyle arasında kin ve düşmanlık bulunan kişi hariç, Allah'a şirk koşmayan bütün kullar bağışlanır, Meleklere-denilir ki; Bu ikisi barışıncaya kadar bekleyiniz, bu ikisi barışıncaya kadar bekleyiniz- bağışlamayı durdurunuz.\" (Müslim)  HASEDİN HARAMLIĞI HASEDİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 796, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizi haset etmekten sakındırıyorum! Çünkü haset, ateşin odunu -ya da otu- yiyip bitirdiği gibi iyilikleri yer bitirir.\" (Ebu Davud) AYIP ARAŞTIRMAKTAN VE BAŞKASININ DUYMASINI HOŞLANMADIĞI SÖZÜ DİNLEMEKTEN MEN", source: "Hadis-i Şerif" },
    { id: 797, text: "Muavıye (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Gerçek şu ki, eğer sen müslümanların ayıplarını araştırırsan, onları ifsat etmiş ya da az kalsın onları ifsat edecek hale gelirsin.\" (Ebu Davud, sahih bir isnatla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 798, text: "Ibn-i Mes'ud (r.a)'dan şöyle rivayet edilmiştir: \"Bir gün ona bir adam getirilir ve denilir ki; Bu falanca var ya, bunun sakalından şarap damlıyor! Bunun üzerine İbn-i Mes'ud; Şüphesiz ki biz, ayıp araştırmaktan men olunduk. Ama bize ortaya çıkan bir şey olursa, sahibini onunla sorumlu tutarız.\" (Ebu Davud) GEREKSİZ YERE KÖTÜ ZANDA BULUNMAMAK", source: "Hadis-i Şerif" },
    { id: 799, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'İn şöyle buyurduğu rivayet edilmiştir: \"Sizi zandan sakınınyorum! Çünkü zan, en yalan sözdür.\" (Buhari ve Müslim) MÜSLÜMANLARI HOR GÖRMENİN HARAMLIGI", source: "Hadis-i Şerif" },
    { id: 800, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir kişiye, müslüman kardeşini hor görmesi şer olarak yeter.\" (Müslim)  GEREKSİZ YERE KÖTÜ ZANDA BULUNMAMAK", source: "Hadis-i Şerif" },
    { id: 801, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kalbinde zerre kadar kibir bulunan bir kişi cennete giremez. Bir adam; Ama insan elbisesinin ve ayakkabısının güzel olmasını arzular, dedi. Bunun üzerine Resûlüllah (s.av) şöyle buyurdu; Şüphesiz ki Allah güzeldir; güzeli sever. Kibir ise, hakkı reddetmek ve insanları hor görmektir.\" (Müslim) MÜSLÜMANLARIN FELAKETİNE SEVİNMENİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 802, text: "Vasile b. Eska' (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kardeşinin felaketinden dolayı sevinç gösterme. Sonra Allah ona acır; seni de belaya çarptırır.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)   ŞERİATIN AÇIK HÜKÜMLERİYLE SABİT OLAN ŞEYLERE DİL UZATMANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 803, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İnsanların arasında yaygın iki huy vardır ki, onlar kendileri için -nimete- küfürdür. Bunlar; Nesebe dil uzatıp sövmek ve ölülere yüksek sesle ağlayıp feryâd-ı figan etmektir.\" (Müslim) ALDATMA VE HİLEDEN NEHİY", source: "Hadis-i Şerif" },
    { id: 804, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bize karşı silah taşırsa, bizden değildir. Kim bizi aldatırsa, bizden değildir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 805, text: "Ibn-i Ömer (r.a)'dan şöyle rivayet edilmiştir:  ALDATMA VE HİLEDEN NEHİY \"Peygamber (a.s), almaya niyeti olmadığı halde müşteri kızıştırmak için malın fiyatını artırmayı yasaklamıştır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 806, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'e bir adam alış verişte aldatıldığını anlattı. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu; Sen kiminle alış veriş yaparsan 'İslamda aldatma yoktur'de.\" (Buharı ve Müslim) SÖZDEN CAYMANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 807, text: "Abdullah b. Amr b.As (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Dört huy kimde varsa o halis münafıktır. Kimde bu dört huydan sadece biri varsa, onu terk edinceye kadar kendisinde münafıklıktan bir huy kalmış olur. Bunlar; Bir şey emanet edildiği zaman hainlik eder. Konuştuğu zaman yalan söyler. Söz verdiğinde sözünden cayar ve biriyle mücadeleye kalkıştığında haktan ayrılır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 808, text: "İbn-i Mes'ud, İbn-i Ömer ve Enes (r.a)'dan Resûlüilah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kıyamet günü sözünden cayan herkes için dikilecek bir bayrak vardır ve denilir ki; Bu, sözünden cayan falancanın bayrağıdır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 809, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Yüce Allah şöyle buyurmuştur; Ben kıyamet günü üç kişinin hasmıyım. Benim adımı söyleyerek verdiği sözden cayan adam, hür bir kişiyi satıp parasını yiyen adam ve bir işçiyi ücret karşılığında kiralayıp ondan faydanan, ama parasını vermeyen adam.\" (Buhari) İYİLİĞİ BAŞA KAKMANIN MENİ", source: "Hadis-i Şerif" },
    { id: 810, text: "Ebu Zer (r.a) 'dan Resûlüilah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Üç sınıf insan vardır ki Allah onlarla kıyamet günü konuşma-yacak  ÖVÜNME VE HADDİ AŞMANIN NEHYİ onlara -rahmet- nazarıyla bakmayacak ve onları temize çıkarmayacaktır.\" -Ebu Zer (r.a); Resûlüllah (s.a.v) bunu üç kez tekrar etti, dedi- Bunun üzerine Ebu Zer şöyle der; Ey Allah'ın Resulü, zarara ziyana uğrayıp pişman olan o adamlar da kim? Şöyle buyurur; Elbisesini yerlerde sürüyen, yaptığı iyiliği başa kakan ve yalan yere yemin ederek malının satışında sürüm sağlayandır.\" (Müslim) ÖVÜNME VE HADDİ AŞMANIN NEHYİ", source: "Hadis-i Şerif" },
    { id: 811, text: "lyâz b. Hımâr (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Şüphesiz ki Allah bana, hiçbir kimsenin diğerine azgınlık yapmayıp, birinin diğerine karşı üstünlük taslamayacağı kadar birbirinize tevazu göstermenizi vahyetti.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 812, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir adam 'İnsanlar helak oldu'dediği zaman, o kişi onların en çok helak olanı olmuş olur.\" (Müslim)   MÜSLÜMANLAR ARASINDA ÜÇ GÜNDEN FAZLA DARGIN DURMANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 813, text: "Enes (r.a)'dan Resülüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ilişkilerinizi kesmeyiniz, birbirinize sırt çevirmeyiniz, birbirinize haset etmeyiniz; Ey Allah'ın kulları kardeş olunuz! Bir müslümana, kardeşinden -dargın olarak- üç günden fazla ayrı kalması helal değildir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 814, text: "Ebu Eyyub (r.a)'dan Resülüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir müslümana, kardeşinden -dargın olarak- üç günden fazla ayrı kalması helal değildir; karşılaştıkları zaman biri bu tarafa, diğeri de öbür tarafa dönmektedirler. Onlardan en hayırlısı, selam -verip konuşmaya- ilk başlayandır.\" (Buhari ve Müslim)  MÜSLÜMANLAR ARASINDA ÜÇ GÜNDEN FAZLA DARGIN DURMAN...", source: "Hadis-i Şerif" },
    { id: 815, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ameller Pazartesi ve Perşembe günleri huzura arzolunur. Kardeşiyle arasında düşmanlık bulunan kişi hariç, Allah'a ortak koşmayan her kişiyi Cenab-ı Allah affeder. Allah (c.c) ; Şu iki kişiyi barışıncaya kadar bırakınız, buyurur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 816, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir müslümana, kardeşinden -dargın olarak- üç günden fazla ayrı kalması helal değildir. Kim üç günden fazla dargın kalır da ölürse, cehennem ateşine girer.\" (Ebu Davud, Buharı ve Müslim şartı üzere sahih bir isnatla rivayet etmiştir.) ÜÇ KİŞİDEN İKİSİNİN, ÜÇÜNCÜDEN İZİN ALMADAN GİZLİCE FISILDAŞMALARININ NEHYİ", source: "Hadis-i Şerif" },
    { id: 817, text: "Ibn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Üç kişi bir araya geldiğinde, ikisi diğer üçüncüyü bırakıp da kendi arasında fısıldaşmasın.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 818, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Siz üç kişi olduğunuz zaman iki kişi, insanlara karışıp dağılıncaya kadar diğer üçüncü kişiyi bırakarak fısıldaşmasın. Çünkü bu durum onu üzer.\" (Buharı ve Müslim) MAZERETSİZ ÇOCUK, KADIN, KÖLE VE HAYVANI TERBİYEYİ AŞAN MİKTARDA CEZALANDIRMAK", source: "Hadis-i Şerif" },
    { id: 819, text: "İbn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir kadın, ölünceye kadar bir kediyi hapsettiğinden dolayı azap olundu ve bu yüzden ateşe girdi. Onu hapsettiği zaman ona  MAZERETSİZ ÇOCUK, KADIN KÖLE VE HAYVANI TERBİYEYİ AŞAN... : hiçbir şey yedirmemiş, içirmemiş ve yer haşerelerini yemesi için serbset de bırakmamış idi.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 820, text: "Ibn-i Ömer (r.a)'dan şöyle rivayet edilmiştir: \"İbn-i Ömer (r.a), Kureyş'ten kuş dikip ona atış yapan iki gencin yanına uğramıştı. Hedefi vuramayan her atış için kuş sahibine bir şeyler ödüyorlardı. İbn-i Ömer'i gördüklerinde dağılıp ayrıldılar. Bunun üzerine İbn-i Ömer şöyle dedi; Bunu kim yaptı? Bunu yapana Allah lanet etsin! Şüphesiz ki Allah Resulü (s.a.v) canlı bir varlığı hedef yapana lanet etmiştir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 821, text: "Enes (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) hayvanların hapsedilerek-telef-edilmesini yasakladı.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 822, text: "Ibn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Kim bir köleyi işlemediği bir suçtan dolayı cezalandırır veya tokatlarsa, onun keffareti o köleyi azad etmesidir,\" (Müslim) BİT VE BENZERİ DAHİ OLSA CANLIYA ATEŞLE İŞKENCE ETMENİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 823, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bizi bir askeri birlik ile gönderirken Kureyş'ten iki kişinin ismini vererek şöyle buyurdu; Falan ve falanı yakalarsanız onları ateşle yakınız! Sonra yola çıkmaya koyulduğumuzda Resûlüllah (s.a.v) şöyle buyurdu; Ben size falan ve falanı yakmanızı emretmiştim. Ancak ateşle yalnız Allah azap eder; dolayısıyla eğer onları bulursanız öldürünüz!\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 824, text: "Ibn-i Mes'ud (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz bir seferde Resûlüllah (s.a.v) ile beraberdik. Kendisi bir  HİBE ETTİĞİ ŞEYDEN DÖNMENİN UYGUNSUZLUĞU ihtiyacını görmeye gitmişti. Biz yanında iki yavrusu olan bir serçe kuşu gördük ve yavrularını aldık. Ana serçe geldi ve bizim başımızda dolaşmaya başladı. Bir de Peygamber (a.s) çıkıp geldi ve şöyle buyurdu; 'Yavrusunu alarak bunu feryat ettiren hanginizdir? Yavrusunu ona geri veriniz.' Bir keresinde de karınca yuvasını yakarken gördü ve şöyle buyurdu; 'Burayı kim yaktı?' Dedik ki; 'Biz yaktık. 'Bunun üzerine şöyle devam etti; Şüphesiz ki ateşin Rabbi olandan başkasının ateş ile azap etmesi doğru değildir.\" (Ebu Davud, sahih bir isnatla rivayet etmiştir.) ALACAKLININ HAKKINI, İMKANI OLAN ZENGİNİN VERMEYİŞİNİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 825, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Zenginin, borcunu ödememesi zulümdür. Sizden birinizin -alacağı- bir zengine havale edilirse havaleyi kabul etsin.\" (Buhari ve Müslim) HİBE ETTİĞİ ŞEYDEN DÖNMENİN UYGUNSUZLUĞU", source: "Hadis-i Şerif" },
    { id: 826, text: "Ibn-i Abbas (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hibesinden dönen kimse, kusmuğuna dönüp -yiyen- köpek gibidir.\" (Buhari ve Müslim) Diğer bir rivayet de şöyledir: \"Hibesine dönen, kusmuğuna dönüp -yiyen- gibidir.\"", source: "Hadis-i Şerif" },
    { id: 827, text: "Ömer b. Hattab (r.a)'dan şöyle dediği rivayet edilmiştir: \"Allah yolunda -mücahidin birine- bir at hibe ettim. At onun yanında iken ona bakamayıp zayıflatmıştı. Onu satın almak istedim ve çok ucuza alabileceğimi sanıyordum. Bu durumu Peygamber (a.s)'a sorduğumda şöyle buyurdu; Onu sana bir dirheme bile verse sakın satın alma, sadakana geri dönme. Çünkü sadakasına dönen, kusmuğuna dönüp yiyen- kimse gibidir.\" (Buhari ve Müslim) YETİM MALINI YAĞMALAMANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 828, text: "Ebu Hureyre (r.a)'dan Peygamber (a.s)'ın şöyle buyurduğu rivayet edilmiştir:  FAİZİN NE KADAR BÜYÜK BİR HARAM OLUŞU \"Helak eden yedi husustan kaçınınız! Ashab; 'Onlar nelerdir Ey Allah'ın Resulü?' dediler. Şöyle buyurdular; Allah'a ortak koşmak, sihir yapmak, haksız yere Allah'ın haram kıldığı cana kıymak, faiz yemek, yetim malı yemek, düşmanla karşılaşıldığı o zor günde geri kaçmak ve hiçbir şeyden habersiz iffetli mü'min kadınlara iftira etmektir.\" (Buharı ve Müslim) FAİZİN NE KADAR BÜYÜK BİR HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 829, text: "İbn-i Mes' ud (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) faiz yiyene de yedirene de lanet etmiştir.\" (Müslim) RİYANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 830, text: "Ebu Hureyre (r.a)'dan, Resûlüllah (s.a.v)'i şöyle buyururken işittiğini rivayet etmiştir: \"Ben, ortaklığa ihtiyacı olmayanların en zenginiyim. Kim benden başka birini bana ortak koşarak bir amel yaparsa, onu da ortak koştuğunu da başbaşa bırakırım.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 831, text: "İbn-i Ömer (r.a)'dan rivayette bir takım insanlar kendisine gelip söyle demişlerdir; \"Biz sultanlarımızın huzuruna girdiğimizde onlara, yanlarından çıktığımızda konuştuklarımızın tersini söylüyoruz -ne dersin? İbn-i Ömer (r.a) şöyle demiştir; Biz bunu, Resûlüllah (s.a.v) zamanında münafıklık sayardık.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 832, text: "Cündüb b. Abdullah b. Süfyan (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Kim -yaptığı iyiliği- işittirirse, Allah da onun -ayıplarını-işittirir. Kim riya için amel- yaparsa, Allah da onun iki yüzlülüğünü ortaya çıkarır.\" (Buhari ve Müslim) RİYA SANILAN AMA RİYA OLMAYAN HUSUSLAR", source: "Hadis-i Şerif" },
    { id: 833, text: "Ebu Zer (r.a) ' dan şöyle dediği rivayet edilmiştir:  RİYA SANILAN AMA RİYA OLMAYAN HUSUSLAR \"Resûlüllah (s.a.v)'e denildi ki; Bir adam hayırlı bir amel yapar ve insanlar da ondan dolayı bu kişiyi methederse, bu duruma ne dersiniz? Şöyle buyurdu; Bu durum, mü'minin peşin müjdelenmesidir.\" (Müslim) DİNİ BİR MAZERET OLMADAN YABANCI KADINA VEYA TÜY BİTMEMİŞ DELİKANLIYA BAKMANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 834, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Âdem oğluna zinadan yana nasibi yazılmıştır, imkanı yok o bu fiili mutlaka yapacaktır. İki gözün zinası; -harama- bakmaktır. İki kulağın zinası; -çirkin sözleri- dinlemektir. Dilin zinası; -çirkin sözleri- konuşmaktır. Elin zinası; -haramı- tutmaktır. Ayağın zinası; -haram yerlere- atılan adımlardır. Kalb ise; zaten zinaya meyli vardır ve onu arzular. Tenasül uzuvları da bu durumu ya doğrular, ya da yalanlar.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 835, text: "Ebu Talha Zeyd b. Sehl (r.a)'dan şöyle dediği rivayet edilmiştir; \"Bizler evin avlusunda oturup konuşuyorduk. Bir den Resûlüllah (s.a.v) çıkıp geldi ve karşımızda durup şöyle buyurdu; Size ne oluyor ki, yolların üzerinde oturup duruyorsunz? Yol üzerindeki toplanmalardan kaçınınız. Biz de dedik ki; 'Biz, sakıncası olmayan bir şey için oturduk; oturduk müzakere ediyorduk, bir şeyler konuşuyorduk.' Bunun üzerine şöyle buyurdu; Eğer mutlaka oturacaksanız, o zaman oranın hakkını verin. O hak da- gözleri yummak, selam almak ve güzel sözler konuşmaktır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 836, text: "Cerîr (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'e ani bakmaktan sordum, şöyle buyurdu; Bakışını hemen çevir!\" (Müslim) YABANCI KADINLA BAŞBAŞA KALMANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 837, text: "Ukbe b. Âmir (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kadınların yanına girmekten kaçınınız. Ensardan bir kişi;  YABANCI KADINLA BAŞBAŞA KALMANIN HAHAMLIĞI 'Kadının kocası tarafından olan erkek yakınlarına -kaynı vs.- ne dersıniz?dedi. Bunun üzerine şöyle buyurdu; Koca tarafından olan yakınları ile başbaşa kalmak ise ölümdür.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 838, text: "İbn-i Abbas (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz mahremi dışında bir kadınla sakın başbaşa kalmasın.\" (Buhari ve Müslim) GİYİM VE HAREKETLERDE ERKEĞİN KADINA, KADININ DA ERKEĞE BENZEMELERİNİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 839, text: "İbn-i Abbas (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) -giyim ve davranışlarında- kadınlara benzemeye çalışan erkeklere ve erkeklere benzemeye çalışan kadınlara lanet etmiştir.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 840, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) kadın elibesesi giyen erkeğe ve erkek elbisesi giyen kadına lanet etmiştir.\" (Ebu Davud, sahih bir isnatla rivayet etmiştir.) ŞEYTAN VE KAFİRLERE BENZEMENİN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 841, text: "Cabir (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sol -elle- yemeyiniz. Çünkü şeytan sol eliyle yer, sol eliyle içerdi.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 842, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz Yahudiler ve Hristiyanlar -saçlarını- boyamazlar. Siz ise onlara aykırı hareket ediniz.\" (Buhari ve Müslim)  ERKEK VE KADININ SAÇINI SİYAHA BOYAMASININ YASAKLIĞI ERKEK VE KADININ SAÇINI SİYAHA BOYAMASININ YASAKLIĞI", source: "Hadis-i Şerif" },
    { id: 843, text: "Cabir (r.a)'dan şöyle dediği rivayet edilmiştir: \"Ebu Bekir (r.a)'ın babası Ebu Kuhâfe, Mekke'nin fethi günü başı ve sakalı kar gibi beyaz bir halde getirilir. Resûlüllah (s.a.v) şöyle buyurur; Bu -beyaz- saçları değiştiriniz ve siyaha boyamaktan da kaçınınız.\" (Müslim) BAŞIN BİR KISMINI TIRAŞ EDİP BİR KISMINI BIRAKMANIN YASAKLIĞI TIRAŞ ETMENİN KADINA DEĞİL DE ERKEĞE MÜBAH OLUŞU", source: "Hadis-i Şerif" },
    { id: 844, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmişti: \"Resûlüllah (s.a.v) başın bir kısmının tıraş edilip bir kısmının bırakılmasını yasaklamıştır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 845, text: "Ibn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v), başının saçlarının bir kısmının tıraş edilip bir kısmının bırakıldığı küçük bir çocuk gördü. Onları böyle yapmaktan yasaklayarak şöyle buyurdu; Ya hepsini tıraş ediniz, ya da hepsini bırakınız.\" (Ebu Davud, sahih bir isnatla Buhari ve Müslim şartı üzere rivayet etmiştir. PERUK TAKMANIN, DÖVME YAPTIRMANIN, DİŞLERİ İNCELTMENİN VE SEYREKLEŞTİRMENİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 846, text: "Esma (r.a)'dan şöyle rivayet edilmiştir: \"Bir kadın Peygamber (a.s)'a gelip; 'Ey Allah'ın Resulü, kızıma kızamık isabet etti ve saçları döküldü. Ben ise onu evlendirdim; ona emanet saç -peruk- takabilir miyim? Resûlüllah (s.a.v) şöyle buyurdu; Allah peruk takana da takdırana da lanet etmiştir.\" (Buharı ve Müslim)  SAKAL, BAŞ VE DİĞER UZUVLARDAKÎ BEYAZ KILLARI,GENÇLERİN...", source: "Hadis-i Şerif" },
    { id: 847, text: "İbn-i Ömer (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) emanet saç -peruk- takana ve takdırana, vücuduna dövme yapana ve yaptırana lanet etmiştir.\" (Buhari ve Müslim) SAKAL, BAŞ VE DİĞER UZUVLARDAKÎ BEYAZ KILLARI, GENÇLERİN YÜZÜNDEN ÇIKAN İLK , TÜYLERİ YOLMANIN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 848, text: "Amr b. Şuayb babasından, o da dedesinden (r.a) Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Ak tüyleri koparmayınız. Çünkü onlar kıyamet günü müslümanın nuru olacaktır.\" (Hadis hasendir, Ebu Davud, Tirmizi ve Neseî hasen isnatlarla rivayet etmişlerdir. Tirmizi, hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 849, text: "Hz. Âişe (r.a) 'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bizim emrimize -dinimize- uygun olmayan bir iş yaparsa, o yaptığı reddedilmiştir.\" (Müslim)   ÖZÜRSÜZ SAĞ ELLE TEMİZLENMENİN VE AVRET MAHALLİNİ TUTMANIN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 850, text: "Ebu Katâde (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz işediği zaman tenasül aletini sağ eliyle tutmasın, sağ eliyle kurulanıp temizlenmesin ve kabın içine nefes vermesin,\" (Buharı ve Müslim) ÖZÜRSÜZ MEST VE AYAKKABIYI BİR TEKİYLE GİYMENİN VE BUNLARI AYAKTA GİYMENİN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 851, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz tek ayakkabı ile yürümesin; ya ikisini de birden giysin, ya da ikisini de çıkarsın.\" (Buharı ve Müslim)  YATARKEN ATEŞ, KANDİL VS. ŞEYLER! YANAR HALDE BIRAKMA...", source: "Hadis-i Şerif" },
    { id: 852, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Sizden birinizin ayakkabısının bağı koptuğunda, onu düzeltinceye kadar diğer bir teki ile yürümesin.\" (Müslim) YATARKEN ATEŞ, KANDİL VS. ŞEYLERİ YANAR HALDE BIRAKMANIN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 853, text: "İbn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Uyuyacağınız zaman evlerinizde -yanan- ateş bırakmayınız.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 854, text: "Ebu Musa el-Eşarî (r.a)'dan şöyle dediği rivayet edilmiştir:   \"Bir gece Medine'de bir ev, hane halkıyla birlikte tutuşup yanmıştı. Onların durumu Resûlüllah (s.a.v)'e anlatılınca şöyle buyurdu; Şüphesiz ki bu ateş, sizin düşmanınızdır. Uyuyacağınız zaman onu söndürünüz,\" (Buhari ve Müslim) FAYDASIZ İŞ VE SÖZLERDE ZORLUK YÜKLENMENİN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 855, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Faydasız hususlarda- meşakkat yüklenmekten men olunduk.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 856, text: "Mesrûk' dan şöyle dediği rivayet edilmiştir: \"Biz Abdullah b. Mes'ud (r.a)'ın huzuruna girdiğimizde şöyle dedi; Ey İnsanlar! Kim bir şey biliyorsa onu söylesin; eğer bilmiyorsa 'En doğrusunu Allah bilir' desin. Çünkü bilmediğin hususta 'Allah daha iyi bilir' demen de ilimdendir. Yüce Allah Peygamberine (s.a.v) şöyle buyurmuştur; Ey Habibim de ki, ben bundan dolayı sizden bir ücret istemiyorum ve ben size -kendi kafasından- bir şey de yükleyenlerden de değilim.\" (Buhari)  ÖLÜYE YÜKSEK SESLE AĞLAMANIN, SAÇ BAŞ YOLMANIN VEYA ... ÖLÜYE YÜKSEK SESLE AĞLAMANIN, SAÇ BAŞ YOLMANIN VEYA BU MAKSATLA SAÇ KAZITMANIN, KENDİ HELAKİ İÇİN DUA ETMENİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 857, text: "Ömer b. Hattab (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ölü, kendisi için ağlanıp feryâd-ı figan edilmesinden dolayı kabrinde azap görür-rahatsız olur.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 858, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim -ölü için- yanaklarına vurur, yakalarını yırtar ve cahiliye âdeti üzere bağırıp çağırırsa bizden değildir.\" (Buharİ ve Müslim)", source: "Hadis-i Şerif" },
    { id: 859, text: "Muğîre b. Şu'be (r.a)'dan Resûlüllah (s.a.v)'i şöyle buyururken işittiği rivayet edilmiştir: \"Kimin -Ölümüne- yüksek sesle ağlanır ve feryâd-ı figan edilirse   kıyamet günü kendisine böyle ağlanıldığı için azap olunur.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 860, text: "Ümmü Atiyye Nuseybe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bizimle biat ettiği zaman, ölünün arkasından feryat etmeyeceğimize dair bizden söz aldı.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 861, text: "Numan b. Besir (r.a)'dan şöyle dediği rivayet edilmiştir: \"Abdullah b. Ravâha (r.a)'a baygınlık geldi. Bunun üzerine kız kardeşi; 'Vâ cebelâhü -vah dağım, dayanağım! Şöyle şöyle...' diye sayıyordu. Abdullah ayıldığı zaman şöyle dedi; Sen ne dedinse, bana 'Sen öyle misin?' denildi.\" KÂHİN, MÜNECCİM VE GAİPTEN HABER VEREN, ÇAKIL TAŞI, ARPA VS. ŞEYLERLE FAL BAKANLARA GİTMENİN HARAM OLUŞU  UĞURSUZ SAYMANIN YASAK EDİLİŞİ", source: "Hadis-i Şerif" },
    { id: 862, text: "Safiyye b. Ebu Ubeyd'den, ondan da Peygamber (a.s)'ın bazı eşlerinin söylediklerine göre Resûlüllah (s.a.v) 'in şöyle buyur duğu rivayet edilmiştir: \"Kim gelecekten haber veren birine gidip ona bir şey sorar ve onu tasdik ederse, o kişinin kırk günlük kıldığı namaz kabul olunmaz.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 863, text: "Kabîse b. Muhârik (r.a)'dan Resûlüllah (s.a.v)'i şöyle buyururken işittiği rivayet edilmiştir: \"Kuş ötmesinde uğur veya uğursuzluk aramak, kuş uçmasıyla ve ufak taşlarla fal bakmak sihir çeşitlerindendir.\" (Ebu Davud, sahih bir isnatla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 864, text: "Ebu Mes'ud el-Bedrî(r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) köpek satışından elde edilen parayı, zina parasını ve falcının kazancını yasaklamıştır.\" (Buharı ve Müslim) UĞURSUZ SAYMANIN YASAK EDİLİŞİ", source: "Hadis-i Şerif" },
    { id: 865, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hastalıkda -kendiliğinden- bulaşma olmaz. Kuş uçmasında da uğursuzluk yoktur. Fe'l ise benim hoşuma gider. Asahab; 'Fe'l nedir?'dediklerinde, 'Güzel söz' buyurdu.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 866, text: "Ibn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hastalıkda -kendiliğinden- bulaşma olmaz. Kuş uçmasında da uğursuzluk uğursuzluk yoktur. Eğer bir şeyde uğursuzluk olsaydı, evde, kadında ve atta olurdu.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 867, text: "Büreyde (r.a)'dan şöyle rivayet edilmiştir: \"Peygamber (a.s) kuş uçmasında uğursuzluk aramazdı.\" (Ebu Davud, sahih bir isnatla rivayet etmiştir.) HAYVAN RESMİ YAPMANIN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 868, text: "İbn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  HAYVAN RESMİ YAPMANIN HARAMLIĞI \"Bu -canlı- resimleri yapanlara kıyamet günü azap edilir ve kendilerine denilir ki; Yarattıklarınıza can verin bakalım!\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 869, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bir yolculuktan dönmüştü. Ben ise, üzerinde resimler bulunan bir perde ile evin önündeki sofayı örtmüştüm. Resûlüllah (s.a.v) bunu görünce yüzünün rengi değişti ve şöyle buyurdu; Ey Âişe! Kıyamet günü Allah indinde insanların en şiddetli azaba çarptırılacak olanları, Allah'ın yarattığına benzetmeye çalışanlardır. Hz. Âişe dedi ki; Bunun üzerine onu parçalara ayırdık ve ondan bir veya iki yastık -yüzü- yaptık.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 870, text: "Ebu Talha (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İçinde köpek ve -canlı- resmi bulunan bir eve melekler asla girmez.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 871, text: "Ibn-i Ömer (r.a)'dan şöyle buyurduğu rivayet edilmiştir: \"Cebrail (a.s) Resûlüllah (s.a.v)'e geleceğini vaad etmişti. Fakat gecikince Resûlüllah (s.a.v)'e beklemek ağır gelmiş ve dışarı çıkmıştı. Hemen Cebrail kendisini karşıladı. Resûlüllah (s.a.v) gecikmesinden dolayı şikayetini belirtince Cebrail şöyle dedi: Biz, içinde köpek ve -canlıya ait- resim bulunan bir eve asla girmeyiz.\" (Buhari) AV, DAVAR VE ZİRAAT HARİCİNDE KÖPEK BESLEMENİN HARAMLIĞI", source: "Hadis-i Şerif" },
    { id: 872, text: "Ibn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v)'i şöyle buyururken işittim; Kim -av veya sürü köpeği hariç- köpek beslerse, o kişinin sevabından her gün iki kırat eksilir,\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 873, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim -ziraat ve sürü köpeği hariç- köpek barındırırsa, o kişinin amelinden her gün bir kırat eksilir.\" (Buhari ve Müslim)  DEVE VE BAŞKA HAYVANLARA ÇAN TAKMANIN, YOLCULUKTA ... DEVE VE BAŞKA HAYVANLARA ÇAN TAKMANIN, YOLCULUKTA ÇAN VE KÖPEK TAŞIMANIN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 874, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Melekler, yanlarında köpek veya çan bulunduran bir gruba arkadaşlık etmezler.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 875, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Çan, şeytanın çalgılarındandır.\" (Müslim) PİSLİK YİYEN DEVEYE BİNMENİN MEKRUH; AMA TEMİZ YEM YİYİP DE ETİ TEMİZLENİRSE 0 ZAMAN MEKRUH OLMAYIŞI", source: "Hadis-i Şerif" },
    { id: 876, text: "İbn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) pislik yiyen devenin üzerine binmeyi yasak etmiştir.\" (Ebu Davud,sahih isnatla rivayet etmiştir.)   MESCİDE TÜKÜRMEKTEN MEN VE BU GİBİ ŞEYLERİ TEMİZLEYİP MESCİDİ TEMİZ TUTMAYI SAĞLAMANIN EMREDİLİŞİ", source: "Hadis-i Şerif" },
    { id: 877, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Mescide tükürmek büyük bir hatadır. Onun keffareti ise gömülmesidir.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 878, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) -mescidin- kıble duvarında balgam veya tükürük, ya da sümük gördü; hemen onu kazıdı.\" (Buhari ve Müslim) MESCIDDE ÇEKİŞME, BAĞIRMA, KAYBINI ARAMA, ALIŞ VERİŞ VEYA KİRA İŞLERİ İLE MEŞGUL OLMANIN MEKRUH OLUŞU  MESCÎDDE ÇEKİŞME, BAĞIRMA, KAYBINI ARAMA, ALIŞ VERİŞ VEYA", source: "Hadis-i Şerif" },
    { id: 879, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'i şöyle buyururken işittiği rivayet edilmiştir: \"Kim mescidde kaybettiği bir şeyini arayan birini işitirse, 'Allah onu sana geri getirmesin' desin. Çünkü mescidler bunun için yapılmamıştır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 880, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Mescidde bir şey satan veya satın alan birini gördüğünüz zaman 'Allah senin ticaretine kâr vermesin' deyiniz. Mescidde kaybettiği bir şeyi arayan birini gördüğünüzde de 'Allah onu sana geri getirmesin' deyiniz.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 881, text: "Büreyde (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam mescidde kaybettiği bir şeyi arayarak 'Kim bana kırmızı deveyi gösterecek?' demişti. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu; Bulamayasın! Şüphesiz ki mescidler ne için yapılmışsa, onun için yapılmıştır- o maksatla kullanılır.\" (Müslim)   SOĞAN, SARIMSAK, PIRASA VS. KÖTÜ KOKULU YİYECEKLERİ YİYİP, KOKUSUNU GİDERMEDEN MAZERETSİZ MESCİDE GİTMENİN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 882, text: "İbn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bu ağaçtan -yani sarımsak ağacından- yerse, bizim mescidimize sakın yaklaşmasın.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 883, text: "Ömer b. Hattab (r.a)'dan şöyle rivayet edilmiştir: \"Kendisi Cuma günü hutbe vermiş ve hutbesinde şöyle buyurmuştur; Ey İsanlar! Siz şu iki ağaçtan; soğan ve sarımsak ağacından yiyorsunuz. Oysa ben onları hoş görmemekteyim. Şüphesiz ki ben Resûlüllah (s.a.v)'i, bu ikisinin kokusunu mescidde bir adamda duyduğu zaman emredip Bakî mezarlığına çıkartıldığını gördüm. O halde onları kim yerse, onların -kokularını- pişirerek öldürsün.\" (Müslim)  CUMA GÜNÜ İMAM HUTBEDE İKEN DİZLERİ DİKİP, ELLERİ ... CUMA GÜNÜ İMAM HUTBEDE İKEN DİZLERİ DİKİP, ELLERİ BAĞLAYARAK OTURMANIN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 884, text: "Muaz b. Enes el-Cühenî (r.a)'dan şöyle rivayet edilmiştir: \"Peygamber (a.s), Cuma günü imam hutbe verirken dizler dikip elleri bağlayarak oturmayı yasaklamıştır.\" (Ebu Davud ve Tirmizi rivayet etmiş; hadis hasendir demişlerdir.) KURBAN KESECEK OLANIN, ZİLHİCCENİN İLK ON GÜNÜ GİRDİĞİNDE KURBAN KESİNCEYE KADAR SAÇ VE TIRNAKLARINI KESMESİNİN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 885, text: "Ümmü Seleme (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kimin kesecek bir kurbanı varsa, Zilhicce hilali göründüğünde kurbanını kesinceye kadar saçından ve tırnaklarından hiçbir şey almasın.\" (Müslim)   MAHLUKAT ADINA YEMİN ETMENİN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 886, text: "İbn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki Allah sizleri, babalarınız adıyla yemin etmekten men etmiştir. Artık kim yemin edecekse Allah adına yemin etsin ya da sussun.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 887, text: "Abdurrahman b. Semure (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Putlara ve babalarınıza yemin etmeyiniz.\" (Müslim) YALANDAN BİLEREK YEMİN ETMENİN BÜYÜK HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 888, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  YALANDAN BİLEREK YEMİN ETMENİN BÜYÜK HARAM OLUŞU \"Kim yemin ederek müslüman bir kişinin malını haksız yere -gasp ederse- gazabına uğramış olarak Allah'a kavuşur. Ibn-i Mes'ud şöyle dedi: Sonra Resûlüllah (s.a.v) delil olarak bize Yüce Allah'ın kitabından -şu ayeti- okudu; Şüphesiz Allah'a verdikleri sözlerine ve yeminlerine karşılık az bir karşılık satın alanlar var ya, işte onlar için ahirette bir nasip yoktur. Allah kıyamet günü onlarla konuşmayacak, onlara bakmayacak ve onları temize çıkarmayacaktır. Onlar için çok acıklı bir azap vardır.\" Âl-i İmran;77 (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 889, text: "Ebu Umâme İyâs b. Sa'lebe el-Harisi (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Kim yemin ederek müslüman bir kişinin hakkını gasbederse, şüphesiz Allah ona cehennemi vacip, cenneti de haram kılar. Bir adam; 'Ey Allah'ın Resulü, basit bir şey olsa yine öyle mi?'diye sorunca şöyle buyurdu; Velev ki misvak ağacından bir dal parçası olsun!\" (Müslim) YEMİN EDİP DE SONRA BAŞKA BİR ŞEYİ DAHA HAYIRLI GÖRDÜĞÜ İÇİN YEMİNİNİN TERSİNİ YAPAN KİŞİNİN KEFFARET VERMESİNİN MENDUP OLUŞU", source: "Hadis-i Şerif" },
    { id: 890, text: "Abdurrahman b. Semure (r.a)'dan Resûlüllah (s.a.v)'in kendisine şöyle buyurduğu rivayet edilmiştir: \"Bir şey üzerine yemin eder de sonra ondan daha hayırlısını görürsen, o hayırlı olanı yerine getir; yemininden dolayı da keffaret ver.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 891, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim bir şeye yemin eder de sonra ondan daha hayırlısını görürse, yemininden dolayı keffaret versin ve o hayırlı olan şeyi yapsın.\" (Müslim) YEMİN-İ LAĞVIN BAĞIŞLANMASI VE BUNDAN DOLAYI KEFFARET GEREKMEMESİ", source: "Hadis-i Şerif" },
    { id: 892, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Allah sizi yeminlerinizdeki lağvden -dil sürçmesinden- dolayı sorumlu tutmaz.... âyeti, bir adamın 'Vallahi hayır, vallahi evet' diye söylediği yemininden dolayı indirilmiştir.\"  YEMİN-İ LAĞVIN BAĞIŞLANMASI VE KEFFARET GEREKMEMESİ", source: "Hadis-i Şerif" },
    { id: 893, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Yemin malın satılmasını artırır; ama kazancın -bereketini-yok eder.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 894, text: "Cabir (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Allah rızası adına sadece cennet istenebilir.\" (Ebu Davud)", source: "Hadis-i Şerif" },
    { id: 895, text: "İbn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim Allah adıyla sığınırsa, onu koruyunuz. Kim Allah adına bir şey isterse, ona veriniz. Kim sizi davet ederse, icabet ediniz. Kim size bir iyilik yaparsa, onun karşılığını veriniz. Eğer karşılığını vereceğiniz bir şey bulamazsanız, karşılığını verdiğinize kani oluncaya kadar kendisine dua ediniz.\" (Ebu Davud ve Neseî, Buhari ve Müslim'in isnadlarıyla rivayet edilmiştir.)   HÜKÜMDARA ŞEHİNŞAH -PADİŞAHLAR PADİŞAHI- DEMENİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 896, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Aziz ve Celil olan Allah indinde en alçak isim, 'Padişahlar padişahı' adıyla isimlendirilen adamın ismidir.\" (Buhari ve Mülim) FASIK, BÎDATÇI VE BENZERLERİNE \"EFENDİ\" GİBİ BENZERİ SÖZLERLE SESLENMENİN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 897, text: "Büreyde (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sakın münafık birine 'Beyefendi' demeyiniz; çünkü eğer o 'Beyefendi' yapılarak büyütülürse, gerçekten Yüce Rabbinizi kızdırmış olursunuz.\" (Ebu Davud, sahih bir isnatla rivayet etmiştir.)  SITMAYA SÖVMENİN MEKRUH OLUŞU SITMAYA SÖVMENİN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 898, text: "Cabir (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) Ümmü Sâib veya Ümmü Müseyyeb'in yanına varıp, 'Ey Ümmü Sâib veya Ümmü Müseyyeb! Sana ne oluyor ki, böyle titreyip duruyorsun?'diye sordu. Dedi ki; 'Allah artırmasın, sıtmaya tutulmuşum!' Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu; Sakın sıtmaya sövme. Çünkü o hastalık, körüğün demirin pasını giderdiği gibi Âdem oğlunun hatalarını gidermektedir.\" (Müslim) RÜZGÂR ESTİĞİNDE SÖYLENECEK SÖZ VE ONA SÖVMENİN MENİ", source: "Hadis-i Şerif" },
    { id: 899, text: "Ebu Münzir Übey b.Ka'b (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sakın rüzgâra sövmeyiniz. Hoşlanmadığınız bir durum gördüğünüz zaman şöyle deyiniz;   Allah'ım! Senden bu rüzgârın hayırlısını, rüzgârda bulunan hayrı ve kendisine verilen emrin hayırlısını istiyoruz. Yine bu rüzgârın şerrinden, rüzgârda bulunan şerden ve kendisine verilen emrin şerrinden sana sığınıyoruz.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 900, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğunu işittiği rivayet edilmiştir: \"Rüzgâr Allah'ın rahmetindendir; kah rahmet getirir, kah azap getirir. Rüzgârı gördüğünüz zaman ona sövmeyiniz. Allah'dan hayrını isteyiniz ve onun şerrinden de Allah'a sığınınız.\" (Ebu Davud, hasen bir isnatla rivayet etmiştir.) HOROZA SÖVMENİN MEKRUHLUĞU", source: "Hadis-i Şerif" },
    { id: 901, text: "Zeyd b. Halid el-Cüheni (r.a)'dan Resûlüliah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Horoza sövmeyiniz; çünkü o namaz için uyandırır.\" (Ebu Davud, hasen bir isnatla rivayet etmiştir.)  MÜSLÜMANA \"EY KAFİR\" DEMENİN HARAM OLUŞU ŞU YILDIZ SEBEBİYLE YAĞMURA KAVUŞTUK DEMENİN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 902, text: "Zeyd b. Halid (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) Hudeybiye'de gece yağan yağmurun ardından bize sabah namazı kıldırdı. Namazdan ayrılınca insanlara döndü ve şöyle buyurdu; 'Rabbinizin size ne buyurduğunu biliyor musunuz?' Dediler ki; 'Allah ve Resulü en iyisini bilir.' Bunun üzerine şöyle devam etti; Kullarımdan bir bölümü bana iman ederek sabahladı, diğer bölümü de kafir olarak sabahladı. 'Allah'ın lütfü ve rahmeti sebebiyle yağmur yağdırıldı' diyen kişi var ya, işte o bana iman etmiş, yıldızı inkar etmiştir. Ama 'Şu şu yıldız sebebiyle yağmur yağdırılmıştır' diyen kişiye gelince, işte o beni inkar etmiş, yıldıza iman etmiştir.\" (Buhari ve Müslim) MÜSLÜMANA \"EY KAFİR\" DEMENİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 903, text: "İbn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir kişi kardeşine 'Ey kâfir ' dediği zaman, bu söz onlardan birine döner. Eğer dediği gibi ise -tamam o kişi kâfirdir- Ama öyle değilse, söylediği söz kendi aleyhine döner.\" (Buharı ve Müslim) ÇİRKİN SÖZ SÖYLEMENİN VE DİLİ BUNLARA ALIŞTIRMANIN MENİ", source: "Hadis-i Şerif" },
    { id: 904, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Mü'min dürten-iğneleyen, lanetliyen, kötü sözlü ve hayasız biri değildir.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)", source: "Hadis-i Şerif" },
    { id: 905, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hangi şeyde çirkinlik varsa mutlaka onu lekeler. Hangi şeyde de haya varsa mutlaka onu süsler.\" (Tirmizi rivayet etmiş ve hadis hasendir demiştir.)  İNSANLARLA ANLAMAYACAĞI YABANCİ KELİMELERLE KONUŞMAK.. İNSANLARLA ANLAMAYACAĞI YABANCI KELİMELERLE KONUŞMAK EDEBİYAT YAPMAK VE GRAMERE GİRMEKTEN KAÇINMAK", source: "Hadis-i Şerif" },
    { id: 906, text: "İbn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Işlerde ileri gidenler-konuşmalarında edebi yönden derine inip anlaşılamayacak uslüp kullananlar helak oldular.\" Resûlüllah (s.a.v) bu sözü üç kere tekrar etmiştir. (Müslim)", source: "Hadis-i Şerif" },
    { id: 907, text: "Abdullah b. Amr b.Âs (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki Allah, sığırın diliyle otları evirip çevirmesi gibi, sözü ağzında geveleyerek belagat taslayan kişiye çok kızar.\" (Ebu Davud ve Tırmizi) \"NEFSİM PİSLENDİ\" DEMENİN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 908, text: "Hz. Âişe (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu ivayet edilmiştir: \"Sizden biriniz sakın 'Nefsim kirlendi' demesin. Ama 'Nefsim kötüleşti' desin.\" (Buhari ve Müslim) ÜZÜME \"KERM\" DEMENİN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 909, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Üzümü 'Kerm' ismiyle isimlendirmeyiniz. Çünkü Kerm, müslümanın kalbidir.\" (Buharİ ve Müslim. Bu lafız Müslim'indir.)", source: "Hadis-i Şerif" },
    { id: 910, text: "Vâil b. Hucr (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Üzüme-Kerm demeyiniz; ama üzüm ve üzüm asması deyiniz.\" (Müslim)  NİKAH GİBİ MEŞRU BİR MAZARET OLMADAN BİR KADININ GÜZEL... NİKAH GİBİ MEŞRU BİR MAZARET OLMADAN BİR KADININ GÜZELLİKLERİNİ BİR ERKEĞE ANLATMANIN YASAKLIĞI", source: "Hadis-i Şerif" },
    { id: 911, text: "Ibn-i Mes'ud (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sakın bir kadın başka bir kadınla yakın ilişkiye girmesin; sonra o kadını kocasına anlatır da, kocası sanki ona bakıyor gibi olur.\" (Buharı ve Müslim) İNSANIN \"ALLAH'IM DİLERSEN BENİ BAĞIŞLA\" DEMESİNİN MEKRUH OLUŞU, KESİN İFADELERLE DUA ETMENİN GEREĞİ HAKKINDADIR", source: "Hadis-i Şerif" },
    { id: 912, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyur duğu rivayet edilmiştir: \"Sizden biriniz sakın 'Allah'ım dilersen beni bağışla. Allah'ım dilersen bana merhamet et' demesin. İsteğini kararlılıkla ortaya koysun. Çünkü Allah'ı zorlayan hiçbir şey yoktur,\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 913, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz dua ettiği zaman isteğini kararlılıkla ortaya koysun. 'Allah'ım dilersen bana ver' demesin. Çünkü Allah'ı zorlayacak hiçbir şey yoktur.\" (Buharı ve Müslim) \"ALLAH VE FALANCA DİLERSE\" DEMENİN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 914, text: "Huzeyfe b. Yeman (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sakın 'Allah dilerse, bir de falanca dilerse' demeyiniz; ama 'Allah dilerse, sonra da falanca dilerse' deyiniz.\" (Ebu Davud sahih bir isnatla rivayet etmiştir.) YATSIDAN SONRA KONUŞMANIN MEKRUH OLUŞU  DİNİ BİR MAZERETİ BULUNMAYAN BİR KADININ, KOCASI ÇAĞIRDI...", source: "Hadis-i Şerif" },
    { id: 915, text: "Ebu Berze (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) yatsıdan evvel uyumayı ve yatsıdan sonra da konuşmayı hoş görmüyordu.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 916, text: "İbn-i Ömer (r.a)'dan şöyle rivayet edilmiştir: \"Resûlüllah (s.a.v) hayatının sonlarında bir ara yatsı namazı kıldırmış ve selam verince de şöyle buyurmuştur; Şu gecenizi görüyorsunuz değil mi? Şüphesiz yüz senenin başında, bu gün yeryüzünde bulunanlardan hiçbir kimse -hayatta- kalmayacaktır.\" (Buhari ve Müslim) DİNİ BİR MAZERETİ BULUNMAYAN BİR KADININ, KOCASI ÇAĞIRDIĞI ZAMAN YATAĞINDAN KAÇINMASININ HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 917, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir kişi hanımını yatağına çağırdığı zaman kadın yüz çevirir   ve kocası kendisine kızarak gecelerse, sabahlayıncaya kadar melekler o kadına lanet ederler.\" (Buhari ve Müslim) KOCASI YANINDA BULUNAN BİR KADININ ONDAN İZİN ALMADAN ORUÇ TUTMASININ HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 918, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir kadına, kocası yanında iken ondan izin almadan -nafîle-oruç tutması helal değildir, Kadın-kocasının izni olmadan bir kimseyi kocasının evine alması da helal değildir.\" (Buhari ve Müslim) CEMAATİN İMAMDAN EVVEL BAŞINI RÜKU VE SECDEDEN KALDIRMASININ HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 919, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  NAMAZDA ELİ BÖĞÜRE KOYMANINMEKRUH OLUŞU \"Sizden biriniz başını imamdan önce kaldırdığı zaman Allah'ın, başını merkep başı gibi yapmasından, ya da suretini merkep suretine çevirmesinden çekinmez mi?\" (Buharı ve Müslim) NAMAZDA ELİ BÖĞÜRE KOYMANIN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 920, text: "Ebu Hureyre (r.a)'dan şöyle dediği rivayet edilmiştir: \"Namazda eli böğüre koymaktan yasaklandık.\" (Buharı ve Millim) YEMEĞİN HAZIR VE NEFSİN DE İŞTAH DUYDUĞU BİR ZAMAN DA YA DA ABDEST SIKIŞIK İKEN NAMAZ KILMANIN KERAHATİ", source: "Hadis-i Şerif" },
    { id: 921, text: "Hz. Âişe (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir:   \"Yemek hazır iken namaz kılınmaz. Büyük veya küçük abdest kendisini zorluyor iken de namaz kılınmaz.\" (Müslim) NAMAZDA GÖZÜ GÖĞE DİKMENİN YASAK OLUŞU", source: "Hadis-i Şerif" },
    { id: 922, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bazı cemâate ne oluyor ki, namaz içinde gözlerini göğe kaldırıyorlar?\" Resûlüllah (s.a.v)'in bu husustaki sözü o kadar ağırlaştı ki, sonunda şöyle buyurdu; \"Ya böyle yapmaktan vazgeçerler, ya da gözlerinin -nuru- alınır.\" (Buhari) NAMAZDA ÖZÜRSÜZ YERE BAŞI ETRAFA ÇEVİRMENİN KERAHATİ", source: "Hadis-i Şerif" },
    { id: 923, text: "Hz. Âişe (r.a)'dan şöyle dediği rivayet edilmiştir:  KABİRLERE KARŞI NAMAZA DURMANIN YASAKLANIŞI \"Resûlüllah (s.a.v)'e namazda etrafla ilgilenmeyi sorduğumda şöyle buyurdu; O, öyle bir kapmadır ki, şeytan onunla kulu namazdan çekip kapmaktadır.\" (Buharı)", source: "Hadis-i Şerif" },
    { id: 924, text: "Hz. Enes (r.a)'dan Resûlüllah (s.a.v)'İn kendisine şöyle buyurduğu rivayet edilmiştir: \"Namazda etrafla meşgul olmaktan sakın! Çünkü namazda etrafla meşgul olup bakınmak, helak edicidir. Eğer elinde olma yarak vazgeçemiyorsa, o zaman nafile namazlarda yapsın, farzlar da değil.\" (Tirmizi rivayet etmiş ve hadis hasendir, sahihtir de miştir.) KABİRLERE KARŞI NAMAZA DURMANIN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 925, text: "Ebu Mersed Kennâz b. Husayn (r.a)dan Resûlüllah(s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Kabirlere karşı namaz kılmayınız ve kabirlerin üzerlerine oturmayınız.\" (Müslim)   NAMAZ KILANIN ÖNÜNDEN GEÇMENİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 926, text: "Ebu Cuheym Abdullah b. Haris b. Sımme el-Ensari (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Namaz kılanın önünden geçen kimse, üzerine ne kadar sorumluluk aldığını eğer bilseydi, onun Önünden geçmektense kırk gün beklemesi daha hayırlı olurdu.\" Rivayet eden dedi ki; Kırk gün mü, kırk ay mı veya kırk sene mi dediğini bilemiyorum. (Buhari ve Müslim) MÜEZZİN KAMETE BAŞLADIKTAN SONRA SÜNNET, NAFİLE VEYA BAŞKA BİR NAMAZA BAŞLAMANIN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 927, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:  SADECE CUMA GÜNÜ ORUÇ TUTMANIN VEYA SADECE CUMA GE... \"Namaz için kamete başlanıldığı zaman, farz namazından başka bir namaz -kılmak- yoktur.\" (Müslim) SADECE CUMA GÜNÜ ORUÇ TUTMANIN VEYA SADECE CUMA GECESİNDE NAFİLE NAMAZ KILMANIN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 928, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s,a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Geceler arasında sadece Cuma gecesini ibadet etmeye ayırmayınız. Günler arasında da sadece Cuma gününü oruç tutmaya ayırmayınız. Ancak o gün sizden birinizin tuttuğu oruca rastlamışsa o başka.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 929, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Sizden biriniz sadece Cuma günü oruç tutmasın. Ancak bir gün öncesiyle veya bir gün sonrasıyla birlikte tutulabilir.\" (Buharı ve Müslim)   İKİ VEYA DAHA FAZLA GÜN YİYİP İÇMEDEN ORUÇ TUTMANIN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 930, text: "Ebu Hureyre ve Hz. Âişe (r.a)'dan şöyle rivayet olunmuştur; ''Peygamber (a.s) peşpeşe aralıksız tutulan orucu yasaklamıştır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 931, text: "Ibn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) hiç iftar edilmeden aralıksız tutulan orucu yasaklamıştı. Bunun üzerine ashab dediler ki; 'Ama sen ara vermeden tutuyorsun?' Bunun üzerine Peygamber (a.s) şöyle buyurdu; Ben sizin gibi değilim. Çünkü ben -Rabbim tarafından- yedirilip içiriliyorum.\" (Buharı ve Müslim. Bu Buharı'nin lafzıdır.) KABİR ÜZERİNE OTURMANIN HARAM OLUŞU  KABİRLERİ KİREÇLEMEK VE ÖZERLERİNE BİNA YAPMANIN YASAK...", source: "Hadis-i Şerif" },
    { id: 932, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden birinizin kor üzerine oturup da -ateşin- elbisesini yakması ve cildine ulaşması, kabir üzerine oturmasından kendisi için daha hayırlıdır,\" (Müslim) KABİRLERİ KİREÇLEMEK VE ÜZERLERİNE BİNA YAPMANIN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 933, text: "Cabir (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) kabirlerin badana edilmesini, üzerlerine oturulmasını ve üsüerine bina yapılmasını yasaklamıştır.\" (Müslim) KÖLENİN EFENDİSİNDEN KAÇMASININ BÜYÜK HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 934, text: "Cerir b. Abdullah (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Hangi köle -efendisinden- kaçarsa, artık zimmet ondan uzaklaşmış olur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 935, text: "Cerir (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir köle kaçtığı zaman, kıldığı namazı kabul olunmaz.\" (Müslim) DİNİ CEZALARDA SUÇLUYA İLTİMAS GEÇMENİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 936, text: "Hz. Âişe (r.a)'dan şöyle rivayet edilmiştir: \"Manzum kabilesinden hırsızlık yapan bir kadının durumu Kureyş'e ağır geldi ve dediler ki; 'Kim bu kadınla alakalı olarak Resûlüllah (s.a.v) ile konuşabilir?' Bir kısmı da; 'Bu işe ancak Resûlüllah (s.a.v)'in sevgilisi Usâme b. Zeyd cesaret edebilir' dediler. Ve Usâme Resûlüllah (s.a.v) ile konuştu. Resûlüllah (s.a.v); 'Yüce Allah'ın hadlerinden -cezalarından- bir haddin yapılmaması için aracı mı oluyorsun?'buyurdu. Sonra kalktı, hemen bir hutbe verdi ve şöyle buyurdu;  DURGUN SUYA KÜÇÜK ABDEST BOZMANIN YASAK EDİLİŞİ Şüphesiz ki sizden öncekilerin helak olmasına sebep- şu idi; Onlardan soylu olan hırsızlık yaptığında onu bırakırlar; ama onlar içinde zayıf olan hırsızlık yaptığında ise onun üzerine haddi -cezayı- tatbik ederlerdi. Allah'a yemin olsun ki, eğer Muhammed'in kızı Fatıma dahi hırsızlık yapsa, elbette onun elini keserdim.\" (Buharı ve Müslim) YOLLARA, GÖLGELİKLERE, SU KAYNAKLARINA VS. YERLERE BÜYÜK ABDEST BOZMANIN YASAK EDİLİŞİ", source: "Hadis-i Şerif" },
    { id: 937, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Lanete sebep olan iki şeyden sakınınız!\" Ashab; Lanete sebep olan iki şey de nedir? diye sordular. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu; \"İnsanların yoluna veya gölgelendiği yerlere abdest bozmaktır.\" (Müslim) DURGUN SUYA KÜÇÜK ABDEST BOZMANIN YASAK EDİLİŞİ", source: "Hadis-i Şerif" },
    { id: 938, text: "Cabir (r.a)'dan şöyle buyurduğu rivayet edilmiştir: \"Resûlüllah (s.a.v) durgun suya işenmesini yasaklamıştır.\" BABANIN HİBEDE BAZI ÇOCUKLARINI BAZILARINDAN ÜSTÜN TUTMASININ MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 939, text: "Numan b. Beşir (r.a)'dan şöyle rivayet edilmiştir: \"Babası onu Resûlüllah (s.a.v)'in huzuruna getirip; 'Ben bu oğluma, kendime ait olan bir köleyi verdim' dedi. Resûlüllah (s.a.v) şöyle buyurdu; 'Bütün evlatlarına da aynısını verdin mi?' Babası; 'Hayır' dedi. Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu; O zaman -evladına verdiğin- hibenden dön.\" (Buharı ve Müslim) KADININ ÜÇ GÜNDEN FAZLA YAS TUTMASININ HARAM OLUŞU ANCAK KOCASI İÇİN DÖRT AY ON GÜN TUTABİLECEĞİ HK.", source: "Hadis-i Şerif" },
    { id: 940, text: "Zeyneb b. Ebu Seleme (r.a)'dan şöyle dediği rivayet edilmiştir: \"Peygamber (a.s)'ın hanımı Ümmü Habibe (r.a)'ın babası Ebu Süfyan b. Harb (r.a) vefat ettiği zaman yanına girmiştim. İçinde Safran veya başka bir şey bulunan koku istedi. Kokudan evvela cariye sürdü, sonra da kendi yanaklarına sürdü ve şöyle devam etti; 'Allah'a yemin olsun ki benim kokuya ihtiyacım yok; ancak ben Resûlüllah (s.a.v)'i minber üzerinde şöyle buyururken işittim: Allah'a ve ahiret gününe inanan hiçbir kadının bir ölüye üç geceden fazla yas tutması helal değildir. Ancak kocasına dört ay on gün yas tutabilir.\" Zeyneb şöyle dedi: Ben, kardeşi öldüğü zaman Zeyneb b. Cahş (r.a)'ın yanına girmiştim. Bir koku isteyip ondan süründü ve sonra şöyle dedi; Allah'a yemin olsun ki benim kokuya bir ihtiyacım yok. Ancak ben Resûlüllah (s.a.v)'i minber üzerinde şöyle buyururken işittim; Allah'a ve ahiret gününe inanan hiçbir kadının üç günden fazla bir ölüye yas tutması helal değildir. Ancak kocasına dört ay on gün yas tutabilir,\" (Buhari ve Müslim)   SİMSARLIK, KÖYLÜNÜN MALINI ŞEHİR DIŞIN DA KARŞILAYIP ELİNDEN UCUZ ALMAK, DİN KARDEŞİNİN MÜŞTERİSİNİ ELİNDEN KAPMAK VE EVLİLİK TEKLİFİ YAPILAN KADIN ÜSTÜNE DÜNÜR GÖNDERMENİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 941, text: "Enes (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) şehirlinin, isterse ana baba bir kardeşi bile olsa, köylüye simsarlık yapmasını yasaklamıştır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 942, text: "Ibn-i Abbas (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Pazara gelenleri, malları ucuza kapmak için yol üzerinde karşılamayınız. Şehirli, köylünün malını satmasın.\" Tavus İbn-i Abbas'a; 'Şehirli, köylünün malını satmasın' sözü de ne demek?diye sorunca, İbn-i Abbas şöyle dedi; 'Ona simsarlık yapmasın.' (Buhari ve Müslim)  ŞERİATIN İZİN VERDİĞİ YERLERİN DIŞINDA MALI BOŞ YERE...", source: "Hadis-i Şerif" },
    { id: 943, text: "Ibn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bazınız, bazınızın yaptığı satış üzerine satış yapmaya kalkışmasın, Kendisine izin verilmesi hariç, din kardeşinin istettiği kadına da evlilik teklifinde bulunmasın.\" (Buhari ve Müslim. Lafız Müslim'indir.) ŞERİATIN İZİN VERDİĞİ YERLERİN DIŞINDA MALI BOŞ YERE HARCAMANIN YASAK EDİLİŞİ", source: "Hadis-i Şerif" },
    { id: 944, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Şüphesiz ki Allah sizin için üç şeye razı olur ve yine sizin için üç şeyi de çirkin görür. Sizin için razı olduğu hususlar; O'na ibadet edip kendisine hiçbir şeyi ortak koşmamanız, toptan hepinizin Allah'ın ipine sarılmanız ve ayrılığa düşmemenizdir. Sizin için çirkin gördüğü hususlar da; Dedi kodu, çok sual sormanız ve malı ziyan etmenizdir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 945, text: "Muğire b. Şu'be'nin katibi Verrâd'dan şöyle dediği rivayet edilmiştir: \"Muğîre, Muaviye (r.a)'a yazdığı mektupta bana şöyle yazdırdı; Şüphesiz ki Peygamber (a.s) her farz namazının arkasından şöyle buyururdu: Lâ ilahe illallahü vahdehû lâ şerike leh. Lehül-mülk ve lehül-hamd ve hüve alâ külü şey'in kadîr. Allâhümme lâ mania limâ a'tayte ve lâ mû'tıye limâ mena'te ve lâ yenfeu zel-ceddi minke el-ceddi. Yine Muaviye'ye şöyle yazdırdı: Yüce Allah- dedi kodudan, malı ziyan etmekten, çok soru sormaktan, annelere isyan etmekten, kız çocuklarını diri diri gömmekten, verilmesi gerekenin verilmemesinden ve hakkı olmayanı istemekten men etmiştir.\" (Buhari ve Müslim) CİDDİ VEYA ŞAKA OLSUN MÜSLÜMANA SİLAH VS. ŞEYLERİ DOĞRULTMANIN, KININDAN ÇIKAN KILICI ALIP VERMENİN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 946, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Sizden biriniz silah ile kardeşine işarette bulunmasın. Çünkü o farkında olmayabilir, belki de şeytan elinden silahı çeker ve böylelikle ateşten bir çukura yuvarlanmış olur.\" (Buhari ve Müslim)  EZANDAN SONRA FARZ KILININCAYA KADAR MAZERETSİZ MES...", source: "Hadis-i Şerif" },
    { id: 947, text: "Cabir (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) kınından çekilmiş kılıcın elden ele alınıp verilmesini yasaklamıştır.\" (Ebu Davud ve Tirmizi rivayet etmiş ve Tirmizi hadis hasendir demiştir.) EZANDAN SONRA FARZ KILININCAYA KADAR MAZERETSİZ MESCİDDEN AYRILMANIN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 948, text: "Ebu Şa'sâ'dan şöyle dediği rivayet edilmiştir: \"Biz Ebu Hureyre (r.a) ile beraber mescidde oturuyorduk. Birden müezzin ezan okumaya başladı. Bir adam mescidden kalktı yürümeye başladı. Bunun üzerine Ebu Hureyre mescidden çıkıncaya kadar gözüyle o adamı takip etti ve şöyle dedi; İşte bu adam var ya, Kâsım'ın babasına -Muhammed (a.s)'a- isyan etmiş oldu.\" (Müslim) REYHAN KOKUSUNU ÖZÜRSÜZ GERİ ÇEVİRMENİN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 949, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Kime reyhan kokusu sunulursa, sakın onu reddetmesin. Çünkü onun taşınması hafif, kokusu ise güzeldir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 950, text: "Enes b. Malik (r.a)'dan şöyle rivayet edilmiştir: \"Şüphesiz ki Peygamber (a.s) güzel -kokuyu- geri çevirmezdi.\" (Buhari) KİBİRLENİP KENDİNİ BEĞENMESİNDEN KORKULANLARI YÜZÜNE KARŞI ÖVMENİN MEKRUH OLUŞU VE BUNDAN EMİN OLUNURSA METH ETMENİN CAİZ OLUŞU", source: "Hadis-i Şerif" },
    { id: 951, text: "Ebu Musa el-Eş'ari (r.a)'dan şöyle dediği rivayet edilmiştir: \"Peygamber (a.s) bir adamı Öven ve övgüsünde aşırıya kaçan bir kimseyi işitince şöyle buyurdu: Adamı helak ettiniz veya sırtından hançerlediniz.\" (Buhari ve Müslim)  VEBALI OLAN YERDEN KAÇMANIN VEYA GİRMENİN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 952, text: "Ebu Bekre (r.a)'dan şöyle rivayet edilmiştir: \"Bir adam Peygamber (a.s)' ın huzurunda anıldı ve bir kişi onu hayırla meth etti. Bunun üzerine Peygamber (s.a.v) birkaç kere; 'Yazıklar olsun sana! Arkadaşının boynunu kestin ' buyurduktan sonra şöyle devam etti: Eğer sizden biriniz mutlaka övmesi gerekiyorsa ve onu öyle görüyorsa 'Ben şöyle şöyle sanıyorum' desin. Artık onun hesabı Allah'a aittir. Allah'a rağmen hiçbir kimse aklanmamalıdır.\" (Buhari ve Müslim) VEBALI OLAN BİR YERDEN KAÇMANIN VEYA ÖYLE BİR YERE GİRMENİN MEKRUH OLUŞU", source: "Hadis-i Şerif" },
    { id: 953, text: "Usâme b. Zeyd (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Bir yerde Taun -Veba hastalığını- işittiğiniz zaman sakın oraya girmeyiniz! Siz orada iken bir yerde vuku bulursa, sakın oradan çıkmayınız!\" (Buhari ve Müslim)   BÜYÜNÜN BÜYÜK BİR HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 954, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Helak edici yedi husustan kaçınınız!\" Ashab; Ey Allah'ın Resulü, onlar nelerdir?dediler. Bunun üzerine şöyle buyurdu: Allah'a ortak koşmak, büyü yapmak, haksız yere Allah'ın haram kıldığı canı öldürmek, faiz yemek, yetim malı yemek, düşmanla karşılaşıldığı gün kaçmak ve hiçbir şeyden habersiz, iffetli mü'min kadınlara iftira etmektir.\" (Buhari ve Müslim) KAFİRLERİN ELİNE GEÇME KORKUSU OLDUĞU ZAMAN KÜFÜR BELDELERİNE KUR'AN İLE GİTMENİN YASAKLANIŞI", source: "Hadis-i Şerif" },
    { id: 955, text: "Ibn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) Kur'an ile düşman yurduna yolculuk yapılmasını yasaklamıştır.\" (Buharı ve Müslim)  ALTIN VE GÜMÜŞ KAPLARI YEME İÇME VE TEMİZLİKTE KULLANMA... ALTIN VE GÜMÜŞ KAPLARI YEME İÇME VE TEMİZLİKTE KULLANMANIN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 956, text: "Ümmü Seleme (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Gümüş kapda bir şey içen, muhakkak karnında cehennem ateşini lakır lakır öttürmüş olur.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 957, text: "Huzeyfe (r.a)'dan şöyle dediği rivayet edilmiştir: \"Şüphesiz ki Peygamber (a.s) bizi ipek ve atlas giymekten, altın ve gümüş kapdan bir şey içmekten men etmiş ve şöyle buyur muştur; Bunlar dünyada onlara -kafirlere- aittir. Ahirette ise sizin -mü'minlerin- olacaktır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 958, text: "Enes b. Sîrîn'den şöyle rivayet edilmiştir:   \"Ben, Enes b. Malik (r.a) ile beraber Mecusilerden bir grubun yanında bulunmuştum. Gümüş bir kabın içinde pelte getirildi. Hz. Enes- onu yemedi. Ona-getirene- kabı değiştir, denildi. Bunun üzerine onu ahşap bir kaba aktardı. Bu şekilde getirilince artık onu yedi.\" (Beyhakî sahih bir isnatla rivayet etmiştir.) ERKEĞİN ZÂFERANLI ELBİSEYİ GİYMESİNİN HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 959, text: "Enes (r.a)'dan şöyle dediği rivayet edilmiştir: \"Peygamber (a.s) erkeğin zâferanlı elbise giyinmesini yasaklamıştır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 960, text: "Abdullah b. Amr b. As (r.a)'dan şöyle dediği rivayet edilmiştir: \"Peygamber (a.s) benim üzerimde zâferanlanmış iki elbise görünce; 'Bunu sana annen mi emretti?'buyurdu. Ben de; 'Onları yıkayacağım'dedim. Bunun üzerine Peygamber (a.s); yıkamak yetmez, onları yak, buyurdu.\" (Müslim)  AKŞAMA KADAR SUSMANIN YASAK EDİLMESİ AKŞAMA KADAR SUSMANIN YASAK EDİLMESİ", source: "Hadis-i Şerif" },
    { id: 961, text: "Ali (r.a)'dan şöyle dediği rivayet edilmiştir; \"Resûlüllah (s.a.v)'den şunu ezberledim; Buluğa erdikten sonra artık yetimlik olmaz. Gündüz vaktinden geceye kadar susmak da yoktur.\" (Ebu Davud hasen bir isnatla rivayet etmiştir.)", source: "Hadis-i Şerif" },
    { id: 962, text: "Kays b. Ebu Hazım'dan şöyle dediği rivayet edilmiştir: \"Ebu Bekir Sıddık (r.a), Zeyneb ismiyle anılan Ahmes kabilesinden bir kadının yanına vardı. Onun konuşmadığını görünce şöyle dedi; 'Sana ne oluyor ki konuşmuyorsun?' Dediler ki; 'O, konuşmamaya karar verdi.' Bunun üzerine Ebu Bekir Sıddık (r.a); 'Konuş. Çünkü susmak helal değildir. Bu, cahiliyet işlerindendir' dedi. Böylelikle kadın konuştu.\" (Buhari) NESEBİNİ BABASINDAN BAŞKASINA DAYANDIRMANIN VE KÖLENİN EFENDİSİNDEN BAŞKASINA BAĞLANMASININ HARAM OLUŞU", source: "Hadis-i Şerif" },
    { id: 963, text: "Sa'd b. Ebu Vakkas (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim babası olmadığını bildiği halde, babasından başkasını babası diye iddia ederse, o kimseye cennet haramdır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 964, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Babalarınızdan yüz çevirmeyiniz. Kim babasından yüz çevirirse, o nimete-küfretmektir.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 965, text: "Ebu Zer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Bildiği halde, babasından başkasını babası olduğunu iddia eden kimse mutlaka -nimete- küfretmiş olur. Kim kendisinin olmayan bir şeyi kendisinin olduğunu iddia ederse bizden değildir ve ateşteki yerini hazırlasın. Kim de bir kişiye 'Kafir' veya 'Allah düşmanı' diye çağırır da durum söylediği gibi olmazsa, söylediği söz kendi aleyhine döner.\" (Buhari ve Müslim. Bu lafız, Müslim'in lafzıdır,)  ALLAH VE RESULÜNÜN YASAKLADIKLARINI YAPMAKTAN SAKINMAK ALLAH VE RESULÜNÜN YASAKLADIKLARINI YAPMAKTAN SAKINMAK", source: "Hadis-i Şerif" },
    { id: 966, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Şüphesiz ki Yüce Allah kıskançtır. Allah'ın kıskançlığı ise, bir kişinin Allah'ın haram kıldığı şeyleri yapmasıdır.\" (Buharı ve Müslim) YASAKLANAN ŞEYİ YAPANIN SÖYLEMESİ VE YAPMASI GEREKEN HUSUSLAR", source: "Hadis-i Şerif" },
    { id: 967, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim yemin eder ve yemininde 'Lât ve Uzza hakkı için' derse, hemen 'Allah'dan başka hiçbir ilah yoktur' desin. Kim de kardeşine 'Gel seninle kumar oynayalım' derse, hemen bir sadaka versin.\" (Buhari ve Müslim)   MUHTELİF KONULARLA İLGİLİ HADİSLER", source: "Hadis-i Şerif" },
    { id: 968, text: "Rib'i b. Hırâş'dan şöyle rivayet edilmiştir: \"Ebu Mes'ud el-Ensari ile birlikte Huzeyfe b. Yeman (r.a)'a gitmiştim. Ebu Mes'ud kendisine; 'Resûlüllah (s.a.v)'den Deccâl ile ilgili işittiğin şeyleri bana anlat' dedi. Bunun üzerine Huzeyfe şunları anlattı; Şüphesiz ki Deccâl, beraberinde su ve ateş olduğu halde ortaya çıkacaktır. Insanların su diye gördüğüne gelince, aslında o yakıcı bir ateştir. Insanların ateş diye gördükleri ise, aslında tatlı ve soğuk bir sudur. Sizden kim ona yetişirse, hemen ateş olarak gördüğüne yanaşsın. Çünkü o tatlı ve hoş bir sudur.\" Ebu Mes'ud; Şüphesiz bunu ben de işitmiştim, dedi. (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 969, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Mekke ve Medine'nin dışında bütün her yere Deccâl ayak basacaktır. Melekler buralarda bulunan bütün yolları tutup saf halinde beklerler. Bunun üzerine Deccâl çorak bir yere iner. Medine üç sarsıntı ile sarsılır. Allah (c.c) bütün kafir ve münafığı oradan çıkarır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 970, text: "Enes (r.a)'dan Resâlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Deccâl'e Isfahan Yahudilerinden yetmiş bin kişi, üzerlerinde talasanlar olduğu halde tabi olur.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 971, text: "Ummü Şerîk (r.a)'dan Resâlüllah (s.a.v)'in şöyle buyurduğunu İşittiği rivayet edilmiştir: \"İnsanlar Deccâl'den dağlara doğru kaçacaklardır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 972, text: "Imrân b. Husayn (r.a)'dan Resâlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Âdem'in yaratılışı ile kıyametin kopacağı saat arasında Deccâl'den daha büyük bir olay yoktur!\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 973, text: "Muğîre b. Şu'be (r.a)'dan şöyle dediği rivayet edilmiştir: \"Benim Resûlüllah (s.a.v)'e Deccâl hakkında sorduğum sorudan daha çok hiçbir kimse soru. sormamıştır. Şüphesiz ki Resûlüllah (s.a.v) bana; 'O sana zarar veremez' buyurunca dedim ki; 'İnsanlar Deccâl ile birlikte dağ kadar ekmek, ırmak kadar da su bulunduğunu söylüyorlar!' Bunun üzerine Resûlüllah (s.a.v) şöyle buyurdu; O, Allah katında bundan daha alçaktır.\" (Buharİ ve Müslim)", source: "Hadis-i Şerif" },
    { id: 974, text: "Enes (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: Hiçbir peygamber yoktur ki, ümmetini bir gözü kör olan yalancı -Deccâl- dan korkutmuş olmasın. Şüphesiz ki onun bir gözü kördür, ama hiç şüpheniz olmasın ki Yüce Rabbiniz kör değildir. O-nun iki gözü arasında 'K-F-R-kafir' yazılıdır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 975, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a,v) 'in şöyle buyurduğu rivayet edilmiştir:  MUHTELİF KONULARLA İLGİLİ HADİSLER \"Dikkat ediniz! Size, hiçbir peygamberin kavmine kendisinden bahsetmediği Deccâl hakkında haber vereyim mi? Şüphesiz ki onun bir gözü kördür. O, kendisiyle birlikte cennet ve cehennemin bir benzerini getirecektir. Onun cennet dediği var ya, o mutlaka cehennemdir.\" (Buharı ve Müslim.)", source: "Hadis-i Şerif" },
    { id: 976, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kıyamet, müslümarılarla yahudiler savaşmadıkça kopmayacaktır. Sonunda bir yahudi, taş ve ağacın arkasına saklanır; bunun üzerine taş ve ağaç; 'Ey Müslüman! Arkamda saklanan bir yahudidir. Gel ve onu öldür!' der. Ancak 'Garkad' denilen ağaç hariç; çünkü o, yahudi ağacıdır.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 977, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Nefsim elinde olan -Allah'a- yemin olsun ki, bir adam kabirden geçerken kabrin üzerine çullanıp 'Keşke bu kabrin sahibi yerinde ben olsaydım!' demedikçe dünya yıkılmaz. Oysa bu temenniyi dini için değil de, başına gelen beladan dolayı yapacaktır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 978, text: "Ebu Said el-Hudri (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Ahir zaman da halifelerinizden bir halife, avuçla mal dağıtacak ve onu saymayacaktır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 979, text: "Ebu Musa el-Eş'ari (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İnsanların üzerine öyle bir zaman gelecek ki, kişi altından sadaka vermek için dolaşıp duracak da o sadakayı alacak kimse bulamayacaktır. Erkeklerin azlığı ve kadınların da çokluğundan dolayı bir erkeğin peşinden kırk kadın gidip kendisine sığındığı görülecektir.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 980, text: "İbn-i Ömer (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yüce Allah bir topluluğa azab indirdiği zaman, o azab o topluluğun içinde bulunan -iyi , kötü- herkese isabet eder. Sonra amellerine göre diriltilirler.\" (Buharı ve Müslim)  MUHTELİF KONULARLA İLGİLİ HADİSLER", source: "Hadis-i Şerif" },
    { id: 981, text: "Cabir (r.a)'dan şöyle dediği rivayet edilmiştir: \"Peygamber (a.s)'ın hutbe okurken üzerine yaslanıp durduğu bir hurma kütüğü vardı. Minber konulduğu zaman o kütükten, gebe devenin -doğum sancısında çıkardığı- ses gibi bir inilti işittik. Sonunda Peygamber (a.s) hutbeden inip elini onun üzerine koydu ve böylelikle sakinleşip sustu.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 982, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Mü'min, bir delikten iki kere ısırılmaz.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 983, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"İmamlarınız-size namaz kıldırıyorlar. Eğer doğru -kıldırırlarsa- sevabı hepinize aittir. Ama hata ederlerse sevabı size, -sorumluğu da- onların aleyhlerinedir.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 984, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Aziz ve Yüce olan Allah, zincirlere bağlanmış bir halde cennete giren bir topluluktan hoşnut olmuştur.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 985, text: "Hz. Âişe (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğu rivayet edilmiştir: \"Melekler nurdan yaratılmıştır. Cinler de dumansız bir ateşten yaratılmıştır. Adem ise -Kur'an'da- size açıklandığı şekilde yaratılmıştır.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 986, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Üç sınıf insan vardır ki, Allah kıyamet günü onlarla konuşmayacak, onları temize çıkarmayacak, onlara bakmayacak ve onlar için çok acıklı bir azap vardır; zina eden ihtiyar, yalancı idareci ve büyüklük taslayan fakir.\" (Müslim)  MUHTELİF KONULARLA İLGİLİ HADİSLER", source: "Hadis-i Şerif" },
    { id: 987, text: "Amr b. As (r.a)'dan Resûlüllah (s.a.v)'in söyle buyurduğunu işittiği rivayet edilmiştir: \"Bir hakim hüküm vereceği zaman ictihad eder de sonra içtihadında isabet ederse, onun için iki mükafat vardır. Eğer ictihad edip hüküm verir ve hata ederse, onun için bir mükafat vardır.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 988, text: "Ebu Zeyd Amr b. Ahtab el-Ensari (r.a)'dan şöyle dediği rivayet edilmiştir: \"Resûlüllah (s.a.v) bize sabah namazı kıldırdı. Sonra minbere çıkıp öğle namazı vakti girinceye kadar bize hutbe verdi. Minberden indi ve namaz kıldı. Sonra tekrar minbere çıktı ve ikindi namazı vakti girinceye kadar bize hutbe verdi. Sonra minberden indi ve namaz kıldı. Sonra minbere çıktı ve güneş batıncaya kadar- bize hutbe verdi. Olmuş ve olacak olanları bize haber verdi. Bizim en iyi bilenimiz, en fazla ezberleyenimizdir.\" (Müslim) İSTİĞFAR", source: "Hadis-i Şerif" },
    { id: 989, text: "Eğar el-Müzeni (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Şüphesiz ki benim kalbim -nurdan bir perde ile- perdelen-miştir ve ben her gün yüz kere Allah'a mutlaka tövbe ederim.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 990, text: "Ebu Hureyre (r.a) 'dan Resûlüllah (s.a.v)'in şöyle buyurduğunu işittiği rivayet edilmiştir: \"Allah'a yemin olsun ki ben, bir günde yetmiş kereden fazla Allah'a tövbe edip bağışlanma diliyorum.\" (Buhari)", source: "Hadis-i Şerif" },
    { id: 991, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'în şöyle buyurduğu rivayet edilmiştir: \"Nefsim elinde olana yemin olsun ki, eğer siz günah işlememiş olsanız, Yüce Allah sizi mutlaka gönderir ve Allah'a tövbe eden, Allah'ın da tövbelerini kabul ettiği bir topluluğu sizin yerinize mutlaka getirirdi.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 992, text: "İhn-i Ömer (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz, Resûlüllah (s.a.v)'in sadece bir mecliste yüz defa 'Rabbim, beni bağışla ve tövbemi kabul buyur; şüphesiz ki sen tövbeleri  İSTİĞFAR en çok kabul eden ve en fazla merhamet edensin' diye dua ettiğini sayardık.\" (Ebu Davud ve Tirmizi rivayet etmiş ve Tirmizi, hadis sahihtir demiştir.)", source: "Hadis-i Şerif" },
    { id: 993, text: "İbn-i Abbas (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Kim istiğfar etmeye devam ederse, Allah onun için her sıkıntıdan bir çıkış yolu, her üzüntüden de bir ferahlık yaratır. Onu hiç ummadığı yerden rızıklandırır.\" (Ebu Davud) ALLAH'IN CENNETTE MÜ'MİNLERE HAZIRLADIĞI NİMETLER", source: "Hadis-i Şerif" },
    { id: 994, text: "Cabir (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Cennet ehli cennette yerler ve içerler, abdest bozmazlar, sümkürmezler ve idrar yapmazlar. Ama onların bu yedikleri, geğirti ve misk gibi terle dışarı atılır. Nefes alıp veme nasıl kendilerine ilham olunduysa, aynı ilham ile tesbih ederle, tekbir getirirler.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 995, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Yüce Allah şöyle buyurmuştur, Ben, salih kullarım için hiçbir gözün görmediği, hiçbir kulağın işitmediği ve hiçbir beşerin kalbinden dahi geçiremeyeceği şeyler hazırladım. İsterseniz şu ayeti okuyunuz: Hiçbir kimse, yaptıklarının mükafatı olarak gözler aydınlığı -nimetlerden- neler gizlendiğini asla bilemez!\" Secde;17 (Buhari ve Müslim)", source: "Hadis-i Şerif" },
    { id: 996, text: "Ebu Musa (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Gerçekten mü'min için cennette, göğe doğru altmış mil uzunluğunda içi boş ve tek bir inciden yapılmış bir çadır bulunmaktadır. Onun içinde mü'minin aileleri vardır; mü'min onları ziyaret eder ama bir kısmı diğerini göremez.\" (Buhari ve Müslim)  ALLAH'IN CENNETTE MÜ'MİNLERE HAZIRLADIĞI NİMETLER", source: "Hadis-i Şerif" },
    { id: 997, text: "Ebu Said ve Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir: \"Cennet ehli cennete girdiği zaman bir münâdî şöyle seslenir; Şüphesiz ki artık size yaşam vardır; ebedi olarak ölmeyeceksiniz. Artık size sağlık afiyet vardır; ebedi olarak hastalanmayacaksınız. Artık size gençlik vardır; ebedi olarak yaşlanmayacaksınız. Artık size nimetlere erişme vardır; ebedi olarak hüzünlenmeyeceksiniz.\" (Müslim)", source: "Hadis-i Şerif" },
    { id: 998, text: "Ebu Hureyre (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir; \"Sizden birinizin cennetteki en düşük makamı, kendisine -Yüce Allah'ın- 'Dile bakalım ne dilersen!' demesidir. Yüce Allah ona; 'Diledin mi?' diye sorar, o da 'Evet' der. Bunun üzerine ona şöyle buyurur; Şüphesiz ki sana dilediğin ne varsa, bir kat fazlasıyla birlikte verilecektir! (Müslim)", source: "Hadis-i Şerif" },
    { id: 999, text: "Ebu Said el- Hudri (r.a)'dan Resûlüllah (s.a.v)'in şöyle buyurduğu rivayet edilmiştir:   \"Şüphesiz ki Aziz ve Celil olan Allah, cennet ehline şöyle buyurur; 'Ey cennet ehli!' Onlar; 'Rabbimiz buyur, emrine amadeyiz ve hayır senin elindedir' derler. Yüce Allah; 'Razı oldunuz mu?'buyurur. Onlar; 'Ey Rabbimiz, bize ne oluyor ki razı olmayalım! Oysa bize, yaratıklarından hiçbir kimseye vermediğini verdin'derler. Bunun üzerine Yüce Allah; 'Dikkat edin, size bundan daha üstününü vereyim mi?'buyurur. Onlar; 'Hangi şey bundan daha üstün olabilir ki?Derler. Bunun üzerine Yüce Allah şöyle buyurur; Size rızâmı helal kılıyorum. Artık bundan sonra size asla kızmayacağım.\" (Buharı ve Müslim)", source: "Hadis-i Şerif" },
    { id: 1000, text: "Cerir b. Abdullah (r.a)'dan şöyle dediği rivayet edilmiştir: \"Biz, Resûlüllah (s.a.v)'in huzurunda bulunuyorduk. Dolunay şeklindeki aya baktı ve şöyle buyurdu: Şüphesiz ki siz, şu ayı gördüğünüz gibi Rabbinizi çıplak gözle görebileceksiniz. O'nu görüp müşahede etmekte, herhangi bir sıkıntı çekmeyeceksiniz.\" (Buhari ve Müslim)", source: "Hadis-i Şerif" },
];

